def _governed_ontology_mutation(method_name: str):
    """Route a generic canonical write through the shared authority command."""

    def decorate(handler):
        @wraps(handler)
        def governed(**kwargs):
            from ...services.ontology_mutation_command_service import (
                execute_governed_ontology_method,
                normalise_governed_ontology_arguments,
                resolve_governed_ontology_arguments,
            )

            if method_name == "create_concepts":
                input_error = _create_concepts_input_placement_error(kwargs)
                if input_error is not None:
                    return input_error
            governed_arguments = normalise_governed_ontology_arguments(
                method_name,
                kwargs,
            )
            try:
                governed_arguments = resolve_governed_ontology_arguments(
                    method_name,
                    governed_arguments,
                )
            except Exception as exc:
                from ...services.ontology_mutation_command_service import (
                    OntologyMutationCommandError,
                )

                if isinstance(exc, OntologyMutationCommandError):
                    return {
                        "success": False,
                        "effect_status": "not_started",
                        "mutation_outcome": "not_started",
                        "changed": False,
                        "error_code": exc.reason_code,
                        "error": exc.public_message,
                    }
                raise
            preview = bool(
                (
                    method_name
                    in {"delete_concept", "merge_concepts", "rename_concept"}
                    and governed_arguments.get("simulate", True)
                )
                or (
                    method_name in {"remove_relationship", "remove_relationships_bulk"}
                    and governed_arguments.get("dry_run", False)
                )
            )
            return execute_governed_ontology_method(
                method_name=method_name,
                arguments=governed_arguments,
                mutate=lambda: handler(**governed_arguments),
                preview=preview,
            )

        return governed

    return decorate


def _utc_now_iso() -> str:
    from datetime import datetime, timezone

    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _run_async_compat(async_fn):
    """Run an async function from sync code.

    If we're already inside a running event loop (e.g. when called via the
    internal chat orchestrator), running `asyncio.run()` would raise.
    In that case, we execute the coroutine in a fresh event loop in a worker
    thread and block until completion.
    """

    import asyncio
    import concurrent.futures
    import contextvars

    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run(async_fn())

    caller_context = contextvars.copy_context()

    def _run_in_worker():
        return asyncio.run(async_fn())

    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
        return executor.submit(caller_context.run, _run_in_worker).result()


def _scoped_assertion_actor_claim(
    kwargs: Mapping[str, Any],
    field_names: Sequence[str],
    *,
    mismatch_field: str,
) -> Any:
    """Return one compatible actor claim across legacy payload aliases."""

    claimed_values: list[Any] = []
    normalised_values: set[str] = set()
    for field_name in field_names:
        value = kwargs.get(field_name)
        if not isinstance(value, str) or not value.strip():
            continue
        cleaned = value.strip()
        normalised = cleaned if cleaned.startswith("#") else f"#V#{cleaned}"
        claimed_values.append(value)
        normalised_values.add(normalised)
    if len(normalised_values) > 1:
        raise WorkflowActorScopeError(
            "workflow_actor_scope_mismatch",
            mismatch_fields=(mismatch_field,),
        )
    return claimed_values[0] if claimed_values else None


def _scoped_assertion_actor_scope_error_response(
    exc: Exception,
) -> dict[str, Any]:
    reason = str(getattr(exc, "reason", "") or "workflow_actor_scope_mismatch")
    if reason == "workflow_actor_authority_required":
        reason = "authenticated_actor_context_required"
    mismatch_fields = getattr(exc, "mismatch_fields", ())
    return make_error_response(
        reason,
        (
            "Scoped-assertion access requires trusted actor provenance, and "
            "payload identity claims must match that actor."
        ),
        details={
            "mismatch_fields": [
                str(item)
                for item in mismatch_fields
                if item in {"user_id", "org_id", "namespace"}
            ]
        },
    )


def _resolve_internal_mcp_scoped_assertion_actor_scope(
    kwargs: Mapping[str, Any],
    *,
    surface: str,
    require_actor: bool = False,
    ignore_untrusted_payload_identity: bool = False,
) -> tuple[Any | None, dict[str, Any] | None]:
    """Resolve actor scope without promoting generic tool-payload identity.

    InternalMCP's default gateway installs user/organisation payload fields as a
    compatibility access context. That context is not authentication. Scoped
    assertion paths therefore bind only an actor that pre-dated the invocation,
    an explicitly trusted operator fallback, or a deliberate direct in-process
    call with no identity claims. Generic knowledge reads may instead discard
    untrusted claims and bind no actor, preserving their base-publication view.
    """

    from ...security.access_control import (
        get_effective_organisation_concept_id,
        get_effective_user_concept_id,
    )
    from ...services.workflow_actor_scope_service import (
        resolve_authoritative_workflow_actor_scope,
    )
    from .gateway import (
        get_internal_mcp_actor_context_source,
        get_internal_mcp_preexisting_actor_context,
    )

    try:
        source = get_internal_mcp_actor_context_source()
        preexisting_actor = get_internal_mcp_preexisting_actor_context()
        payload_claims_are_trusted = source == "trusted_operator_payload_fallback"
        discard_payload_claims = (
            ignore_untrusted_payload_identity and not payload_claims_are_trusted
        )
        if discard_payload_claims:
            claimed_user = None
            claimed_org = None
            claimed_namespace = None
        else:
            claimed_user = _scoped_assertion_actor_claim(
                kwargs,
                (
                    "acting_user_concept_id",
                    "user_concept_id",
                    "user_id",
                    "actor_user_id",
                ),
                mismatch_field="user_id",
            )
            claimed_org = _scoped_assertion_actor_claim(
                kwargs,
                (
                    "organisation_concept_id",
                    "org_concept_id",
                    "organisation_id",
                    "org_id",
                ),
                mismatch_field="org_id",
            )
            claimed_namespace = kwargs.get("namespace")
        has_identity_claim = any(
            isinstance(value, str) and bool(value.strip())
            for value in (claimed_user, claimed_org, claimed_namespace)
        )

        ambient_kwargs: dict[str, Any]
        allow_unscoped_claims = False
        if preexisting_actor is not None:
            ambient_kwargs = {
                "ambient_user_id": preexisting_actor[0],
                "ambient_org_id": preexisting_actor[1],
                "ambient_context_supplied": True,
            }
        elif source == "trusted_operator_payload_fallback":
            ambient_kwargs = {
                "ambient_user_id": None,
                "ambient_org_id": None,
                "ambient_context_supplied": False,
            }
            allow_unscoped_claims = True
        elif source is None:
            ambient_user = get_effective_user_concept_id()
            ambient_org = get_effective_organisation_concept_id()
            if ambient_user or ambient_org:
                ambient_kwargs = {
                    "ambient_user_id": ambient_user,
                    "ambient_org_id": ambient_org,
                    "ambient_context_supplied": True,
                }
            elif not has_identity_claim:
                # Preserve actorless direct unit/startup reads. They see no
                # scoped rows because no audience is bound.
                ambient_kwargs = {
                    "ambient_user_id": None,
                    "ambient_org_id": None,
                    "ambient_context_supplied": False,
                }
                allow_unscoped_claims = True
            else:
                raise WorkflowActorScopeError("workflow_actor_authority_required")
        elif source == "tool_payload_fallback" and not has_identity_claim:
            if require_actor:
                raise WorkflowActorScopeError("workflow_actor_authority_required")
            # Actorless generic reads retain their established base-publication
            # behaviour. With no audience keys, lower services cannot expose
            # scoped rows.
            ambient_kwargs = {
                "ambient_user_id": None,
                "ambient_org_id": None,
                "ambient_context_supplied": False,
            }
            allow_unscoped_claims = True
        else:
            # In particular, ``tool_payload_fallback`` is the ordinary gateway
            # path whose identity originated in these same untrusted fields.
            raise WorkflowActorScopeError("workflow_actor_authority_required")

        actor_scope = resolve_authoritative_workflow_actor_scope(
            claimed_user_id=claimed_user,
            claimed_org_id=claimed_org,
            claimed_namespace=claimed_namespace,
            allow_unscoped_claims=allow_unscoped_claims,
            **ambient_kwargs,
        )
        if require_actor and not bool(
            actor_scope.user_concept_id or actor_scope.organisation_concept_id
        ):
            raise WorkflowActorScopeError("workflow_actor_authority_required")
        return actor_scope, None
    except WorkflowActorScopeError as exc:
        logger.info(
            "Denied %s scoped-assertion access: %s",
            surface,
            getattr(exc, "reason", type(exc).__name__),
        )
        return None, _scoped_assertion_actor_scope_error_response(exc)


@contextmanager
def _bind_internal_mcp_scoped_assertion_actor(actor_scope: Any):
    """Apply only the actor scope returned by the provenance guard."""

    from ...security.access_control import (
        force_access_control_enforcement,
        override_current_actor,
    )

    with (
        override_current_actor(
            actor_scope.user_concept_id,
            actor_scope.organisation_concept_id,
        ),
        force_access_control_enforcement(),
    ):
        yield


def _internal_mcp_knowledge_context_view(actor_scope: Any) -> str:
    """Select the semantic read view from verified actor authority only."""

    if actor_scope.user_concept_id or actor_scope.organisation_concept_id:
        return "actor_effective"
    return "base_publication"


def _annotate_bounded_relation_lookup(
    payload: Mapping[str, Any],
    *,
    concept_id: str,
    predicate_filter: Any,
    relation_kind: Any,
) -> dict[str, Any]:
    """Expose the bounded recovery appropriate to an incomplete relation read.

    A truncated actor overlay and an incomplete incoming-relationship index are
    different coverage gaps.  Neither can be repaired by advancing the offset
    over the returned lower bound.  The former can be read through the scoped
    assertion surface; the latter must be restarted with an exact represented
    predicate so the canonical predicate lookup can be used.  Keeping those
    recoveries typed prevents a plausible-looking partial neighbourhood from
    being mistaken for evidence that no existing related concept exists.
    """

    result = dict(payload)
    if not bool(result.get("total_hits_is_lower_bound")):
        return result
    diagnostics = result.get("relation_query_diagnostics")
    actor_overlay_truncated = bool(
        isinstance(diagnostics, Mapping)
        and (
            diagnostics.get("scoped_concept_query_truncated")
            or diagnostics.get("actor_effective_text_query_truncated")
        )
    )
    incoming_diagnostics = (
        diagnostics.get("incoming_asserted_binary")
        if isinstance(diagnostics, Mapping)
        else None
    )
    incoming_coverage_incomplete = bool(
        isinstance(incoming_diagnostics, Mapping)
        and incoming_diagnostics.get("requested") is not False
        and incoming_diagnostics.get("complete") is False
    )
    if not actor_overlay_truncated and not incoming_coverage_incomplete:
        return result

    paging = dict(result.get("paging") or {})
    paging.update(
        {
            "continuation_supported": False,
            "next_offset": None,
            "offset_semantics": (
                "bounded_actor_overlay_snapshot"
                if actor_overlay_truncated
                else "bounded_incoming_relation_snapshot"
            ),
        }
    )
    result["paging"] = paging

    if not actor_overlay_truncated:
        preserved_arguments: dict[str, Any] = {
            "concept_id": concept_id,
            "offset": 0,
        }
        relation_kind_token = str(relation_kind or "").strip().lower()
        if relation_kind_token:
            preserved_arguments["relation_kind"] = relation_kind_token
        result["continuation"] = {
            "status": "bounded_incoming_relation_coverage_incomplete",
            "can_continue_with_offset": False,
            "reason": (
                "Incoming asserted-relationship coverage was incomplete. A "
                "later offset would page only the observed lower bound and "
                "cannot establish that no existing related concept exists."
            ),
            "recovery_options": [
                {
                    "action": "narrow_and_restart",
                    "tool": "find_relations_with_argument",
                    "restart_offset": 0,
                    "preserve_arguments": preserved_arguments,
                    "required_argument": "predicate_filter",
                    "required_value_kind": "exact_represented_predicate_ids",
                    "reason": (
                        "An exact predicate permits a bounded canonical "
                        "incoming-relationship lookup."
                    ),
                }
            ],
        }
        return result

    scoped_arguments: dict[str, Any] = {
        "argument_concept_id": concept_id,
        "limit": 200,
        "offset": 0,
    }
    if isinstance(predicate_filter, list) and predicate_filter:
        scoped_arguments["predicates"] = predicate_filter
    relation_kind_token = str(relation_kind or "").strip().lower()
    if relation_kind_token == "text":
        scoped_arguments["object_kind"] = "text"
    elif relation_kind_token == "binary":
        scoped_arguments["object_kind"] = "concept"

    result["continuation"] = {
        "status": "bounded_overlay_incomplete",
        "can_continue_with_offset": False,
        "reason": (
            "The actor-effective overlay was capped before combined sorting "
            "and paging, so a later offset would not be a complete continuation."
        ),
        "recovery_options": [
            {
                "action": "narrow_and_restart",
                "restart_offset": 0,
                "suggested_filters": [
                    "predicate_filter",
                    "relation_kind",
                ],
            },
            {
                "tool": "list_scoped_assertions",
                "arguments": scoped_arguments,
                "scope": "scoped_overlay_only",
            },
        ],
    }
    return result


def _get_vontology_tree(**kwargs):
    from ...vontology.utils_vontology import get_vontology_tree

    return get_vontology_tree(**kwargs)


def _get_concept_publication_scope(**kwargs):
    from ...services.ontology_scope_change_service import (
        get_concept_publication_scope,
    )

    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="ontology publication scope",
        ignore_untrusted_payload_identity=True,
    )
    if denial is not None:
        return denial
    try:
        with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
            snapshot = get_concept_publication_scope(kwargs.get("concept_id"))
    except (LookupError, PermissionError):
        return make_error_response(
            "ontology_scope_target_not_found",
            "The requested ontology scope target is unavailable.",
        )
    except ValueError as exc:
        return make_error_response("invalid_ontology_scope_read", str(exc))
    return {"success": True, **snapshot}


def _resolve_publication_scope_profile(**kwargs):
    from ...services.publication_scope_profile_service import (
        PUBLICATION_SCOPE_DECISION_SCHEMA_VERSION,
        resolve_publication_scope_profile,
    )

    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="publication scope profile resolution",
        ignore_untrusted_payload_identity=True,
    )
    if denial is not None:
        return {
            "schema_version": PUBLICATION_SCOPE_DECISION_SCHEMA_VERSION,
            "status": "access_denied",
            "mutation_performed": False,
            **denial,
        }
    accepted_arguments = {
        key: kwargs.get(key)
        for key in (
            "plane",
            "type_concept_ids",
            "predicate_concept_id",
            "subject_type_concept_ids",
            "object_type_concept_ids",
            "source_context",
            "source_kind",
            "lifecycle_state",
            "role_concept_ids",
            "stable_identity_present",
            "selected_scope_mode",
            "selection_reason",
            "producer",
        )
        if key in kwargs
    }
    with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
        return resolve_publication_scope_profile(**accepted_arguments)


def _scope_change_request_id(kwargs: Mapping[str, Any]) -> str:
    supplied = kwargs.get("request_id")
    if isinstance(supplied, str) and supplied.strip():
        return supplied.strip()
    from ...services.ontology_publication_authority_service import (
        current_ontology_invocation,
    )

    invocation = current_ontology_invocation()
    return (
        str(invocation.effect_id).strip()
        if invocation is not None and invocation.effect_id
        else ""
    )


def _scope_change_payload_provenance_denial(
    kwargs: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Reject payload-established identity before any scope snapshot read."""

    from ...services.ontology_publication_authority_service import (
        current_ontology_invocation,
    )
    from .gateway import get_internal_mcp_actor_context_source

    def denied(error_code: str, message: str) -> dict[str, Any]:
        return {
            "success": False,
            "effect_status": "not_started",
            "mutation_outcome": "not_started",
            "changed": False,
            "error_code": error_code,
            "error": message,
        }

    source = get_internal_mcp_actor_context_source()
    has_payload_identity_claim = any(
        isinstance(kwargs.get(field_name), str)
        and bool(str(kwargs.get(field_name)).strip())
        for field_name in (
            "actor_concept_id",
            "organisation_concept_id",
            "organization_concept_id",
            "org_id",
            "user_concept_id",
            "user_id",
        )
    )
    if source == "tool_payload_fallback" and has_payload_identity_claim:
        return denied(
            "client_supplied_identity_is_not_authority",
            "Client or model supplied identity cannot authorise publication.",
        )
    if source == "trusted_operator_payload_fallback":
        return denied(
            "von_operator_is_not_semantic_ontology_authority",
            "Von operational authority does not confer semantic ontology authority.",
        )
    invocation = current_ontology_invocation()
    if (
        invocation is not None
        and invocation.executing_agent_concept_id
        and not invocation.delegation_id
    ):
        return denied(
            "ontology_agent_delegation_required",
            "An executing agent needs an exact server-issued ontology delegation.",
        )
    return None


def _run_concept_publication_scope_change(
    *,
    preview: bool,
    invocation_tool_name: str,
    kwargs: Mapping[str, Any],
) -> dict[str, Any]:
    from ...services.ontology_scope_change_service import (
        OntologyScopeChangeRequestError,
        change_concept_publication_scope,
    )

    provenance_denial = _scope_change_payload_provenance_denial(kwargs)
    if provenance_denial is not None:
        return provenance_denial
    try:
        return change_concept_publication_scope(
            concept_id=kwargs.get("concept_id"),
            destination_kind=kwargs.get("destination_kind"),
            destination_concept_id=kwargs.get("destination_concept_id"),
            scope_edit=kwargs.get("scope_edit"),
            expected_scope_fingerprint=kwargs.get("expected_scope_fingerprint"),
            request_id=_scope_change_request_id(kwargs),
            preview=preview,
            reason=kwargs.get("reason"),
            invocation_tool_name=invocation_tool_name,
        )
    except (LookupError, PermissionError):
        return make_error_response(
            "ontology_scope_target_not_found",
            "The requested ontology scope target is unavailable.",
        )
    except OntologyScopeChangeRequestError as exc:
        return make_error_response(exc.reason_code, exc.public_message)
    except ValueError as exc:
        return make_error_response("invalid_ontology_scope_change", str(exc))
    except RuntimeError:
        return make_error_response(
            "ontology_authority_store_unavailable",
            "Ontology authority verification or durable receipts are unavailable.",
        )


def _preview_concept_publication_scope_change(**kwargs):
    return _run_concept_publication_scope_change(
        preview=True,
        invocation_tool_name="preview_concept_publication_scope_change",
        kwargs=kwargs,
    )


def _change_concept_publication_scope(**kwargs):
    return _run_concept_publication_scope_change(
        preview=False,
        invocation_tool_name="change_concept_publication_scope",
        kwargs=kwargs,
    )


