def _get_paper_metadata(**kwargs):
    from .arxiv_proxy_mcp import get_arxiv_proxy, ArxivProxyError
    from ...services.arxiv_metadata_service import (
        ArxivMetadataError,
        fetch_arxiv_metadata,
    )

    arxiv_id = kwargs.get("arxiv_id")
    if not arxiv_id:
        return make_error_response(
            "missing_parameter",
            "Missing required parameter: arxiv_id",
            details={"missing": ["arxiv_id"]},
            suggestions=[
                "Provide the arXiv ID (e.g., '2301.12345' or 'arxiv:2301.12345')"
            ],
        )

    async def _async_metadata():
        proxy_error: str | None = None
        try:
            proxy = await get_arxiv_proxy()
            get_metadata = getattr(proxy, "get_paper_metadata", None)
            if callable(get_metadata):
                proxy_result = get_metadata(arxiv_id=arxiv_id)
                if inspect.isawaitable(proxy_result):
                    proxy_result = await proxy_result
                if isinstance(proxy_result, Mapping):
                    if proxy_result.get("success") is False:
                        proxy_error = str(
                            proxy_result.get("error")
                            or proxy_result.get("message")
                            or "arxiv_proxy_metadata_failed"
                        )
                    else:
                        proxy_metadata_record, proxy_metadata_error = (
                            _coerce_arxiv_metadata_record(proxy_result)
                        )
                        if proxy_metadata_record is not None:
                            return proxy_result
                        proxy_error = (
                            proxy_metadata_error or "arxiv_proxy_metadata_unusable"
                        )
                else:
                    proxy_error = (
                        f"arxiv_proxy_metadata_unusable:{type(proxy_result).__name__}"
                    )
            else:
                proxy_error = "arxiv_proxy_metadata_unsupported"
        except ArxivProxyError as e:
            proxy_error = str(e)
        except Exception as e:
            proxy_error = f"{type(e).__name__}:{e}"

        try:
            metadata = fetch_arxiv_metadata(arxiv_id=arxiv_id)
            payload = dict(metadata)
            payload["success"] = True
            if proxy_error:
                payload["metadata_fallback_reason"] = proxy_error
            return payload
        except ArxivMetadataError as e:
            return make_error_response(
                "arxiv_metadata_unavailable",
                str(e),
                details={
                    "arxiv_id": arxiv_id,
                    "exception_type": "ArxivMetadataError",
                    "proxy_error": proxy_error,
                },
            )

    return _run_async_compat(_async_metadata)


def _coerce_arxiv_metadata_record(
    metadata_payload: Any,
) -> tuple[dict[str, Any] | None, str | None]:
    """Normalise arXiv metadata payloads to a single mapping shape."""

    if not isinstance(metadata_payload, Mapping):
        return None, f"unexpected_metadata_response:{type(metadata_payload).__name__}"

    if metadata_payload.get("success") is False:
        return None, str(
            metadata_payload.get("error")
            or metadata_payload.get("message")
            or "metadata_fetch_failed"
        )

    paper_payload = metadata_payload.get("paper")
    if isinstance(paper_payload, Mapping):
        return dict(paper_payload), None

    result_payload = metadata_payload.get("result")
    if isinstance(result_payload, Mapping):
        return dict(result_payload), None

    if any(
        key in metadata_payload
        for key in ("title", "summary", "abstract", "authors", "categories", "id")
    ):
        return dict(metadata_payload), None

    return None, "metadata_payload_unusable"


def _materialise_arxiv_file_copy_representation(
    *,
    user_concept_id: str,
    arxiv_id: str,
    file_copy_concept_id: str,
    fallback_title: str | None = None,
    namespace: str | None = None,
    metadata: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Attempt deterministic scholarly representation materialisation for an arXiv file copy."""

    try:
        from ...services.arxiv_paper_link_service import (
            materialise_scholarly_representation_for_arxiv_file_copy,
            materialise_scholarly_representation_for_file_copy,
        )

        metadata_record: dict[str, Any] | None = (
            dict(metadata) if isinstance(metadata, Mapping) else None
        )
        metadata_error: str | None = None
        if not isinstance(metadata_record, Mapping):
            metadata_payload = _get_paper_metadata(arxiv_id=arxiv_id)
            metadata_record, metadata_error = _coerce_arxiv_metadata_record(
                metadata_payload
            )

        if isinstance(metadata_record, Mapping):
            with _with_namespace_actor_override(namespace):
                arxiv_report = materialise_scholarly_representation_for_arxiv_file_copy(
                    user_concept_id=user_concept_id,
                    arxiv_id=arxiv_id,
                    file_copy_concept_id=file_copy_concept_id,
                    metadata=dict(metadata_record),
                    logger=logger,
                )
            if isinstance(arxiv_report, Mapping):
                materialised = dict(arxiv_report)
            else:
                materialised = {
                    "success": False,
                    "verified": False,
                    "reason": "unexpected_arxiv_materialisation_response",
                    "response_type": type(arxiv_report).__name__,
                }
            materialised["attempted"] = True
            materialised["metadata_source"] = (
                str(metadata_record.get("metadata_source") or "").strip()
                or "get_paper_metadata"
            )
            materialised["metadata_available"] = True
            if metadata_error:
                materialised["metadata_error"] = metadata_error
            if bool(materialised.get("verified")):
                return materialised

        generic_metadata: dict[str, Any] = {}
        if isinstance(metadata_record, Mapping):
            generic_metadata.update(dict(metadata_record))
        if (
            isinstance(fallback_title, str)
            and fallback_title.strip()
            and "title" not in generic_metadata
        ):
            generic_metadata["title"] = fallback_title.strip()

        with _with_namespace_actor_override(namespace):
            fallback_report = materialise_scholarly_representation_for_file_copy(
                user_concept_id=user_concept_id,
                file_copy_concept_id=file_copy_concept_id,
                metadata=generic_metadata or None,
                logger=logger,
            )
        if isinstance(fallback_report, Mapping):
            materialised = dict(fallback_report)
        else:
            materialised = {
                "success": False,
                "verified": False,
                "reason": "unexpected_generic_materialisation_response",
                "response_type": type(fallback_report).__name__,
            }

        materialised["attempted"] = True
        materialised["arxiv_id"] = arxiv_id
        materialised["fallback_mode"] = "from_arxiv_path"
        materialised["metadata_source"] = (
            str(generic_metadata.get("metadata_source") or "").strip()
            or "get_paper_metadata"
        )
        materialised["metadata_available"] = bool(generic_metadata)
        if metadata_error:
            materialised["metadata_error"] = metadata_error
        return materialised
    except Exception as exc:
        return {
            "attempted": True,
            "success": False,
            "verified": False,
            "arxiv_id": arxiv_id,
            "reason": "scholarly_representation_materialisation_exception",
            "error": str(exc),
        }


def _get_arxiv_cache_root() -> "Path":
    from .arxiv_proxy_mcp import resolve_arxiv_cache_root

    return resolve_arxiv_cache_root()


def _inspect_arxiv_cache(arxiv_id: str) -> dict[str, Any]:
    from .arxiv_proxy_mcp import inspect_cached_arxiv_artifacts

    cache_root = _get_arxiv_cache_root()
    try:
        diagnostics = inspect_cached_arxiv_artifacts(
            arxiv_id=str(arxiv_id),
            storage_path=cache_root,
        )
    except Exception as exc:  # pragma: no cover - defensive diagnostics only
        return {
            "schema_version": "arxiv_cache_state.v1",
            "arxiv_id": str(arxiv_id),
            "cache_root": str(cache_root),
            "cache_root_exists": cache_root.exists(),
            "cache_state": "inspection_failed",
            "has_cached_pdf": False,
            "cached_pdf_path": None,
            "has_cached_markdown": False,
            "cached_markdown_path": None,
            "partial_cache_without_pdf": False,
            "inspection_error": str(exc),
        }
    return dict(diagnostics)


def _recommended_arxiv_cache_recovery_action(
    cache_diagnostics: Mapping[str, Any] | None,
) -> str:
    cache_state = str((cache_diagnostics or {}).get("cache_state") or "").strip()
    if cache_state == "cached_pdf_available":
        return "finalise_cached_pdf"
    if cache_state == "markdown_only_partial_cache":
        return "reacquire_pdf_from_source"
    return "download_from_source"


def _best_effort_delete_cached_file(
    *,
    cache_root: "Path",
    file_path: "Path | str | None",
) -> tuple[bool, str | None]:
    from pathlib import Path

    if file_path is None:
        return False, None

    candidate = Path(str(file_path))
    try:
        resolved_cache = cache_root.resolve()
        resolved_file = candidate.resolve()
        if resolved_cache in resolved_file.parents and resolved_file.is_file():
            resolved_file.unlink()
            return True, None
    except Exception as exc:  # pragma: no cover - best effort cleanup
        return False, str(exc)
    return False, None


def _rehydrate_cached_arxiv_pdf_from_durable_blob(
    *,
    arxiv_id: str,
    preferred_filename: str | None = None,
) -> dict[str, Any] | None:
    import hashlib

    from src.backend.services.blob_store import get_blob_store_from_env

    from .arxiv_proxy_mcp import (
        _arxiv_pdf_blob_key,
        _build_blob_uri,
        _extract_arxiv_version,
        _infer_blob_backend,
        _normalise_arxiv_id,
    )

    stable_id = _normalise_arxiv_id(str(arxiv_id))
    storage_key = _arxiv_pdf_blob_key(stable_id)

    try:
        blob_store = get_blob_store_from_env()
        if not blob_store.exists(storage_key):
            return None
        payload = blob_store.get_bytes(storage_key)
    except Exception:
        return None

    if not isinstance(payload, (bytes, bytearray)) or not bytes(payload):
        return None

    cache_root = _get_arxiv_cache_root()
    cache_root.mkdir(parents=True, exist_ok=True)
    filename = (
        preferred_filename.strip()
        if isinstance(preferred_filename, str) and preferred_filename.strip()
        else f"{stable_id.replace('/', '_')}.pdf"
    )
    if not filename.lower().endswith(".pdf"):
        filename = f"{filename}.pdf"
    cached_path = cache_root / Path(filename).name
    data = bytes(payload)
    cached_path.write_bytes(data)

    backend = _infer_blob_backend(blob_store)
    return {
        "success": True,
        "arxiv_id": stable_id,
        "file_path": str(cached_path),
        "size_bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "version": _extract_arxiv_version(stable_id),
        "storage": {
            "backend": backend,
            "key": storage_key,
            "uri": _build_blob_uri(blob_store, backend=backend, key=storage_key),
        },
        "acquisition_path": "rehydrate_from_durable_blob",
        "durable_blob_rehydrated": True,
    }


def _register_arxiv_file_copy_instance(
    *,
    namespace: str | None,
    user_concept_id: str,
    arxiv_id: str,
    type_concept_id: str,
    name: str,
    sha256: str,
    size_bytes: int,
    content_type: str,
    blob_backend: str,
    blob_key: str,
    blob_uri: str,
    original_path: str,
    extra_metadata: Mapping[str, Any] | None = None,
):
    from ...services.computer_file_copy_service import (
        create_computer_file_copy_instance,
    )
    from ...services.namespace_service import derive_actor_context_from_namespace

    metadata: dict[str, Any] = {
        "source": "arxiv",
        "arxiv_id": str(arxiv_id),
        "original_path": str(original_path),
    }
    if isinstance(extra_metadata, Mapping):
        metadata.update(
            {
                str(key): value
                for key, value in extra_metadata.items()
                if isinstance(key, str)
            }
        )

    _namespace_user_concept_id, namespace_organisation_concept_id = (
        derive_actor_context_from_namespace(namespace)
    )

    with _with_namespace_actor_override(namespace):
        return create_computer_file_copy_instance(
            type_concept_id=type_concept_id,
            user_concept_id=str(user_concept_id),
            organisation_concept_id=namespace_organisation_concept_id,
            namespace=namespace,
            namespace_source="request.namespace" if namespace else None,
            name=str(name),
            sha256=str(sha256),
            size_bytes=int(size_bytes),
            content_type=str(content_type),
            blob_backend=str(blob_backend),
            blob_key=str(blob_key),
            blob_uri=str(blob_uri),
            metadata=metadata,
        )


def _ensure_arxiv_file_copy_registration(
    *,
    namespace: str | None,
    user_concept_id: str,
    arxiv_id: str,
    type_concept_id: str,
    name: str,
    sha256: str,
    size_bytes: int,
    content_type: str,
    blob_backend: str,
    blob_key: str,
    blob_uri: str,
    original_path: str,
    extra_metadata: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    from ...services.computer_file_copy_service import (
        find_existing_computer_file_copy_instance,
    )

    existing = find_existing_computer_file_copy_instance(
        user_concept_id=str(user_concept_id),
        blob_key=str(blob_key),
        type_concept_id=str(type_concept_id),
        sha256=str(sha256),
    )
    if existing is not None:
        return {
            "record": existing,
            "registration": {
                "attempted": True,
                "succeeded": True,
                "status": "reused_existing",
                "computer_file_copy_concept_id": existing.concept_id,
                "reused_existing": True,
            },
        }

    record = _register_arxiv_file_copy_instance(
        namespace=namespace,
        user_concept_id=user_concept_id,
        arxiv_id=arxiv_id,
        type_concept_id=type_concept_id,
        name=name,
        sha256=sha256,
        size_bytes=size_bytes,
        content_type=content_type,
        blob_backend=blob_backend,
        blob_key=blob_key,
        blob_uri=blob_uri,
        original_path=original_path,
        extra_metadata=extra_metadata,
    )
    return {
        "record": record,
        "registration": {
            "attempted": True,
            "succeeded": True,
            "status": "registered",
            "computer_file_copy_concept_id": record.concept_id,
        },
    }


def _coerce_scholarly_materialisation_metadata(
    kwargs: Mapping[str, Any],
) -> dict[str, Any]:
    from ...services.arxiv_paper_link_service import (
        extract_scholarly_author_names,
        extract_scholarly_metadata_publication_date,
        extract_scholarly_metadata_summary,
        extract_scholarly_metadata_title,
        extract_scholarly_topic_labels,
    )

    metadata: dict[str, Any] = {}
    for key in ("metadata", "paper_metadata", "scholarly_metadata"):
        raw = kwargs.get(key)
        if isinstance(raw, Mapping):
            metadata.update(dict(raw))

    title = kwargs.get("title")
    if isinstance(title, str) and title.strip():
        metadata["title"] = title.strip()
    elif "title" not in metadata:
        derived_title = extract_scholarly_metadata_title(metadata)
        if derived_title:
            metadata["title"] = derived_title

    summary = kwargs.get("summary") or kwargs.get("abstract")
    if isinstance(summary, str) and summary.strip():
        metadata["summary"] = summary.strip()
    elif "summary" not in metadata and "abstract" not in metadata:
        derived_summary = extract_scholarly_metadata_summary(metadata)
        if derived_summary:
            metadata["summary"] = derived_summary

    publication_date = kwargs.get("publication_date")
    if isinstance(publication_date, str) and publication_date.strip():
        metadata["publication_date"] = publication_date.strip()
    elif "publication_date" not in metadata and "published" not in metadata:
        derived_publication_date = extract_scholarly_metadata_publication_date(metadata)
        if derived_publication_date:
            metadata["publication_date"] = derived_publication_date

    author_names = kwargs.get("author_names") or kwargs.get("authors")
    if isinstance(author_names, Sequence) and not isinstance(
        author_names, (str, bytes, bytearray)
    ):
        cleaned_authors = [
            str(item).strip()
            for item in author_names
            if isinstance(item, str) and item.strip()
        ]
        if cleaned_authors:
            metadata["authors"] = cleaned_authors
    elif "authors" not in metadata:
        derived_authors = extract_scholarly_author_names(metadata)
        if derived_authors:
            metadata["authors"] = derived_authors

    topic_labels = kwargs.get("topic_labels") or kwargs.get("categories")
    if isinstance(topic_labels, Sequence) and not isinstance(
        topic_labels, (str, bytes, bytearray)
    ):
        cleaned_topics = [
            str(item).strip()
            for item in topic_labels
            if isinstance(item, str) and item.strip()
        ]
        if cleaned_topics:
            metadata["categories"] = cleaned_topics
    elif "categories" not in metadata:
        derived_topics = extract_scholarly_topic_labels(metadata)
        if derived_topics:
            metadata["categories"] = derived_topics

    return metadata


_CREATE_CONCEPTS_SCOPE_DEFAULT = "user_org_default"
_CREATE_CONCEPTS_SCOPE_USER_ONLY = "user_only_default"
_CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL = "organisation_general"
_CREATE_CONCEPTS_SCOPE_GLOBAL_GENERAL = "global_general"
_CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY = "canonical_id_only"
_CREATE_CONCEPTS_PER_ITEM_IDENTITY_REVIEW_FIELDS = (
    "identity_candidate_concept_ids",
    "identity_rejected_candidate_concept_ids",
)
_CREATE_CONCEPTS_SCOPE_MODE_ALIASES: dict[str, str] = {
    "default": _CREATE_CONCEPTS_SCOPE_DEFAULT,
    "user_org_default": _CREATE_CONCEPTS_SCOPE_DEFAULT,
    "user_org": _CREATE_CONCEPTS_SCOPE_DEFAULT,
    "private": _CREATE_CONCEPTS_SCOPE_USER_ONLY,
    "user_only": _CREATE_CONCEPTS_SCOPE_USER_ONLY,
    "user_only_default": _CREATE_CONCEPTS_SCOPE_USER_ONLY,
    "organisation_general": _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL,
    "organization_general": _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL,
    "organisation": _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL,
    "organization": _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL,
    "org_general": _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL,
    "global_general": _CREATE_CONCEPTS_SCOPE_GLOBAL_GENERAL,
    "global": _CREATE_CONCEPTS_SCOPE_GLOBAL_GENERAL,
    "public": _CREATE_CONCEPTS_SCOPE_GLOBAL_GENERAL,
}


def _create_concepts_input_placement_error(
    arguments: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Reject deterministic create-input errors before canonical lookups."""

    misplaced_fields = [
        field_name
        for field_name in _CREATE_CONCEPTS_PER_ITEM_IDENTITY_REVIEW_FIELDS
        if field_name in arguments
    ]
    if misplaced_fields:
        payload = make_error_response(
            "complex_create_requires_typed_effects",
            (
                "This governed create path supports one exact core concept only. "
                f"Rejected fields: {', '.join(misplaced_fields)}. No mutation was "
                "started, and no automatic recovery is available for this request "
                "shape."
            ),
            details={"rejected_fields": misplaced_fields},
        )
        payload.update(
            {
                "effect_status": "not_started",
                "mutation_outcome": "not_started",
                "changed": False,
            }
        )
        return payload

    duplicate_resolution_mode = arguments.get("duplicate_resolution_mode")
    if (
        duplicate_resolution_mode is not None
        and duplicate_resolution_mode
        != _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY
    ):
        return make_error_response(
            "invalid_parameter",
            (
                "Invalid duplicate_resolution_mode "
                f"'{duplicate_resolution_mode}'."
            ),
            details={
                "duplicate_resolution_mode": duplicate_resolution_mode,
                "supported_duplicate_resolution_modes": [
                    _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY
                ],
                "default_behaviour": (
                    "canonical identity then semantic name resolution"
                ),
            },
            suggestions=[
                (
                    "Omit duplicate_resolution_mode to preserve semantic "
                    "duplicate resolution"
                ),
                (
                    "Use duplicate_resolution_mode='canonical_id_only' only "
                    "for deterministic stable identities"
                ),
            ],
        )
    collision_resolution_mode = arguments.get("collision_resolution_mode")
    if (
        collision_resolution_mode is not None
        and collision_resolution_mode != ACTOR_SCOPED_REFERENT_COLLISION_MODE
    ):
        return make_error_response(
            "invalid_parameter",
            (
                "Invalid collision_resolution_mode "
                f"'{collision_resolution_mode}'."
            ),
            details={
                "collision_resolution_mode": collision_resolution_mode,
                "supported_collision_resolution_modes": [
                    ACTOR_SCOPED_REFERENT_COLLISION_MODE
                ],
            },
            suggestions=[
                (
                    "Use only the exact arguments from a "
                    f"{ACTOR_SCOPED_REFERENT_RECOVERY_ACTION} affordance"
                )
            ],
        )
    if collision_resolution_mode == ACTOR_SCOPED_REFERENT_COLLISION_MODE and not (
        isinstance(arguments.get("requested_concept_id"), str)
        and str(arguments.get("requested_concept_id")).strip()
    ):
        return make_error_response(
            "invalid_parameter",
            "Actor-scoped referent recovery requires requested_concept_id.",
            details={"missing": ["requested_concept_id"]},
            suggestions=[
                (
                    "Execute the complete arguments from the original "
                    f"{ACTOR_SCOPED_REFERENT_RECOVERY_ACTION} affordance"
                )
            ],
        )
    return None


def _normalise_create_concepts_scope_mode(raw_value: Any) -> str | None:
    if not isinstance(raw_value, str):
        return None
    cleaned = raw_value.strip().lower().replace("-", "_")
    if not cleaned:
        return None
    return _CREATE_CONCEPTS_SCOPE_MODE_ALIASES.get(cleaned)


def _resolve_create_concepts_scope_mode(
    arguments: Mapping[str, Any],
) -> tuple[str, str, dict[str, Any] | None]:
    """Resolve supported scope aliases without silently changing audience."""

    supplied: list[tuple[str, Any, str]] = []
    for field_name in (
        "scope_mode",
        "visibility_scope_mode",
        "publication_scope",
    ):
        raw_value = arguments.get(field_name)
        if raw_value is None:
            continue
        normalised_value = _normalise_create_concepts_scope_mode(raw_value)
        if normalised_value is None:
            payload = make_error_response(
                "invalid_parameter",
                f"Invalid {field_name} '{raw_value}'.",
                details={
                    "field": field_name,
                    "value": raw_value,
                    "supported_scope_modes": sorted(
                        _CREATE_CONCEPTS_SCOPE_MODE_ALIASES
                    ),
                },
                suggestions=[
                    "Use user_only_default for actor-private concepts",
                    (
                        "Use organisation or organisation_general for "
                        "organisation-scoped shared concepts"
                    ),
                    "Use global_general for broadly visible concepts",
                ],
            )
            payload.update(
                {
                    "effect_status": "not_started",
                    "mutation_outcome": "not_started",
                    "changed": False,
                }
            )
            return (
                _CREATE_CONCEPTS_SCOPE_USER_ONLY,
                f"request.{field_name}",
                payload,
            )
        supplied.append((field_name, raw_value, normalised_value))

    if not supplied:
        return (
            _CREATE_CONCEPTS_SCOPE_USER_ONLY,
            "default.user_only_default",
            None,
        )

    distinct_modes = {normalised_value for _, _, normalised_value in supplied}
    if len(distinct_modes) > 1:
        payload = make_error_response(
            "conflicting_scope_mode_fields",
            (
                "Conflicting publication-scope fields were supplied; "
                "no mutation started."
            ),
            details={
                "supplied_scope_fields": {
                    field_name: raw_value for field_name, raw_value, _ in supplied
                },
                "normalised_scope_modes": sorted(distinct_modes),
            },
            suggestions=[
                (
                    "Supply exactly one of scope_mode, visibility_scope_mode, "
                    "or publication_scope"
                )
            ],
        )
        payload.update(
            {
                "effect_status": "not_started",
                "mutation_outcome": "not_started",
                "changed": False,
            }
        )
        return _CREATE_CONCEPTS_SCOPE_USER_ONLY, "conflict", payload

    field_name, _, scope_mode = supplied[0]
    return scope_mode, f"request.{field_name}", None


@_governed_ontology_mutation("create_concepts")
def _create_concepts(**kwargs):
    from .transport import (
        InternalMCPHandlerCancelled,
        raise_if_internal_mcp_cancelled,
    )

    # A handler may sit in the bounded executor queue until after its caller's
    # deadline. Never begin a write-side preflight in that state.
    raise_if_internal_mcp_cancelled()

    input_error = _create_concepts_input_placement_error(kwargs)
    if input_error is not None:
        return input_error

    from ...vontology.utils_vontology import create_vontology_concept
    from ...vontology.code_concepts_registry import PREDICATE_TYPE_ID
    from ...services.create_concepts_duplicate_guard_service import (
        CreateConceptDuplicateGuardBlock,
        build_canonical_identity_conflict_create_concepts_result,
        build_duplicate_guard_block_create_concepts_result,
        build_duplicate_prevented_create_concepts_result,
        find_existing_concept_for_create_concepts,
    )
    from ...services.concept_external_identity_service import (
        ExternalIdentityInputError,
        canonical_concept_id_for_external_identifiers,
        normalise_create_external_identifiers,
        persist_external_identity_markers,
    )
    from ...services.create_concepts_parent_resolution_service import (
        resolve_parent_for_create_concepts,
    )
    from ...services.relationship_extent_index_service import (
        defer_relationship_extent_index_sync,
    )
    from ...security.access_control import (
        override_current_organisation,
        override_current_user,
    )

    parent_id: str | None = kwargs.get("parent_id")
    concepts = kwargs.get("concepts", [])
    raw_namespace = kwargs.get("namespace")
    namespace = (
        raw_namespace.strip()
        if isinstance(raw_namespace, str) and raw_namespace.strip()
        else None
    )
    allow_duplicate_instances_raw = kwargs.get("allow_duplicate_instances", False)
    allow_duplicate_instances = (
        allow_duplicate_instances_raw
        if isinstance(allow_duplicate_instances_raw, bool)
        else str(allow_duplicate_instances_raw).strip().lower()
        in {"1", "true", "yes", "on"}
    )
    raw_duplicate_resolution_mode = kwargs.get("duplicate_resolution_mode")
    canonical_id_only = False
    if raw_duplicate_resolution_mode is not None:
        canonical_id_only = (
            isinstance(raw_duplicate_resolution_mode, str)
            and raw_duplicate_resolution_mode
            == _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY
        )
        if not canonical_id_only:
            return make_error_response(
                "invalid_parameter",
                (
                    "Invalid duplicate_resolution_mode "
                    f"'{raw_duplicate_resolution_mode}'."
                ),
                details={
                    "duplicate_resolution_mode": raw_duplicate_resolution_mode,
                    "supported_duplicate_resolution_modes": [
                        _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY
                    ],
                    "default_behaviour": "canonical identity then semantic name resolution",
                },
                suggestions=[
                    "Omit duplicate_resolution_mode to preserve semantic duplicate resolution",
                    (
                        "Use duplicate_resolution_mode='canonical_id_only' only "
                        "for deterministic stable identities"
                    ),
                ],
            )
    scope_mode, scope_mode_source, scope_mode_error = (
        _resolve_create_concepts_scope_mode(kwargs)
    )
    if scope_mode_error is not None:
        return scope_mode_error

    from ...services.workflow_event_integration_service import (
        resolve_event_actor_context,
    )

    actor_user_id, actor_org_id = resolve_event_actor_context(
        user_id=kwargs.get("created_by_concept_id"),
        org_id=kwargs.get("organisation_concept_id") or kwargs.get("org_id"),
        namespace=namespace,
    )

    if scope_mode == _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL and not actor_org_id:
        return make_error_response(
            "missing_organisation_context",
            "organisation_general scope requires an organisation context.",
            details={
                "scope_mode": scope_mode,
                "namespace": namespace,
                "created_by_concept_id": actor_user_id,
                "organisation_concept_id": actor_org_id,
            },
            suggestions=[
                "Provide namespace in #V#user@org form",
                "Or include organisation_concept_id in the tool payload",
                "Or use scope_mode='user_only_default' or 'global_general'",
            ],
        )

    if not parent_id:
        return make_error_response(
            "missing_parameter",
            "Missing required parameter: parent_id",
            details={"missing": ["parent_id"]},
            suggestions=[
                "Provide a parent type concept ID, e.g., parent_id='#V#person' or '#V#physical_object'"
            ],
        )

    # Block #V#thing as parent type (JVNAUTOSCI-1072).
    # #V#thing is the universal top type - everything is implicitly a thing.
    # Explicit relationships to it provide no semantic value.
    BLOCKED_PARENT_TYPES = {"#V#thing"}
    if parent_id in BLOCKED_PARENT_TYPES:
        # Analyse what's being created to give better guidance
        concept_names = [c.get("name", "") for c in concepts if isinstance(c, dict)]
        creating_multiple = len(concepts) > 1
        kind_requested = "unspecified"
        if concepts and isinstance(concepts[0], dict):
            raw_kind_requested = concepts[0].get("kind")
            if isinstance(raw_kind_requested, str) and raw_kind_requested.strip():
                kind_requested = raw_kind_requested.strip().lower()

        # Build contextual suggestions
        suggestions = [
            "1. FIRST look for an existing parent type that is a semantically close "
            "generalisation of what you're creating by querying search_concepts with a "
            "domain/category-specific query.",
        ]

        if creating_multiple or kind_requested == "instance":
            suggestions.append(
                "2. If no suitable parent exists, CREATE A NEW PARENT TYPE FIRST as a subtype of an "
                "appropriate root parent (for example #V#event for things that happen in time, "
                "#V#physical_object for tangible items, #V#abstract_object for ideas/concepts, "
                "#V#information_object for documents/recordings). "
                "The new parent should be a semantically close generalisation of the child."
            )
            suggestions.append(
                "3. Then create your instances as instances of that specific type, not the broad category"
            )
            suggestions.append(
                "Example: For Otter recordings, first create type '#V#otter_recording_session' "
                "as subtype of #V#event, then create instances of #V#otter_recording_session"
            )
        else:
            suggestions.append(
                "2. Consider semantically close parent types: #V#physical_object, #V#abstract_object, "
                "#V#event, #V#process, #V#information_object, #V#living_organism. "
                "If none fits, create one that does."
            )

        return make_error_response(
            "blocked_parent_type",
            f"Cannot use '{parent_id}' as parent type. Every concept needs a semantically close parent. "
            "If no parent exists, create a specific parent type first. "
            "Using the universal top type is not allowed.",
            details={
                "blocked_parent_id": parent_id,
                "concepts_count": len(concepts),
                "kind_requested": kind_requested,
                "sample_names": concept_names[:3] if concept_names else [],
            },
            suggestions=suggestions,
        )

    parent_resolution = resolve_parent_for_create_concepts(parent_id)
    # Parent resolution can involve bounded fallback reads. Honour a transport
    # timeout before progressing to any item-level work.
    raise_if_internal_mcp_cancelled()
    if not parent_resolution.success:
        canonical_parent = parent_resolution.canonical_parent_id
        related_ids = [
            cid
            for cid in [
                canonical_parent,
                *parent_resolution.fallback_candidates_checked,
            ]
            if cid
        ]
        suggestions = [
            "Create the parent concept first",
            "Search for similar concepts using search_concepts",
        ]
        if parent_resolution.fallback_candidates_checked:
            suggestions.append(
                "For workflow concepts, prefer an existing workflow supertype "
                f"({', '.join(parent_resolution.fallback_candidates_checked)})"
            )
        return make_error_response(
            "parent_not_found",
            f"Parent concept '{canonical_parent}' not found. Create it first or check the ID.",
            details={
                "canonical_parent_id": canonical_parent,
                "original_parent_id": parent_id,
                "fallback_candidates_checked": list(
                    parent_resolution.fallback_candidates_checked
                ),
            },
            suggestions=suggestions,
            related_concept_ids=related_ids,
        )
    assert parent_resolution.resolved_parent_id is not None
    validated_parent_id: str = parent_resolution.resolved_parent_id
    authority_resolved_parent_id = kwargs.get("authority_resolved_parent_id")
    if (
        isinstance(authority_resolved_parent_id, str)
        and authority_resolved_parent_id.strip()
        and validated_parent_id != authority_resolved_parent_id.strip()
    ):
        return make_error_response(
            "create_parent_precondition_changed",
            (
                "The canonical parent changed after the create effect was "
                "authorised. No concepts were created."
            ),
            details={
                "authorised_parent_id": authority_resolved_parent_id.strip(),
                "current_parent_id": validated_parent_id,
            },
        )
    if not concepts or not isinstance(concepts, list):
        return make_error_response(
            "missing_parameter",
            "Missing or invalid 'concepts' array",
            details={"missing": ["concepts"]},
            suggestions=[
                "Provide an array of concept objects, e.g., concepts=[{name: 'MyType'}]"
            ],
        )
    requested_non_predicate_kinds = {
        (
            str(concept_data.get("kind") or "unspecified").strip().lower()
            if isinstance(concept_data, dict)
            else "invalid"
        )
        for concept_data in concepts
        if not (
            isinstance(concept_data, dict)
            and str(concept_data.get("kind") or "unspecified").strip().lower()
            == "predicate"
        )
    }
    if (
        parent_resolution.resolved_parent_kind is not None
        and parent_resolution.resolved_parent_kind != "type"
        and requested_non_predicate_kinds
    ):
        return make_error_response(
            "parent_is_not_a_type",
            (
                f"Parent concept '{validated_parent_id}' is "
                f"{parent_resolution.resolved_parent_kind!r}, not a semantic "
                "type. No concepts were created."
            ),
            details={
                "original_parent_id": parent_id,
                "resolved_parent_id": validated_parent_id,
                "resolved_parent_kind": parent_resolution.resolved_parent_kind,
                "requested_child_kinds": sorted(requested_non_predicate_kinds),
            },
            suggestions=[
                "Choose an existing semantic type for parent_id",
                (
                    "Use scope_mode or organisation_concept_id for ownership and "
                    "visibility; do not use an organisation or owner individual "
                    "as parent_id"
                ),
                (
                    "If the intended type does not exist, create that type first "
                    "under a semantically close type parent"
                ),
            ],
            related_concept_ids=[validated_parent_id],
        )

    results = []
    cancelled_after_partial_error: str | None = None

    def _identity_persistence_outcome(
        receipt: Mapping[str, Any],
    ) -> tuple[str, bool | None, list[dict[str, Any]], list[dict[str, Any]]]:
        failures = [
            dict(item)
            for item in (receipt.get("failures") or [])
            if isinstance(item, Mapping)
        ]
        indeterminate_failures = [
            dict(item)
            for item in (receipt.get("indeterminate_failures") or [])
            if isinstance(item, Mapping)
        ]
        raw_status = str(receipt.get("effect_status") or "").strip().lower()
        if indeterminate_failures or raw_status == "indeterminate":
            effect_status = "indeterminate"
        elif raw_status in {"failed", "partial", "succeeded"}:
            effect_status = raw_status
        elif failures or receipt.get("success") is False:
            effect_status = "failed"
        else:
            effect_status = "succeeded"

        if "changed" in receipt and (
            isinstance(receipt.get("changed"), bool) or receipt.get("changed") is None
        ):
            changed = receipt.get("changed")
        else:
            writes = receipt.get("writes")
            changed = bool(
                isinstance(writes, list)
                and any(
                    isinstance(write, Mapping)
                    and (write.get("relation_created") or write.get("context_updated"))
                    for write in writes
                )
            )
        return effect_status, changed, failures, indeterminate_failures

    def _identity_candidate_ids(
        concept_data: Mapping[str, Any],
        *,
        field_name: str,
    ) -> tuple[tuple[str, ...], bool]:
        raw_values = concept_data.get(field_name)
        if raw_values is None:
            return (), False
        error_suffix = field_name.removeprefix("identity_")
        if not isinstance(raw_values, list):
            raise ExternalIdentityInputError(
                f"invalid_identity_{error_suffix}",
                f"{field_name} must be a list of actor-visible concept IDs.",
            )
        invalid_indexes = [
            index
            for index, candidate_id in enumerate(raw_values)
            if not isinstance(candidate_id, str) or not candidate_id.strip()
        ]
        if invalid_indexes:
            raise ExternalIdentityInputError(
                f"invalid_identity_{error_suffix}",
                f"{field_name} entries must be non-empty concept ID strings.",
                details={"invalid_indexes": invalid_indexes[:50]},
            )
        candidate_ids = tuple(
            dict.fromkeys(
                str(candidate_id).strip()
                for candidate_id in raw_values
                if isinstance(candidate_id, str) and candidate_id.strip()
            )
        )
        if len(candidate_ids) > 50:
            raise ExternalIdentityInputError(
                f"too_many_identity_{error_suffix}",
                f"{field_name} accepts at most 50 distinct concept IDs.",
            )
        return candidate_ids, True

    def _cancelled_after_completed_items() -> bool:
        nonlocal cancelled_after_partial_error
        try:
            raise_if_internal_mcp_cancelled()
        except InternalMCPHandlerCancelled as exc:
            if not results:
                raise
            cancelled_after_partial_error = str(exc)
            return True
        return False

    with (
        override_current_user(actor_user_id),
        override_current_organisation(actor_org_id),
        defer_relationship_extent_index_sync(),
    ):
        for concept_data in concepts:
            # This is both the batch boundary and the safe cancellation point after
            # the preceding concept's complete logical write bundle.
            if _cancelled_after_completed_items():
                break
            if not isinstance(concept_data, dict):
                results.append(
                    {"error": "Concept must be an object", "data": concept_data}
                )
                continue

            name = concept_data.get("name")
            raw_kind = concept_data.get("kind")

            if not isinstance(raw_kind, str) or not raw_kind.strip():
                results.append(
                    {
                        "success": False,
                        "effect_status": "failed",
                        "changed": False,
                        "error_code": "concept_kind_required",
                        "message": (
                            "Concept kind is required; choose 'instance', 'type', "
                            "or 'predicate'. No concept was created."
                        ),
                        "concept": None,
                        "input_name": str(name or ""),
                        "requested_name": str(name or ""),
                        "requested_kind": None,
                    }
                )
                continue

            kind = raw_kind.strip().lower()
            if kind not in {"instance", "individual", "type", "predicate"}:
                results.append(
                    {
                        "success": False,
                        "effect_status": "failed",
                        "changed": False,
                        "error_code": "invalid_concept_kind",
                        "message": (
                            f"Unsupported concept kind '{raw_kind}'; choose "
                            "'instance', 'type', or 'predicate'. No concept was created."
                        ),
                        "concept": None,
                        "input_name": str(name or ""),
                        "requested_name": str(name or ""),
                        "requested_kind": kind,
                    }
                )
                continue

            if not name:
                results.append(
                    {
                        "error": "Concept missing required 'name' field",
                        "data": concept_data,
                    }
                )
                continue

            # Map kind to create_as_instance parameter
            if kind == "individual":
                kind = "instance"

            if kind == "predicate":
                create_as_instance = True
                parent_id_for_concept = PREDICATE_TYPE_ID
            else:
                create_as_instance = kind == "instance"
                parent_id_for_concept = validated_parent_id

            try:
                external_identifiers = normalise_create_external_identifiers(
                    external_identifiers=concept_data.get("external_identifiers"),
                    concept_name=str(name),
                    kind=kind,
                )
            except ExternalIdentityInputError as exc:
                results.append(
                    {
                        "success": False,
                        "effect_status": "failed",
                        "changed": False,
                        "error_code": exc.error_code,
                        "message": str(exc),
                        "error_details": dict(exc.details),
                        "concept": None,
                        "input_name": str(name),
                        "requested_name": str(name),
                        "requested_kind": kind,
                    }
                )
                continue

            canonical_concept_id_override = None
            if external_identifiers:
                canonical_concept_id_override = (
                    canonical_concept_id_for_external_identifiers(
                        external_identifiers,
                        kind=kind,
                        parent_id=parent_id_for_concept,
                        scope_mode=scope_mode,
                        actor_user_id=actor_user_id,
                        actor_org_id=actor_org_id,
                    )
                )
                if canonical_concept_id_override is None:
                    results.append(
                        {
                            "success": False,
                            "effect_status": "failed",
                            "changed": False,
                            "error_code": "external_identity_creation_incompatible",
                            "message": (
                                "The external identity could not be mapped to a "
                                "stable concept identity for the requested concept "
                                "kind. No concept was created."
                            ),
                            "concept": None,
                            "input_name": str(name),
                            "requested_name": str(name),
                            "requested_kind": kind,
                            "requested_parent_id": parent_id_for_concept,
                            "external_identifiers": [
                                identifier.to_dict()
                                for identifier in external_identifiers
                            ],
                        }
                    )
                    continue

            try:
                (
                    identity_candidate_concept_ids,
                    identity_candidates_supplied,
                ) = _identity_candidate_ids(
                    concept_data,
                    field_name="identity_candidate_concept_ids",
                )
                (
                    identity_rejected_candidate_concept_ids,
                    identity_rejected_candidates_supplied,
                ) = _identity_candidate_ids(
                    concept_data,
                    field_name="identity_rejected_candidate_concept_ids",
                )
            except ExternalIdentityInputError as exc:
                results.append(
                    {
                        "success": False,
                        "effect_status": "failed",
                        "changed": False,
                        "error_code": exc.error_code,
                        "message": str(exc),
                        "error_details": dict(exc.details),
                        "concept": None,
                        "input_name": str(name),
                        "requested_name": str(name),
                        "requested_kind": kind,
                    }
                )
                continue

            if (
                identity_candidates_supplied or identity_rejected_candidates_supplied
            ) and not external_identifiers:
                results.append(
                    {
                        "success": False,
                        "effect_status": "failed",
                        "changed": False,
                        "error_code": (
                            "identity_candidates_require_external_identifier"
                        ),
                        "message": (
                            "Identity candidate decisions can only apply to an "
                            "explicit external identity. Include the same "
                            "external_identifiers value used in the original "
                            "create or repair attempt."
                        ),
                        "concept": None,
                        "input_name": str(name),
                        "requested_name": str(name),
                        "requested_kind": kind,
                    }
                )
                continue
            conflicting_candidate_ids = sorted(
                set(identity_candidate_concept_ids).intersection(
                    identity_rejected_candidate_concept_ids
                )
            )
            if conflicting_candidate_ids:
                results.append(
                    {
                        "success": False,
                        "effect_status": "failed",
                        "changed": False,
                        "error_code": "conflicting_identity_candidate_review",
                        "message": (
                            "The same concept cannot be both confirmed and "
                            "rejected for one external identity."
                        ),
                        "error_details": {
                            "conflicting_candidate_concept_ids": (
                                conflicting_candidate_ids
                            )
                        },
                        "concept": None,
                        "input_name": str(name),
                        "requested_name": str(name),
                        "requested_kind": kind,
                    }
                )
                continue

            duplicate_match = find_existing_concept_for_create_concepts(
                concept_name=str(name),
                requested_concept_id=(
                    canonical_concept_id_override or concept_data.get("concept_id")
                ),
                kind=kind,
                parent_id_for_concept=parent_id_for_concept,
                preferred_language="en-NZ",
                allow_duplicate_instances=allow_duplicate_instances,
                duplicate_resolution_mode=(
                    _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY
                    if canonical_id_only
                    else None
                ),
                external_identifiers=external_identifiers,
                external_identity_concept_ids=(
                    (canonical_concept_id_override,)
                    if canonical_concept_id_override
                    else ()
                ),
                identity_candidate_concept_ids=identity_candidate_concept_ids,
                identity_rejected_candidate_concept_ids=(
                    identity_rejected_candidate_concept_ids
                ),
            )
            if duplicate_match is not None:
                if isinstance(
                    duplicate_match,
                    CreateConceptDuplicateGuardBlock,
                ):
                    result = build_duplicate_guard_block_create_concepts_result(
                        requested_name=str(name),
                        requested_kind=kind,
                        block=duplicate_match,
                    )
                    results.append(result)
                    continue
                if duplicate_match.identity_conflict:
                    is_external_identity = duplicate_match.match_source.startswith(
                        "external_identifier:"
                    )
                    result = build_canonical_identity_conflict_create_concepts_result(
                        requested_name=str(name),
                        requested_kind=kind,
                        existing_concept_id=duplicate_match.existing_concept_id,
                        guard_scope=duplicate_match.guard_scope,
                        existing_kind=duplicate_match.existing_kind,
                        existing_parent_ids=duplicate_match.existing_parent_ids,
                        requested_parent_id=duplicate_match.requested_parent_id,
                        mismatch_reasons=duplicate_match.mismatch_reasons,
                        error_code=(
                            "external_identity_conflict"
                            if is_external_identity
                            else "canonical_identity_conflict"
                        ),
                        match_source=duplicate_match.match_source,
                    )
                else:
                    result = build_duplicate_prevented_create_concepts_result(
                        requested_name=str(name),
                        requested_kind=kind,
                        existing_concept_id=duplicate_match.existing_concept_id,
                        guard_scope=duplicate_match.guard_scope,
                        match_source=duplicate_match.match_source,
                    )
                    if duplicate_match.match_source.startswith("external_identifier:"):
                        # A create grant authorises a new concept only. Reusing an
                        # existing identity is therefore strictly read-only: marker
                        # repair would be an edit to a target and publication context
                        # absent from this create intent.
                        result["external_identity"] = {
                            "identifiers": [
                                identifier.to_dict()
                                for identifier in external_identifiers
                            ],
                            "persistence": {
                                "success": True,
                                "effect_status": "not_started",
                                "changed": False,
                                "reason_code": "duplicate_reuse_is_read_only",
                            },
                        }
                        result["effect_status"] = "not_started"
                        result["changed"] = False
                        result["requested_parent_id"] = (
                            duplicate_match.requested_parent_id
                        )
                        result["existing_parent_ids"] = list(
                            duplicate_match.existing_parent_ids
                        )
                        result["requested_parent_already_present"] = bool(
                            duplicate_match.requested_parent_id
                            and duplicate_match.requested_parent_id
                            in set(duplicate_match.existing_parent_ids)
                        )
                if duplicate_match.resolution_source:
                    result["external_identity_resolution_source"] = (
                        duplicate_match.resolution_source
                    )
                result["concept_id"] = duplicate_match.existing_concept_id
                results.append(result)
                continue

            # Duplicate preflights are read-only and may consume the entire
            # transport budget. Never start an insert after cancellation.
            if _cancelled_after_completed_items():
                break
            result = create_vontology_concept(
                parent_id=parent_id_for_concept,
                new_concept_name=name,
                create_as_instance=create_as_instance,
                allow_duplicate_instance_suffix=allow_duplicate_instances,
                description=concept_data.get("description"),
                notes=concept_data.get("notes"),
                vontology_path=concept_data.get("vontology_path"),
                instance_of_type=concept_data.get("instance_of_type")
                or kwargs.get("instance_of_type"),
                created_by_concept_id=actor_user_id,
                organisation_concept_id=actor_org_id,
                event_namespace=namespace,
                visibility_scope_mode=scope_mode,
                canonical_concept_id_override=(
                    canonical_concept_id_override or concept_data.get("concept_id")
                ),
                maintain_relationship_inverses=False,
                resolve_visibility_from_event_namespace=False,
            )
            if (
                external_identifiers
                and canonical_concept_id_override
                and result.get("error_code") == "already_exists"
            ):
                # The external-identity preflight did not verify this record.
                # A unique-key collision may be a concurrent legitimate create,
                # an actor-invisible record, or an unrelated record occupying the
                # predicted ID. None is safe to report as successful reuse until
                # a later actor-scoped lookup verifies the persisted identity.
                result = {
                    "success": False,
                    "effect_status": "failed",
                    "changed": False,
                    "error_code": "external_identity_collision_unverified",
                    "message": (
                        "The actor-scoped external identity became occupied before "
                        "creation completed, but its identity was not verified. "
                        "No existing concept was exposed or reused."
                    ),
                    "concept": None,
                    "canonical_concept_id": canonical_concept_id_override,
                    "input_name": name,
                    "retryable": True,
                }
            # Enrich result with the requested name for traceability and surface
            # the canonical created concept_id at a stable top-level key so UI
            # summaries can reliably name what was created.
            result["requested_name"] = name
            result["requested_kind"] = kind
            concept_id_value = result.get("concept_id")
            if not isinstance(concept_id_value, str) or not concept_id_value.strip():
                nested_concept = result.get("concept")
                if isinstance(nested_concept, dict):
                    nested_id = nested_concept.get("concept_id")
                    if isinstance(nested_id, str) and nested_id.strip():
                        concept_id_value = nested_id
            if not isinstance(concept_id_value, str) or not concept_id_value.strip():
                canonical_id = result.get("canonical_concept_id")
                if isinstance(canonical_id, str) and canonical_id.strip():
                    concept_id_value = canonical_id
            if not isinstance(concept_id_value, str) or not concept_id_value.strip():
                existing_id = result.get("existing_concept_id")
                if isinstance(existing_id, str) and existing_id.strip():
                    concept_id_value = existing_id
            if isinstance(concept_id_value, str) and concept_id_value.strip():
                result["concept_id"] = concept_id_value.strip()
                if result.get("success") and external_identifiers:
                    try:
                        raise_if_internal_mcp_cancelled()
                    except InternalMCPHandlerCancelled as exc:
                        # The primary concept is already durable. Preserve that
                        # receipt, but do not begin the logically subsequent
                        # identity-marker write after cancellation.
                        persistence_failure = {
                            "stage": "external_identity_persistence",
                            "error_code": (
                                "external_identity_persistence_not_started_"
                                "after_concept_creation"
                            ),
                            "effect_status": "not_started",
                            "dispatched": False,
                        }
                        identity_persistence = {
                            "success": False,
                            "effect_status": "not_started",
                            "changed": False,
                            "writes": [],
                            "failures": [],
                            "indeterminate_failures": [],
                            "error_code": persistence_failure["error_code"],
                            "cancellation": str(exc),
                        }
                        result["external_identity"] = {
                            "identifiers": [
                                identifier.to_dict()
                                for identifier in external_identifiers
                            ],
                            "canonical_concept_id_override": (
                                canonical_concept_id_override
                            ),
                            "persistence": identity_persistence,
                        }
                        result["partial_failures"] = [persistence_failure]
                        if isinstance(result.get("concept"), dict):
                            result["concept"]["partial_failures"] = [
                                persistence_failure
                            ]
                        result["effect_status"] = "partial"
                        result["changed"] = True
                        results.append(result)
                        cancelled_after_partial_error = str(exc)
                        break
                    identity_persistence = persist_external_identity_markers(
                        concept_id=concept_id_value.strip(),
                        identifiers=external_identifiers,
                    )
                    result["external_identity"] = {
                        "identifiers": [
                            identifier.to_dict() for identifier in external_identifiers
                        ],
                        "canonical_concept_id_override": (
                            canonical_concept_id_override
                        ),
                        "persistence": identity_persistence,
                    }
                    (
                        identity_effect_status,
                        _identity_changed,
                        identity_failures,
                        identity_indeterminate_failures,
                    ) = _identity_persistence_outcome(identity_persistence)
                    if identity_effect_status == "indeterminate":
                        # Concept creation is known durable, while marker
                        # finality is unknown. Preserve both facts and force
                        # canonical inspection before another effect.
                        result["effect_status"] = "indeterminate"
                        result["changed"] = True
                        result["indeterminate_failures"] = (
                            identity_indeterminate_failures
                            or [
                                {
                                    "stage": "external_identity_persistence",
                                    "outcome": "indeterminate",
                                }
                            ]
                        )
                    elif identity_failures or identity_effect_status in {
                        "failed",
                        "partial",
                    }:
                        persistence_failures = identity_failures or [
                            {
                                "stage": "external_identity_persistence",
                                "outcome": identity_effect_status,
                            }
                        ]
                        result["partial_failures"] = persistence_failures
                        if isinstance(result.get("concept"), dict):
                            concept_partial_failures = result["concept"].setdefault(
                                "partial_failures",
                                [],
                            )
                            if isinstance(concept_partial_failures, list):
                                concept_partial_failures.extend(persistence_failures)
                        result["effect_status"] = "partial"
                        result["changed"] = True
            results.append(result)

    # Count different outcome types for summary
    successful = sum(1 for r in results if isinstance(r, dict) and r.get("success"))
    already_exists = sum(
        1
        for r in results
        if isinstance(r, dict) and r.get("error_code") == "already_exists"
    )
    created_concept_ids = [
        str(r.get("concept_id")).strip()
        for r in results
        if isinstance(r, dict)
        and r.get("success")
        and isinstance(r.get("concept_id"), str)
        and str(r.get("concept_id")).strip()
    ]

    def _collect_item_failures(field: str) -> list[dict[str, Any]]:
        collected: list[dict[str, Any]] = []
        seen: set[str] = set()
        for item_result in results:
            if not isinstance(item_result, dict):
                continue
            concept_id = str(item_result.get("concept_id") or "").strip() or None
            sources: list[Any] = [item_result.get(field)]
            nested_concept = item_result.get("concept")
            if isinstance(nested_concept, dict):
                sources.append(nested_concept.get(field))
            for source in sources:
                if not isinstance(source, list):
                    continue
                for failure in source:
                    if not isinstance(failure, Mapping):
                        continue
                    row = {"concept_id": concept_id, **dict(failure)}
                    signature = repr(sorted(row.items(), key=lambda pair: pair[0]))
                    if signature in seen:
                        continue
                    seen.add(signature)
                    collected.append(row)
        return collected

    partial_failures = _collect_item_failures("partial_failures")
    indeterminate_failures = _collect_item_failures("indeterminate_failures")
    item_effect_statuses = {
        str(item.get("effect_status") or "").strip().lower()
        for item in results
        if isinstance(item, dict)
    }
    failed = len(results) - successful - already_exists
    if indeterminate_failures or "indeterminate" in item_effect_statuses:
        effect_status = "indeterminate"
    elif (
        partial_failures
        or "partial" in item_effect_statuses
        or (failed > 0 and (successful > 0 or already_exists > 0))
    ):
        effect_status = "partial"
    elif failed > 0:
        effect_status = "failed"
    else:
        effect_status = "succeeded"
    applied_scope_modes = sorted(
        {
            str(
                (
                    ((r.get("concept") or {}).get("creation_visibility") or {}).get(
                        "effective_scope_mode"
                    )
                )
            ).strip()
            for r in results
            if isinstance(r, dict)
            and isinstance(r.get("concept"), dict)
            and isinstance((r.get("concept") or {}).get("creation_visibility"), dict)
            and str(
                (
                    ((r.get("concept") or {}).get("creation_visibility") or {}).get(
                        "effective_scope_mode"
                    )
                )
            ).strip()
        }
    )

    item_changed_values: list[bool | None] = []
    for item_result in results:
        if not isinstance(item_result, dict):
            continue
        raw_changed = item_result.get("changed")
        if isinstance(raw_changed, bool) or (
            "changed" in item_result and raw_changed is None
        ):
            item_changed_values.append(raw_changed)
        elif item_result.get("effect_status") == "indeterminate":
            item_changed_values.append(None)
        elif item_result.get("success"):
            item_changed_values.append(True)
        else:
            item_changed_values.append(False)
    changed: bool | None
    if any(value is True for value in item_changed_values):
        changed = True
    elif any(value is None for value in item_changed_values):
        changed = None
    else:
        changed = False
    response = {
        "success": (
            failed == 0
            and not partial_failures
            and not indeterminate_failures
            and effect_status == "succeeded"
        ),
        "effect_status": effect_status,
        "changed": changed,
        "results": results,
        "total": len(concepts),
        "successful": successful,
        "already_existed": already_exists,
        "failed": failed,
        "partial_failure_count": len(partial_failures),
        "partial_failures": partial_failures,
        "indeterminate_failure_count": len(indeterminate_failures),
        "indeterminate_failures": indeterminate_failures,
        "created_concept_ids": created_concept_ids,
        "parent_id_used": validated_parent_id,  # Canonicalised parent ID that was actually used
        "parent_resolution": parent_resolution.to_dict(),
        "scope_selection": {
            "requested_scope_mode": scope_mode or _CREATE_CONCEPTS_SCOPE_USER_ONLY,
            "scope_mode_source": scope_mode_source,
            "created_by_concept_id": actor_user_id,
            "organisation_concept_id": actor_org_id,
            "effective_scope_modes": applied_scope_modes,
            "namespace": namespace,
        },
    }
    if cancelled_after_partial_error is not None:
        response.update(
            {
                "success": False,
                "effect_status": (
                    "indeterminate" if effect_status == "indeterminate" else "partial"
                ),
                "error_code": "handler_cancelled_after_partial_completion",
                "error": (
                    "Concept creation was cancelled after one or more batch items "
                    "had completed. Completed item receipts are preserved and no "
                    "later item was started."
                ),
                "cancellation_requested": True,
                "cancellation_error": cancelled_after_partial_error,
                "completed_before_cancellation": len(results),
                "unattempted_count": len(concepts) - len(results),
            }
        )
    return response


def _extract_annotations(**kwargs):
    from ...services.annotation_extraction_service import extract_annotations

    return extract_annotations(**kwargs)


def _search_concepts(**kwargs):
    from ...services.concept_search_service import search_concepts

    return search_concepts(**kwargs)


def _indeterminate_effect_error(
    message: str,
    *,
    details: dict[str, Any],
) -> dict[str, Any]:
    """Report an unexpected write-path exception without inventing finality."""

    response = make_error_response(
        "effect_outcome_unknown",
        message,
        details=details,
        suggestions=["Inspect canonical state before retrying the effect."],
    )
    response.update(
        {
            "effect_status": "indeterminate",
            "mutation_outcome": "unknown",
            "changed": None,
            "retryable": False,
            "recovery_affordances": [
                {"action_type": "inspect_operation_state_before_retry"}
            ],
        }
    )
    return response


@_governed_ontology_mutation("upsert_text_relation")
def _upsert_text_relation(**kwargs):
    from ...services.text_value_service import upsert_text_for_concept
    from ...services.text_relation_predicate_validation_service import (
        TextRelationPredicateResolutionError,
        resolve_text_relation_predicate_for_write,
    )
    from ...services.rag_text_relation_change_hook_service import (
        maybe_sync_concept_text_relations_to_rag,
    )

    concept_id = kwargs.get("concept_id")
    predicate = kwargs.get("predicate")
    text = kwargs.get("text")
    language = kwargs.get("language", "en-NZ")
    context = kwargs.get("context")
    provenance = kwargs.get("provenance")
    namespace = kwargs.get("namespace")
    mutation_dispatched = False

    if not concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'concept_id' parameter",
            details={"missing": ["concept_id"]},
            suggestions=["Provide the concept ID to attach text to"],
        )
    if not predicate:
        return make_error_response(
            "missing_parameter",
            "Missing 'predicate' parameter",
            details={"missing": ["predicate"]},
            suggestions=[
                "Provide a predicate like 'hasContent', 'hasDescription', or a custom predicate"
            ],
        )
    if not text:
        return make_error_response(
            "missing_parameter",
            "Missing 'text' parameter",
            details={"missing": ["text"]},
            suggestions=["Provide the text content to attach"],
        )

    try:
        predicate_resolution = resolve_text_relation_predicate_for_write(predicate)
        storage_predicate = predicate_resolution.storage_predicate
        mutation_dispatched = True
        result = upsert_text_for_concept(
            subject_concept_id=concept_id,
            predicate=storage_predicate,
            text=text,
            lang=language,
            provenance=provenance if isinstance(provenance, dict) else None,
            context=context,
        )

        # Best-effort hook: if the orchestrator provided an authenticated namespace,
        # keep concept text-relations RAG index fresh.
        maybe_sync_concept_text_relations_to_rag(
            namespace=namespace,
            concept_id=concept_id,
            predicate=storage_predicate,
        )

        text_preview = text[:100] + "..." if len(text) > 100 else text
        return {
            "success": True,
            "effect_status": "succeeded",
            "changed": bool(
                result.get("relation_created") or result.get("context_updated")
            ),
            "text_value_id": str(result.get("text_value_id")),
            "relation_id": str(result.get("relation_id")),
            "relation_created": result.get("relation_created"),
            "context_updated": result.get("context_updated"),
            "predicate": storage_predicate,
            "input_predicate": predicate_resolution.input_predicate,
            "predicate_concept_id": predicate_resolution.predicate_concept_id,
            "text_preview": text_preview,
            "language": language,
        }
    except TextRelationPredicateResolutionError as exc:
        return make_error_response(
            exc.error_code,
            str(exc),
            details=exc.details,
            suggestions=exc.suggestions,
        )
    except Exception as exc:
        if not mutation_dispatched:
            return make_error_response(
                "exception",
                f"Failed to prepare text relation: {exc}",
                details={"exception_type": type(exc).__name__},
            )
        return _indeterminate_effect_error(
            (
                "The text-relation operation raised unexpectedly; canonical "
                "state may already have changed."
            ),
            details={
                "exception_type": type(exc).__name__,
                "exception": str(exc),
                "concept_id": concept_id,
                "predicate": predicate,
            },
        )


_SCOPED_ASSERTION_EXACT_PREDICATE_ERROR = (
    "predicate must be an exact #V# concept ID"
)
_SCOPED_ASSERTION_BARE_TEXT_PREDICATE_ERROR_CODE = (
    "unsupported_text_relation_predicate"
)
_SCOPED_ASSERTION_CODE_PREDICATE_RE = re.compile(
    r"^[A-Za-z0-9_][A-Za-z0-9._-]*$"
)


def _is_scoped_assertion_predicate_syntax_error(error: ValueError) -> bool:
    from ...services.text_relation_predicate_validation_service import (
        TextRelationPredicateResolutionError,
    )

    return (
        str(error) == _SCOPED_ASSERTION_EXACT_PREDICATE_ERROR
        or (
            isinstance(error, TextRelationPredicateResolutionError)
            and error.error_code
            == _SCOPED_ASSERTION_BARE_TEXT_PREDICATE_ERROR_CODE
        )
    )


def _exact_scoped_assertion_predicate_recovery(
    *,
    actor_scope: Any,
    arguments: Mapping[str, Any],
    error: ValueError,
) -> dict[str, Any] | None:
    """Return one executable syntax-only predicate repair, or no affordance."""

    concept_predicate_syntax_error = (
        str(error) == _SCOPED_ASSERTION_EXACT_PREDICATE_ERROR
    )
    text_predicate_syntax_error = (
        _is_scoped_assertion_predicate_syntax_error(error)
        and not concept_predicate_syntax_error
    )
    if not concept_predicate_syntax_error and not text_predicate_syntax_error:
        return None
    raw_predicate = str(arguments.get("predicate") or "").strip()
    if (
        not raw_predicate
        or raw_predicate.startswith("#V#")
        or _SCOPED_ASSERTION_CODE_PREDICATE_RE.fullmatch(raw_predicate) is None
    ):
        return None

    target_text = arguments.get("target_text")
    target_concept_id = str(arguments.get("target_concept_id") or "").strip()
    has_text = isinstance(target_text, str) and bool(target_text.strip())
    has_concept = bool(target_concept_id)
    if has_text == has_concept:
        return None
    if concept_predicate_syntax_error != has_concept:
        return None
    if text_predicate_syntax_error != has_text:
        return None
    if has_concept and not target_concept_id.startswith("#V#"):
        return None
    evidence = arguments.get("evidence")
    if evidence is not None and not isinstance(evidence, Mapping):
        return None

    from ...security.access_control import can_access_concept
    from ...services.relationship_write_service import (
        resolve_existing_predicate_value_kind,
    )
    from ...utils.concept_id_utils import canonicalise_vontology_concept_id

    predicate_concept_id = canonicalise_vontology_concept_id(raw_predicate)
    subject_concept_id = str(
        arguments.get("subject_concept_id") or ""
    ).strip()
    if not predicate_concept_id or not subject_concept_id:
        return None

    expected_value_kind = "text" if has_text else "concept"
    with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
        if not can_access_concept(subject_concept_id):
            return None
        if not can_access_concept(predicate_concept_id):
            return None
        if has_concept and not can_access_concept(target_concept_id):
            return None
        if (
            resolve_existing_predicate_value_kind(predicate_concept_id)
            != expected_value_kind
        ):
            return None

    retry_arguments = {
        field_name: arguments[field_name]
        for field_name in (
            "subject_concept_id",
            "target_text",
            "target_concept_id",
            "language",
            "scope_mode",
            "evidence",
        )
        if field_name in arguments and arguments[field_name] is not None
    }
    retry_arguments["predicate"] = predicate_concept_id
    return {
        "action_type": "retry_exact_scoped_assertion_with_canonical_predicate_id",
        "tool": "upsert_scoped_assertion",
        "arguments": retry_arguments,
        "resolution": {
            "kind": "canonical_code_identifier",
            "input_predicate": raw_predicate,
            "predicate_concept_id": predicate_concept_id,
            "value_kind": expected_value_kind,
        },
    }


def _upsert_scoped_assertion(**kwargs):
    from ...services.rag_text_relation_change_hook_service import (
        maybe_sync_concept_text_relations_to_rag,
    )
    from ...services.scoped_assertion_service import upsert_scoped_assertion

    subject_concept_id = kwargs.get("subject_concept_id")
    predicate = kwargs.get("predicate")
    if not subject_concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'subject_concept_id' parameter",
            details={"missing": ["subject_concept_id"]},
        )
    if not predicate:
        return make_error_response(
            "missing_parameter",
            "Missing 'predicate' parameter",
            details={"missing": ["predicate"]},
        )
    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="scoped assertion mutation",
        require_actor=True,
    )
    if denial is not None:
        return denial
    if actor_scope.user_concept_id is None:
        return make_error_response(
            "authenticated_actor_context_required",
            "Scoped assertion mutation requires an authenticated user actor.",
        )

    service_kwargs = {
        field_name: kwargs.get(field_name)
        for field_name in (
            "subject_concept_id",
            "predicate",
            "target_text",
            "target_concept_id",
            "language",
            "scope_mode",
            "evidence",
            "turn_id",
        )
        if field_name in kwargs
    }
    service_kwargs.update(
        {
            "acting_user_concept_id": actor_scope.user_concept_id,
            "organisation_concept_id": actor_scope.organisation_concept_id,
            "namespace": actor_scope.namespace,
            "canonical_publication": False,
        }
    )
    try:
        with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
            result = upsert_scoped_assertion(**service_kwargs)
        assertion = result.get("assertion")
        if isinstance(assertion, dict) and assertion.get("object_kind") == "text":
            try:
                derived_maintenance = maybe_sync_concept_text_relations_to_rag(
                    namespace=actor_scope.namespace,
                    concept_id=str(subject_concept_id),
                    predicate=str(assertion.get("predicate") or predicate),
                    scoped_assertion_id=assertion.get("assertion_id"),
                )
            except Exception as exc:
                # The canonical assertion and its read-back already succeeded.
                # Derived-index maintenance must not turn that durable receipt
                # into an indeterminate write result.
                logger.warning(
                    "Scoped assertion persisted but RAG refresh scheduling failed: %s",
                    exc,
                )
                derived_maintenance = {
                    "mechanism": "in_memory_bounded_queue",
                    "durable": False,
                    "success": False,
                    "scheduled": False,
                    "skipped": False,
                    "reason": "schedule_failed",
                    "error": str(exc),
                }
            result = {
                **result,
                "derived_maintenance": derived_maintenance,
            }
        return result
    except PermissionError as exc:
        return make_error_response(
            "access_denied",
            str(exc),
            details={"subject_concept_id": subject_concept_id},
        )
    except ValueError as exc:
        predicate_rejected = _is_scoped_assertion_predicate_syntax_error(exc)
        try:
            recovery = _exact_scoped_assertion_predicate_recovery(
                actor_scope=actor_scope,
                arguments=service_kwargs,
                error=exc,
            )
        except Exception:
            # Recovery discovery is a read-only convenience after a known
            # pre-dispatch validation failure. A failed feasibility probe must
            # not erase or weaken that authoritative no-change receipt.
            logger.debug(
                "Scoped assertion predicate recovery probe failed",
                exc_info=True,
            )
            recovery = None
        details = {
            "subject_concept_id": subject_concept_id,
        }
        if predicate_rejected:
            details["rejected_fields"] = ["predicate"]
        if recovery is not None:
            details["predicate_resolution"] = dict(recovery["resolution"])
        payload = make_error_response(
            "invalid_scoped_assertion",
            str(exc),
            details=details,
        )
        payload.update(
            {
                "effect_status": "not_started",
                "mutation_outcome": "not_started",
                "changed": False,
            }
        )
        if recovery is not None:
            payload["recovery_affordances"] = [recovery]
        return payload
    except Exception as exc:
        return _indeterminate_effect_error(
            "The scoped-assertion operation raised unexpectedly.",
            details={
                "exception_type": type(exc).__name__,
                "exception": str(exc),
                "subject_concept_id": subject_concept_id,
            },
        )


def _store_text_assertion(**kwargs):
    from ...services.scoped_assertion_service import (
        add_text_assertion_concept_links,
        store_text_assertion,
    )

    text = kwargs.get("text")
    if not isinstance(text, str) or not text.strip():
        return make_error_response(
            "missing_parameter",
            "Missing non-empty 'text' parameter",
            details={"missing": ["text"]},
        )
    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="text assertion mutation",
        require_actor=True,
    )
    if denial is not None:
        return denial
    if actor_scope.user_concept_id is None:
        return make_error_response(
            "authenticated_actor_context_required",
            "Text assertion mutation requires an authenticated user actor.",
        )

    mutation_dispatched = False
    try:
        with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
            mutation_dispatched = True
            result = store_text_assertion(
                text=text,
                language=kwargs.get("language") or "en-NZ",
                scope_mode=kwargs.get("scope_mode") or "user",
                context_id=kwargs.get("context_id"),
                source_event_id=(
                    kwargs.get("source_event_id")
                    or kwargs.get("source_occurrence_key")
                ),
                evidence=kwargs.get("evidence"),
                acting_user_concept_id=actor_scope.user_concept_id,
                organisation_concept_id=actor_scope.organisation_concept_id,
                namespace=actor_scope.namespace,
                turn_id=kwargs.get("turn_id"),
                canonical_publication=False,
            )
    except PermissionError as exc:
        return make_error_response("access_denied", str(exc))
    except ValueError as exc:
        return make_error_response("invalid_text_assertion", str(exc))
    except Exception as exc:
        if not mutation_dispatched:
            return make_error_response(
                "exception",
                f"Failed to prepare text assertion: {exc}",
                details={"exception_type": type(exc).__name__},
            )
        return _indeterminate_effect_error(
            "The text-assertion operation raised unexpectedly; canonical state "
            "may already have changed.",
            details={
                "exception_type": type(exc).__name__,
                "exception": str(exc),
            },
        )

    concept_links = kwargs.get("concept_links")
    if concept_links is None or concept_links == []:
        return result
    # Enrichment is deliberately after canonical admission. Bad, incomplete,
    # or currently unresolvable links never discard the stored assertion.
    try:
        with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
            link_result = add_text_assertion_concept_links(
                assertion_id=result["assertion_id"],
                links=concept_links,
                acting_user_concept_id=actor_scope.user_concept_id,
                organisation_concept_id=actor_scope.organisation_concept_id,
                namespace=actor_scope.namespace,
                turn_id=kwargs.get("turn_id"),
            )
        result = {
            **result,
            "assertion": link_result.get("assertion") or result.get("assertion"),
            "canonical_read_back": (
                link_result.get("canonical_read_back")
                or result.get("canonical_read_back")
            ),
            "derived_maintenance": (
                link_result.get("derived_maintenance")
                or result.get("derived_maintenance")
            ),
            "enrichment": {
                "success": True,
                "changed": bool(link_result.get("changed")),
                "links_added": int(link_result.get("links_added") or 0),
            },
        }
    except Exception as exc:
        logger.warning(
            "Text assertion persisted but optional concept linking failed: %s",
            exc,
        )
        result = {
            **result,
            "enrichment": {
                "success": False,
                "changed": False,
                "links_added": 0,
                "retryable": True,
                "error_code": (
                    "access_denied"
                    if isinstance(exc, PermissionError)
                    else "invalid_concept_links"
                    if isinstance(exc, ValueError)
                    else "concept_linking_failed"
                ),
                "error": str(exc),
            },
        }
    return result


