def _retract_scoped_assertion(**kwargs):
    from ...services.rag_text_relation_change_hook_service import (
        maybe_sync_concept_text_relations_to_rag,
    )
    from ...services.scoped_assertion_service import retract_scoped_assertion

    assertion_id = kwargs.get("assertion_id")
    if not assertion_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'assertion_id' parameter",
            details={"missing": ["assertion_id"]},
        )
    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="scoped assertion retraction",
        require_actor=True,
    )
    if denial is not None:
        return denial
    if actor_scope.user_concept_id is None:
        return make_error_response(
            "authenticated_actor_context_required",
            "Scoped assertion retraction requires an authenticated user actor.",
        )

    try:
        with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
            result = retract_scoped_assertion(
                assertion_id=assertion_id,
                acting_user_concept_id=actor_scope.user_concept_id,
                organisation_concept_id=actor_scope.organisation_concept_id,
                namespace=actor_scope.namespace,
            )
        assertion = result.get("assertion")
        if (
            isinstance(assertion, dict)
            and assertion.get("object_kind") == "text"
            and assertion.get("subject_concept_id")
            and assertion.get("predicate")
        ):
            try:
                derived_maintenance = maybe_sync_concept_text_relations_to_rag(
                    namespace=actor_scope.namespace,
                    concept_id=str(assertion["subject_concept_id"]),
                    predicate=str(assertion["predicate"]),
                    scoped_assertion_id=str(
                        assertion.get("assertion_id") or assertion_id
                    ),
                )
            except Exception as exc:
                logger.warning(
                    "Scoped assertion retracted but RAG refresh scheduling failed: %s",
                    exc,
                )
                derived_maintenance = {
                    "mechanism": "in_memory_bounded_queue",
                    "durable": False,
                    "success": False,
                    "scheduled": False,
                    "skipped": False,
                    "reason": "schedule_failed",
                    "error": str(exc),
                }
            result = {
                **result,
                "derived_maintenance": derived_maintenance,
            }
        return result
    except PermissionError as exc:
        return make_error_response(
            "access_denied",
            str(exc),
            details={"assertion_id": str(assertion_id)},
        )
    except ValueError as exc:
        return make_error_response(
            "invalid_scoped_assertion",
            str(exc),
            details={"assertion_id": str(assertion_id)},
        )
    except Exception as exc:
        return _indeterminate_effect_error(
            "The scoped-assertion retraction raised unexpectedly.",
            details={
                "exception_type": type(exc).__name__,
                "exception": str(exc),
                "assertion_id": str(assertion_id),
            },
        )


def _list_scoped_assertions(**kwargs):
    from ...services.scoped_assertion_service import (
        list_visible_scoped_assertions_page,
    )

    subject_concept_id = kwargs.get("subject_concept_id")
    predicates = kwargs.get("predicates")
    predicate = kwargs.get("predicate")
    if predicate and not predicates:
        predicates = [predicate]
    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="scoped assertion listing",
        require_actor=True,
    )
    if denial is not None:
        return denial
    with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
        page = list_visible_scoped_assertions_page(
            subject_concept_ids=(
                [str(subject_concept_id)] if subject_concept_id else None
            ),
            argument_concept_id=kwargs.get("argument_concept_id"),
            predicates=predicates,
            object_kind=kwargs.get("object_kind"),
            languages=kwargs.get("languages"),
            assertion_form=kwargs.get("assertion_form"),
            context_id=kwargs.get("context_id"),
            limit=kwargs.get("limit") or 200,
            offset=kwargs.get("offset") or 0,
            user_concept_id=actor_scope.user_concept_id,
            organisation_concept_id=actor_scope.organisation_concept_id,
        )
    assertions = list(page.get("items") or ())
    counts_are_lower_bounds = bool(page.get("counts_are_lower_bounds"))
    return {
        "success": True,
        "assertions": assertions,
        "assertions_found": len(assertions),
        "paging": {
            "limit": page.get("limit"),
            "offset": page.get("offset"),
            "returned": page.get("returned"),
            "has_more": bool(page.get("has_more")),
            "next_offset": page.get("next_offset"),
            "visibility_filtered": bool(page.get("visibility_filtered")),
            "counts_are_lower_bounds": counts_are_lower_bounds,
        },
        **(
            {"assertions_found_is_lower_bound": True} if counts_are_lower_bounds else {}
        ),
        "canonical_publication": False,
    }


def _get_text_relations(**kwargs):
    from ...services.text_value_service import get_texts_for_concept

    concept_id = kwargs.get("concept_id")
    predicate = kwargs.get("predicate")
    language = kwargs.get("language")
    limit = kwargs.get("limit", 50)
    recent_first = kwargs.get("recent_first")
    if recent_first is None:
        recent_first = kwargs.get("sort_recent_first")

    if not concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'concept_id' parameter",
            details={"missing": ["concept_id"]},
            suggestions=["Provide the concept ID to retrieve text relations for"],
        )

    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="text retrieval",
        ignore_untrusted_payload_identity=True,
    )
    if denial is not None:
        return denial
    context_view = _internal_mcp_knowledge_context_view(actor_scope)

    try:
        with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
            relations = get_texts_for_concept(
                subject_concept_id=concept_id,
                predicate=predicate,
                lang=language,
                limit=limit,
                context_view=context_view,
                recent_first=(
                    recent_first
                    if isinstance(recent_first, bool)
                    else str(recent_first or "").strip().lower()
                    in {"1", "true", "yes", "on"}
                ),
            )

        # Add text previews for long content
        for relation in relations:
            text = relation.get("text", "")
            if len(text) > 200:
                relation["text_preview"] = text[:200] + "..."

        return {
            "concept_id": concept_id,
            "context_view": context_view,
            "relations_found": len(relations),
            "relations": relations,
        }
    except Exception as exc:
        return make_error_response(
            "exception",
            f"Failed to get text relations: {exc}",
            details={"exception_type": type(exc).__name__},
        )


@_governed_ontology_mutation("update_text_relation")
def _update_text_relation(**kwargs):
    from ...services.text_value_service import update_text_relation_text
    from ...services.rag_text_relation_change_hook_service import (
        maybe_sync_concept_text_relations_to_rag,
    )

    concept_id = kwargs.get("concept_id")
    relation_id = kwargs.get("relation_id")
    new_text = kwargs.get("new_text")
    language = kwargs.get("language", "en-NZ")
    namespace = kwargs.get("namespace")

    if not concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'concept_id' parameter",
            details={"missing": ["concept_id"]},
            suggestions=["Provide the concept ID that owns the text relation"],
        )
    if not relation_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'relation_id' parameter",
            details={"missing": ["relation_id"]},
            suggestions=["Use get_text_relations to find the relation_id to update"],
        )
    if not new_text:
        return make_error_response(
            "missing_parameter",
            "Missing 'new_text' parameter",
            details={"missing": ["new_text"]},
            suggestions=["Provide the new text content"],
        )

    try:
        result = update_text_relation_text(
            subject_concept_id=concept_id,
            relation_id=relation_id,
            new_text=new_text,
            lang=language,
        )

        maybe_sync_concept_text_relations_to_rag(
            namespace=namespace,
            concept_id=concept_id,
            predicate=result.get("predicate"),
        )

        old_preview = str(result.get("old_text", ""))[:100]
        new_preview = new_text[:100] + "..." if len(new_text) > 100 else new_text

        return {
            "success": True,
            "relation_id": relation_id,
            "old_text_preview": old_preview,
            "new_text_preview": new_preview,
            "text_value_id": str(result.get("text_value_id")),
        }
    except Exception as exc:
        return make_error_response(
            "exception",
            f"Failed to update text relation: {exc}",
            details={"exception_type": type(exc).__name__},
        )


@_governed_ontology_mutation("delete_text_relation")
def _delete_text_relation(**kwargs):
    from ...services.text_value_service import (
        delete_text_relation,
        delete_text_relation_by_predicate_and_text,
    )
    from ...services.rag_text_relation_change_hook_service import (
        maybe_delete_text_relation_doc_from_rag,
    )

    concept_id = kwargs.get("concept_id")
    relation_id = kwargs.get("relation_id")
    predicate = kwargs.get("predicate")
    text = kwargs.get("text")
    language = kwargs.get("language")
    garbage_collect = bool(kwargs.get("garbage_collect"))
    namespace = kwargs.get("namespace")

    if not concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'concept_id' parameter",
            details={"missing": ["concept_id"]},
            suggestions=["Provide the concept ID that owns the text relation"],
        )

    try:
        if relation_id:
            # Delete by relation ID (preferred)
            result = delete_text_relation(
                subject_concept_id=concept_id,
                relation_id=relation_id,
                garbage_collect=garbage_collect,
            )

            maybe_delete_text_relation_doc_from_rag(
                namespace=namespace,
                relation_id=relation_id,
            )

            return {
                "success": True,
                "deleted_relation_id": relation_id,
                "deleted_text_preview": None,
                "text_value_cleaned_up": bool(
                    result.get(
                        "orphaned_text_value_deleted",
                        result.get("text_value_cleaned_up", False),
                    )
                ),
            }
        elif predicate and text:
            # Delete by predicate + text match
            result = delete_text_relation_by_predicate_and_text(
                subject_concept_id=concept_id,
                predicate=predicate,
                text=text,
                lang=language,
                garbage_collect=garbage_collect,
            )

            maybe_delete_text_relation_doc_from_rag(
                namespace=namespace,
                relation_id=result.get("relation_id"),
            )

            return {
                "success": True,
                "deleted_relation_id": result.get("relation_id"),
                "deleted_text_preview": text[:100],
                "text_value_cleaned_up": result.get(
                    "orphaned_text_value_deleted", False
                ),
            }
        else:
            return make_error_response(
                "missing_parameter",
                "Must provide either relation_id or both predicate and text",
                details={"missing": ["relation_id", "predicate+text"]},
                suggestions=[
                    "Provide relation_id for direct deletion, or both predicate and text for matched deletion"
                ],
            )
    except Exception as exc:
        return make_error_response(
            "exception",
            f"Failed to delete text relation: {exc}",
            details={"exception_type": type(exc).__name__},
        )


def _get_text_relations_summary(**kwargs):
    from ...services.text_value_service import get_text_relations_summary

    concept_id = kwargs.get("concept_id")
    predicates = kwargs.get("predicates")
    languages = kwargs.get("languages")
    max_relation_ids_per_group = kwargs.get("max_relation_ids_per_group", 25)

    if not concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'concept_id' parameter",
            details={"missing": ["concept_id"]},
            suggestions=["Provide the concept ID to get text relations summary for"],
        )

    actor_scope, denial = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="text summary",
        ignore_untrusted_payload_identity=True,
    )
    if denial is not None:
        return denial
    context_view = _internal_mcp_knowledge_context_view(actor_scope)

    try:
        with _bind_internal_mcp_scoped_assertion_actor(actor_scope):
            return get_text_relations_summary(
                concept_id,
                predicates=predicates,
                languages=languages,
                max_relation_ids_per_group=max_relation_ids_per_group,
                context_view=context_view,
            )
    except Exception as exc:
        return make_error_response(
            "exception",
            f"Failed to summarise text relations: {exc}",
            details={"exception_type": type(exc).__name__},
        )


@_governed_ontology_mutation("upsert_singleton_text_relation")
def _upsert_singleton_text_relation(**kwargs):
    from ...services.text_value_service import upsert_singleton_text_relation
    from ...services.text_relation_predicate_validation_service import (
        TextRelationPredicateResolutionError,
        resolve_text_relation_predicate_for_write,
    )

    concept_id = kwargs.get("concept_id")
    predicate = kwargs.get("predicate")
    text = kwargs.get("text")
    language = kwargs.get("language", "en-NZ")
    policy = kwargs.get("policy", "replace_others")
    garbage_collect = kwargs.get("garbage_collect")
    provenance = kwargs.get("provenance")
    context = kwargs.get("context")

    if not concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'concept_id' parameter",
            details={"missing": ["concept_id"]},
            suggestions=["Provide the concept ID to attach text to"],
        )
    if not predicate:
        return make_error_response(
            "missing_parameter",
            "Missing 'predicate' parameter",
            details={"missing": ["predicate"]},
            suggestions=["Provide a predicate like 'hasContent' or 'hasDescription'"],
        )
    if not text:
        return make_error_response(
            "missing_parameter",
            "Missing 'text' parameter",
            details={"missing": ["text"]},
            suggestions=["Provide the text content to attach"],
        )

    try:
        predicate_resolution = resolve_text_relation_predicate_for_write(predicate)
        result = upsert_singleton_text_relation(
            subject_concept_id=concept_id,
            predicate=predicate_resolution.storage_predicate,
            text=text,
            lang=language,
            policy=policy,
            provenance=provenance,
            context=context,
            garbage_collect=(
                True if garbage_collect is None else bool(garbage_collect)
            ),
        )
        result["input_predicate"] = predicate_resolution.input_predicate
        result["predicate_concept_id"] = predicate_resolution.predicate_concept_id
        return result
    except TextRelationPredicateResolutionError as exc:
        return make_error_response(
            exc.error_code,
            str(exc),
            details=exc.details,
            suggestions=exc.suggestions,
        )
    except Exception as exc:
        return make_error_response(
            "exception",
            f"Failed to upsert singleton text relation: {exc}",
            details={"exception_type": type(exc).__name__},
        )


