@_governed_ontology_mutation("add_names_to_concept")
def _add_names_to_concept(**kwargs):
    from ...services.text_value_service import upsert_text_for_concept
    from ...db.repositories.concepts_repository import ConceptsRepository

    concept_id = kwargs.get("concept_id")
    names = kwargs.get("names")

    if not concept_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'concept_id' parameter",
            details={"missing": ["concept_id"]},
            suggestions=["Provide the concept ID to add names to"],
        )
    if not names or not isinstance(names, list) or len(names) == 0:
        return make_error_response(
            "missing_parameter",
            "Missing or invalid 'names' array",
            details={"missing": ["names"]},
            suggestions=[
                "Provide an array of names, e.g., names=['Name1', 'Name2'] or names=[{name: 'Name', language: 'fr'}]"
            ],
        )

    # Verify concept exists
    concept = ConceptsRepository.find_one({"concept_id": concept_id})
    if not concept:
        return make_error_response(
            "concept_not_found",
            f"Concept '{concept_id}' not found",
            details={"concept_id": concept_id},
            suggestions=[
                "Check the concept ID for typos",
                "Create the concept first using create_concepts",
            ],
            related_concept_ids=[concept_id],
        )

    results = []
    errors = []

    # Process each name
    for idx, name_obj in enumerate(names):
        # Handle both string and dict formats
        if isinstance(name_obj, str):
            name_text = name_obj
            language = "en-NZ"
            name_type = "NL"
        elif isinstance(name_obj, dict):
            name_text = name_obj.get("name")
            language = name_obj.get("language", "en-NZ")
            name_type = name_obj.get("name_type", "NL")
        else:
            errors.append({"index": idx, "error": "Invalid name format"})
            continue

        if not name_text or not isinstance(name_text, str) or not name_text.strip():
            errors.append({"index": idx, "error": "Missing or invalid name text"})
            continue

        try:
            result = upsert_text_for_concept(
                subject_concept_id=concept_id,
                predicate="hasName",
                text=name_text.strip(),
                lang=language,
                context={"name_type": name_type},
            )
            if result:
                results.append(
                    {
                        "index": idx,
                        "name": name_text.strip(),
                        "language": language,
                        "name_type": name_type,
                        "text_value_id": str(result["text_value_id"]),
                        "relation_id": str(result["relation_id"]),
                    }
                )
            else:
                errors.append(
                    {"index": idx, "name": name_text, "error": "Failed to add"}
                )
        except Exception as e:
            errors.append({"index": idx, "name": name_text, "error": str(e)})

    return {
        "success": len(errors) == 0,
        "concept_id": concept_id,
        "added_count": len(results),
        "error_count": len(errors),
        "results": results,
        "errors": errors if errors else [],
    }


@_governed_ontology_mutation("add_relationship")
def _add_relationship(**kwargs):
    """Add a relationship between two concepts or from concept to text value."""
    from ...db.repositories.concepts_repository import ConceptsRepository
    from ...services.text_value_service import upsert_text_for_concept
    from ...security.access_control import (
        get_effective_organisation_concept_id,
        get_effective_user_concept_id,
    )
    from .transport import (
        InternalMCPHandlerCancelled,
        raise_if_internal_mcp_cancelled,
    )

    raise_if_internal_mcp_cancelled()

    source_id = kwargs.get("source_id")
    predicate = kwargs.get("predicate")
    predicate_ref = kwargs.get("predicate_ref")
    target = kwargs.get("target")
    predicate_if_missing = kwargs.get("predicate_if_missing")
    predicate_resolution: dict[str, Any] | None = None
    predicate_value_kind = "concept"
    predicate_value_kind_explicit = False
    mutation_dispatched = False
    predicate_dependency: dict[str, Any] | None = None
    predicate_dependency_changed = False
    predicate_dependency_partial_failures: list[dict[str, Any]] = []
    actor_user_id = get_effective_user_concept_id()
    actor_org_id = get_effective_organisation_concept_id()
    raw_namespace = kwargs.get("namespace")
    namespace = (
        raw_namespace.strip()
        if isinstance(raw_namespace, str) and raw_namespace.strip()
        else None
    )

    if predicate_ref is not None:
        if isinstance(predicate, str) and predicate.strip():
            return make_error_response(
                "conflicting_predicate_reference",
                "Provide predicate or predicate_ref, not both.",
                details={"conflicting_fields": ["predicate", "predicate_ref"]},
            )
        if not isinstance(predicate_ref, Mapping):
            return make_error_response(
                "invalid_predicate_reference",
                "predicate_ref must be an object.",
                details={"value_type": type(predicate_ref).__name__},
            )
        reference_concept_id = predicate_ref.get("concept_id")
        reference_name = predicate_ref.get("name")
        has_concept_id = bool(
            isinstance(reference_concept_id, str) and reference_concept_id.strip()
        )
        has_name = bool(isinstance(reference_name, str) and reference_name.strip())
        if has_concept_id == has_name:
            return make_error_response(
                "invalid_predicate_reference",
                ("predicate_ref must provide exactly one of concept_id or name."),
                details={
                    "required_choice": ["concept_id", "name"],
                },
            )
        on_missing = str(predicate_ref.get("on_missing") or "fail").strip().lower()
        if on_missing not in {"fail", "create_typed_predicate"}:
            return make_error_response(
                "invalid_predicate_reference",
                (
                    "predicate_ref.on_missing must be 'fail' or "
                    "'create_typed_predicate'."
                ),
                details={"on_missing": on_missing},
            )
        if has_concept_id and on_missing == "create_typed_predicate":
            return make_error_response(
                "invalid_predicate_reference",
                (
                    "Creating a missing predicate requires predicate_ref.name; "
                    "an exact concept_id reference is resolve-only."
                ),
                details={"on_missing": on_missing},
            )
        raw_predicate_value_kind = predicate_ref.get("value_kind")
        predicate_value_kind_explicit = bool(
            isinstance(raw_predicate_value_kind, str)
            and raw_predicate_value_kind.strip()
        )
        predicate_value_kind = (
            str(raw_predicate_value_kind or "concept").strip().lower()
        )
        if predicate_value_kind not in {"concept", "text"}:
            return make_error_response(
                "invalid_predicate_reference",
                "predicate_ref.value_kind must be 'concept' or 'text'.",
                details={"value_kind": predicate_value_kind},
            )
        if has_concept_id:
            predicate = str(reference_concept_id).strip()
            predicate_resolution = {
                "status": "explicit_concept_id",
                "requested": predicate,
                "resolved_concept_id": predicate,
            }
        else:
            predicate = str(reference_name).strip()
            if on_missing == "create_typed_predicate":
                predicate_if_missing = {
                    "name": predicate,
                    "description": predicate_ref.get("description"),
                    "value_kind": predicate_value_kind,
                }

    def _cancellation_after_predicate_dependency() -> dict[str, Any] | None:
        try:
            raise_if_internal_mcp_cancelled()
        except InternalMCPHandlerCancelled as exc:
            if predicate_dependency is None:
                raise
            dependency_changed = predicate_dependency_changed
            dependency_was_partial = bool(
                dependency_changed or predicate_dependency_partial_failures
            )
            response = make_error_response(
                "relationship_not_started_after_predicate_dependency",
                (
                    "The predicate dependency was resolved, but cancellation "
                    "arrived before the relationship write started."
                ),
                details={
                    "source_id": source_id,
                    "predicate": predicate,
                    "target": target,
                    "cancellation": str(exc),
                },
            )
            response.update(
                {
                    "effect_status": (
                        "partial" if dependency_was_partial else "not_started"
                    ),
                    "changed": dependency_changed,
                    "mutation_outcome": (
                        "partial" if dependency_was_partial else "not_started"
                    ),
                    "outcome_finality": "terminal_for_turn",
                    "predicate_dependency": predicate_dependency,
                    "partial_failures": [
                        *predicate_dependency_partial_failures,
                        {
                            "stage": "relationship",
                            "error_code": (
                                "relationship_not_started_after_predicate_dependency"
                            ),
                            "dispatched": False,
                        },
                    ],
                }
            )
            return response
        return None

    if not source_id:
        return make_error_response(
            "missing_parameter",
            "Missing 'source_id' parameter",
            details={"missing": ["source_id"]},
            suggestions=[
                "Provide the source concept ID, e.g., source_id='#V#my_concept'"
            ],
        )
    if not predicate:
        return make_error_response(
            "missing_parameter",
            "Missing predicate parameter or predicate_ref.",
            details={"missing": ["predicate_or_predicate_ref"]},
            suggestions=[
                "Provide predicate, or a predicate_ref with exactly one of "
                "concept_id or name."
            ],
        )
    if not target:
        return make_error_response(
            "missing_parameter",
            "Missing 'target' parameter",
            details={"missing": ["target"]},
            suggestions=["Provide the target concept ID or text value"],
        )

    if source_id == target:
        return make_error_response(
            "relationship_self_reference",
            "Source and target cannot be the same",
            details={"source_id": source_id, "target": target},
            suggestions=["Use different concept IDs for source and target"],
        )

    predicate_dependency_name: str | None = None
    predicate_dependency_description: str | None = None
    if predicate_if_missing is not None:
        if not isinstance(predicate_if_missing, Mapping):
            return make_error_response(
                "invalid_predicate_if_missing",
                "predicate_if_missing must be an object.",
                details={
                    "value_type": type(predicate_if_missing).__name__,
                    "required_fields": ["name"],
                    "optional_fields": ["description", "value_kind"],
                },
            )
        raw_dependency_name = predicate_if_missing.get("name")
        if not isinstance(raw_dependency_name, str) or not raw_dependency_name.strip():
            return make_error_response(
                "invalid_predicate_if_missing",
                "predicate_if_missing.name must be a non-empty string.",
                details={"required_fields": ["name"]},
            )
        predicate_dependency_name = raw_dependency_name.strip()
        raw_dependency_description = predicate_if_missing.get("description")
        if raw_dependency_description is not None and not isinstance(
            raw_dependency_description, str
        ):
            return make_error_response(
                "invalid_predicate_if_missing",
                "predicate_if_missing.description must be a string when supplied.",
                details={
                    "field": "description",
                    "value_type": type(raw_dependency_description).__name__,
                },
            )
        if isinstance(raw_dependency_description, str):
            predicate_dependency_description = (
                raw_dependency_description.strip() or None
            )
        predicate_value_kind = (
            str(predicate_if_missing.get("value_kind") or predicate_value_kind)
            .strip()
            .lower()
        )
        if predicate_value_kind not in {"concept", "text"}:
            return make_error_response(
                "invalid_predicate_if_missing",
                "predicate_if_missing.value_kind must be 'concept' or 'text'.",
                details={"value_kind": predicate_value_kind},
            )

    try:
        repo = ConceptsRepository

        from ...services.relationship_write_service import (
            CORE_RELATIONSHIP_TEXT_PREDICATES,
            add_relationship,
            is_structural_predicate,
            normalise_structural_predicate,
            resolve_existing_predicate_value_kind,
            validate_predicate_concept,
        )
        from ...utils.concept_id_utils import canonicalise_vontology_concept_id

        # Check if source exists
        src = repo.find_one({"concept_id": source_id})
        if not src:
            return make_error_response(
                "source_concept_not_found",
                f"Source concept '{source_id}' not found",
                details={"role": "source", "concept_id": source_id},
                suggestions=[
                    "Create the source concept first using create_concepts",
                    "Check the concept ID for typos",
                ],
                related_concept_ids=[source_id],
            )

        # Common text predicates are frequently provided either as plain predicate IDs
        # (e.g. 'hasContent') or V-prefixed IDs (e.g. '#V#hasContent'). Treat these
        # as text relations without requiring a predicate concept to exist.
        predicate_str = (
            predicate.strip() if isinstance(predicate, str) else str(predicate)
        )
        predicate_str = normalise_structural_predicate(predicate_str)
        predicate_normalised = (
            predicate_str[3:] if predicate_str.startswith("#V#") else predicate_str
        )
        well_known_text_predicates = CORE_RELATIONSHIP_TEXT_PREDICATES
        if (
            not predicate_str.startswith("#V#")
            and predicate_normalised not in well_known_text_predicates
            and not is_structural_predicate(predicate_str)
        ):
            from ...services.concept_resolution_service import (
                resolve_concept_by_name,
            )

            resolution_payload = resolve_concept_by_name(
                name=predicate_str,
                instance_of="#V#predicate",
                match_code_strings=False,
                max_results=5,
            )
            resolution_status = str(
                resolution_payload.get("status") or "not_found"
            ).strip()
            resolved_predicate_id = resolution_payload.get("resolved_concept_id")
            predicate_resolution = {
                "status": resolution_status,
                "requested": predicate_str,
                "resolved_concept_id": resolved_predicate_id,
                "match": resolution_payload.get("match"),
                "candidates": list(resolution_payload.get("candidates") or [])[:5],
            }
            if (
                resolution_status == "resolved"
                and isinstance(resolved_predicate_id, str)
                and resolved_predicate_id.startswith("#V#")
            ):
                predicate_str = resolved_predicate_id
                predicate_normalised = predicate_str[3:]
            elif resolution_status == "ambiguous":
                candidates = list(resolution_payload.get("candidates") or [])[:5]
                response = make_error_response(
                    "predicate_reference_ambiguous",
                    (
                        "The predicate name identifies more than one accessible "
                        "predicate. Select one exact concept ID."
                    ),
                    details={
                        "predicate": predicate_str,
                        "candidates": candidates,
                    },
                )
                response.update(
                    {
                        "effect_status": "not_started",
                        "changed": False,
                        "mutation_outcome": "not_started",
                        "predicate_resolution": predicate_resolution,
                        "recovery_affordances": [
                            {
                                "action_type": "retry_with_predicate_concept_id",
                                "predicate_ref": {
                                    "concept_id": candidate.get("concept_id")
                                },
                            }
                            for candidate in candidates
                            if isinstance(candidate, Mapping)
                            and isinstance(candidate.get("concept_id"), str)
                        ],
                    }
                )
                return response
            elif predicate_dependency_name is not None:
                canonical_new_predicate_id = canonicalise_vontology_concept_id(
                    predicate_dependency_name
                )
                if canonical_new_predicate_id is None:
                    return make_error_response(
                        "predicate_reference_not_canonicalisable",
                        (
                            "The requested predicate name cannot form a canonical "
                            "Vontology concept ID."
                        ),
                        details={"predicate": predicate_dependency_name},
                    )
                predicate_str = canonical_new_predicate_id
                predicate_normalised = predicate_str[3:]
                predicate_resolution.update(
                    {
                        "status": "not_found_create_requested",
                        "resolved_concept_id": predicate_str,
                    }
                )
            else:
                canonical_missing_predicate_id = canonicalise_vontology_concept_id(
                    predicate_str
                )
                recovery_affordances: list[dict[str, Any]] = [
                    {
                        "action_type": "resolve_exact_predicate",
                        "sequence_step": 1,
                        "tool": "resolve_concept_by_name",
                        "arguments": {
                            "name": predicate_str,
                            "instance_of": "#V#predicate",
                            "match_code_strings": False,
                            "max_results": 5,
                        },
                    }
                ]
                recoverable_object_kind: str | None = None
                recovery_limit: dict[str, str] | None = None
                target_concept_id = (
                    str(target).strip()
                    if isinstance(target, str)
                    and str(target).strip().startswith("#V#")
                    else None
                )
                target_text = (
                    target.strip()
                    if isinstance(target, str) and target.strip()
                    else None
                )
                if predicate_value_kind_explicit and predicate_value_kind == "text":
                    recoverable_object_kind = "text"
                elif target_concept_id is not None:
                    recoverable_object_kind = "concept"
                elif (
                    predicate_value_kind_explicit
                    and predicate_value_kind == "concept"
                ):
                    recovery_limit = {
                        "reason_code": "relationship_target_concept_not_verified",
                        "message": (
                            "The requested predicate is concept-valued, but the "
                            "target is not one verified exact concept ID. Resolve "
                            "or create the target before creating a predicate or "
                            "retrying the relationship."
                        ),
                    }
                elif target_text is not None:
                    recoverable_object_kind = "text"
                else:
                    recovery_limit = {
                        "reason_code": "predicate_object_kind_not_safely_inferable",
                        "message": (
                            "The missing predicate's object kind cannot be inferred "
                            "safely from this request. Resolve the predicate first; "
                            "no predicate creation or relationship retry is "
                            "advertised until its concept-or-text kind is known."
                        ),
                    }

                if canonical_missing_predicate_id is None:
                    recovery_limit = {
                        "reason_code": "predicate_concept_id_not_canonicalisable",
                        "message": (
                            "The missing predicate name does not yield one exact "
                            "canonical concept ID, so no creation or relationship "
                            "retry is advertised."
                        ),
                    }
                elif recoverable_object_kind is not None:
                    predicate_parent_id = (
                        "#V#binary_text_predicate"
                        if recoverable_object_kind == "text"
                        else "#V#predicate"
                    )
                    recovery_affordances.extend(
                        [
                            {
                                "action_type": (
                                    "create_singleton_typed_predicate_if_still_missing"
                                ),
                                "sequence_step": 2,
                                "requires_prior_step_status": "not_found",
                                "tool": "create_concepts",
                                "arguments": {
                                    "parent_id": predicate_parent_id,
                                    "concepts": [
                                        {
                                            "name": predicate_str,
                                            "concept_id": (
                                                canonical_missing_predicate_id
                                            ),
                                            "kind": "predicate",
                                            "instance_of_type": predicate_parent_id,
                                        }
                                    ],
                                    "duplicate_resolution_mode": (
                                        _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY
                                    ),
                                },
                            },
                            {
                                "action_type": "verify_exact_typed_predicate",
                                "sequence_step": 3,
                                "tool": "fetch_concept",
                                "arguments": {
                                    "concept_id": canonical_missing_predicate_id,
                                    "include_relations_arg1": True,
                                },
                            },
                            {
                                "action_type": (
                                    "retry_exact_relationship_after_verification"
                                ),
                                "sequence_step": 4,
                                "tool": "add_relationship",
                                "arguments": {
                                    "source_id": source_id,
                                    "predicate": canonical_missing_predicate_id,
                                    "target": target,
                                },
                            },
                        ]
                    )

                error_details: dict[str, Any] = {
                    "predicate": predicate_str,
                    "canonical_candidate_predicate_id": (
                        canonical_missing_predicate_id
                    ),
                }
                if recoverable_object_kind is not None:
                    error_details["recoverable_object_kind"] = (
                        recoverable_object_kind
                    )
                if recovery_limit is not None:
                    error_details["recovery_limit"] = recovery_limit
                response = make_error_response(
                    "predicate_reference_not_found",
                    (
                        "No accessible predicate matched that name. The "
                        "relationship was not started."
                    ),
                    details=error_details,
                )
                response.update(
                    {
                        "effect_status": "not_started",
                        "changed": False,
                        "mutation_outcome": "not_started",
                        "predicate_resolution": predicate_resolution,
                        "recovery_affordances": recovery_affordances,
                    }
                )
                return response
        if predicate_dependency_name is not None:
            canonical_dependency_id = canonicalise_vontology_concept_id(
                predicate_dependency_name
            )
            if (
                not predicate_str.startswith("#V#")
                or predicate_normalised in well_known_text_predicates
            ):
                return make_error_response(
                    "predicate_dependency_requires_dynamic_predicate",
                    (
                        "predicate_if_missing can only ensure an exact dynamic "
                        "predicate identified by a #V# concept ID."
                    ),
                    details={
                        "predicate": predicate_str,
                        "canonical_dependency_id": canonical_dependency_id,
                    },
                )
            if canonical_dependency_id != predicate_str:
                return make_error_response(
                    "predicate_dependency_identity_mismatch",
                    (
                        "predicate_if_missing.name does not canonically identify "
                        "the requested predicate."
                    ),
                    details={
                        "predicate": predicate_str,
                        "predicate_if_missing_name": predicate_dependency_name,
                        "canonical_dependency_id": canonical_dependency_id,
                    },
                    related_concept_ids=[predicate_str],
                )

            (
                predicate_is_valid,
                predicate_error_code,
                predicate_error_details,
            ) = validate_predicate_concept(predicate_str, repo)
            if not predicate_is_valid:
                if predicate_error_code != "predicate_concept_not_found":
                    return make_error_response(
                        str(predicate_error_code or "predicate_dependency_invalid"),
                        (
                            "The requested predicate exists but is not a valid "
                            "predicate dependency. It was not changed."
                        ),
                        details={
                            "predicate": predicate_str,
                            "predicate_validation": predicate_error_details or {},
                        },
                        related_concept_ids=[predicate_str],
                    )

                if predicate_value_kind == "concept":
                    target_id = str(target).strip()
                    target_doc = repo.find_one(
                        {"concept_id": target_id},
                        {"concept_id": 1},
                    )
                    if not target_doc:
                        return make_error_response(
                            "target_concept_not_found",
                            (
                                f"Target concept '{target_id}' was not found. The "
                                "predicate dependency and relationship were not "
                                "created."
                            ),
                            details={
                                "role": "target",
                                "concept_id": target_id,
                                "predicate": predicate_str,
                            },
                            suggestions=[
                                "Create or resolve the target concept before retrying "
                                "the relationship."
                            ],
                            related_concept_ids=[target_id],
                        )

                predicate_concept: dict[str, Any] = {
                    "name": predicate_dependency_name,
                    "kind": "predicate",
                }
                if predicate_dependency_description is not None:
                    predicate_concept["description"] = predicate_dependency_description

                mutation_dispatched = True
                try:
                    creation_result = _create_concepts(
                        parent_id=(
                            "#V#binary_text_predicate"
                            if predicate_value_kind == "text"
                            else "#V#predicate"
                        ),
                        concepts=[predicate_concept],
                        duplicate_resolution_mode=(
                            _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY
                        ),
                        namespace=namespace,
                        created_by_concept_id=actor_user_id,
                        organisation_concept_id=actor_org_id,
                    )
                except InternalMCPHandlerCancelled:
                    raise
                except Exception as exc:
                    response = _indeterminate_effect_error(
                        (
                            "Predicate dependency creation raised unexpectedly; "
                            "the predicate may already exist. The relationship was "
                            "not attempted."
                        ),
                        details={
                            "stage": "predicate_dependency_creation",
                            "predicate": predicate_str,
                            "source_id": source_id,
                            "target": target,
                            "exception_type": type(exc).__name__,
                            "exception": str(exc),
                        },
                    )
                    response["predicate_dependency"] = {
                        "concept_id": predicate_str,
                        "name": predicate_dependency_name,
                        "status": "indeterminate",
                        "verified": False,
                        "changed": None,
                    }
                    return response

                if (
                    creation_result.get("effect_status") == "indeterminate"
                    or creation_result.get("changed") is None
                ):
                    response = _indeterminate_effect_error(
                        (
                            "Predicate dependency creation has an indeterminate "
                            "outcome. The relationship was not attempted."
                        ),
                        details={
                            "stage": "predicate_dependency_creation",
                            "predicate": predicate_str,
                            "source_id": source_id,
                            "target": target,
                            "creation_result": creation_result,
                        },
                    )
                    response["predicate_dependency"] = {
                        "concept_id": predicate_str,
                        "name": predicate_dependency_name,
                        "status": "indeterminate",
                        "verified": False,
                        "changed": None,
                        "creation_result": creation_result,
                    }
                    return response

                predicate_dependency_changed = creation_result.get("changed") is True
                creation_effect_status = str(
                    creation_result.get("effect_status") or ""
                ).strip()
                predicate_dependency = {
                    "concept_id": predicate_str,
                    "name": predicate_dependency_name,
                    "status": "unverified",
                    "verified": False,
                    "changed": predicate_dependency_changed,
                    "creation_result": creation_result,
                }
                if creation_effect_status == "partial" or not creation_result.get(
                    "success"
                ):
                    predicate_dependency_partial_failures.append(
                        {
                            "stage": "predicate_dependency",
                            "error_code": (
                                creation_result.get("error_code")
                                or "predicate_dependency_creation_partial"
                            ),
                            "details": creation_result,
                        }
                    )
                (
                    predicate_is_valid,
                    predicate_error_code,
                    predicate_error_details,
                ) = validate_predicate_concept(predicate_str, repo)
                if not predicate_is_valid:
                    response = make_error_response(
                        (
                            "predicate_dependency_verification_failed"
                            if creation_result.get("success")
                            else "predicate_dependency_creation_failed"
                        ),
                        (
                            "The predicate dependency could not be verified after "
                            "the canonical create/reuse attempt. The relationship "
                            "was not attempted."
                        ),
                        details={
                            "predicate": predicate_str,
                            "predicate_validation_error": predicate_error_code,
                            "predicate_validation": predicate_error_details or {},
                            "creation_result": creation_result,
                        },
                        related_concept_ids=[predicate_str],
                    )
                    response.update(
                        {
                            "effect_status": (
                                "partial" if predicate_dependency_changed else "failed"
                            ),
                            "changed": predicate_dependency_changed,
                            "predicate_dependency": predicate_dependency,
                        }
                    )
                    if predicate_dependency_partial_failures:
                        response["partial_failures"] = list(
                            predicate_dependency_partial_failures
                        )
                    return response

                predicate_dependency.update(
                    {
                        "status": (
                            "created"
                            if predicate_dependency_changed
                            else "reused_existing"
                        ),
                        "verified": True,
                    }
                )
            else:
                predicate_dependency = {
                    "concept_id": predicate_str,
                    "name": predicate_dependency_name,
                    "status": "reused_existing",
                    "verified": True,
                    "changed": False,
                }

        if predicate_normalised in well_known_text_predicates:
            target_text = target if isinstance(target, str) else str(target)
            if cancellation_response := _cancellation_after_predicate_dependency():
                return cancellation_response
            mutation_dispatched = True
            result = upsert_text_for_concept(
                subject_concept_id=source_id,
                predicate=predicate_normalised,
                text=target_text,
                lang="en",
                provenance={"source": "add_relationship"},
            )
            return {
                "success": True,
                "effect_status": "succeeded",
                "changed": bool(
                    result.get("relation_created") or result.get("context_updated")
                ),
                "relationship_type": "text_relation",
                "source_id": source_id,
                "predicate": predicate_normalised,
                "predicate_input": predicate,
                "target": target_text,
                "text_value_id": str(result.get("text_value_id")),
                "relation_id": str(result.get("relation_id")),
                **(
                    {"predicate_dependency": predicate_dependency}
                    if predicate_dependency is not None
                    else {}
                ),
                **(
                    {"predicate_resolution": predicate_resolution}
                    if predicate_resolution is not None
                    else {}
                ),
            }

        is_text_predicate = (
            resolve_existing_predicate_value_kind(predicate_str, repo) == "text"
        )

        # Handle text predicates (target is text value, not concept)
        if is_text_predicate:
            if cancellation_response := _cancellation_after_predicate_dependency():
                return cancellation_response
            mutation_dispatched = True
            result = upsert_text_for_concept(
                subject_concept_id=source_id,
                predicate=predicate_str,
                text=target,
                lang="en",
                provenance={"source": "add_relationship"},
            )
            return {
                "success": True,
                "effect_status": "succeeded",
                "changed": bool(
                    result.get("relation_created") or result.get("context_updated")
                ),
                "relationship_type": "text_relation",
                "source_id": source_id,
                "predicate": predicate_str,
                "target": target,
                "text_value_id": str(result.get("text_value_id")),
                "relation_id": str(result.get("relation_id")),
                **(
                    {"predicate_dependency": predicate_dependency}
                    if predicate_dependency is not None
                    else {}
                ),
                **(
                    {"predicate_resolution": predicate_resolution}
                    if predicate_resolution is not None
                    else {}
                ),
            }

        # Concept-to-concept relationships use the single authoritative pathway.
        if cancellation_response := _cancellation_after_predicate_dependency():
            return cancellation_response
        mutation_dispatched = True
        result = add_relationship(
            source_id=source_id,
            predicate=predicate_str,
            target=target,
            repo=repo,
            # The governed effect authorises the exact assertion on the source.
            # A visible target is a referent, not a second mutation subject;
            # incoming traversal is served by the derived relationship extent.
            maintain_inverse=False,
        )

        if not result.get("success"):
            error_code = result.get("error") or "relationship_add_failed"
            response = make_error_response(
                str(error_code),
                str(error_code),
                details={
                    "source_id": source_id,
                    "predicate": predicate_str,
                    "target": target,
                    "details": result,
                },
                related_concept_ids=(
                    [source_id, target] if target.startswith("#V#") else [source_id]
                ),
            )
            if predicate_dependency is not None:
                response["predicate_dependency"] = predicate_dependency
            if predicate_resolution is not None:
                response["predicate_resolution"] = predicate_resolution
            if predicate_dependency_changed or predicate_dependency_partial_failures:
                response.update(
                    {
                        "effect_status": "partial",
                        "changed": predicate_dependency_changed,
                        "mutation_outcome": "partial",
                        "message": (
                            (
                                "The predicate dependency persisted, but the "
                                "relationship was not added."
                            )
                            if predicate_dependency_changed
                            else (
                                "Predicate dependency resolution reported a "
                                "partial failure, and the relationship was not "
                                "added."
                            )
                        ),
                        "partial_failures": [
                            *predicate_dependency_partial_failures,
                            {
                                "stage": "relationship",
                                "error_code": str(error_code),
                                "details": result,
                            },
                        ],
                    }
                )
            return response

        predicate_out = result.get("predicate") or predicate_str
        target_out = result.get("target_id") or target
        response: dict[str, Any] = {
            "success": True,
            "effect_status": (
                "partial" if result.get("inverse_error") else "succeeded"
            ),
            "relationship_type": "concept_relation",
            "source_id": source_id,
            "predicate": predicate_out,
            "predicate_input": predicate,
            "target": target_out,
            "added": bool(
                result.get("forward_modified")
                if "forward_modified" in result
                else result.get("modified")
            ),
        }
        response["changed"] = bool(response["added"] or predicate_dependency_changed)
        if predicate_dependency is not None:
            response["predicate_dependency"] = predicate_dependency
        if predicate_resolution is not None:
            response["predicate_resolution"] = predicate_resolution
        if "inverse_predicate" in result or "inverse_modified" in result:
            response["inverse"] = {
                "predicate": result.get("inverse_predicate"),
                "added": result.get("inverse_modified"),
            }
        # Propagate warning from service layer (e.g. vacuous typing, JVNAUTOSCI-1010)
        if "warning" in result:
            response["warning"] = result["warning"]
        if result.get("inverse_error"):
            response["partial_failures"] = [
                {
                    "stage": "inverse_relationship",
                    "error": str(result["inverse_error"]),
                }
            ]
        if predicate_dependency_partial_failures:
            response["effect_status"] = "partial"
            response["partial_failures"] = [
                *predicate_dependency_partial_failures,
                *list(response.get("partial_failures") or []),
            ]
        return response

    except InternalMCPHandlerCancelled:
        raise
    except Exception as e:
        if not mutation_dispatched:
            return make_error_response(
                "exception",
                f"Failed to prepare relationship: {e}",
                details={
                    "source_id": source_id,
                    "predicate": predicate,
                    "target": target,
                    "exception_type": type(e).__name__,
                },
            )
        response = _indeterminate_effect_error(
            (
                "The relationship operation raised unexpectedly; canonical "
                "state may already have changed."
            ),
            details={
                "source_id": source_id,
                "predicate": predicate,
                "target": target,
                "exception_type": type(e).__name__,
                "exception": str(e),
            },
        )
        if predicate_dependency is not None:
            response["predicate_dependency"] = predicate_dependency
        if predicate_dependency_changed:
            response["changed"] = True
            response["known_changes"] = [
                {
                    "stage": "predicate_dependency",
                    "concept_id": (
                        predicate_dependency.get("concept_id")
                        if predicate_dependency is not None
                        else predicate_str
                    ),
                    "changed": True,
                }
            ]
        if predicate_dependency_partial_failures:
            response["partial_failures"] = list(predicate_dependency_partial_failures)
        return response


@_governed_ontology_mutation("remove_relationship")
def _remove_relationship(**kwargs):
    """Remove one concept-to-concept relationship via the canonical service path."""
    from ...services.relationship_removal_service import remove_relationship

    source_id = kwargs.get("source_id")
    predicate = kwargs.get("predicate")
    target = kwargs.get("target")
    relation_id = kwargs.get("relation_id")

    if not relation_id:
        missing: list[str] = []
        if not source_id:
            missing.append("source_id")
        if not predicate:
            missing.append("predicate")
        if not target:
            missing.append("target")
        if missing:
            return make_error_response(
                "missing_parameter",
                "Missing required parameters for remove_relationship",
                details={"missing": missing},
                suggestions=[
                    "Provide relation_id OR provide source_id, predicate, and target",
                ],
            )

    try:
        return remove_relationship(
            relation_id=relation_id,
            source_id=source_id,
            predicate=predicate,
            target=target,
            mode=kwargs.get("mode"),
            cascade=kwargs.get("cascade"),
            dry_run=kwargs.get("dry_run", False),
            confirmed=kwargs.get("confirmed", False),
            operator_override=kwargs.get("operator_override", False),
            reason=kwargs.get("reason"),
            request_id=kwargs.get("request_id"),
        )
    except Exception as e:
        return make_error_response(
            "exception",
            f"Exception: {str(e)}",
            details={
                "source_id": source_id,
                "predicate": predicate,
                "target": target,
                "relation_id": relation_id,
                "exception_type": type(e).__name__,
            },
        )


def _upsert_uncertain_relationship_assertion(**kwargs):
    from ...services.uncertain_relationship_service import (
        upsert_uncertain_relationship_assertion,
    )

    source_id = kwargs.get("source_id")
    predicate = kwargs.get("predicate")
    target = kwargs.get("target")
    confidence_score = kwargs.get("confidence_score")

    missing: list[str] = []
    if not source_id:
        missing.append("source_id")
    if not predicate:
        missing.append("predicate")
    if not target:
        missing.append("target")
    if confidence_score is None:
        missing.append("confidence_score")
    if missing:
        return make_error_response(
            "missing_parameter",
            "Missing required parameters for upsert_uncertain_relationship_assertion",
            details={"missing": missing},
        )

    source_id_text = str(source_id)
    predicate_text = str(predicate)
    target_text = str(target)
    if not isinstance(confidence_score, (int, float, str)):
        return make_error_response(
            "invalid_parameter",
            "confidence_score must be numeric",
            details={"confidence_score": confidence_score},
        )
    confidence_value = float(confidence_score)

    try:
        return upsert_uncertain_relationship_assertion(
            source_id=source_id_text,
            predicate=predicate_text,
            target=target_text,
            confidence_score=confidence_value,
            provenance=kwargs.get("provenance"),
            status=kwargs.get("status", "proposed"),
            assertion_id=kwargs.get("assertion_id"),
            evidence_count=kwargs.get("evidence_count"),
        )
    except Exception as e:
        return make_error_response(
            "exception",
            f"Exception: {str(e)}",
            details={"exception_type": type(e).__name__},
        )


