def _concepts_create_input_schema() -> Schema:
    concept_item_schema = Schema(
        required={"name": str, "kind": str},
        optional={
            "concept_id": (str, type(None)),
            "description": (str, type(None)),
            "notes": (str, type(None)),
            "vontology_path": (str, type(None)),
            "instance_of_type": (str, type(None)),
        },
        enum_values={"kind": ["instance", "type", "predicate"]},
        allow_unknown=False,
        description=(
            "one core concept specification; publication scope belongs in the "
            "top-level scope_mode field and semantic typing belongs in the "
            "top-level parent_id field"
        ),
    )
    return Schema(
        required={
            "parent_id": str,
            "concepts": list,
        },
        optional={
            "collision_resolution_mode": (str, type(None)),
            "duplicate_resolution_mode": (str, type(None)),
            "requested_concept_id": (str, type(None)),
            "namespace": (str, type(None)),
            "scope_mode": (str, type(None)),
            "visibility_scope_mode": (str, type(None)),
            "publication_scope": (str, type(None)),
            "created_by_concept_id": (str, type(None)),
            "organisation_concept_id": (str, type(None)),
        },
        enum_values={
            "collision_resolution_mode": [
                ACTOR_SCOPED_REFERENT_COLLISION_MODE,
                None,
            ],
            "duplicate_resolution_mode": [
                _CREATE_CONCEPTS_DUPLICATE_RESOLUTION_CANONICAL_ID_ONLY,
                None,
            ],
            "scope_mode": [
                _CREATE_CONCEPTS_SCOPE_USER_ONLY,
                _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL,
                _CREATE_CONCEPTS_SCOPE_GLOBAL_GENERAL,
                None,
            ],
            "publication_scope": [
                "private",
                "user_only",
                _CREATE_CONCEPTS_SCOPE_USER_ONLY,
                "organisation",
                "organization",
                _CREATE_CONCEPTS_SCOPE_ORGANISATION_GENERAL,
                "organization_general",
                "org_general",
                "global",
                "public",
                _CREATE_CONCEPTS_SCOPE_GLOBAL_GENERAL,
                None,
            ],
        },
        array_length_constraints={"concepts": (1, 1)},
        array_item_schemas={"concepts": concept_item_schema},
        allow_unknown=True,
        description=(
            "Governed create_concepts input: parent_id is one exact semantic type "
            "concept ID, and concepts must contain exactly one core concept "
            "specification: {name, kind, concept_id?, description?, notes?, "
            "vontology_path?, instance_of_type?}. kind is 'instance' for an "
            "individual, 'type' for a subtype, or 'predicate' for a "
            "relationship type. duplicate_resolution_mode='canonical_id_only' "
            "skips semantic name resolution after an exact concept-ID miss; "
            "omitting it preserves the default semantic duplicate check. A name "
            "match may block a duplicate and return a candidate for inspection, "
            "but it is never silently treated as person identity by this governed "
            "command. This effect idempotently reuses only the exact requested "
            "actor-visible concept. Reuse requires compatible kind and direct or "
            "transitive requested typing, then returns that effective existing ID "
            "and its actual publication context. Requested description, notes, "
            "path, and creation scope are reported as satisfied or unapplied; "
            "reuse never silently mutates them. When an actor-hidden "
            "ID collision prevents an instance create, the failure may advertise "
            f"one executable {ACTOR_SCOPED_REFERENT_RECOVERY_ACTION} action. "
            "Use that action's complete arguments to opt into "
            "collision_resolution_mode='actor_scoped_referent'; the server derives "
            "the actor-private ID from trusted actor context and does not create an "
            "alias or identity/equivalence assertion. Recovery mode treats "
            "requested_concept_id only as an identity seed; it does not inspect or "
            "confirm whether that ID is occupied. This governed "
            "effect does not accept batched concepts, external identity or identity "
            "review fields, attributes, tags, linked concepts, duplicate suffixing, "
            "or multiple parents. Add further classifications or relationships "
            "after creation through separate add_relationship effects using exact "
            "existing predicate IDs. Omit scope_mode for actor-private visibility, "
            "or choose exactly 'user_only_default', 'organisation_general', or "
            "'global_general' according to the intended audience. "
            "publication_scope is a compatibility alias and accepts natural "
            "'organisation'/'organization' values. Conflicting scope fields are "
            "rejected before mutation. The requested "
            "scope succeeds only under the authenticated actor's matching live "
            "authority; denial never silently creates a narrower private concept. "
            "Optional namespace is propagated for tenancy attribution. Unknown "
            "top-level fields remain tolerated for orchestrator-added context but "
            "do not enlarge the governed effect."
        ),
    )


def _concepts_create_output_schema() -> Schema:
    return Schema(
        required={
            "results": list,
            "total": int,
            "successful": int,
        },
        optional={
            "actor_scoped_referent": (dict,),
            "canonical_read_back": (dict,),
            "created_concept_ids": (list,),
            "effective_concept_id": (str, type(None)),
            "scope_selection": (dict,),
            "success": (bool,),
            "effect_status": (str,),
            "changed": (bool, type(None)),
            "idempotent_reuse": (bool,),
            "publication_context": (dict, type(None)),
            "requested_concept_id": (str, type(None)),
            "requested_publication_context": (dict, type(None)),
            "requested_scope_applied": (bool,),
            "requested_scope_satisfied": (bool,),
            "resolved_concept_ids": (list,),
            "reuse_match_source": (str, type(None)),
            "satisfied_fields": (list,),
            "unapplied_fields": (list,),
            "partial_failure_count": (int,),
            "partial_failures": (list,),
            "indeterminate_failure_count": (int,),
            "indeterminate_failures": (list,),
        },
        allow_unknown=True,
        description=(
            "create_concepts output: results, total, and successful describe the "
            "single governed outcome. A compatible actor-visible exact-ID reuse "
            "sets changed=false and idempotent_reuse=true, "
            "returns requested_concept_id, effective_concept_id, "
            "resolved_concept_ids, and the actual publication_context, and names "
            "which ancillary requested fields were satisfied or unapplied. "
            "Actor-scoped collision recovery also returns actor_scoped_referent "
            "metadata that explicitly says no alias or equivalence was asserted."
        ),
    )


