def _add_relationship_input_schema() -> Schema:
    return Schema(
        required={
            "source_id": str,
            "target": str,
        },
        optional={
            "predicate": (str, type(None)),
            "predicate_ref": (dict, type(None)),
            "namespace": (str, type(None)),
        },
        allow_unknown=True,
        description=(
            "Governed add_relationship input: source_id and target plus exactly "
            "one predicate reference. predicate accepts a recognised structural "
            "predicate alias, a core text predicate (hasContent, hasDescription, "
            "or hasName), or an exact existing #V# predicate concept ID. "
            "predicate_ref is an equivalent exact-ID form and supports only "
            "{concept_id: '#V#...'}. Resolve a predicate name first with "
            "resolve_concept_by_name using instance_of='#V#predicate'. If it is "
            "genuinely missing, create one correctly typed predicate through a "
            "separate governed create_concepts effect, verify the returned "
            "concept, then retry add_relationship with its exact ID. This call "
            "does not resolve natural-language predicate names or create "
            "predicate dependencies. A visible concept, including a global "
            "concept with no visibility-owner edge, may be used as the target. "
            "The governed effect mutates only the source assertion; it does not "
            "write an inverse relationship onto the target. Incoming traversal "
            "uses the derived relationship-extent index. A canonical relationship "
            "inherits the source concept's exact publication context and has no "
            "independent scope_mode. For a user- or organisation-audience assertion "
            "about a broader visible concept, use upsert_scoped_assertion instead."
        ),
    )


def _add_relationship_output_schema() -> Schema:
    return Schema(
        required={
            "success": bool,
        },
        optional={
            "relationship_type": (str, type(None)),
            "message": (str, type(None)),
            "source_id": (str, type(None)),
            "predicate": (str, type(None)),
            "target": (str, type(None)),
            "already_existed": (bool, type(None)),
            "added": (bool, type(None)),
            "effect_status": (str, type(None)),
            "changed": (bool, type(None)),
            "partial_failures": (list, type(None)),
            "predicate_dependency": (dict, type(None)),
            "predicate_resolution": (dict, type(None)),
            "recovery_affordances": (list, type(None)),
            "text_value_id": (str, type(None)),
            "relation_id": (str, type(None)),
            "error": (str, type(None)),
            "error_code": (str, type(None)),
            "error_details": (dict, type(None)),
        },
        allow_unknown=True,
        description=(
            "add_relationship output: success, effect_status, changed, edge "
            "details, governed authority receipt and canonical read-back when "
            "available, and typed partial or indeterminate failure evidence."
        ),
    )


