# RAG Tool Handlers and Schemas
def _resolve_rag_namespace_from_kwargs(kwargs: dict) -> dict:
    """Resolve namespace for RAG tools and report provenance.

    SECURITY: Do not infer namespaces from arbitrary client-provided user ids.
    Prefer explicit namespace (tool payload) and allow an env default for dev.
    """

    import os
    import re

    def _normalise_concept_id(value: Any) -> str | None:
        if not isinstance(value, str):
            return None
        cleaned = value.strip()
        if not cleaned:
            return None
        if cleaned.startswith("#v#"):
            return "#V#" + cleaned[3:]
        if cleaned.startswith("#V#"):
            return cleaned
        return f"#V#{cleaned.lstrip('#')}"

    def _namespace_slug_from_concept(value: str | None) -> str | None:
        if not isinstance(value, str):
            return None
        slug = value.strip()
        if not slug:
            return None
        if slug.startswith("#V#"):
            slug = slug[3:]
        if "@" in slug:
            slug = slug.split("@", 1)[0]
        if "+" in slug:
            slug = slug.split("+", 1)[0]
        slug = re.sub(r"[^a-z0-9]+", "_", slug.strip().lower()).strip("_")
        return slug or None

    raw_namespace = kwargs.get("namespace")
    explicit_namespace: str | None = None
    if isinstance(raw_namespace, str) and raw_namespace.strip():
        explicit_namespace = raw_namespace.strip()
        if explicit_namespace.startswith("#v#"):
            explicit_namespace = "#V#" + explicit_namespace[3:]
        elif not explicit_namespace.startswith("#V#"):
            explicit_namespace = f"#V#{explicit_namespace.lstrip('#')}"

    user_candidate = _normalise_concept_id(kwargs.get("user_concept_id"))
    if user_candidate is None:
        user_candidate = _normalise_concept_id(kwargs.get("user_id"))
    if user_candidate is None:
        user_candidate = _normalise_concept_id(kwargs.get("actor_concept_id"))
    if user_candidate is None:
        user_candidate = _normalise_concept_id(kwargs.get("created_by_concept_id"))
    if user_candidate is None:
        user_payload = kwargs.get("user")
        if isinstance(user_payload, dict):
            user_candidate = _normalise_concept_id(user_payload.get("id"))

    org_candidate = _normalise_concept_id(kwargs.get("organisation_concept_id"))
    if org_candidate is None:
        org_candidate = _normalise_concept_id(kwargs.get("org_id"))
    payload_user_candidate = user_candidate
    payload_org_candidate = org_candidate

    def _derive_namespace_from_components(
        user_component: str | None, organisation_component: str | None
    ) -> str | None:
        if user_component is None:
            return None
        user_slug = _namespace_slug_from_concept(user_component)
        org_slug = _namespace_slug_from_concept(organisation_component)
        if not user_slug:
            return None
        try:
            from ...services.namespace_service import derive_namespace

            return (
                derive_namespace(user_slug, org_slug)
                if org_slug
                else derive_namespace(user_slug)
            )
        except Exception:
            return None

    # If caller provides only namespace, derive component IDs for consistent
    # provenance and cross-flow telemetry fields.
    if explicit_namespace and (user_candidate is None or org_candidate is None):
        try:
            from ...services.namespace_service import parse_namespace

            parsed = parse_namespace(explicit_namespace)
            parsed_user = parsed.get("user_id")
            parsed_org = parsed.get("org_id")
            if user_candidate is None and isinstance(parsed_user, str):
                user_candidate = _normalise_concept_id(parsed_user)
            if org_candidate is None and isinstance(parsed_org, str):
                org_candidate = _normalise_concept_id(parsed_org)
        except Exception:
            pass

    derived_namespace: str | None = _derive_namespace_from_components(
        user_candidate, org_candidate
    )

    def _finalise_report(report: dict[str, Any]) -> dict[str, Any]:
        enriched = dict(report)
        enriched["derived_user_concept_id"] = user_candidate
        enriched["derived_organisation_concept_id"] = org_candidate
        # Canonical aliases used by cross-flow telemetry/reporting.
        enriched["user_concept_id"] = user_candidate
        enriched["organisation_concept_id"] = org_candidate

        try:
            from ...services.namespace_isolation_diagnostics_service import (
                record_namespace_context_observation,
            )

            record_namespace_context_observation(
                flow="internal_mcp.rag.namespace_resolver",
                namespace=enriched.get("namespace"),
                namespace_source=enriched.get("namespace_source"),
                user_concept_id=user_candidate,
                organisation_concept_id=org_candidate,
                mismatch_detected=bool(enriched.get("namespace_mismatch")),
                details={
                    "namespace_resolution_note": enriched.get(
                        "namespace_resolution_note"
                    ),
                    "provided_namespace": enriched.get("provided_namespace"),
                    "derived_namespace": enriched.get("derived_namespace"),
                },
            )
        except Exception:
            pass

        if bool(enriched.get("namespace_mismatch")):
            logger.warning(
                "[NAMESPACE] RAG resolver mismatch provided=%s derived=%s user=%s org=%s",
                enriched.get("provided_namespace"),
                enriched.get("derived_namespace"),
                user_candidate,
                org_candidate,
            )
        return enriched

    from .gateway import (
        get_internal_mcp_actor_context_source,
        get_internal_mcp_preexisting_actor_context,
    )

    preexisting_actor = get_internal_mcp_preexisting_actor_context()
    actor_context_source = get_internal_mcp_actor_context_source()
    if preexisting_actor is not None:
        trusted_user = _normalise_concept_id(preexisting_actor[0])
        trusted_org = _normalise_concept_id(preexisting_actor[1])
        trusted_namespace = _derive_namespace_from_components(
            trusted_user,
            trusted_org,
        )
        mismatch_fields: list[str] = []
        if (
            payload_user_candidate is not None
            and payload_user_candidate != trusted_user
        ):
            mismatch_fields.append("user_concept_id")
        if payload_org_candidate is not None and payload_org_candidate != trusted_org:
            mismatch_fields.append("organisation_concept_id")
        if explicit_namespace is not None and explicit_namespace != trusted_namespace:
            mismatch_fields.append("namespace")

        user_candidate = trusted_user
        org_candidate = trusted_org
        derived_namespace = trusted_namespace
        if mismatch_fields:
            return _finalise_report(
                {
                    "namespace": None,
                    "namespace_source": "conflict",
                    "namespace_resolution_note": "namespace_mismatch",
                    "namespace_mismatch": True,
                    "mismatch_fields": mismatch_fields,
                    "provided_namespace": explicit_namespace,
                    "derived_namespace": trusted_namespace,
                }
            )
        return _finalise_report(
            {
                "namespace": trusted_namespace,
                "namespace_source": "trusted_actor_context",
                "namespace_resolution_note": "derived_from_trusted_actor",
                "namespace_mismatch": False,
                "provided_namespace": explicit_namespace,
                "derived_namespace": trusted_namespace,
            }
        )

    if actor_context_source == "tool_payload_fallback":
        # The default InternalMCP gateway installs payload identity only as a
        # compatibility context. It is not authentication and must never select
        # another actor's RAG namespace or permissions.
        return _finalise_report(
            {
                "namespace": None,
                "namespace_source": "untrusted_payload_rejected",
                "namespace_resolution_note": ("authenticated_actor_context_required"),
                "namespace_mismatch": False,
                "provided_namespace": explicit_namespace,
                "derived_namespace": None,
            }
        )

    if (
        explicit_namespace
        and derived_namespace
        and explicit_namespace != derived_namespace
    ):
        return _finalise_report(
            {
                "namespace": None,
                "namespace_source": "conflict",
                "namespace_resolution_note": "namespace_mismatch",
                "namespace_mismatch": True,
                "provided_namespace": explicit_namespace,
                "derived_namespace": derived_namespace,
            }
        )

    if explicit_namespace:
        return _finalise_report(
            {
                "namespace": explicit_namespace,
                "namespace_source": "request.namespace",
                "namespace_resolution_note": None,
                "namespace_mismatch": False,
                "provided_namespace": explicit_namespace,
                "derived_namespace": derived_namespace,
            }
        )

    if derived_namespace:
        return _finalise_report(
            {
                "namespace": derived_namespace,
                "namespace_source": "derived.user_org",
                "namespace_resolution_note": "derived_from_user_org",
                "namespace_mismatch": False,
                "provided_namespace": None,
                "derived_namespace": derived_namespace,
            }
        )

    env_ns = os.environ.get("VON_DEFAULT_NAMESPACE")
    if isinstance(env_ns, str) and env_ns.strip():
        return _finalise_report(
            {
                "namespace": env_ns.strip(),
                "namespace_source": "env.VON_DEFAULT_NAMESPACE",
                "namespace_resolution_note": "fallback",
                "namespace_mismatch": False,
                "provided_namespace": None,
                "derived_namespace": derived_namespace,
            }
        )

    return _finalise_report(
        {
            "namespace": None,
            "namespace_source": "missing",
            "namespace_resolution_note": "namespace_required",
            "namespace_mismatch": False,
            "provided_namespace": None,
            "derived_namespace": derived_namespace,
        }
    )


def _rag_namespace_resolution_error(ns_report: dict[str, Any]) -> dict[str, Any] | None:
    namespace = ns_report.get("namespace")
    if isinstance(namespace, str) and namespace.strip():
        return None

    if ns_report.get("namespace_resolution_note") == "namespace_mismatch":
        return {
            "error": "namespace_mismatch",
            "message": (
                "Explicit namespace conflicts with derived user/org namespace; "
                "request was not executed."
            ),
            **ns_report,
            "success": False,
        }

    return {
        "error": "namespace_required",
        "message": "RAG access requires authenticated user context (namespace)",
        **ns_report,
        "success": False,
    }


def _with_rag_provenance(*, payload: dict, item_kind: str, source_system: str) -> dict:
    result = dict(payload)
    user_concept_id = payload.get("user_concept_id")
    if not isinstance(user_concept_id, str) or not user_concept_id.strip():
        user_concept_id = payload.get("derived_user_concept_id")
    organisation_concept_id = payload.get("organisation_concept_id")
    if (
        not isinstance(organisation_concept_id, str)
        or not organisation_concept_id.strip()
    ):
        organisation_concept_id = payload.get("derived_organisation_concept_id")

    provenance = {
        "item_kind": item_kind,
        "source_system": source_system,
        "namespace": payload.get("namespace"),
        "namespace_source": payload.get("namespace_source"),
        "user_concept_id": user_concept_id,
        "organisation_concept_id": organisation_concept_id,
    }
    existing = result.get("provenance")
    if isinstance(existing, dict):
        provenance = {**existing, **provenance}
    result["provenance"] = provenance
    return result


def _classify_turn_execution_failure_mode(item: dict[str, Any]) -> str:
    from ...services.turn_execution_record_service import (
        _classify_turn_execution_failure_mode as _service_classifier,
    )

    return _service_classifier(item)


def _is_likely_failure_to_act(failure_mode: str) -> bool:
    from ...services.turn_execution_record_service import (
        is_turn_execution_likely_failure_to_act,
    )

    return is_turn_execution_likely_failure_to_act(failure_mode)


def _derive_turn_execution_failure_recommendations(
    failure_mode_counts: dict[str, int],
) -> list[str]:
    recommendations: list[str] = []
    mutation_not_executed = int(failure_mode_counts.get("mutation_not_executed", 0))
    failed_or_blocked = int(failure_mode_counts.get("mutation_failed_or_blocked", 0))
    verification_issues = int(
        failure_mode_counts.get("postcondition_inconclusive", 0)
    ) + int(failure_mode_counts.get("unresolved_required_effects", 0))
    false_completion = int(failure_mode_counts.get("false_completion_claim", 0)) + int(
        failure_mode_counts.get("false_completion_gate_state", 0)
    )

    if mutation_not_executed > 0:
        recommendations.append(
            "Inspect the sampled turns to distinguish missing authority, unavailable capability, model abandonment, or failed execution, while preserving bounded strategies that remain available."
        )
    if failed_or_blocked > 0:
        recommendations.append(
            "Surface the specific failure evidence and the bounded recovery or retry options that remain available."
        )
    if verification_issues > 0:
        recommendations.append(
            "Inspect canonical read-back for consequential effects and report uncertainty honestly when evidence is inconclusive."
        )
    if false_completion > 0:
        recommendations.append(
            "Compare the reply with recorded effects and evidence, and make the terminal state reflect the observed outcome."
        )
    if not recommendations:
        recommendations.append(
            "No dominant failure pattern detected in the sampled window. Expand filters or time range to gather more evidence."
        )
    return recommendations


def _turn_execution_failure_mode_priority(failure_mode: str) -> int:
    order = {
        "false_completion_claim": 0,
        "false_completion_gate_state": 1,
        "mutation_not_executed": 2,
        "mutation_failed_or_blocked": 3,
        "unresolved_required_effects": 4,
        "postcondition_inconclusive": 5,
        "unvalidated_completion_claim": 6,
        "partial_unspecified": 7,
        "completed_verified": 8,
        "unknown": 9,
    }
    return order.get(failure_mode, 99)


def _turn_execution_failure_mode_confidence(failure_mode: str) -> str:
    if failure_mode in {
        "false_completion_claim",
        "false_completion_gate_state",
        "mutation_not_executed",
        "mutation_failed_or_blocked",
    }:
        return "high"
    if failure_mode in {
        "unresolved_required_effects",
        "postcondition_inconclusive",
        "unvalidated_completion_claim",
        "partial_unspecified",
    }:
        return "medium"
    return "low"


def _turn_execution_failure_mode_expected_action(failure_mode: str) -> str:
    if failure_mode in {"mutation_not_executed", "mutation_failed_or_blocked"}:
        return "Attempt and complete the required mutation tools, then verify state changes."
    if failure_mode in {"unresolved_required_effects", "postcondition_inconclusive"}:
        return "Run deterministic postcondition checks and require verified satisfied status."
    if failure_mode in {"false_completion_claim", "false_completion_gate_state"}:
        return "Block completion claims until required effects and checks are fully satisfied."
    if failure_mode == "unvalidated_completion_claim":
        return "Validate completion claims against execution evidence before narrating success."
    return "Preserve deterministic execution and verification evidence for this turn."


def _turn_execution_failure_mode_observed_action(item: Mapping[str, Any]) -> str:
    decision = item.get("decision")
    decision_text = str(decision).strip() if isinstance(decision, str) else "unknown"
    unresolved = int(item.get("unresolved_effect_count") or 0)
    safe_completion = item.get("safe_to_claim_completion")
    requires_follow_up = bool(item.get("requires_follow_up"))

    return (
        f"decision={decision_text}; unresolved_effect_count={unresolved}; "
        f"safe_to_claim_completion={safe_completion}; requires_follow_up={requires_follow_up}"
    )


def _extract_turn_execution_workflow_candidate_id(raw_value: Any) -> str | None:
    if not isinstance(raw_value, Mapping):
        return None
    for key in (
        "workflow_id",
        "selected_workflow_id",
        "concept_id",
        "candidate_workflow_id",
    ):
        value = raw_value.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def _summarise_turn_execution_tool_invocations(
    raw_tool_invocations: Any,
    *,
    max_items: int = 5,
) -> list[dict[str, Any]]:
    if not isinstance(raw_tool_invocations, list):
        return []

    summary: list[dict[str, Any]] = []
    for raw_entry in raw_tool_invocations:
        if not isinstance(raw_entry, Mapping):
            continue
        tool_name = None
        for key in ("tool", "tool_name", "method"):
            value = raw_entry.get(key)
            if isinstance(value, str) and value.strip():
                tool_name = value.strip()
                break
        status = raw_entry.get("status")
        status_text = (
            status.strip() if isinstance(status, str) and status.strip() else None
        )

        if tool_name is None and status_text is None:
            continue

        entry: dict[str, Any] = {}
        if tool_name is not None:
            entry["tool"] = tool_name
        if status_text is not None:
            entry["status"] = status_text
        for field_name in (
            "call_id",
            "execution_id",
            "effect_id",
            "effect_status",
            "error_code",
            "mutation_outcome",
            "outcome_finality",
            "capability_kind",
            "capability_display_name",
            "execution_method",
            "represented_workflow_id",
            "workflow_id",
            "instance_id",
            "durable_submission_status",
            "final_status",
        ):
            value = raw_entry.get(field_name)
            if isinstance(value, str) and value.strip():
                entry[field_name] = value.strip()
        evidence = raw_entry.get("evidence")
        if isinstance(evidence, Mapping):
            evidence_provenance = (
                evidence.get("provenance")
                if isinstance(evidence.get("provenance"), Mapping)
                else {}
            )
            for field_name in (
                "execution_id",
                "effect_id",
                "effect_status",
                "error_code",
                "mutation_outcome",
                "outcome_finality",
                "workflow_id",
                "instance_id",
                "durable_submission_status",
                "final_status",
            ):
                if field_name in entry:
                    continue
                value = evidence.get(field_name)
                if isinstance(value, str) and value.strip():
                    entry[field_name] = value.strip()
            for field_name in (
                "capability_kind",
                "execution_method",
                "represented_workflow_id",
            ):
                if field_name in entry:
                    continue
                value = evidence_provenance.get(field_name)
                if isinstance(value, str) and value.strip():
                    entry[field_name] = value.strip()
        if isinstance(raw_entry.get("changed"), bool):
            entry["changed"] = raw_entry.get("changed")
        summary.append(entry)
        if len(summary) >= max_items:
            break

    return summary


def _summarise_late_effect_observations(
    raw_observations: Any,
    *,
    max_items: int = 32,
) -> tuple[list[dict[str, Any]], int]:
    """Return an actor-safe bounded receipt projection for late effects."""

    if not isinstance(raw_observations, list):
        return [], 0

    summary: list[dict[str, Any]] = []
    for raw_entry in raw_observations[-max_items:]:
        if not isinstance(raw_entry, Mapping):
            continue
        entry = {
            key: raw_entry.get(key)
            for key in (
                "schema_version",
                "observation_id",
                "effect_id",
                "execution_id",
                "call_id",
                "capability_name",
                "method_name",
                "outcome",
                "effect_status",
                "changed",
                "observed_at_utc",
                "output_schema_validation",
                "output_schema_valid",
                "output_schema_error",
                "payload_truncated",
                "payload_redacted",
                "storage_transformed",
                "error_type",
                "error",
            )
            if key in raw_entry
        }
        payload = raw_entry.get("payload")
        if isinstance(payload, Mapping):
            entry["receipt"] = {
                key: payload.get(key)
                for key in (
                    "success",
                    "status",
                    "effect_status",
                    "changed",
                    "error",
                    "error_code",
                    "mutation_outcome",
                    "partial_failures",
                )
                if key in payload
            }
        summary.append(entry)
    return summary, len(raw_observations)


def _summarise_effect_observation_journal(
    raw_journal: Any,
    *,
    max_items: int = 32,
) -> tuple[list[dict[str, Any]], int]:
    """Return a bounded mechanical lifecycle projection for ordinary effects."""

    if not isinstance(raw_journal, Mapping):
        return [], 0
    items = [
        (str(effect_id), value)
        for effect_id, value in raw_journal.items()
        if isinstance(effect_id, str) and isinstance(value, Mapping)
    ]
    summary: list[dict[str, Any]] = []
    for effect_id, raw_entry in items[-max_items:]:
        identity = (
            raw_entry.get("identity")
            if isinstance(raw_entry.get("identity"), Mapping)
            else {}
        )
        entry: dict[str, Any] = {
            "schema_version": identity.get("schema_version"),
            "effect_id": effect_id,
        }
        for field_name in ("call_id", "capability_name", "created_at_utc"):
            if field_name in identity:
                entry[field_name] = identity.get(field_name)

        available_phases: list[str] = []
        for phase_name in (
            "dispatch_intent",
            "turn_terminal",
            "current_state_observation",
            "late_terminal",
            "canonical_reconciliation",
        ):
            raw_phase = raw_entry.get(phase_name)
            if not isinstance(raw_phase, Mapping):
                continue
            available_phases.append(phase_name)
            phase_projection = {
                key: raw_phase.get(key)
                for key in (
                    "schema_version",
                    "phase",
                    "recorded_at_utc",
                    "dispatch_state",
                    "execution_id",
                    "outcome",
                    "status",
                    "verified",
                    "effect_status",
                    "changed",
                    "initial_effect_status",
                    "current_outcome_status",
                    "outcome_resolved",
                    "reconciliation_basis",
                    "observation_identity_sha256",
                    "method_name",
                    "read_method_name",
                    "read_call_id",
                    "receipt_id",
                    "intent_fingerprint",
                    "target_concept_ids",
                    "canonical_scope",
                    "evidence_id",
                    "output_schema_validation",
                    "output_schema_valid",
                    "payload_truncated",
                    "error_type",
                    "error",
                )
                if key in raw_phase
            }
            transport = raw_phase.get("transport")
            if isinstance(transport, Mapping):
                phase_projection["transport"] = {
                    key: transport.get(key)
                    for key in (
                        "execution_id",
                        "outcome",
                        "timeout_sec",
                        "configured_hard_timeout_sec",
                        "minimum_execution_window_sec",
                        "timeout_phase",
                        "late_result_policy",
                    )
                    if key in transport
                }
            receipt = raw_phase.get("receipt")
            if not isinstance(receipt, Mapping):
                payload = raw_phase.get("payload")
                receipt = payload if isinstance(payload, Mapping) else None
            if isinstance(receipt, Mapping):
                phase_projection["receipt"] = {
                    key: receipt.get(key)
                    for key in (
                        "success",
                        "status",
                        "effect_status",
                        "changed",
                        "error",
                        "error_code",
                        "mutation_outcome",
                        "partial_failures",
                    )
                    if key in receipt
                }
            entry[phase_name] = phase_projection
        entry["historical_phases"] = list(available_phases)
        entry["available_phases"] = available_phases
        recorded_phases = [
            phase_name
            for phase_name in available_phases
            if str(raw_entry.get(phase_name, {}).get("recorded_at_utc") or "")
        ]
        entry["latest_phase"] = (
            max(
                recorded_phases,
                key=lambda phase_name: str(
                    raw_entry.get(phase_name, {}).get("recorded_at_utc") or ""
                ),
            )
            if recorded_phases
            else (available_phases[-1] if available_phases else None)
        )
        # Keep each immutable receipt visible above.  Current outcome is only a
        # derived actor-safe projection, with exact canonical read-back taking
        # precedence over earlier transport and turn-terminal observations.
        current_phase = next(
            (
                phase_name
                for phase_name in (
                    "canonical_reconciliation",
                    "late_terminal",
                    "current_state_observation",
                    "turn_terminal",
                )
                if isinstance(raw_entry.get(phase_name), Mapping)
            ),
            None,
        )
        current_raw = raw_entry.get(current_phase) if current_phase else None
        current_projection = entry.get(current_phase) if current_phase else None
        entry["current_outcome"] = (
            dict(current_projection)
            if isinstance(current_projection, Mapping)
            else None
        )
        outcome_resolved = False
        if current_phase in {
            "canonical_reconciliation",
            "current_state_observation",
        } and isinstance(
            current_raw, Mapping
        ):
            outcome_resolved = (
                current_raw.get("outcome_resolved")
                if isinstance(current_raw.get("outcome_resolved"), bool)
                else bool(
                    current_raw.get("effect_status")
                    not in {None, "indeterminate", "unknown"}
                    and isinstance(current_raw.get("changed"), bool)
                )
            )
        elif current_phase == "late_terminal" and isinstance(current_raw, Mapping):
            late_payload = current_raw.get("payload")
            outcome_resolved = bool(
                current_raw.get("outcome") == "late_success"
                and current_raw.get("effect_status")
                not in {None, "indeterminate", "unknown"}
                and isinstance(late_payload, Mapping)
                and late_payload.get("mutation_outcome") != "unknown"
            )
        elif current_phase == "turn_terminal" and isinstance(current_raw, Mapping):
            transport = current_raw.get("transport")
            receipt = current_raw.get("receipt")
            outcome_resolved = bool(
                isinstance(transport, Mapping)
                and transport.get("outcome") not in {None, "timed_out"}
                and current_raw.get("effect_status")
                not in {None, "indeterminate", "unknown"}
                and isinstance(receipt, Mapping)
                and receipt.get("mutation_outcome") != "unknown"
            )
        entry["outcome_resolved"] = outcome_resolved
        summary.append(entry)
    return summary, len(items)


def _extract_turn_execution_tool_invocation_summary(
    item: Mapping[str, Any],
) -> list[dict[str, Any]]:
    existing_summary = item.get("tool_invocation_summary")
    if isinstance(existing_summary, list):
        return _summarise_turn_execution_tool_invocations(existing_summary)

    direct_invocations = item.get("tool_invocations")
    if isinstance(direct_invocations, list):
        return _summarise_turn_execution_tool_invocations(direct_invocations)

    execution_raw = item.get("execution")
    execution = execution_raw if isinstance(execution_raw, Mapping) else {}
    return _summarise_turn_execution_tool_invocations(execution.get("tool_invocations"))


def _extract_turn_execution_selector_intended_workflow_id(
    item: Mapping[str, Any],
) -> str | None:
    workflow_routing_diagnostics_raw = item.get("workflow_routing_diagnostics")
    workflow_routing_diagnostics = (
        workflow_routing_diagnostics_raw
        if isinstance(workflow_routing_diagnostics_raw, Mapping)
        else {}
    )
    selector_raw = workflow_routing_diagnostics.get("selector")
    selector = selector_raw if isinstance(selector_raw, Mapping) else {}

    for candidate in (
        selector.get("selected_model_candidate"),
        selector.get("selection_metadata"),
    ):
        workflow_id = _extract_turn_execution_workflow_candidate_id(candidate)
        if workflow_id:
            return workflow_id

    model_attempts_raw = selector.get("model_attempts")
    model_attempts = model_attempts_raw if isinstance(model_attempts_raw, list) else []
    for raw_attempt in model_attempts:
        if not isinstance(raw_attempt, Mapping):
            continue
        for candidate in (
            raw_attempt,
            raw_attempt.get("selected"),
            raw_attempt.get("response"),
        ):
            workflow_id = _extract_turn_execution_workflow_candidate_id(candidate)
            if workflow_id:
                return workflow_id

    return None


def _extract_turn_execution_dispatch_workflow_id(
    item: Mapping[str, Any],
) -> str | None:
    workflow_routing_diagnostics_raw = item.get("workflow_routing_diagnostics")
    workflow_routing_diagnostics = (
        workflow_routing_diagnostics_raw
        if isinstance(workflow_routing_diagnostics_raw, Mapping)
        else {}
    )
    dispatch_raw = workflow_routing_diagnostics.get("dispatch")
    dispatch = dispatch_raw if isinstance(dispatch_raw, Mapping) else {}
    dispatch_workflow_id = dispatch.get("dispatch_workflow_id")
    if isinstance(dispatch_workflow_id, str) and dispatch_workflow_id.strip():
        return dispatch_workflow_id.strip()
    selected_workflow_id = item.get("selected_workflow_id")
    if isinstance(selected_workflow_id, str) and selected_workflow_id.strip():
        return selected_workflow_id.strip()
    return None


def _has_turn_execution_selector_dispatch_divergence(item: Mapping[str, Any]) -> bool:
    selector_workflow_id = _extract_turn_execution_selector_intended_workflow_id(item)
    dispatch_workflow_id = _extract_turn_execution_dispatch_workflow_id(item)
    if not selector_workflow_id or not dispatch_workflow_id:
        return False
    return selector_workflow_id != dispatch_workflow_id


def _has_turn_execution_weak_follow_up_action(item: Mapping[str, Any]) -> bool:
    tool_summary = _extract_turn_execution_tool_invocation_summary(item)
    tool_names = [
        str(entry.get("tool")).strip().lower()
        for entry in tool_summary
        if isinstance(entry, Mapping)
        and isinstance(entry.get("tool"), str)
        and str(entry.get("tool")).strip()
    ]
    if not tool_names:
        return False
    return all(tool_name == "concept_exists" for tool_name in tool_names)


def _build_turn_execution_replay_case_diagnostic_flags(
    item: Mapping[str, Any],
) -> list[str]:
    flags: list[str] = []
    if _has_turn_execution_selector_dispatch_divergence(item):
        flags.append("selector_dispatch_divergence")
    if _has_turn_execution_weak_follow_up_action(item):
        flags.append("weak_follow_up_action")
    return flags


def _normalise_turn_execution_string_sequence(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    values: list[str] = []
    seen: set[str] = set()
    for raw in value:
        if not isinstance(raw, str):
            continue
        text = raw.strip()
        if not text:
            continue
        lowered = text.lower()
        if lowered in seen:
            continue
        seen.add(lowered)
        values.append(text)
    return values


def _build_turn_execution_episode_critique_lookup(
    *,
    db: Any,
    namespace: Any,
    request_ids: Sequence[str],
) -> dict[str, dict[str, Any]]:
    if not isinstance(namespace, str) or not namespace.strip():
        return {}
    resolved_request_ids = [
        request_id.strip()
        for request_id in request_ids
        if isinstance(request_id, str) and request_id.strip()
    ]
    if not resolved_request_ids:
        return {}
    try:
        coll = db["episode_critique_memories"]
    except Exception:
        return {}

    try:
        cursor = coll.find(
            {
                "namespace": namespace.strip(),
                "request_id": {"$in": resolved_request_ids},
            },
            {
                "_id": 0,
                "memory_id": 1,
                "request_id": 1,
                "workflow_id": 1,
                "verdict": 1,
                "critic_summary_text": 1,
                "improvement_suggestion_count": 1,
                "improvement_suggestion_categories": 1,
                "improvement_target_workflow_ids": 1,
                "improvement_target_tool_names": 1,
            },
        )
    except Exception:
        return {}

    lookup: dict[str, dict[str, Any]] = {}
    for raw in cursor:
        if not isinstance(raw, Mapping):
            continue
        request_id = raw.get("request_id")
        if not isinstance(request_id, str) or not request_id.strip():
            continue
        memory_id_raw = raw.get("memory_id")
        workflow_id_raw = raw.get("workflow_id")
        verdict_raw = raw.get("verdict")
        critic_summary_text_raw = raw.get("critic_summary_text")
        lookup[request_id.strip()] = {
            "memory_id": (
                memory_id_raw.strip()
                if isinstance(memory_id_raw, str) and memory_id_raw.strip()
                else None
            ),
            "request_id": request_id.strip(),
            "workflow_id": (
                workflow_id_raw.strip()
                if isinstance(workflow_id_raw, str) and workflow_id_raw.strip()
                else None
            ),
            "verdict": (
                verdict_raw.strip()
                if isinstance(verdict_raw, str) and verdict_raw.strip()
                else None
            ),
            "critic_summary_text": (
                critic_summary_text_raw.strip()
                if isinstance(critic_summary_text_raw, str)
                and critic_summary_text_raw.strip()
                else None
            ),
            "improvement_suggestion_count": int(
                raw.get("improvement_suggestion_count") or 0
            ),
            "improvement_suggestion_categories": _normalise_turn_execution_string_sequence(
                raw.get("improvement_suggestion_categories")
            ),
            "improvement_target_workflow_ids": _normalise_turn_execution_string_sequence(
                raw.get("improvement_target_workflow_ids")
            ),
            "improvement_target_tool_names": _normalise_turn_execution_string_sequence(
                raw.get("improvement_target_tool_names")
            ),
        }
    return lookup


def _build_turn_execution_follow_up_summary_by_request_id(
    items: Sequence[Mapping[str, Any]],
) -> dict[str, dict[str, Any]]:
    grouped: dict[str, list[Mapping[str, Any]]] = {}
    for item in items:
        session_id = (
            item.get("chat_session_id")
            if isinstance(item.get("chat_session_id"), str)
            else item.get("session_id")
        )
        if not isinstance(session_id, str) or not session_id.strip():
            continue
        grouped.setdefault(session_id.strip(), []).append(item)

    summaries: dict[str, dict[str, Any]] = {}
    for session_items in grouped.values():
        ordered = sorted(
            session_items,
            key=lambda item: (
                str(item.get("created_at_utc") or ""),
                str(item.get("request_id") or ""),
            ),
        )
        group_keys: list[str | None] = []
        for item in ordered:
            selected_workflow_id_raw = item.get("selected_workflow_id")
            selected_workflow_id = (
                selected_workflow_id_raw.strip()
                if isinstance(selected_workflow_id_raw, str)
                and selected_workflow_id_raw.strip()
                else None
            )
            group_keys.append(
                _extract_turn_execution_selector_intended_workflow_id(item)
                or _extract_turn_execution_dispatch_workflow_id(item)
                or selected_workflow_id
            )
        for index, item in enumerate(ordered):
            request_id = item.get("request_id")
            if not isinstance(request_id, str) or not request_id.strip():
                continue
            group_key = group_keys[index]
            if not isinstance(group_key, str) or not group_key.strip():
                continue
            follow_up_item: Mapping[str, Any] | None = None
            for later_index in range(index + 1, len(ordered)):
                if group_keys[later_index] != group_key:
                    continue
                follow_up_item = ordered[later_index]
                break
            if follow_up_item is None:
                continue
            follow_up_request_id = follow_up_item.get("request_id")
            if (
                not isinstance(follow_up_request_id, str)
                or not follow_up_request_id.strip()
            ):
                continue
            follow_up_tool_invocation_summary = (
                _extract_turn_execution_tool_invocation_summary(follow_up_item)
            )
            follow_up_weak_follow_up_action = _has_turn_execution_weak_follow_up_action(
                follow_up_item
            )
            summaries[request_id.strip()] = {
                "available": True,
                "group_key": group_key,
                "follow_up_request_id": follow_up_request_id.strip(),
                "follow_up_created_at_utc": follow_up_item.get("created_at_utc"),
                "follow_up_selector_dispatch_divergence": (
                    _has_turn_execution_selector_dispatch_divergence(follow_up_item)
                ),
                "follow_up_weak_follow_up_action": follow_up_weak_follow_up_action,
                "follow_up_tool_invocation_summary": follow_up_tool_invocation_summary,
                "follow_up_action_strengthened": (
                    _has_turn_execution_weak_follow_up_action(item)
                    and not follow_up_weak_follow_up_action
                    and bool(follow_up_tool_invocation_summary)
                ),
            }
    return summaries


def _build_turn_execution_episode_evaluation_context(
    item: Mapping[str, Any],
    *,
    critique_lookup: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    request_id = item.get("request_id")
    if not isinstance(request_id, str) or not request_id.strip():
        return {"available": False}
    critique_doc = critique_lookup.get(request_id.strip())
    if not isinstance(critique_doc, Mapping):
        return {"available": False}

    selected_workflow_id_raw = item.get("selected_workflow_id")
    selected_workflow_id = (
        selected_workflow_id_raw.strip()
        if isinstance(selected_workflow_id_raw, str)
        and selected_workflow_id_raw.strip()
        else None
    )
    candidate_workflow_ids = {
        workflow_id
        for workflow_id in (
            _extract_turn_execution_selector_intended_workflow_id(item),
            _extract_turn_execution_dispatch_workflow_id(item),
            selected_workflow_id,
        )
        if isinstance(workflow_id, str) and workflow_id.strip()
    }
    critique_workflow_id = critique_doc.get("workflow_id")
    if isinstance(critique_workflow_id, str) and critique_workflow_id.strip():
        candidate_workflow_ids.add(critique_workflow_id.strip())

    targeted_workflow_ids = [
        workflow_id
        for workflow_id in _normalise_turn_execution_string_sequence(
            critique_doc.get("improvement_target_workflow_ids")
        )
        if workflow_id in candidate_workflow_ids
    ]

    tool_names = {
        str(entry.get("tool")).strip().lower()
        for entry in _extract_turn_execution_tool_invocation_summary(item)
        if isinstance(entry, Mapping)
        and isinstance(entry.get("tool"), str)
        and str(entry.get("tool")).strip()
    }
    targeted_tool_names = [
        tool_name
        for tool_name in _normalise_turn_execution_string_sequence(
            critique_doc.get("improvement_target_tool_names")
        )
        if tool_name.lower() in tool_names
    ]

    improvement_suggestion_count = int(
        critique_doc.get("improvement_suggestion_count") or 0
    )
    useful_suggestion_present = improvement_suggestion_count > 0 and bool(
        targeted_workflow_ids or targeted_tool_names
    )
    return {
        "available": True,
        "memory_id": critique_doc.get("memory_id"),
        "verdict": critique_doc.get("verdict"),
        "workflow_id": critique_workflow_id,
        "critic_summary_text": critique_doc.get("critic_summary_text"),
        "improvement_suggestion_count": improvement_suggestion_count,
        "improvement_suggestion_categories": _normalise_turn_execution_string_sequence(
            critique_doc.get("improvement_suggestion_categories")
        ),
        "improvement_target_workflow_ids": _normalise_turn_execution_string_sequence(
            critique_doc.get("improvement_target_workflow_ids")
        ),
        "improvement_target_tool_names": _normalise_turn_execution_string_sequence(
            critique_doc.get("improvement_target_tool_names")
        ),
        "useful_target_workflow_ids": targeted_workflow_ids,
        "useful_target_tool_names": targeted_tool_names,
        "useful_suggestion_present": useful_suggestion_present,
    }


def _build_turn_execution_replay_diagnosis_layers(
    item: Mapping[str, Any],
    *,
    episode_evaluation_context: Mapping[str, Any],
) -> dict[str, Any]:
    selector_intended_workflow_id = (
        _extract_turn_execution_selector_intended_workflow_id(item)
    )
    dispatch_workflow_id = _extract_turn_execution_dispatch_workflow_id(item)
    tool_invocation_summary = _extract_turn_execution_tool_invocation_summary(item)
    routing_diagnosable = bool(selector_intended_workflow_id) and bool(
        dispatch_workflow_id
    )
    action_diagnosable = bool(tool_invocation_summary)
    telemetry_sufficient = (
        routing_diagnosable
        and action_diagnosable
        and isinstance(item.get("request_id"), str)
        and bool(str(item.get("request_id")).strip())
        and isinstance(item.get("decision_reason"), str)
        and bool(str(item.get("decision_reason")).strip())
        and isinstance(item.get("prompt_preview"), str)
        and bool(str(item.get("prompt_preview")).strip())
    )
    episode_evaluation_available = bool(episode_evaluation_context.get("available"))
    return {
        "routing_layer": {
            "diagnosable": routing_diagnosable,
            "selector_intended_workflow_id": selector_intended_workflow_id,
            "dispatch_workflow_id": dispatch_workflow_id,
        },
        "action_layer": {
            "diagnosable": action_diagnosable,
            "tool_invocation_count": len(tool_invocation_summary),
        },
        "telemetry_layer": {
            "diagnosable": telemetry_sufficient,
            "request_id_present": bool(
                isinstance(item.get("request_id"), str)
                and str(item.get("request_id")).strip()
            ),
            "decision_reason_present": bool(
                isinstance(item.get("decision_reason"), str)
                and str(item.get("decision_reason")).strip()
            ),
            "prompt_preview_present": bool(
                isinstance(item.get("prompt_preview"), str)
                and str(item.get("prompt_preview")).strip()
            ),
        },
        "episode_evaluation_layer": {
            "diagnosable": episode_evaluation_available,
            "improvement_suggestion_count": (
                episode_evaluation_context.get("improvement_suggestion_count")
                if episode_evaluation_available
                else 0
            ),
            "useful_suggestion_present": bool(
                episode_evaluation_context.get("useful_suggestion_present")
            ),
        },
    }


def _build_turn_execution_case_id(request_id: Any, index: int) -> str:
    if isinstance(request_id, str) and request_id.strip():
        cleaned_chars: list[str] = []
        for char in request_id.strip():
            if char.isalnum() or char in {"_", "-"}:
                cleaned_chars.append(char)
            else:
                cleaned_chars.append("_")
        token = "".join(cleaned_chars).strip("_")
        if token:
            return f"turn_exec_{token}"
    return f"turn_exec_case_{index:03d}"


def _normalise_turn_execution_jira_base_url(raw_value: Any) -> str:
    if isinstance(raw_value, str) and raw_value.strip():
        return raw_value.strip().rstrip("/")
    env_value = os.getenv("ATLASSIAN_BASE_URL")
    if isinstance(env_value, str) and env_value.strip():
        return env_value.strip().rstrip("/")
    return _DEFAULT_JIRA_BASE_URL


def _extract_turn_execution_jira_issue_keys_from_text(value: Any) -> list[str]:
    if not isinstance(value, str) or not value.strip():
        return []
    keys: list[str] = []
    seen: set[str] = set()
    for match in _JIRA_ISSUE_KEY_PATTERN.finditer(value):
        project = str(match.group(1)).upper()
        issue_number = str(match.group(2))
        issue_key = f"{project}-{issue_number}"
        if issue_key in seen:
            continue
        seen.add(issue_key)
        keys.append(issue_key)
    return keys


def _extract_turn_execution_jira_issue_keys(item: Mapping[str, Any]) -> list[str]:
    candidate_values = [
        item.get("prompt_preview"),
        item.get("decision_reason"),
    ]
    keys: list[str] = []
    seen: set[str] = set()
    for candidate in candidate_values:
        for issue_key in _extract_turn_execution_jira_issue_keys_from_text(candidate):
            if issue_key in seen:
                continue
            seen.add(issue_key)
            keys.append(issue_key)
    return keys


def _build_turn_execution_case_triage(
    item: Mapping[str, Any],
    *,
    jira_base_url: str,
) -> dict[str, Any]:
    issue_keys = _extract_turn_execution_jira_issue_keys(item)
    browse_urls = [f"{jira_base_url}/browse/{issue_key}" for issue_key in issue_keys]
    request_id = (
        str(item.get("request_id")).strip()
        if isinstance(item.get("request_id"), str)
        else None
    )
    suggested_jql = (
        f'project = JVNAUTOSCI AND text ~ "\\"{request_id}\\""' if request_id else None
    )
    return {
        "jira_issue_keys": issue_keys,
        "jira_browse_urls": browse_urls,
        "suggested_jql": suggested_jql,
    }


def _build_turn_execution_replay_case(
    item: Mapping[str, Any],
    *,
    index: int,
    jira_base_url: str,
    follow_up_context: Mapping[str, Any] | None = None,
    episode_evaluation_context: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    failure_mode = (
        str(item.get("failure_mode")).strip()
        if isinstance(item.get("failure_mode"), str)
        else "unknown"
    )
    request_id = item.get("request_id")
    selector_intended_workflow_id = (
        _extract_turn_execution_selector_intended_workflow_id(item)
    )
    dispatch_workflow_id = _extract_turn_execution_dispatch_workflow_id(item)
    tool_invocation_summary = _extract_turn_execution_tool_invocation_summary(item)
    diagnostic_flags = _build_turn_execution_replay_case_diagnostic_flags(item)
    episode_evaluation = (
        dict(episode_evaluation_context)
        if isinstance(episode_evaluation_context, Mapping)
        else {"available": False}
    )
    follow_up = (
        dict(follow_up_context)
        if isinstance(follow_up_context, Mapping)
        else {"available": False}
    )
    diagnosis_layers = _build_turn_execution_replay_diagnosis_layers(
        item,
        episode_evaluation_context=episode_evaluation,
    )
    return {
        "case_id": _build_turn_execution_case_id(request_id, index),
        "request_id": request_id,
        "session_id": item.get("chat_session_id"),
        "created_at_utc": item.get("created_at_utc"),
        "workflow_id": item.get("selected_workflow_id"),
        "failure_mode": failure_mode,
        "confidence": _turn_execution_failure_mode_confidence(failure_mode),
        "expected_action": _turn_execution_failure_mode_expected_action(failure_mode),
        "observed_action": _turn_execution_failure_mode_observed_action(item),
        "pass_criteria": {
            "action_attempted": True,
            "postcondition_satisfied": True,
            "no_false_success": True,
        },
        "diagnostic_flags": diagnostic_flags,
        "evidence": {
            "decision": item.get("decision"),
            "decision_reason": item.get("decision_reason"),
            "requires_follow_up": item.get("requires_follow_up"),
            "safe_to_claim_completion": item.get("safe_to_claim_completion"),
            "unresolved_effect_count": item.get("unresolved_effect_count"),
            "blocking_effect_ids": (
                item.get("blocking_effect_ids")
                if isinstance(item.get("blocking_effect_ids"), list)
                else []
            ),
            "prompt_preview": item.get("prompt_preview"),
            "selector_intended_workflow_id": selector_intended_workflow_id,
            "dispatch_workflow_id": dispatch_workflow_id,
            "selector_dispatch_divergence": (
                bool(selector_intended_workflow_id)
                and bool(dispatch_workflow_id)
                and selector_intended_workflow_id != dispatch_workflow_id
            ),
            "workflow_discovery": {
                "budget_exhausted": bool(
                    item.get("workflow_discovery_budget_exhausted")
                ),
                "timeout_budget_seconds": item.get(
                    "workflow_discovery_timeout_budget_seconds"
                ),
                "search_time_ms": item.get("workflow_discovery_search_time_ms"),
                "match_absence_reason": item.get(
                    "workflow_discovery_match_absence_reason"
                ),
                "candidate_count": item.get("workflow_discovery_candidate_count"),
                "match_count": item.get("workflow_discovery_match_count"),
            },
            "required_evidence": {
                "declared_effect_count": item.get(
                    "workflow_required_effects_declared_count"
                ),
                "required_tools": (
                    item.get("workflow_required_effects_required_tools")
                    if isinstance(
                        item.get("workflow_required_effects_required_tools"), list
                    )
                    else []
                ),
                "missing_required_tool_count": item.get(
                    "required_evidence_tool_missing_count"
                ),
                "missing_required_tools": (
                    item.get("required_evidence_tool_missing_names")
                    if isinstance(
                        item.get("required_evidence_tool_missing_names"), list
                    )
                    else []
                ),
            },
            "tool_invocation_summary": tool_invocation_summary,
            "terminal_outcome_receipt_projection": (
                dict(
                    cast(
                        Mapping[str, Any],
                        item.get("terminal_outcome_receipt_projection"),
                    )
                )
                if isinstance(item.get("terminal_outcome_receipt_projection"), Mapping)
                else None
            ),
            "weak_follow_up_action": _has_turn_execution_weak_follow_up_action(item),
            "follow_up": follow_up,
            "episode_evaluation": episode_evaluation,
            "diagnosis_layers": diagnosis_layers,
        },
        "triage": _build_turn_execution_case_triage(
            item,
            jira_base_url=jira_base_url,
        ),
    }


def _build_turn_execution_benchmark_fingerprint(
    *,
    filters: Mapping[str, Any],
    replay_cases: Sequence[Mapping[str, Any]],
) -> str:
    import hashlib
    import json

    canonical_payload = {
        "filters": dict(filters),
        "replay_cases": [
            {
                "case_id": case.get("case_id"),
                "request_id": case.get("request_id"),
                "failure_mode": case.get("failure_mode"),
                "workflow_id": case.get("workflow_id"),
            }
            for case in replay_cases
        ],
    }
    encoded = json.dumps(
        canonical_payload,
        sort_keys=True,
        ensure_ascii=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()[:16]


def _build_turn_execution_triage_index(
    replay_cases: Sequence[Mapping[str, Any]],
    *,
    jira_base_url: str,
) -> dict[str, Any]:
    links_by_issue: dict[str, dict[str, Any]] = {}
    request_ids_without_issue_keys: list[str] = []

    for case in replay_cases:
        triage_raw = case.get("triage")
        triage: Mapping[str, Any] = (
            triage_raw if isinstance(triage_raw, Mapping) else {}
        )
        issue_keys_raw_value = triage.get("jira_issue_keys")
        issue_keys_raw = (
            issue_keys_raw_value if isinstance(issue_keys_raw_value, list) else []
        )
        issue_keys = [
            key.strip()
            for key in issue_keys_raw
            if isinstance(key, str) and key.strip()
        ]
        request_id = (
            str(case.get("request_id")).strip()
            if isinstance(case.get("request_id"), str)
            else ""
        )
        case_id = (
            str(case.get("case_id")).strip()
            if isinstance(case.get("case_id"), str)
            else ""
        )

        if not issue_keys and request_id:
            request_ids_without_issue_keys.append(request_id)

        for issue_key in issue_keys:
            entry = links_by_issue.setdefault(
                issue_key,
                {
                    "issue_key": issue_key,
                    "browse_url": f"{jira_base_url}/browse/{issue_key}",
                    "case_ids": [],
                    "request_ids": [],
                },
            )
            if case_id and case_id not in entry["case_ids"]:
                entry["case_ids"].append(case_id)
            if request_id and request_id not in entry["request_ids"]:
                entry["request_ids"].append(request_id)

    issue_links = sorted(
        links_by_issue.values(),
        key=lambda row: str(row.get("issue_key") or ""),
    )
    unique_request_ids_without_issue_keys = list(
        dict.fromkeys(request_ids_without_issue_keys)
    )
    return {
        "jira_base_url": jira_base_url,
        "issue_link_count": len(issue_links),
        "issue_links": issue_links,
        "request_ids_without_issue_keys": unique_request_ids_without_issue_keys,
        "request_ids_without_issue_keys_count": len(
            unique_request_ids_without_issue_keys
        ),
    }


def _safe_float_or_none(value: Any) -> float | None:
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _build_turn_execution_regression_assessment(
    *,
    metrics: Mapping[str, Any],
    baseline_likely_failure_rate_pct: Any,
    baseline_false_success_rate_pct: Any,
    baseline_unresolved_follow_up_rate_pct: Any,
    regression_tolerance_pct: Any,
) -> dict[str, Any]:
    tolerance = _safe_float_or_none(regression_tolerance_pct)
    if tolerance is None or tolerance < 0:
        tolerance = 0.0

    comparisons: list[dict[str, Any]] = []
    regression_detected = False

    def _add_comparison(
        *,
        metric_name: str,
        current_key: str,
        baseline_value_raw: Any,
    ) -> None:
        nonlocal regression_detected
        baseline_value = _safe_float_or_none(baseline_value_raw)
        current_value = _safe_float_or_none(metrics.get(current_key))
        if baseline_value is None or current_value is None:
            return
        delta_pct = round(current_value - baseline_value, 2)
        regressed = delta_pct > tolerance
        if regressed:
            regression_detected = True
        comparisons.append(
            {
                "metric": metric_name,
                "baseline_pct": round(baseline_value, 2),
                "current_pct": round(current_value, 2),
                "delta_pct": delta_pct,
                "regressed": regressed,
            }
        )

    _add_comparison(
        metric_name="likely_failure_rate_pct",
        current_key="likely_failure_rate_pct",
        baseline_value_raw=baseline_likely_failure_rate_pct,
    )
    _add_comparison(
        metric_name="false_success_rate_pct",
        current_key="false_success_rate_pct",
        baseline_value_raw=baseline_false_success_rate_pct,
    )
    _add_comparison(
        metric_name="unresolved_follow_up_rate_pct",
        current_key="unresolved_follow_up_rate_pct",
        baseline_value_raw=baseline_unresolved_follow_up_rate_pct,
    )

    return {
        "baseline_provided": len(comparisons) > 0,
        "regression_tolerance_pct": round(tolerance, 2),
        "regression_detected": regression_detected,
        "comparisons": comparisons,
    }


def _derive_turn_execution_capability_gaps(
    items: Sequence[Mapping[str, Any]],
    *,
    failure_mode_counts: Mapping[str, int],
    replay_diagnostic_metrics: Mapping[str, Any] | None = None,
    workflow_discovery_metrics: Mapping[str, Any] | None = None,
    required_evidence_metrics: Mapping[str, Any] | None = None,
) -> list[dict[str, Any]]:
    gaps: list[dict[str, Any]] = []

    if not items:
        gaps.append(
            {
                "gap_id": "no_turn_execution_records",
                "title": "No turn execution records found in selected window",
                "evidence_count": 0,
                "severity": "high",
                "description": (
                    "Benchmark cannot evaluate failure-to-act rates because no "
                    "turn_execution_records are available for the selected namespace "
                    "and filters."
                ),
            }
        )
        return gaps

    missing_request_id_count = 0
    missing_workflow_selection_count = 0
    missing_prompt_preview_count = 0
    for item in items:
        request_id = item.get("request_id")
        if not isinstance(request_id, str) or not request_id.strip():
            missing_request_id_count += 1
        selected_workflow_id = item.get("selected_workflow_id")
        if (
            not isinstance(selected_workflow_id, str)
            or not selected_workflow_id.strip()
        ):
            missing_workflow_selection_count += 1
        prompt_preview = item.get("prompt_preview")
        if not isinstance(prompt_preview, str) or not prompt_preview.strip():
            missing_prompt_preview_count += 1

    if missing_request_id_count > 0:
        gaps.append(
            {
                "gap_id": "missing_request_id",
                "title": "Turn execution records missing request_id",
                "evidence_count": missing_request_id_count,
                "severity": "high",
                "description": (
                    "Some turn execution records cannot be joined to replay cases because "
                    "request_id is absent."
                ),
            }
        )
    if missing_workflow_selection_count > 0:
        gaps.append(
            {
                "gap_id": "missing_workflow_selection",
                "title": "Turn execution records missing selected_workflow_id",
                "evidence_count": missing_workflow_selection_count,
                "severity": "medium",
                "description": (
                    "Workflow routing metadata is incomplete for part of the corpus, "
                    "which weakens per-workflow reliability breakdowns."
                ),
            }
        )
    if missing_prompt_preview_count > 0:
        gaps.append(
            {
                "gap_id": "missing_prompt_preview",
                "title": "Turn execution records missing prompt preview",
                "evidence_count": missing_prompt_preview_count,
                "severity": "low",
                "description": (
                    "Prompt previews are absent for some records, reducing triage readability."
                ),
            }
        )

    false_success_evidence = int(
        failure_mode_counts.get("false_completion_claim", 0)
    ) + int(failure_mode_counts.get("false_completion_gate_state", 0))
    if false_success_evidence > 0:
        gaps.append(
            {
                "gap_id": "false_success_regressions",
                "title": "False-success completion signals still present",
                "evidence_count": false_success_evidence,
                "severity": "high",
                "description": (
                    "At least one turn indicates completion was claimed while execution "
                    "evidence remained unresolved."
                ),
            }
        )

    unknown_failures = int(failure_mode_counts.get("unknown", 0))
    if unknown_failures > 0:
        gaps.append(
            {
                "gap_id": "unknown_failure_mode",
                "title": "Unclassifiable turn execution outcomes",
                "evidence_count": unknown_failures,
                "severity": "medium",
                "description": (
                    "Some records do not fit current failure-mode taxonomy and should "
                    "be reviewed for schema or classifier extension."
                ),
            }
        )

    discovery_metrics = (
        workflow_discovery_metrics
        if isinstance(workflow_discovery_metrics, Mapping)
        else {}
    )
    discovery_timeout_count = int(discovery_metrics.get("budget_exhausted_count") or 0)
    if discovery_timeout_count > 0:
        gaps.append(
            {
                "gap_id": "workflow_discovery_timeout_learning_candidates",
                "title": "Workflow discovery timeout examples need policy learning",
                "evidence_count": discovery_timeout_count,
                "severity": "high",
                "description": (
                    "At least one turn exhausted the discovery budget. The benchmark "
                    "now reports these as learning candidates so timeout-policy changes "
                    "can be evaluated instead of silently treating the route as normal."
                ),
            }
        )

    evidence_metrics = (
        required_evidence_metrics
        if isinstance(required_evidence_metrics, Mapping)
        else {}
    )
    missing_required_tool_count = int(
        evidence_metrics.get("missing_required_tool_turn_count") or 0
    )
    if missing_required_tool_count > 0:
        gaps.append(
            {
                "gap_id": "grounded_required_evidence_missing",
                "title": "Grounded retrieval workflows missed required evidence tools",
                "evidence_count": missing_required_tool_count,
                "severity": "high",
                "description": (
                    "At least one workflow declared required grounded-evidence tools "
                    "but the turn evidence shows not all of those tools ran."
                ),
            }
        )

    replay_metrics = (
        replay_diagnostic_metrics
        if isinstance(replay_diagnostic_metrics, Mapping)
        else {}
    )
    diagnostic_candidate_case_count = int(
        replay_metrics.get("diagnostic_candidate_case_count") or 0
    )
    telemetry_sufficient_case_count = int(
        replay_metrics.get("telemetry_sufficient_case_count") or 0
    )
    if diagnostic_candidate_case_count > telemetry_sufficient_case_count:
        gaps.append(
            {
                "gap_id": "replay_diagnostic_coverage_incomplete",
                "title": "Replay cases do not preserve enough telemetry to localise the failing layer",
                "evidence_count": (
                    diagnostic_candidate_case_count - telemetry_sufficient_case_count
                ),
                "severity": "medium",
                "description": (
                    "At least one corrective-evidence replay case is missing enough routing/action telemetry to "
                    "separate routing, action choice, and observability failures cleanly."
                ),
            }
        )

    episode_evaluation_available_count = int(
        replay_metrics.get("episode_evaluation_available_count") or 0
    )
    if diagnostic_candidate_case_count > episode_evaluation_available_count:
        gaps.append(
            {
                "gap_id": "missing_episode_evaluation_context_for_replay_cases",
                "title": "Replay cases are missing linked episode-evaluation context",
                "evidence_count": (
                    diagnostic_candidate_case_count - episode_evaluation_available_count
                ),
                "severity": "medium",
                "description": (
                    "At least one corrective-evidence replay case could not be joined to episode-evaluation output, "
                    "so the benchmark cannot show whether the critic/suggestion layer is also failing."
                ),
            }
        )

    episode_evaluation_useful_suggestion_count = int(
        replay_metrics.get("episode_evaluation_useful_suggestion_count") or 0
    )
    if (
        episode_evaluation_available_count > 0
        and episode_evaluation_available_count
        > episode_evaluation_useful_suggestion_count
    ):
        gaps.append(
            {
                "gap_id": "episode_evaluation_suggestions_not_actionable",
                "title": "Some linked episode-evaluation outputs lack useful actionable suggestions",
                "evidence_count": (
                    episode_evaluation_available_count
                    - episode_evaluation_useful_suggestion_count
                ),
                "severity": "low",
                "description": (
                    "The critic layer is present for the replay case, but at least one linked episode evaluation "
                    "did not surface a workflow/tool-targeted suggestion that aligns with the observed failure."
                ),
            }
        )

    return gaps


def _format_turn_execution_rate(numerator: int, denominator: int) -> float:
    if denominator <= 0:
        return 0.0
    return round((float(numerator) / float(denominator)) * 100.0, 2)


_TERMINAL_OUTCOME_RECOVERABLE_RETRYABILITY = frozenset(
    {
        "now",
        "after_input",
        "after_external_change",
        "after_represented_learning",
    }
)


def _terminal_outcome_receipt_has_retry_signal(item: Mapping[str, Any]) -> bool:
    """Project represented recovery facts into the legacy retry benchmark signal."""

    projection = item.get("terminal_outcome_receipt_projection")
    if not isinstance(projection, Mapping) or not projection.get("available"):
        return False
    validation = projection.get("validation")
    if not isinstance(validation, Mapping) or validation.get("valid") is not True:
        return False
    retryability = str(projection.get("retryability") or "").strip()
    recovery_affordances = projection.get("recovery_affordances")
    return (
        retryability in _TERMINAL_OUTCOME_RECOVERABLE_RETRYABILITY
        and isinstance(recovery_affordances, list)
        and bool(recovery_affordances)
    )


def _build_terminal_outcome_receipt_metrics(
    items: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Count represented receipt facts without reclassifying their semantics."""

    outcome_counts: dict[str, int] = {}
    causal_stage_counts: dict[str, int] = {}
    retryability_counts: dict[str, int] = {}
    decision_authority_counts: dict[str, int] = {}
    available_count = 0
    valid_count = 0
    non_success_count = 0
    typed_non_success_count = 0
    causal_stage_located_count = 0
    recoverable_count = 0
    recoverable_with_affordance_count = 0
    learning_candidate_count = 0

    for item in items:
        projection = item.get("terminal_outcome_receipt_projection")
        if not isinstance(projection, Mapping) or not projection.get("available"):
            continue
        available_count += 1
        validation = projection.get("validation")
        if isinstance(validation, Mapping) and validation.get("valid") is True:
            valid_count += 1

        outcome = str(projection.get("outcome") or "").strip()
        causal_stage = str(projection.get("causal_stage") or "").strip()
        retryability = str(projection.get("retryability") or "").strip()
        cause_code = str(projection.get("cause_code") or "").strip()
        if outcome:
            outcome_counts[outcome] = outcome_counts.get(outcome, 0) + 1
        if causal_stage:
            causal_stage_counts[causal_stage] = (
                causal_stage_counts.get(causal_stage, 0) + 1
            )
        if retryability:
            retryability_counts[retryability] = (
                retryability_counts.get(retryability, 0) + 1
            )

        provenance = projection.get("provenance")
        decision_authority = (
            str(provenance.get("decision_source") or "").strip()
            if isinstance(provenance, Mapping)
            else ""
        )
        if decision_authority:
            decision_authority_counts[decision_authority] = (
                decision_authority_counts.get(decision_authority, 0) + 1
            )

        if outcome and outcome != "verified_success":
            non_success_count += 1
            if cause_code:
                typed_non_success_count += 1
            if causal_stage and causal_stage != "unknown":
                causal_stage_located_count += 1
        if retryability in _TERMINAL_OUTCOME_RECOVERABLE_RETRYABILITY:
            recoverable_count += 1
            recovery_affordances = projection.get("recovery_affordances")
            if isinstance(recovery_affordances, list) and recovery_affordances:
                recoverable_with_affordance_count += 1
        if isinstance(projection.get("learning_candidate"), Mapping):
            learning_candidate_count += 1

    scanned_count = len(items)
    return {
        "schema_version": "terminal_outcome_receipt_metrics.v1",
        "scanned_count": scanned_count,
        "available_count": available_count,
        "missing_count": max(0, scanned_count - available_count),
        "valid_count": valid_count,
        "invalid_count": max(0, available_count - valid_count),
        "valid_receipt_coverage_pct": _format_turn_execution_rate(
            valid_count,
            scanned_count,
        ),
        "non_success_count": non_success_count,
        "typed_non_success_count": typed_non_success_count,
        "typed_non_success_coverage_pct": _format_turn_execution_rate(
            typed_non_success_count,
            non_success_count,
        ),
        "causal_stage_located_count": causal_stage_located_count,
        "causal_stage_coverage_pct": _format_turn_execution_rate(
            causal_stage_located_count,
            non_success_count,
        ),
        "recoverable_count": recoverable_count,
        "recoverable_with_affordance_count": recoverable_with_affordance_count,
        "recovery_affordance_coverage_pct": _format_turn_execution_rate(
            recoverable_with_affordance_count,
            recoverable_count,
        ),
        "learning_candidate_count": learning_candidate_count,
        "outcome_counts": outcome_counts,
        "causal_stage_counts": causal_stage_counts,
        "retryability_counts": retryability_counts,
        "decision_authority_counts": decision_authority_counts,
    }


def _safe_turn_execution_float_values(values: Sequence[Any]) -> list[float]:
    numeric_values: list[float] = []
    for value in values:
        if isinstance(value, (int, float)):
            numeric_values.append(float(value))
    return numeric_values


def _summarise_turn_execution_numeric_values(values: Sequence[Any]) -> dict[str, Any]:
    numeric_values = _safe_turn_execution_float_values(values)
    if not numeric_values:
        return {"count": 0, "avg": None, "max": None}
    return {
        "count": len(numeric_values),
        "avg": round(sum(numeric_values) / len(numeric_values), 3),
        "max": round(max(numeric_values), 3),
    }


def _derive_workflow_discovery_timeout_policy_recommendation(
    *,
    timeout_count: int,
    timeout_budget_values: Sequence[Any],
    timeout_search_time_values: Sequence[Any],
) -> dict[str, Any]:
    budget_summary = _summarise_turn_execution_numeric_values(timeout_budget_values)
    search_time_summary = _summarise_turn_execution_numeric_values(
        timeout_search_time_values
    )
    if timeout_count <= 0:
        return {
            "action": "none",
            "reason": "No workflow discovery timeout learning examples were present.",
            "evidence_count": 0,
        }

    observed_budget_max = budget_summary.get("max")
    suggested_min_timeout_seconds = None
    if isinstance(observed_budget_max, (int, float)):
        suggested_min_timeout_seconds = round(
            min(
                60.0,
                max(float(observed_budget_max) * 2.0, float(observed_budget_max) + 5.0),
            ),
            3,
        )

    return {
        "action": "review_and_raise_timeout_budget",
        "authority_surface": (
            "represented workflow-discovery timeout policy or "
            "VON_WORKFLOW_DISCOVERY_TIMEOUT_SECONDS deployment setting"
        ),
        "reason": (
            "At least one turn exhausted the workflow-discovery budget, so the "
            "timeout should be reviewed through the represented policy/deployment "
            "surface rather than learned as a successful selector completion."
        ),
        "evidence_count": timeout_count,
        "timeout_budget_seconds": budget_summary,
        "search_time_ms": search_time_summary,
        "suggested_min_timeout_seconds": suggested_min_timeout_seconds,
        "promotion_guardrail": (
            "Apply only after replay confirms the longer budget improves candidate "
            "discovery without masking downstream required-evidence failures."
        ),
    }


def _build_turn_execution_benchmark_signals(
    *,
    metrics: Mapping[str, Any],
    baseline_unresolved_follow_up_rate_pct: Any,
    regression_tolerance_pct: Any,
    regression_assessment: Mapping[str, Any] | None,
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    def _signal_status(passed: bool | None) -> str:
        if passed is True:
            return "pass"
        if passed is False:
            return "fail"
        return "not_evaluated"

    def _add_signal(
        *,
        signal_id: str,
        dimension: str,
        title: str,
        passed: bool | None,
        details: Mapping[str, Any],
    ) -> None:
        signals.append(
            {
                "signal_id": signal_id,
                "dimension": dimension,
                "title": title,
                "status": _signal_status(passed),
                "passed": passed,
                "details": dict(details),
            }
        )

    selection_metrics_raw = metrics.get("selection_metrics")
    selection_metrics = (
        selection_metrics_raw if isinstance(selection_metrics_raw, Mapping) else {}
    )
    gate_metrics_raw = metrics.get("gate_metrics")
    gate_metrics = gate_metrics_raw if isinstance(gate_metrics_raw, Mapping) else {}
    retry_metrics_raw = metrics.get("retry_metrics")
    retry_metrics = retry_metrics_raw if isinstance(retry_metrics_raw, Mapping) else {}
    user_metrics_raw = metrics.get("user_imposition_metrics")
    user_metrics = user_metrics_raw if isinstance(user_metrics_raw, Mapping) else {}
    action_quality_metrics_raw = metrics.get("action_quality_metrics")
    action_quality_metrics = (
        action_quality_metrics_raw
        if isinstance(action_quality_metrics_raw, Mapping)
        else {}
    )
    workflow_discovery_metrics_raw = metrics.get("workflow_discovery_metrics")
    workflow_discovery_metrics = (
        workflow_discovery_metrics_raw
        if isinstance(workflow_discovery_metrics_raw, Mapping)
        else {}
    )
    required_evidence_metrics_raw = metrics.get("required_evidence_metrics")
    required_evidence_metrics = (
        required_evidence_metrics_raw
        if isinstance(required_evidence_metrics_raw, Mapping)
        else {}
    )
    replay_diagnostic_metrics_raw = metrics.get("replay_diagnostic_metrics")
    replay_diagnostic_metrics = (
        replay_diagnostic_metrics_raw
        if isinstance(replay_diagnostic_metrics_raw, Mapping)
        else {}
    )

    signals: list[dict[str, Any]] = []

    likely_failure_plain_response_count = int(
        selection_metrics.get("likely_failure_plain_response_count") or 0
    )
    _add_signal(
        signal_id="workflow_selection_prefers_tool_path",
        dimension="workflow_selection",
        title="Likely-failure turns avoid plain-response workflows",
        passed=likely_failure_plain_response_count == 0,
        details={
            "observed_plain_response_count": likely_failure_plain_response_count,
            "expected_plain_response_count": 0,
        },
    )

    false_success_count = int(gate_metrics.get("false_success_count") or 0)
    _add_signal(
        signal_id="completion_gate_false_success_guard",
        dimension="gate_outcomes",
        title="Completion gate reports zero false-success outcomes",
        passed=false_success_count == 0,
        details={
            "observed_false_success_count": false_success_count,
            "expected_false_success_count": 0,
        },
    )

    follow_up_count = int(retry_metrics.get("follow_up_count") or 0)
    follow_up_with_retry_signal_count = int(
        retry_metrics.get("follow_up_with_retry_signal_count") or 0
    )
    retry_guard_passed = (
        True
        if follow_up_count <= 0
        else follow_up_with_retry_signal_count >= follow_up_count
    )
    _add_signal(
        signal_id="retry_guardrail_signals_recorded",
        dimension="retries",
        title="Follow-up turns carry retry/stop telemetry signals",
        passed=retry_guard_passed,
        details={
            "follow_up_count": follow_up_count,
            "follow_up_with_retry_signal_count": follow_up_with_retry_signal_count,
        },
    )

    follow_up_rate_pct = _safe_float_or_none(
        user_metrics.get("follow_up_turn_rate_pct")
    )
    baseline_follow_up_rate_pct = _safe_float_or_none(
        baseline_unresolved_follow_up_rate_pct
    )
    tolerance = _safe_float_or_none(regression_tolerance_pct)
    if tolerance is None or tolerance < 0:
        tolerance = 0.0
    if follow_up_rate_pct is None or baseline_follow_up_rate_pct is None:
        user_imposition_passed = None
        max_follow_up_rate_pct = None
    else:
        max_follow_up_rate_pct = round(baseline_follow_up_rate_pct + tolerance, 2)
        user_imposition_passed = follow_up_rate_pct <= max_follow_up_rate_pct
    _add_signal(
        signal_id="user_imposition_rate_vs_baseline",
        dimension="user_imposition",
        title="Follow-up burden does not exceed baseline tolerance",
        passed=user_imposition_passed,
        details={
            "observed_follow_up_turn_rate_pct": follow_up_rate_pct,
            "max_follow_up_turn_rate_pct": max_follow_up_rate_pct,
            "baseline_follow_up_turn_rate_pct": baseline_follow_up_rate_pct,
            "regression_tolerance_pct": round(tolerance, 2),
        },
    )

    weak_follow_up_with_divergence_count = int(
        action_quality_metrics.get(
            "weak_follow_up_with_selector_dispatch_divergence_count"
        )
        or 0
    )
    weak_follow_up_request_ids_raw = action_quality_metrics.get(
        "weak_follow_up_with_selector_dispatch_divergence_request_ids"
    )
    weak_follow_up_request_ids = (
        [
            str(request_id).strip()
            for request_id in weak_follow_up_request_ids_raw
            if isinstance(request_id, str) and request_id.strip()
        ]
        if isinstance(weak_follow_up_request_ids_raw, list)
        else []
    )
    _add_signal(
        signal_id="likely_failure_cases_avoid_selector_dispatch_divergence_with_weak_follow_up",
        dimension="action_quality",
        title="Likely-failure turns avoid weak follow-up action after selector/dispatch divergence",
        passed=weak_follow_up_with_divergence_count == 0,
        details={
            "observed_case_count": weak_follow_up_with_divergence_count,
            "expected_case_count": 0,
            "request_ids": weak_follow_up_request_ids,
        },
    )

    workflow_discovery_timeout_count = int(
        workflow_discovery_metrics.get("budget_exhausted_count") or 0
    )
    _add_signal(
        signal_id="workflow_discovery_timeouts_are_learning_visible",
        dimension="workflow_discovery",
        title="Workflow discovery timeout examples are visible to policy learning",
        passed=workflow_discovery_timeout_count == 0,
        details={
            "budget_exhausted_count": workflow_discovery_timeout_count,
            "budget_exhausted_rate_pct": workflow_discovery_metrics.get(
                "budget_exhausted_rate_pct"
            ),
            "zero_candidate_timeout_count": workflow_discovery_metrics.get(
                "zero_candidate_timeout_count"
            ),
            "timeout_false_success_count": workflow_discovery_metrics.get(
                "timeout_false_success_count"
            ),
        },
    )

    missing_required_tool_turn_count = int(
        required_evidence_metrics.get("missing_required_tool_turn_count") or 0
    )
    _add_signal(
        signal_id="grounded_retrieval_required_tools_executed",
        dimension="required_evidence",
        title="Grounded retrieval workflows execute declared required evidence tools",
        passed=missing_required_tool_turn_count == 0,
        details={
            "declared_required_evidence_turn_count": required_evidence_metrics.get(
                "declared_required_evidence_turn_count"
            ),
            "missing_required_tool_turn_count": missing_required_tool_turn_count,
            "missing_required_tool_rate_pct": required_evidence_metrics.get(
                "missing_required_tool_rate_pct"
            ),
            "zero_required_tool_execution_count": required_evidence_metrics.get(
                "zero_required_tool_execution_count"
            ),
        },
    )
    selected_case_count = int(replay_diagnostic_metrics.get("selected_case_count") or 0)
    diagnostic_candidate_case_count = int(
        replay_diagnostic_metrics.get("diagnostic_candidate_case_count") or 0
    )
    telemetry_sufficient_case_count = int(
        replay_diagnostic_metrics.get("telemetry_sufficient_case_count") or 0
    )
    routing_layer_diagnosable_count = int(
        replay_diagnostic_metrics.get("routing_layer_diagnosable_count") or 0
    )
    action_layer_diagnosable_count = int(
        replay_diagnostic_metrics.get("action_layer_diagnosable_count") or 0
    )
    episode_evaluation_available_count = int(
        replay_diagnostic_metrics.get("episode_evaluation_available_count") or 0
    )
    episode_evaluation_useful_suggestion_count = int(
        replay_diagnostic_metrics.get("episode_evaluation_useful_suggestion_count") or 0
    )
    replay_diagnostic_passed: bool | None
    if diagnostic_candidate_case_count <= 0:
        replay_diagnostic_passed = None
    else:
        replay_diagnostic_passed = (
            telemetry_sufficient_case_count >= diagnostic_candidate_case_count
        )
    _add_signal(
        signal_id="replay_cases_preserve_diagnostic_layer_coverage",
        dimension="diagnostics",
        title="Replay cases preserve enough routing/action telemetry to localise the failing layer",
        passed=replay_diagnostic_passed,
        details={
            "selected_case_count": selected_case_count,
            "diagnostic_candidate_case_count": diagnostic_candidate_case_count,
            "routing_layer_diagnosable_count": routing_layer_diagnosable_count,
            "action_layer_diagnosable_count": action_layer_diagnosable_count,
            "telemetry_sufficient_case_count": telemetry_sufficient_case_count,
            "episode_evaluation_available_count": episode_evaluation_available_count,
            "episode_evaluation_useful_suggestion_count": (
                episode_evaluation_useful_suggestion_count
            ),
        },
    )
    corrective_follow_up_count = int(
        replay_diagnostic_metrics.get("corrective_evidence_follow_up_count") or 0
    )
    corrective_stronger_follow_up_count = int(
        replay_diagnostic_metrics.get("corrective_evidence_stronger_follow_up_count")
        or 0
    )
    corrective_persistently_weak_follow_up_request_ids_raw = (
        replay_diagnostic_metrics.get(
            "corrective_evidence_persistently_weak_follow_up_request_ids"
        )
    )
    corrective_persistently_weak_follow_up_request_ids = (
        [
            request_id.strip()
            for request_id in corrective_persistently_weak_follow_up_request_ids_raw
            if isinstance(request_id, str) and request_id.strip()
        ]
        if isinstance(corrective_persistently_weak_follow_up_request_ids_raw, list)
        else []
    )
    corrective_follow_up_passed: bool | None
    if corrective_follow_up_count <= 0:
        corrective_follow_up_passed = None
    else:
        corrective_follow_up_passed = (
            corrective_stronger_follow_up_count >= corrective_follow_up_count
        )
    _add_signal(
        signal_id="corrective_evidence_follow_up_strengthens_verification_action",
        dimension="action_quality",
        title="Corrective-evidence follow-up turns strengthen verification action quality",
        passed=corrective_follow_up_passed,
        details={
            "corrective_evidence_follow_up_count": corrective_follow_up_count,
            "corrective_evidence_stronger_follow_up_count": (
                corrective_stronger_follow_up_count
            ),
            "persistently_weak_follow_up_request_ids": (
                corrective_persistently_weak_follow_up_request_ids
            ),
        },
    )

    baseline_provided = bool(
        regression_assessment.get("baseline_provided", False)
        if isinstance(regression_assessment, Mapping)
        else False
    )
    if baseline_provided:
        regression_detected = bool(
            regression_assessment.get("regression_detected", False)
            if isinstance(regression_assessment, Mapping)
            else False
        )
        _add_signal(
            signal_id="overall_regression_assessment",
            dimension="benchmark",
            title="Overall benchmark metrics stay within baseline tolerance",
            passed=not regression_detected,
            details={"regression_detected": regression_detected},
        )

    summary = {
        "pass_count": sum(1 for signal in signals if signal.get("status") == "pass"),
        "fail_count": sum(1 for signal in signals if signal.get("status") == "fail"),
        "not_evaluated_count": sum(
            1 for signal in signals if signal.get("status") == "not_evaluated"
        ),
        "total_count": len(signals),
    }
    return signals, summary


_TURN_EXECUTION_OUTCOME_LABEL_NAMES: tuple[str, ...] = (
    "successful_completion",
    "false_success",
    "unresolved_follow_up_needed",
    "tool_or_workflow_misrouting",
    "abstain_escalate_no_safe_route",
    "workflow_discovery_timeout",
    "required_evidence_missing",
)


def _parse_iso_datetime_or_none(value: Any) -> datetime | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except Exception:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _compute_percentile(values: Sequence[int], percentile: float) -> float | None:
    if not values:
        return None
    ordered = sorted(int(max(0, value)) for value in values)
    if len(ordered) == 1:
        return float(ordered[0])

    bounded_percentile = min(100.0, max(0.0, float(percentile)))
    position = (bounded_percentile / 100.0) * float(len(ordered) - 1)
    lower_index = int(position)
    upper_index = min(len(ordered) - 1, lower_index + 1)
    if lower_index == upper_index:
        return float(ordered[lower_index])
    fraction = position - float(lower_index)
    interpolated = ordered[lower_index] + (
        float(ordered[upper_index] - ordered[lower_index]) * fraction
    )
    return round(float(interpolated), 2)


def _extract_pre_dispatch_payload(item: Mapping[str, Any]) -> Mapping[str, Any]:
    workflow_routing_diagnostics_raw = item.get("workflow_routing_diagnostics")
    workflow_routing_diagnostics = (
        workflow_routing_diagnostics_raw
        if isinstance(workflow_routing_diagnostics_raw, Mapping)
        else {}
    )
    dispatch_raw = workflow_routing_diagnostics.get("dispatch")
    dispatch = dispatch_raw if isinstance(dispatch_raw, Mapping) else {}
    pre_dispatch_raw = dispatch.get("pre_dispatch")
    return pre_dispatch_raw if isinstance(pre_dispatch_raw, Mapping) else {}


def _build_turn_execution_latency_and_trend_views(
    items: Sequence[Mapping[str, Any]],
    *,
    include_completed: bool,
) -> tuple[dict[str, Any], dict[str, Any]]:
    total_items = len(items)
    pre_dispatch_durations: list[int] = []
    bucket_map: dict[str, dict[str, Any]] = {}
    step_stats: dict[str, dict[str, Any]] = {}

    slowest_request_id: str | None = None
    slowest_created_at_utc: str | None = None
    slowest_duration_ms = 0
    slowest_step_id: str | None = None
    slowest_step_label: str | None = None

    for item in items:
        request_id = (
            str(item.get("request_id")).strip()
            if isinstance(item.get("request_id"), str)
            else ""
        )
        created_at_utc = (
            str(item.get("created_at_utc")).strip()
            if isinstance(item.get("created_at_utc"), str)
            else ""
        )
        created_at_dt = _parse_iso_datetime_or_none(created_at_utc)
        bucket_key = (
            created_at_dt.date().isoformat() if created_at_dt is not None else "undated"
        )
        bucket_start_utc = (
            datetime.combine(
                created_at_dt.date(),
                datetime.min.time(),
                tzinfo=timezone.utc,
            )
            .isoformat()
            .replace("+00:00", "Z")
            if created_at_dt is not None
            else None
        )
        bucket = bucket_map.setdefault(
            bucket_key,
            {
                "bucket_id": bucket_key,
                "bucket_start_utc": bucket_start_utc,
                "scanned_count": 0,
                "outcome_label_counts": {
                    label_name: 0 for label_name in _TURN_EXECUTION_OUTCOME_LABEL_NAMES
                },
                "overall_outcome_counts": {},
                "request_ids": [],
                "_pre_dispatch_durations": [],
            },
        )
        bucket["scanned_count"] += 1
        if (
            request_id
            and request_id not in bucket["request_ids"]
            and len(bucket["request_ids"]) < 10
        ):
            bucket["request_ids"].append(request_id)

        execution_correctness_raw = item.get("execution_correctness")
        execution_correctness = (
            execution_correctness_raw
            if isinstance(execution_correctness_raw, Mapping)
            else {}
        )
        metric_labels_raw = execution_correctness.get("metric_labels")
        metric_labels = (
            metric_labels_raw if isinstance(metric_labels_raw, Mapping) else {}
        )
        for label_name in _TURN_EXECUTION_OUTCOME_LABEL_NAMES:
            if bool(metric_labels.get(label_name, False)):
                bucket["outcome_label_counts"][label_name] += 1

        overall_outcome = (
            str(execution_correctness.get("overall_outcome")).strip()
            if isinstance(execution_correctness.get("overall_outcome"), str)
            else ""
        )
        if overall_outcome:
            overall_counts = bucket["overall_outcome_counts"]
            overall_counts[overall_outcome] = overall_counts.get(overall_outcome, 0) + 1

        pre_dispatch = _extract_pre_dispatch_payload(item)
        total_duration_ms = _coerce_int_or_none(pre_dispatch.get("total_duration_ms"))
        if total_duration_ms is None:
            total_duration_ms = None
        elif total_duration_ms < 0:
            total_duration_ms = 0

        if total_duration_ms is not None:
            pre_dispatch_durations.append(total_duration_ms)
            bucket["_pre_dispatch_durations"].append(total_duration_ms)
            if total_duration_ms >= slowest_duration_ms:
                slowest_duration_ms = total_duration_ms
                slowest_request_id = request_id or None
                slowest_created_at_utc = created_at_utc or None
                slowest_step_id = (
                    str(pre_dispatch.get("slowest_step_id")).strip()
                    if isinstance(pre_dispatch.get("slowest_step_id"), str)
                    else None
                )
                slowest_step_label = (
                    str(pre_dispatch.get("slowest_step_label")).strip()
                    if isinstance(pre_dispatch.get("slowest_step_label"), str)
                    else None
                )

        steps_raw = pre_dispatch.get("steps")
        steps = steps_raw if isinstance(steps_raw, list) else []
        for raw_step in steps:
            if not isinstance(raw_step, Mapping):
                continue
            step_id = (
                str(raw_step.get("step_id")).strip()
                if isinstance(raw_step.get("step_id"), str)
                else ""
            ) or "unknown"
            step_label = (
                str(raw_step.get("step_label")).strip()
                if isinstance(raw_step.get("step_label"), str)
                else ""
            ) or step_id
            step_duration_ms = _coerce_int_or_none(raw_step.get("duration_ms"))
            if step_duration_ms is None or step_duration_ms < 0:
                step_duration_ms = 0
            step_status = (
                str(raw_step.get("status")).strip().lower()
                if isinstance(raw_step.get("status"), str)
                else ""
            ) or "unknown"

            stats = step_stats.setdefault(
                step_id,
                {
                    "step_id": step_id,
                    "step_label": step_label,
                    "observed_count": 0,
                    "failed_count": 0,
                    "total_duration_ms": 0,
                    "max_duration_ms": 0,
                    "slowest_request_id": None,
                    "slowest_created_at_utc": None,
                    "_durations": [],
                },
            )
            stats["observed_count"] += 1
            stats["total_duration_ms"] += step_duration_ms
            stats["_durations"].append(step_duration_ms)
            if step_status == "failed":
                stats["failed_count"] += 1
            if step_duration_ms >= int(stats["max_duration_ms"]):
                stats["max_duration_ms"] = step_duration_ms
                stats["slowest_request_id"] = request_id or None
                stats["slowest_created_at_utc"] = created_at_utc or None

    observed_pre_dispatch_count = len(pre_dispatch_durations)
    avg_pre_dispatch_duration_ms = (
        round(sum(pre_dispatch_durations) / observed_pre_dispatch_count, 2)
        if observed_pre_dispatch_count > 0
        else None
    )
    latency_summary = {
        "item_scope": (
            "all_matching_turns" if include_completed else "likely_failure_subset"
        ),
        "observed_pre_dispatch_count": observed_pre_dispatch_count,
        "observed_pre_dispatch_rate_pct": _format_turn_execution_rate(
            observed_pre_dispatch_count, total_items
        ),
        "avg_pre_dispatch_duration_ms": avg_pre_dispatch_duration_ms,
        "median_pre_dispatch_duration_ms": _compute_percentile(
            pre_dispatch_durations, 50
        ),
        "p95_pre_dispatch_duration_ms": _compute_percentile(pre_dispatch_durations, 95),
        "max_pre_dispatch_duration_ms": (
            max(pre_dispatch_durations) if observed_pre_dispatch_count > 0 else None
        ),
        "slowest_request_id": slowest_request_id,
        "slowest_created_at_utc": slowest_created_at_utc,
        "slowest_step_id": slowest_step_id,
        "slowest_step_label": slowest_step_label,
        "slowest_pre_dispatch_duration_ms": (
            slowest_duration_ms if observed_pre_dispatch_count > 0 else None
        ),
    }

    pre_dispatch_step_breakdown: list[dict[str, Any]] = []
    for step_id, stats in step_stats.items():
        durations = stats.pop("_durations")
        observed_count = int(stats.get("observed_count") or 0)
        total_duration_ms = int(stats.get("total_duration_ms") or 0)
        entry = {
            **stats,
            "step_id": step_id,
            "avg_duration_ms": (
                round(total_duration_ms / observed_count, 2)
                if observed_count > 0
                else None
            ),
            "median_duration_ms": _compute_percentile(durations, 50),
            "p95_duration_ms": _compute_percentile(durations, 95),
        }
        pre_dispatch_step_breakdown.append(entry)
    pre_dispatch_step_breakdown.sort(
        key=lambda row: (
            -(float(row.get("avg_duration_ms") or 0.0)),
            -(float(row.get("max_duration_ms") or 0.0)),
            str(row.get("step_id") or ""),
        )
    )

    turn_outcome_buckets: list[dict[str, Any]] = []
    for bucket_key in sorted(bucket_map.keys()):
        bucket = bucket_map[bucket_key]
        durations = bucket.pop("_pre_dispatch_durations")
        scanned_count = int(bucket.get("scanned_count") or 0)
        outcome_label_counts = bucket.get("outcome_label_counts") or {}
        turn_outcome_buckets.append(
            {
                **bucket,
                "item_scope": (
                    "all_matching_turns"
                    if include_completed
                    else "likely_failure_subset"
                ),
                "outcome_label_rates_pct": {
                    f"{label_name}_rate_pct": _format_turn_execution_rate(
                        int(outcome_label_counts.get(label_name) or 0),
                        scanned_count,
                    )
                    for label_name in _TURN_EXECUTION_OUTCOME_LABEL_NAMES
                },
                "pre_dispatch_observed_count": len(durations),
                "avg_pre_dispatch_duration_ms": (
                    round(sum(durations) / len(durations), 2) if durations else None
                ),
                "p95_pre_dispatch_duration_ms": _compute_percentile(durations, 95),
            }
        )

    latency_views = {
        "summary": latency_summary,
        "pre_dispatch_step_breakdown": pre_dispatch_step_breakdown,
    }
    trend_views = {
        "bucket_granularity": "day",
        "item_scope": (
            "all_matching_turns" if include_completed else "likely_failure_subset"
        ),
        "turn_outcome_buckets": turn_outcome_buckets,
    }
    return latency_views, trend_views


def _build_selector_regression_assessment(
    *,
    selector_metrics: Mapping[str, Any],
    baseline_selector_accuracy_pct: Any,
    baseline_selector_misrouting_rate_pct: Any,
    regression_tolerance_pct: Any,
) -> dict[str, Any]:
    tolerance = _safe_float_or_none(regression_tolerance_pct)
    if tolerance is None or tolerance < 0:
        tolerance = 0.0

    comparisons: list[dict[str, Any]] = []
    regression_detected = False

    current_accuracy_pct = _safe_float_or_none(
        selector_metrics.get("selector_accuracy_pct")
    )
    baseline_accuracy_pct = _safe_float_or_none(baseline_selector_accuracy_pct)
    if current_accuracy_pct is not None and baseline_accuracy_pct is not None:
        min_expected_accuracy_pct = round(
            max(0.0, baseline_accuracy_pct - tolerance), 2
        )
        accuracy_regressed = current_accuracy_pct < min_expected_accuracy_pct
        regression_detected = regression_detected or accuracy_regressed
        comparisons.append(
            {
                "metric": "selector_accuracy_pct",
                "baseline_pct": round(baseline_accuracy_pct, 2),
                "current_pct": round(current_accuracy_pct, 2),
                "delta_pct": round(current_accuracy_pct - baseline_accuracy_pct, 2),
                "min_expected_pct": min_expected_accuracy_pct,
                "regressed": accuracy_regressed,
            }
        )

    outcome_label_rates_raw = selector_metrics.get("outcome_label_rates_pct")
    outcome_label_rates = (
        outcome_label_rates_raw if isinstance(outcome_label_rates_raw, Mapping) else {}
    )
    current_misrouting_rate_pct = _safe_float_or_none(
        outcome_label_rates.get("tool_or_workflow_misrouting_rate_pct")
    )
    baseline_misrouting_rate_pct = _safe_float_or_none(
        baseline_selector_misrouting_rate_pct
    )
    if (
        current_misrouting_rate_pct is not None
        and baseline_misrouting_rate_pct is not None
    ):
        max_expected_misrouting_rate_pct = round(
            baseline_misrouting_rate_pct + tolerance,
            2,
        )
        misrouting_regressed = (
            current_misrouting_rate_pct > max_expected_misrouting_rate_pct
        )
        regression_detected = regression_detected or misrouting_regressed
        comparisons.append(
            {
                "metric": "selector_misrouting_rate_pct",
                "baseline_pct": round(baseline_misrouting_rate_pct, 2),
                "current_pct": round(current_misrouting_rate_pct, 2),
                "delta_pct": round(
                    current_misrouting_rate_pct - baseline_misrouting_rate_pct,
                    2,
                ),
                "max_expected_pct": max_expected_misrouting_rate_pct,
                "regressed": misrouting_regressed,
            }
        )

    return {
        "baseline_provided": len(comparisons) > 0,
        "regression_tolerance_pct": round(tolerance, 2),
        "regression_detected": regression_detected,
        "comparisons": comparisons,
    }


def _build_latency_regression_assessment(
    *,
    latency_summary: Mapping[str, Any],
    baseline_pre_dispatch_avg_duration_ms: Any,
    baseline_pre_dispatch_p95_duration_ms: Any,
    latency_regression_tolerance_pct: Any,
) -> dict[str, Any]:
    tolerance_pct = _safe_float_or_none(latency_regression_tolerance_pct)
    if tolerance_pct is None or tolerance_pct < 0:
        tolerance_pct = 0.0

    comparisons: list[dict[str, Any]] = []
    regression_detected = False

    def _add_latency_comparison(
        *,
        metric_name: str,
        current_value_raw: Any,
        baseline_value_raw: Any,
    ) -> None:
        nonlocal regression_detected
        current_value = _safe_float_or_none(current_value_raw)
        baseline_value = _safe_float_or_none(baseline_value_raw)
        if current_value is None or baseline_value is None:
            return
        max_expected_value = round(
            baseline_value * (1.0 + (tolerance_pct / 100.0)),
            2,
        )
        delta_ms = round(current_value - baseline_value, 2)
        delta_pct = (
            round((delta_ms / baseline_value) * 100.0, 2)
            if baseline_value > 0
            else None
        )
        regressed = current_value > max_expected_value
        regression_detected = regression_detected or regressed
        comparisons.append(
            {
                "metric": metric_name,
                "baseline_ms": round(baseline_value, 2),
                "current_ms": round(current_value, 2),
                "delta_ms": delta_ms,
                "delta_pct": delta_pct,
                "max_expected_ms": max_expected_value,
                "regressed": regressed,
            }
        )

    _add_latency_comparison(
        metric_name="avg_pre_dispatch_duration_ms",
        current_value_raw=latency_summary.get("avg_pre_dispatch_duration_ms"),
        baseline_value_raw=baseline_pre_dispatch_avg_duration_ms,
    )
    _add_latency_comparison(
        metric_name="p95_pre_dispatch_duration_ms",
        current_value_raw=latency_summary.get("p95_pre_dispatch_duration_ms"),
        baseline_value_raw=baseline_pre_dispatch_p95_duration_ms,
    )

    return {
        "baseline_provided": len(comparisons) > 0,
        "latency_regression_tolerance_pct": round(tolerance_pct, 2),
        "regression_detected": regression_detected,
        "comparisons": comparisons,
    }


def _build_measurement_dashboard_signal_summary(
    signals: Sequence[Mapping[str, Any]],
) -> dict[str, int]:
    return {
        "pass_count": sum(1 for signal in signals if signal.get("status") == "pass"),
        "fail_count": sum(1 for signal in signals if signal.get("status") == "fail"),
        "not_evaluated_count": sum(
            1 for signal in signals if signal.get("status") == "not_evaluated"
        ),
        "total_count": len(signals),
    }


def _build_execution_dashboard_summary_cards(
    *,
    turn_metrics: Mapping[str, Any],
    selector_metrics: Mapping[str, Any],
    latency_summary: Mapping[str, Any],
    imposition_assessment: Mapping[str, Any],
    turn_regression_assessment: Mapping[str, Any],
    selector_regression_assessment: Mapping[str, Any],
    latency_regression_assessment: Mapping[str, Any],
) -> list[dict[str, Any]]:
    turn_outcome_rates_raw = turn_metrics.get("outcome_label_rates_pct")
    turn_outcome_rates = (
        turn_outcome_rates_raw if isinstance(turn_outcome_rates_raw, Mapping) else {}
    )
    selector_outcome_rates_raw = selector_metrics.get("outcome_label_rates_pct")
    selector_outcome_rates = (
        selector_outcome_rates_raw
        if isinstance(selector_outcome_rates_raw, Mapping)
        else {}
    )
    receipt_metrics_raw = turn_metrics.get("terminal_outcome_receipts")
    receipt_metrics = (
        receipt_metrics_raw if isinstance(receipt_metrics_raw, Mapping) else {}
    )

    def _comparison_for(
        assessment: Mapping[str, Any],
        metric_name: str,
    ) -> Mapping[str, Any]:
        comparisons_raw = assessment.get("comparisons")
        comparisons = comparisons_raw if isinstance(comparisons_raw, list) else []
        for raw in comparisons:
            if not isinstance(raw, Mapping):
                continue
            if str(raw.get("metric")).strip() == metric_name:
                return raw
        return {}

    def _card(
        *,
        card_id: str,
        title: str,
        value: Any,
        unit: str,
        comparison: Mapping[str, Any] | None = None,
        status: str = "info",
    ) -> dict[str, Any]:
        payload = {
            "card_id": card_id,
            "title": title,
            "value": value,
            "unit": unit,
            "status": status,
        }
        if isinstance(comparison, Mapping) and comparison:
            payload["comparison"] = dict(comparison)
            if bool(comparison.get("regressed")):
                payload["status"] = "fail"
            elif (
                comparison.get("baseline_pct") is not None
                or comparison.get("baseline_ms") is not None
            ):
                payload["status"] = "pass"
        return payload

    cards = [
        _card(
            card_id="successful_completion_rate",
            title="Successful completion rate",
            value=turn_outcome_rates.get("successful_completion_rate_pct"),
            unit="pct",
        ),
        _card(
            card_id="false_success_rate",
            title="False success rate",
            value=turn_metrics.get("false_success_rate_pct"),
            unit="pct",
            comparison=_comparison_for(
                turn_regression_assessment,
                "false_success_rate_pct",
            ),
            status=(
                "pass"
                if float(turn_metrics.get("false_success_rate_pct") or 0.0) <= 0.0
                else "warn"
            ),
        ),
        _card(
            card_id="unresolved_follow_up_rate",
            title="Unresolved follow-up rate",
            value=turn_metrics.get("unresolved_follow_up_rate_pct"),
            unit="pct",
            comparison=_comparison_for(
                turn_regression_assessment,
                "unresolved_follow_up_rate_pct",
            ),
        ),
        _card(
            card_id="valid_terminal_receipt_coverage",
            title="Valid terminal receipt coverage",
            value=receipt_metrics.get("valid_receipt_coverage_pct"),
            unit="pct",
        ),
        _card(
            card_id="typed_non_success_coverage",
            title="Typed non-success coverage",
            value=receipt_metrics.get("typed_non_success_coverage_pct"),
            unit="pct",
        ),
        _card(
            card_id="recovery_affordance_coverage",
            title="Recovery-affordance coverage",
            value=receipt_metrics.get("recovery_affordance_coverage_pct"),
            unit="pct",
        ),
        _card(
            card_id="selector_accuracy",
            title="Selector accuracy",
            value=selector_metrics.get("selector_accuracy_pct"),
            unit="pct",
            comparison=_comparison_for(
                selector_regression_assessment,
                "selector_accuracy_pct",
            ),
        ),
        _card(
            card_id="selector_misrouting_rate",
            title="Selector misrouting rate",
            value=selector_outcome_rates.get("tool_or_workflow_misrouting_rate_pct"),
            unit="pct",
            comparison=_comparison_for(
                selector_regression_assessment,
                "selector_misrouting_rate_pct",
            ),
            status=(
                "pass"
                if float(
                    selector_outcome_rates.get("tool_or_workflow_misrouting_rate_pct")
                    or 0.0
                )
                <= 0.0
                else "warn"
            ),
        ),
        _card(
            card_id="avg_pre_dispatch_duration",
            title="Average pre-dispatch duration",
            value=latency_summary.get("avg_pre_dispatch_duration_ms"),
            unit="ms",
            comparison=_comparison_for(
                latency_regression_assessment,
                "avg_pre_dispatch_duration_ms",
            ),
        ),
        _card(
            card_id="minimal_imposition_score",
            title="Minimal-imposition score",
            value=imposition_assessment.get("weighted_score_pct"),
            unit="pct",
            status=(
                "pass"
                if str(imposition_assessment.get("status") or "") == "good"
                else (
                    "warn"
                    if str(imposition_assessment.get("status") or "") == "caution"
                    else (
                        "fail"
                        if str(imposition_assessment.get("status") or "") == "high"
                        else "info"
                    )
                )
            ),
        ),
    ]
    return cards


def _normalise_recommendation_rows(value: Any) -> list[dict[str, Any]]:
    rows = value if isinstance(value, list) else []
    normalised: list[dict[str, Any]] = []
    for raw in rows:
        if not isinstance(raw, Mapping):
            continue
        entry = dict(raw)
        priority = entry.get("priority")
        if not isinstance(priority, str) or not priority.strip():
            entry["priority"] = "medium"
        normalised.append(entry)
    return normalised


def _combine_dashboard_recommendations(
    *,
    turn_report: Mapping[str, Any],
    selector_report: Mapping[str, Any],
    latency_regression_assessment: Mapping[str, Any],
    imposition_assessment: Mapping[str, Any],
) -> list[dict[str, Any]]:
    recommendations: list[dict[str, Any]] = []
    seen_keys: set[str] = set()

    for source_name, report in (
        ("turn_execution", turn_report),
        ("selector_routing", selector_report),
    ):
        for recommendation in _normalise_recommendation_rows(
            report.get("recommendations")
        ):
            summary = str(recommendation.get("summary") or "").strip()
            recommendation_id = str(
                recommendation.get("recommendation_id") or ""
            ).strip()
            dedupe_key = recommendation_id or summary
            if not dedupe_key or dedupe_key in seen_keys:
                continue
            seen_keys.add(dedupe_key)
            recommendations.append(
                {
                    **recommendation,
                    "source_surface": source_name,
                }
            )

    for recommendation in _normalise_recommendation_rows(
        imposition_assessment.get("recommendations")
    ):
        summary = str(recommendation.get("summary") or "").strip()
        recommendation_id = str(recommendation.get("recommendation_id") or "").strip()
        dedupe_key = recommendation_id or summary
        if not dedupe_key or dedupe_key in seen_keys:
            continue
        seen_keys.add(dedupe_key)
        recommendations.append(
            {
                **recommendation,
                "source_surface": "minimal_imposition",
            }
        )

    if bool(latency_regression_assessment.get("regression_detected")):
        comparisons_raw = latency_regression_assessment.get("comparisons")
        comparisons = comparisons_raw if isinstance(comparisons_raw, list) else []
        recommendations.append(
            {
                "recommendation_id": "inspect_pre_dispatch_latency_regressions",
                "priority": "high",
                "summary": (
                    "Inspect the slowest pre-dispatch steps and convert repeated latency spikes into regression gates or workflow/runtime fixes."
                ),
                "details": {
                    "comparisons": [
                        dict(comparison)
                        for comparison in comparisons
                        if isinstance(comparison, Mapping)
                        and comparison.get("regressed")
                    ]
                },
                "source_surface": "pre_dispatch_latency",
            }
        )

    return recommendations


def _turn_execution_build_benchmark(**kwargs):
    from ...db.connection_manager import get_db
    from ...services.turn_execution_record_service import (
        TURN_EXECUTION_CORRECTNESS_SCHEMA_VERSION,
    )
    from ...services.minimal_imposition_benchmark_service import (
        build_minimal_imposition_assessment,
    )

    include_completed = bool(kwargs.get("include_completed", True))
    max_cases_raw = kwargs.get("max_cases")
    max_cases = 25
    if isinstance(max_cases_raw, int):
        max_cases = max(1, min(200, max_cases_raw))

    forwarded = dict(kwargs)
    forwarded["include_completed"] = include_completed
    result = _turn_execution_search_failures(**forwarded)
    if not isinstance(result, dict):
        return result
    if not result.get("success", False):
        return result

    raw_items = result.get("items")
    items = [dict(item) for item in raw_items] if isinstance(raw_items, list) else []
    sorted_items = sorted(
        items,
        key=lambda item: (
            _turn_execution_failure_mode_priority(
                str(item.get("failure_mode"))
                if isinstance(item.get("failure_mode"), str)
                else "unknown"
            ),
            str(item.get("request_id") or ""),
            str(item.get("created_at_utc") or ""),
        ),
    )

    likely_items = [
        item for item in sorted_items if bool(item.get("likely_failure_to_act", False))
    ]
    selected_cases = likely_items[:max_cases]
    request_ids_for_critique_lookup = [
        request_id.strip()
        for request_id in (item.get("request_id") for item in selected_cases)
        if isinstance(request_id, str) and request_id.strip()
    ]
    episode_critique_lookup = _build_turn_execution_episode_critique_lookup(
        db=get_db(),
        namespace=kwargs.get("namespace"),
        request_ids=request_ids_for_critique_lookup,
    )
    follow_up_summary_by_request_id = (
        _build_turn_execution_follow_up_summary_by_request_id(likely_items)
    )

    jira_base_url = _normalise_turn_execution_jira_base_url(kwargs.get("jira_base_url"))

    replay_cases: list[dict[str, Any]] = []
    for idx, item in enumerate(selected_cases, start=1):
        request_id_raw = item.get("request_id")
        request_id = (
            request_id_raw.strip()
            if isinstance(request_id_raw, str) and request_id_raw.strip()
            else None
        )
        replay_cases.append(
            _build_turn_execution_replay_case(
                item,
                index=idx,
                jira_base_url=jira_base_url,
                follow_up_context=(
                    follow_up_summary_by_request_id.get(
                        request_id, {"available": False}
                    )
                    if request_id
                    else {"available": False}
                ),
                episode_evaluation_context=(
                    _build_turn_execution_episode_evaluation_context(
                        item,
                        critique_lookup=episode_critique_lookup,
                    )
                ),
            )
        )
    diagnostic_candidate_case_count = 0
    routing_layer_diagnosable_count = 0
    action_layer_diagnosable_count = 0
    telemetry_sufficient_case_count = 0
    episode_evaluation_available_count = 0
    episode_evaluation_useful_suggestion_count = 0
    corrective_evidence_follow_up_count = 0
    corrective_evidence_stronger_follow_up_count = 0
    corrective_evidence_persistently_weak_follow_up_request_ids: list[str] = []
    for case in replay_cases:
        evidence_raw = case.get("evidence")
        if not isinstance(evidence_raw, Mapping):
            continue
        evidence: Mapping[str, Any] = evidence_raw
        diagnosis_layers_raw = evidence.get("diagnosis_layers")
        diagnosis_layers = (
            diagnosis_layers_raw if isinstance(diagnosis_layers_raw, Mapping) else {}
        )
        routing_layer_raw = diagnosis_layers.get("routing_layer")
        routing_layer: Mapping[str, Any] = (
            routing_layer_raw if isinstance(routing_layer_raw, Mapping) else {}
        )
        action_layer_raw = diagnosis_layers.get("action_layer")
        action_layer: Mapping[str, Any] = (
            action_layer_raw if isinstance(action_layer_raw, Mapping) else {}
        )
        telemetry_layer_raw = diagnosis_layers.get("telemetry_layer")
        telemetry_layer: Mapping[str, Any] = (
            telemetry_layer_raw if isinstance(telemetry_layer_raw, Mapping) else {}
        )
        episode_evaluation_layer_raw = diagnosis_layers.get("episode_evaluation_layer")
        episode_evaluation_layer: Mapping[str, Any] = (
            episode_evaluation_layer_raw
            if isinstance(episode_evaluation_layer_raw, Mapping)
            else {}
        )
        replay_diagnostic_candidate = bool(
            evidence.get("selector_dispatch_divergence")
            or evidence.get("weak_follow_up_action")
            or episode_evaluation_layer.get("diagnosable")
        )
        if replay_diagnostic_candidate:
            diagnostic_candidate_case_count += 1
        if replay_diagnostic_candidate and bool(routing_layer.get("diagnosable")):
            routing_layer_diagnosable_count += 1
        if replay_diagnostic_candidate and bool(action_layer.get("diagnosable")):
            action_layer_diagnosable_count += 1
        if replay_diagnostic_candidate and bool(telemetry_layer.get("diagnosable")):
            telemetry_sufficient_case_count += 1
        if replay_diagnostic_candidate and bool(
            episode_evaluation_layer.get("diagnosable")
        ):
            episode_evaluation_available_count += 1
        if replay_diagnostic_candidate and bool(
            episode_evaluation_layer.get("useful_suggestion_present")
        ):
            episode_evaluation_useful_suggestion_count += 1

        follow_up_raw = evidence.get("follow_up")
        follow_up = follow_up_raw if isinstance(follow_up_raw, Mapping) else {}
        if replay_diagnostic_candidate and bool(follow_up.get("available")):
            corrective_evidence_follow_up_count += 1
            if bool(follow_up.get("follow_up_action_strengthened")):
                corrective_evidence_stronger_follow_up_count += 1
            elif bool(follow_up.get("follow_up_weak_follow_up_action")):
                request_id = case.get("request_id")
                if isinstance(request_id, str) and request_id.strip():
                    corrective_evidence_persistently_weak_follow_up_request_ids.append(
                        request_id.strip()
                    )

    workflow_counts: dict[str, int] = {}
    workflow_failure_counts: dict[str, int] = {}
    for item in sorted_items:
        workflow_id = item.get("selected_workflow_id")
        workflow_key = (
            workflow_id.strip()
            if isinstance(workflow_id, str) and workflow_id.strip()
            else "unknown"
        )
        workflow_counts[workflow_key] = workflow_counts.get(workflow_key, 0) + 1
        if bool(item.get("likely_failure_to_act", False)):
            workflow_failure_counts[workflow_key] = (
                workflow_failure_counts.get(workflow_key, 0) + 1
            )

    scanned_count = len(sorted_items)
    terminal_outcome_receipt_metrics = _build_terminal_outcome_receipt_metrics(
        sorted_items
    )
    likely_failure_count = len(likely_items)
    false_success_count = sum(
        1
        for item in sorted_items
        if item.get("failure_mode")
        in {"false_completion_claim", "false_completion_gate_state"}
    )
    workflow_discovery_timeout_items = [
        item
        for item in sorted_items
        if bool(item.get("workflow_discovery_budget_exhausted"))
    ]
    workflow_discovery_timeout_count = len(workflow_discovery_timeout_items)
    workflow_discovery_timeout_false_success_count = sum(
        1
        for item in workflow_discovery_timeout_items
        if item.get("failure_mode")
        in {"false_completion_claim", "false_completion_gate_state"}
    )
    workflow_discovery_zero_candidate_timeout_count = sum(
        1
        for item in workflow_discovery_timeout_items
        if int(item.get("workflow_discovery_candidate_count") or 0) <= 0
        and int(item.get("workflow_discovery_match_count") or 0) <= 0
    )
    required_evidence_declared_items = [
        item
        for item in sorted_items
        if int(item.get("workflow_required_effects_declared_count") or 0) > 0
        or bool(item.get("workflow_required_effects_required_tools"))
    ]
    required_evidence_missing_items = [
        item
        for item in required_evidence_declared_items
        if int(item.get("required_evidence_tool_missing_count") or 0) > 0
    ]
    required_evidence_zero_tool_execution_count = sum(
        1
        for item in required_evidence_declared_items
        if bool(item.get("workflow_required_effects_required_tools"))
        and not bool(item.get("tool_invocation_summary"))
    )
    workflow_discovery_timeout_policy_recommendation = (
        _derive_workflow_discovery_timeout_policy_recommendation(
            timeout_count=workflow_discovery_timeout_count,
            timeout_budget_values=[
                item.get("workflow_discovery_timeout_budget_seconds")
                for item in workflow_discovery_timeout_items
            ],
            timeout_search_time_values=[
                item.get("workflow_discovery_search_time_ms")
                for item in workflow_discovery_timeout_items
            ],
        )
    )
    unresolved_follow_up_count = sum(
        1 for item in sorted_items if bool(item.get("requires_follow_up", False))
    )
    safe_completion_count = sum(
        1 for item in sorted_items if bool(item.get("safe_to_claim_completion", False))
    )
    likely_failure_plain_response_count = sum(
        1
        for item in likely_items
        if str(item.get("selected_workflow_id") or "").strip()
        in {"#V#chat_assistant_workflow", "#V#plain_response_workflow"}
    )
    likely_failure_tool_workflow_count = sum(
        1
        for item in likely_items
        if str(item.get("selected_workflow_id") or "").strip()
        == "#V#tool_calling_workflow"
    )
    selector_dispatch_divergence_count = 0
    weak_follow_up_action_count = 0
    weak_follow_up_with_selector_dispatch_divergence_count = 0
    weak_follow_up_with_selector_dispatch_divergence_request_ids: list[str] = []
    for item in likely_items:
        selector_dispatch_divergence = _has_turn_execution_selector_dispatch_divergence(
            item
        )
        weak_follow_up_action = _has_turn_execution_weak_follow_up_action(item)
        if selector_dispatch_divergence:
            selector_dispatch_divergence_count += 1
        if weak_follow_up_action:
            weak_follow_up_action_count += 1
        if selector_dispatch_divergence and weak_follow_up_action:
            weak_follow_up_with_selector_dispatch_divergence_count += 1
            request_id = item.get("request_id")
            if isinstance(request_id, str) and request_id.strip():
                weak_follow_up_with_selector_dispatch_divergence_request_ids.append(
                    request_id.strip()
                )
    bounded_loop_stop_reasons = {
        "attempt_budget_exhausted",
        "elapsed_budget_exhausted",
        "no_progress_guard_triggered",
        "stall_latency_budget_exhausted",
    }
    follow_up_with_retry_signal_count = 0
    bounded_retry_stop_count = 0
    stall_latency_stop_count = 0
    escalation_signal_count = 0
    for item in sorted_items:
        if not bool(item.get("requires_follow_up", False)):
            continue
        loop_attempts = _coerce_int_or_none(item.get("loop_attempts")) or 0
        repeat_iteration = bool(item.get("repeat_iteration", False))
        loop_stop_reason = (
            str(item.get("loop_stop_reason")).strip()
            if isinstance(item.get("loop_stop_reason"), str)
            else ""
        )
        if (
            repeat_iteration
            or loop_attempts > 0
            or bool(loop_stop_reason)
            or _terminal_outcome_receipt_has_retry_signal(item)
        ):
            follow_up_with_retry_signal_count += 1
        if loop_stop_reason in bounded_loop_stop_reasons:
            bounded_retry_stop_count += 1
        if loop_stop_reason == "stall_latency_budget_exhausted":
            stall_latency_stop_count += 1
        if bool(item.get("escalation_signal", False)):
            escalation_signal_count += 1

    failure_mode_counts: dict[str, int] = {}
    failure_mode_counts_raw = result.get("failure_mode_counts")
    if isinstance(failure_mode_counts_raw, dict):
        for key, value in failure_mode_counts_raw.items():
            key_text = str(key).strip() or "unknown"
            try:
                failure_mode_counts[key_text] = int(value)
            except Exception:
                failure_mode_counts[key_text] = 0

    outcome_label_counts = {
        label_name: 0 for label_name in _TURN_EXECUTION_OUTCOME_LABEL_NAMES
    }
    overall_outcome_counts: dict[str, int] = {}
    for item in sorted_items:
        execution_correctness_raw = item.get("execution_correctness")
        execution_correctness = (
            execution_correctness_raw
            if isinstance(execution_correctness_raw, Mapping)
            else {}
        )
        metric_labels_raw = execution_correctness.get("metric_labels")
        metric_labels = (
            metric_labels_raw if isinstance(metric_labels_raw, Mapping) else {}
        )
        for label_name in outcome_label_counts:
            if bool(metric_labels.get(label_name, False)):
                outcome_label_counts[label_name] += 1
        overall_outcome = (
            str(execution_correctness.get("overall_outcome")).strip()
            if isinstance(execution_correctness.get("overall_outcome"), str)
            else ""
        )
        if overall_outcome:
            overall_outcome_counts[overall_outcome] = (
                overall_outcome_counts.get(overall_outcome, 0) + 1
            )
    latency_views, trend_views = _build_turn_execution_latency_and_trend_views(
        sorted_items,
        include_completed=include_completed,
    )
    filters_payload = {
        "namespace": kwargs.get("namespace"),
        "limit": result.get("limit"),
        "offset": result.get("offset"),
        "decision": kwargs.get("decision"),
        "decisions": kwargs.get("decisions"),
        "workflow_id": kwargs.get("workflow_id"),
        "requires_follow_up": kwargs.get("requires_follow_up"),
        "prompt_contains": kwargs.get("prompt_contains"),
        "from_utc": kwargs.get("from_utc"),
        "to_utc": kwargs.get("to_utc"),
        "include_completed": include_completed,
        "max_cases": max_cases,
        "jira_base_url": jira_base_url,
    }
    metrics_payload = {
        "scanned_count": scanned_count,
        "likely_failure_count": likely_failure_count,
        "likely_failure_rate_pct": _format_turn_execution_rate(
            likely_failure_count, scanned_count
        ),
        "false_success_count": false_success_count,
        "false_success_rate_pct": _format_turn_execution_rate(
            false_success_count, scanned_count
        ),
        "unresolved_follow_up_count": unresolved_follow_up_count,
        "unresolved_follow_up_rate_pct": _format_turn_execution_rate(
            unresolved_follow_up_count, scanned_count
        ),
        "selection_metrics": {
            "likely_failure_tool_workflow_count": likely_failure_tool_workflow_count,
            "likely_failure_plain_response_count": likely_failure_plain_response_count,
            "likely_failure_tool_workflow_rate_pct": _format_turn_execution_rate(
                likely_failure_tool_workflow_count, likely_failure_count
            ),
        },
        "workflow_discovery_metrics": {
            "budget_exhausted_count": workflow_discovery_timeout_count,
            "budget_exhausted_rate_pct": _format_turn_execution_rate(
                workflow_discovery_timeout_count, scanned_count
            ),
            "zero_candidate_timeout_count": (
                workflow_discovery_zero_candidate_timeout_count
            ),
            "timeout_false_success_count": (
                workflow_discovery_timeout_false_success_count
            ),
            "timeout_budget_seconds": _summarise_turn_execution_numeric_values(
                [
                    item.get("workflow_discovery_timeout_budget_seconds")
                    for item in workflow_discovery_timeout_items
                ]
            ),
            "timeout_search_time_ms": _summarise_turn_execution_numeric_values(
                [
                    item.get("workflow_discovery_search_time_ms")
                    for item in workflow_discovery_timeout_items
                ]
            ),
        },
        "required_evidence_metrics": {
            "declared_required_evidence_turn_count": len(
                required_evidence_declared_items
            ),
            "missing_required_tool_turn_count": len(required_evidence_missing_items),
            "missing_required_tool_rate_pct": _format_turn_execution_rate(
                len(required_evidence_missing_items),
                len(required_evidence_declared_items),
            ),
            "zero_required_tool_execution_count": (
                required_evidence_zero_tool_execution_count
            ),
        },
        "action_quality_metrics": {
            "selector_dispatch_divergence_count": selector_dispatch_divergence_count,
            "selector_dispatch_divergence_rate_pct": _format_turn_execution_rate(
                selector_dispatch_divergence_count, likely_failure_count
            ),
            "weak_follow_up_action_count": weak_follow_up_action_count,
            "weak_follow_up_action_rate_pct": _format_turn_execution_rate(
                weak_follow_up_action_count, likely_failure_count
            ),
            "weak_follow_up_with_selector_dispatch_divergence_count": (
                weak_follow_up_with_selector_dispatch_divergence_count
            ),
            "weak_follow_up_with_selector_dispatch_divergence_rate_pct": (
                _format_turn_execution_rate(
                    weak_follow_up_with_selector_dispatch_divergence_count,
                    likely_failure_count,
                )
            ),
            "weak_follow_up_with_selector_dispatch_divergence_request_ids": list(
                dict.fromkeys(
                    weak_follow_up_with_selector_dispatch_divergence_request_ids
                )
            )[:10],
        },
        "replay_diagnostic_metrics": {
            "selected_case_count": len(replay_cases),
            "diagnostic_candidate_case_count": diagnostic_candidate_case_count,
            "routing_layer_diagnosable_count": routing_layer_diagnosable_count,
            "action_layer_diagnosable_count": action_layer_diagnosable_count,
            "telemetry_sufficient_case_count": telemetry_sufficient_case_count,
            "episode_evaluation_available_count": episode_evaluation_available_count,
            "episode_evaluation_useful_suggestion_count": (
                episode_evaluation_useful_suggestion_count
            ),
            "corrective_evidence_follow_up_count": corrective_evidence_follow_up_count,
            "corrective_evidence_stronger_follow_up_count": (
                corrective_evidence_stronger_follow_up_count
            ),
            "corrective_evidence_persistently_weak_follow_up_request_ids": list(
                dict.fromkeys(
                    corrective_evidence_persistently_weak_follow_up_request_ids
                )
            )[:10],
        },
        "gate_metrics": {
            "false_success_count": false_success_count,
            "safe_completion_count": safe_completion_count,
            "requires_follow_up_count": unresolved_follow_up_count,
            "requires_follow_up_rate_pct": _format_turn_execution_rate(
                unresolved_follow_up_count, scanned_count
            ),
        },
        "retry_metrics": {
            "follow_up_count": unresolved_follow_up_count,
            "follow_up_with_retry_signal_count": follow_up_with_retry_signal_count,
            "follow_up_with_retry_signal_rate_pct": _format_turn_execution_rate(
                follow_up_with_retry_signal_count, unresolved_follow_up_count
            ),
            "bounded_retry_stop_count": bounded_retry_stop_count,
            "bounded_retry_stop_rate_pct": _format_turn_execution_rate(
                bounded_retry_stop_count, unresolved_follow_up_count
            ),
            "stall_latency_stop_count": stall_latency_stop_count,
        },
        "user_imposition_metrics": {
            "follow_up_turn_count": unresolved_follow_up_count,
            "follow_up_turn_rate_pct": _format_turn_execution_rate(
                unresolved_follow_up_count, scanned_count
            ),
            "escalation_signal_count": escalation_signal_count,
            "escalation_signal_rate_pct": _format_turn_execution_rate(
                escalation_signal_count, unresolved_follow_up_count
            ),
        },
        "failure_mode_counts": failure_mode_counts,
        "terminal_outcome_receipts": terminal_outcome_receipt_metrics,
        "outcome_label_counts": outcome_label_counts,
        "outcome_label_rates_pct": {
            f"{label_name}_rate_pct": _format_turn_execution_rate(count, scanned_count)
            for label_name, count in outcome_label_counts.items()
        },
        "overall_outcome_counts": overall_outcome_counts,
        "metric_schema": {
            "summary_schema_version": TURN_EXECUTION_CORRECTNESS_SCHEMA_VERSION,
            "outcome_labels": list(_TURN_EXECUTION_OUTCOME_LABEL_NAMES),
        },
        "decision_counts": (
            result.get("decision_counts")
            if isinstance(result.get("decision_counts"), dict)
            else {}
        ),
        "workflow_counts": workflow_counts,
        "workflow_failure_counts": workflow_failure_counts,
        "latency_metrics": (
            latency_views.get("summary")
            if isinstance(latency_views.get("summary"), Mapping)
            else {}
        ),
    }
    regression_assessment = _build_turn_execution_regression_assessment(
        metrics=metrics_payload,
        baseline_likely_failure_rate_pct=kwargs.get("baseline_likely_failure_rate_pct"),
        baseline_false_success_rate_pct=kwargs.get("baseline_false_success_rate_pct"),
        baseline_unresolved_follow_up_rate_pct=kwargs.get(
            "baseline_unresolved_follow_up_rate_pct"
        ),
        regression_tolerance_pct=kwargs.get("regression_tolerance_pct"),
    )
    benchmark_signals, benchmark_signal_summary = (
        _build_turn_execution_benchmark_signals(
            metrics=metrics_payload,
            baseline_unresolved_follow_up_rate_pct=kwargs.get(
                "baseline_unresolved_follow_up_rate_pct"
            ),
            regression_tolerance_pct=kwargs.get("regression_tolerance_pct"),
            regression_assessment=regression_assessment,
        )
    )
    imposition_assessment = build_minimal_imposition_assessment(
        turn_execution_metrics=metrics_payload,
        profile_concept_id=kwargs.get("profile_concept_id"),
        workflow_id="#V#tool_calling_workflow",
    )
    capability_gaps = _derive_turn_execution_capability_gaps(
        sorted_items,
        failure_mode_counts=failure_mode_counts,
        replay_diagnostic_metrics=metrics_payload.get("replay_diagnostic_metrics"),
        workflow_discovery_metrics=metrics_payload.get("workflow_discovery_metrics"),
        required_evidence_metrics=metrics_payload.get("required_evidence_metrics"),
    )
    if not bool(imposition_assessment.get("success")):
        capability_gaps.append(
            {
                "gap_id": "minimal_imposition_profile_missing",
                "title": "Minimal-imposition benchmark profile is not yet materialised",
                "severity": "high",
                "description": imposition_assessment.get("message")
                or "Minimal-imposition assessment could not be computed because the profile was unavailable.",
            }
        )
    missing_imposition_dimensions = imposition_assessment.get(
        "missing_telemetry_dimensions"
    )
    if (
        isinstance(missing_imposition_dimensions, list)
        and missing_imposition_dimensions
    ):
        capability_gaps.append(
            {
                "gap_id": "minimal_imposition_telemetry_missing",
                "title": "Minimal-imposition benchmark still relies on missing telemetry",
                "severity": "medium",
                "description": (
                    "Some imposition dimensions are still unmeasured and are being "
                    "reported explicitly rather than hidden in the composite score."
                ),
                "missing_dimension_ids": [
                    str(item.get("dimension_id"))
                    for item in missing_imposition_dimensions
                    if isinstance(item, Mapping) and item.get("dimension_id")
                ],
            }
        )
    recommendations_raw = result.get("recommendations")
    recommendations: list[Any] = (
        list(recommendations_raw)
        if isinstance(recommendations_raw, list)
        else list(_derive_turn_execution_failure_recommendations(failure_mode_counts))
    )
    if workflow_discovery_timeout_count > 0:
        recommendations.append(
            "Review workflow-discovery timeout policy using the benchmark timeout "
            "learning payload before treating selector timeout recoveries as normal "
            "successful completions."
        )
    if required_evidence_missing_items:
        recommendations.append(
            "Treat grounded-retrieval workflow completions that miss declared "
            "required evidence tools as negative learning examples for selector and "
            "workflow policy."
        )
    imposition_recommendations = imposition_assessment.get("recommendations")
    if isinstance(imposition_recommendations, list):
        recommendations.extend(imposition_recommendations)
    payload = {
        "collection": "turn_execution_records",
        "benchmark_generated_at_utc": _utc_now_iso(),
        "filters": filters_payload,
        "metrics": metrics_payload,
        "benchmark_fingerprint": _build_turn_execution_benchmark_fingerprint(
            filters=filters_payload,
            replay_cases=replay_cases,
        ),
        "seeded_cases": replay_cases,
        "replay_cases": replay_cases,
        "triage_index": _build_turn_execution_triage_index(
            replay_cases,
            jira_base_url=jira_base_url,
        ),
        "regression_assessment": regression_assessment,
        "benchmark_signals": benchmark_signals,
        "benchmark_signal_summary": benchmark_signal_summary,
        "workflow_discovery_timeout_policy_recommendation": (
            workflow_discovery_timeout_policy_recommendation
        ),
        "imposition_assessment": imposition_assessment,
        "capability_gaps": capability_gaps,
        "recommendations": recommendations,
        "latency_views": latency_views,
        "trend_views": trend_views,
        "effective_namespace": result.get("effective_namespace"),
        "effective_namespace_source": result.get("effective_namespace_source"),
        "namespace": result.get("namespace"),
        "namespace_source": result.get("namespace_source"),
        "namespace_resolution_note": result.get("namespace_resolution_note"),
        "success": True,
    }
    return _with_rag_provenance(
        payload=payload,
        item_kind="turn_execution_benchmark_report",
        source_system="mongo.turn_execution_records",
    )


def _benchmark_suite_source_system(
    *,
    source: str,
    represented_source_system: str,
    fixture_source_system: str,
    inline_source_system: str,
) -> str:
    if source == "vontology":
        return represented_source_system
    if source == "seed_bundle_import_fixture":
        return fixture_source_system
    if source == "inline":
        return inline_source_system
    return "unknown.benchmark_suite"


def _turn_execution_build_selector_benchmark(**kwargs):
    if (
        kwargs.get("bundle_path") is not None
        and not _internal_mcp_global_workflow_admin_authorised()
    ):
        return make_error_response(
            "host_path_authority_required",
            "Selecting a host-local selector benchmark bundle requires trusted operator authority.",
        )
    from ...services.workflow_selector_benchmark_service import (
        build_selector_routing_benchmark_report,
    )

    inline_cases = kwargs.get("cases")
    try:
        result = build_selector_routing_benchmark_report(
            cases=inline_cases if isinstance(inline_cases, list) else None,
            case_set=kwargs.get("case_set"),
            max_cases=kwargs.get("max_cases"),
            bundle_path=kwargs.get("bundle_path"),
            suite_concept_id=kwargs.get("suite_concept_id"),
        )
    except ValueError as exc:
        return make_error_response(
            "selector_benchmark_invalid_input",
            "Selector routing benchmark could not be built from the requested corpus.",
            details={"error": str(exc)},
        )
    except Exception as exc:
        return make_error_response(
            "selector_benchmark_build_failed",
            "Selector routing benchmark evaluation failed.",
            details={"error": str(exc)},
        )

    if not isinstance(result, dict):
        return result

    corpus = result.get("corpus")
    source = (
        str(corpus.get("source")).strip()
        if isinstance(corpus, Mapping) and isinstance(corpus.get("source"), str)
        else "unknown"
    )
    source_system = _benchmark_suite_source_system(
        source=source,
        represented_source_system="vontology.selector_routing_benchmark_suite",
        fixture_source_system="repo.selector_routing_benchmark_seed_bundle_import_fixture",
        inline_source_system="inline.selector_routing_benchmark_cases",
    )
    return _with_rag_provenance(
        payload=result,
        item_kind="selector_routing_benchmark_report",
        source_system=source_system,
    )


