def _turn_execution_build_dashboard(**kwargs):
    if denial := _internal_mcp_operator_control_plane_denial("turn telemetry"):
        return denial
    from ...services.minimal_imposition_benchmark_service import (
        build_minimal_imposition_assessment,
    )

    include_completed = kwargs.get("include_completed")
    if include_completed is None:
        include_completed = True

    operational_certification: dict[str, Any] = {}
    effective_operational_namespace: str | None = None
    effective_operational_user_id: str | None = None
    effective_operational_org_id: str | None = None
    operational_run_id = _clean_optional_string(
        kwargs.get("operational_certification_run_id")
    )
    if operational_run_id:
        from ...services.experiment_run_service import get_experiment_run_state
        from ...services.operational_certification_runner_service import (
            validate_campaign_experiment_observation,
        )

        operational_run = get_experiment_run_state(operational_run_id)
        if not isinstance(operational_run, Mapping):
            return make_error_response(
                "operational_certification_run_not_found",
                "The requested operational certification experiment run was not found.",
                details={"run_id": operational_run_id},
            )
        requested_namespace = _clean_optional_string(kwargs.get("namespace"))
        requested_user_id = _clean_optional_string(kwargs.get("user_concept_id"))
        requested_org_id = _clean_optional_string(kwargs.get("organisation_concept_id"))
        if not requested_namespace or not requested_user_id or not requested_org_id:
            return make_error_response(
                "operational_certification_scope_required",
                "Certification dashboard read-back requires explicit caller namespace, user, and organisation scope.",
                details={
                    "run_id": operational_run_id,
                    "missing": [
                        field_name
                        for field_name, field_value in (
                            ("namespace", requested_namespace),
                            ("user_concept_id", requested_user_id),
                            ("organisation_concept_id", requested_org_id),
                        )
                        if not field_value
                    ],
                },
            )
        run_namespace = _clean_optional_string(operational_run.get("namespace"))
        run_user_id = _clean_optional_string(operational_run.get("user_id"))
        run_org_id = _clean_optional_string(operational_run.get("org_id"))
        run_scope_mismatches = [
            field_name
            for field_name, requested, observed in (
                ("namespace", requested_namespace, run_namespace),
                ("user_id", requested_user_id, run_user_id),
                ("org_id", requested_org_id, run_org_id),
            )
            if requested != observed
        ]
        if run_scope_mismatches:
            return make_error_response(
                "operational_certification_scope_mismatch",
                "The certification run belongs to a different caller scope.",
                details={
                    "run_id": operational_run_id,
                    "requested_namespace": requested_namespace,
                    "run_namespace": run_namespace,
                    "mismatches": run_scope_mismatches,
                },
            )
        effective_operational_namespace = requested_namespace
        effective_operational_user_id = requested_user_id
        effective_operational_org_id = requested_org_id
        observations = operational_run.get("observations")
        for observation in reversed(
            observations if isinstance(observations, list) else []
        ):
            if not isinstance(observation, Mapping):
                continue
            evidence = observation.get("evidence")
            campaign = (
                evidence.get("operational_certification_campaign_result")
                if isinstance(evidence, Mapping)
                else None
            )
            if not isinstance(campaign, Mapping):
                continue
            integrity_errors = validate_campaign_experiment_observation(observation)
            if integrity_errors:
                return make_error_response(
                    "operational_certification_integrity_mismatch",
                    "The certification campaign observation is internally inconsistent.",
                    details={
                        "run_id": operational_run_id,
                        "integrity_errors": integrity_errors,
                    },
                )
            provenance = observation.get("execution_provenance")
            if not isinstance(provenance, Mapping):
                return make_error_response(
                    "operational_certification_provenance_missing",
                    "The persisted certification campaign has no execution provenance.",
                    details={"run_id": operational_run_id},
                )
            provenance_mismatches = [
                field_name
                for field_name, expected in (
                    ("effective_namespace", effective_operational_namespace),
                    ("effective_user_id", effective_operational_user_id),
                    ("effective_org_id", effective_operational_org_id),
                )
                if _clean_optional_string(provenance.get(field_name)) != expected
            ]
            if provenance_mismatches:
                return make_error_response(
                    "operational_certification_provenance_scope_mismatch",
                    "The persisted certification provenance belongs to a different caller scope.",
                    details={
                        "run_id": operational_run_id,
                        "mismatches": provenance_mismatches,
                    },
                )
            operational_certification = dict(campaign)
            break
        if not operational_certification:
            return make_error_response(
                "operational_certification_campaign_missing",
                "The experiment run has no strict operational certification campaign result.",
                details={"run_id": operational_run_id},
            )

    turn_execution_kwargs = {
        "namespace": (
            effective_operational_namespace
            if operational_run_id
            else kwargs.get("namespace")
        ),
        "limit": kwargs.get("limit"),
        "offset": kwargs.get("offset"),
        "decision": kwargs.get("decision"),
        "decisions": kwargs.get("decisions"),
        "workflow_id": kwargs.get("workflow_id"),
        "requires_follow_up": kwargs.get("requires_follow_up"),
        "prompt_contains": kwargs.get("prompt_contains"),
        "from_utc": kwargs.get("from_utc"),
        "to_utc": kwargs.get("to_utc"),
        "include_completed": bool(include_completed),
        "max_cases": kwargs.get("max_cases"),
        "jira_base_url": kwargs.get("jira_base_url"),
        "baseline_likely_failure_rate_pct": kwargs.get(
            "baseline_likely_failure_rate_pct"
        ),
        "baseline_false_success_rate_pct": kwargs.get(
            "baseline_false_success_rate_pct"
        ),
        "baseline_unresolved_follow_up_rate_pct": kwargs.get(
            "baseline_unresolved_follow_up_rate_pct"
        ),
        "regression_tolerance_pct": kwargs.get("regression_tolerance_pct"),
        "profile_concept_id": kwargs.get("profile_concept_id"),
    }
    turn_execution_report = _turn_execution_build_benchmark(**turn_execution_kwargs)
    if not isinstance(turn_execution_report, dict):
        return turn_execution_report
    if not turn_execution_report.get("success", False):
        return turn_execution_report

    selector_kwargs = {
        "case_set": kwargs.get("selector_case_set"),
        "max_cases": kwargs.get("selector_max_cases"),
        "bundle_path": kwargs.get("selector_bundle_path"),
        "suite_concept_id": kwargs.get("selector_suite_concept_id"),
    }
    selector_report = _turn_execution_build_selector_benchmark(**selector_kwargs)
    if not isinstance(selector_report, dict):
        return selector_report
    if not selector_report.get("success", False):
        return selector_report

    turn_metrics_raw = turn_execution_report.get("metrics")
    turn_metrics = turn_metrics_raw if isinstance(turn_metrics_raw, Mapping) else {}
    selector_metrics_raw = selector_report.get("metrics")
    selector_metrics = (
        selector_metrics_raw if isinstance(selector_metrics_raw, Mapping) else {}
    )
    latency_views_raw = turn_execution_report.get("latency_views")
    latency_views = latency_views_raw if isinstance(latency_views_raw, Mapping) else {}
    latency_summary_raw = latency_views.get("summary")
    latency_summary = (
        latency_summary_raw if isinstance(latency_summary_raw, Mapping) else {}
    )

    selector_regression_assessment = _build_selector_regression_assessment(
        selector_metrics=selector_metrics,
        baseline_selector_accuracy_pct=kwargs.get("baseline_selector_accuracy_pct"),
        baseline_selector_misrouting_rate_pct=kwargs.get(
            "baseline_selector_misrouting_rate_pct"
        ),
        regression_tolerance_pct=kwargs.get("regression_tolerance_pct"),
    )
    latency_regression_assessment = _build_latency_regression_assessment(
        latency_summary=latency_summary,
        baseline_pre_dispatch_avg_duration_ms=kwargs.get(
            "baseline_pre_dispatch_avg_duration_ms"
        ),
        baseline_pre_dispatch_p95_duration_ms=kwargs.get(
            "baseline_pre_dispatch_p95_duration_ms"
        ),
        latency_regression_tolerance_pct=kwargs.get("latency_regression_tolerance_pct"),
    )

    turn_regression_assessment_raw = turn_execution_report.get("regression_assessment")
    turn_regression_assessment = (
        turn_regression_assessment_raw
        if isinstance(turn_regression_assessment_raw, Mapping)
        else {}
    )
    imposition_assessment = build_minimal_imposition_assessment(
        turn_execution_metrics=turn_metrics,
        selector_metrics=selector_metrics,
        profile_concept_id=kwargs.get("profile_concept_id"),
        workflow_id="#V#tool_calling_workflow",
    )

    combined_signals: list[dict[str, Any]] = []
    for source_surface, report in (
        ("turn_execution", turn_execution_report),
        ("selector_routing", selector_report),
    ):
        signals_raw = report.get("benchmark_signals")
        signals = signals_raw if isinstance(signals_raw, list) else []
        for raw_signal in signals:
            if not isinstance(raw_signal, Mapping):
                continue
            combined_signals.append({**raw_signal, "source_surface": source_surface})

    if operational_certification:
        operational_certified = operational_certification.get("certified") is True
        combined_signals.append(
            {
                "signal_id": "operational_certification_campaign",
                "dimension": "operational_certification",
                "title": "Represented operational certification campaign",
                "status": "pass" if operational_certified else "fail",
                "passed": operational_certified,
                "details": {
                    "run_id": operational_run_id,
                    "report_sha256": operational_certification.get("report_sha256"),
                    "failed_certification_gate_ids": operational_certification.get(
                        "failed_certification_gate_ids"
                    )
                    or [],
                    "pass_rates": operational_certification.get("pass_rates") or {},
                },
                "source_surface": "operational_certification",
            }
        )

    if bool(latency_regression_assessment.get("baseline_provided")):
        combined_signals.append(
            {
                "signal_id": "pre_dispatch_latency_vs_baseline",
                "dimension": "pre_dispatch_latency",
                "title": "Pre-dispatch latency remains within configured baseline tolerance",
                "status": (
                    "fail"
                    if bool(latency_regression_assessment.get("regression_detected"))
                    else "pass"
                ),
                "passed": not bool(
                    latency_regression_assessment.get("regression_detected")
                ),
                "details": {
                    "comparisons": latency_regression_assessment.get("comparisons")
                    or []
                },
                "source_surface": "pre_dispatch_latency",
            }
        )

    active_regressions: list[dict[str, Any]] = []
    for source_surface, assessment in (
        ("turn_execution", turn_regression_assessment),
        ("selector_routing", selector_regression_assessment),
        ("pre_dispatch_latency", latency_regression_assessment),
    ):
        comparisons_raw = assessment.get("comparisons")
        comparisons = comparisons_raw if isinstance(comparisons_raw, list) else []
        for raw_comparison in comparisons:
            if not isinstance(raw_comparison, Mapping):
                continue
            if not bool(raw_comparison.get("regressed")):
                continue
            active_regressions.append(
                {
                    **raw_comparison,
                    "source_surface": source_surface,
                }
            )

    summary_cards = _build_execution_dashboard_summary_cards(
        turn_metrics=turn_metrics,
        selector_metrics=selector_metrics,
        latency_summary=latency_summary,
        imposition_assessment=imposition_assessment,
        turn_regression_assessment=turn_regression_assessment,
        selector_regression_assessment=selector_regression_assessment,
        latency_regression_assessment=latency_regression_assessment,
    )
    recommendations = _combine_dashboard_recommendations(
        turn_report=turn_execution_report,
        selector_report=selector_report,
        latency_regression_assessment=latency_regression_assessment,
        imposition_assessment=imposition_assessment,
    )

    payload = {
        "collection": "turn_execution_dashboard",
        "dashboard_generated_at_utc": _utc_now_iso(),
        "filters": {
            "turn_execution": turn_execution_report.get("filters"),
            "selector_routing": selector_report.get("filters"),
            "selector_case_set": kwargs.get("selector_case_set"),
            "selector_bundle_path": kwargs.get("selector_bundle_path"),
            "selector_max_cases": kwargs.get("selector_max_cases"),
            "baseline_selector_accuracy_pct": kwargs.get(
                "baseline_selector_accuracy_pct"
            ),
            "baseline_selector_misrouting_rate_pct": kwargs.get(
                "baseline_selector_misrouting_rate_pct"
            ),
            "baseline_pre_dispatch_avg_duration_ms": kwargs.get(
                "baseline_pre_dispatch_avg_duration_ms"
            ),
            "baseline_pre_dispatch_p95_duration_ms": kwargs.get(
                "baseline_pre_dispatch_p95_duration_ms"
            ),
            "latency_regression_tolerance_pct": kwargs.get(
                "latency_regression_tolerance_pct"
            ),
        },
        "overview": {
            "turn_execution": {
                "benchmark_fingerprint": turn_execution_report.get(
                    "benchmark_fingerprint"
                ),
                "scanned_count": turn_metrics.get("scanned_count"),
                "likely_failure_rate_pct": turn_metrics.get("likely_failure_rate_pct"),
                "false_success_rate_pct": turn_metrics.get("false_success_rate_pct"),
                "unresolved_follow_up_rate_pct": turn_metrics.get(
                    "unresolved_follow_up_rate_pct"
                ),
                "terminal_outcome_receipts": turn_metrics.get(
                    "terminal_outcome_receipts"
                )
                or {},
            },
            "selector_routing": {
                "benchmark_fingerprint": selector_report.get("benchmark_fingerprint"),
                "scanned_count": selector_metrics.get("scanned_count"),
                "selector_accuracy_pct": selector_metrics.get("selector_accuracy_pct"),
                "selector_misrouting_rate_pct": (
                    selector_metrics.get("outcome_label_rates_pct", {}).get(
                        "tool_or_workflow_misrouting_rate_pct"
                    )
                    if isinstance(
                        selector_metrics.get("outcome_label_rates_pct"), Mapping
                    )
                    else None
                ),
            },
            "pre_dispatch_latency": latency_summary,
            "minimal_imposition": {
                "weighted_cost_pct": imposition_assessment.get("weighted_cost_pct"),
                "weighted_score_pct": imposition_assessment.get("weighted_score_pct"),
                "status": imposition_assessment.get("status"),
                "dimension_counts": imposition_assessment.get("dimension_counts") or {},
            },
            "operational_certification": (
                {
                    "run_id": operational_run_id,
                    "certified": operational_certification.get("certified"),
                    "report_sha256": operational_certification.get("report_sha256"),
                    "pass_rates": operational_certification.get("pass_rates") or {},
                    "family_pass_rates": {
                        family_id: (
                            family.get("pass_rates")
                            if isinstance(family, Mapping)
                            else {}
                        )
                        for family_id, family in (
                            operational_certification.get("families") or {}
                        ).items()
                    },
                    "failed_certification_gate_ids": operational_certification.get(
                        "failed_certification_gate_ids"
                    )
                    or [],
                }
                if operational_certification
                else {}
            ),
        },
        "summary_cards": summary_cards,
        "regression_views": {
            "turn_execution": turn_regression_assessment,
            "selector_routing": selector_regression_assessment,
            "pre_dispatch_latency": latency_regression_assessment,
            "active_regressions": active_regressions,
        },
        "trend_views": turn_execution_report.get("trend_views") or {},
        "latency_views": latency_views,
        "drilldowns": {
            "turn_execution_replay_cases": turn_execution_report.get("replay_cases")
            or [],
            "selector_replay_cases": selector_report.get("replay_cases") or [],
            "turn_execution_triage_index": turn_execution_report.get("triage_index")
            or {},
        },
        "benchmark_signals": combined_signals,
        "benchmark_signal_summary": _build_measurement_dashboard_signal_summary(
            combined_signals
        ),
        "imposition_assessment": imposition_assessment,
        "recommendations": recommendations,
        "data_sources": {
            "turn_execution_report": {
                "item_kind": (
                    turn_execution_report.get("provenance", {}).get("item_kind")
                    if isinstance(turn_execution_report.get("provenance"), Mapping)
                    else None
                ),
                "benchmark_fingerprint": turn_execution_report.get(
                    "benchmark_fingerprint"
                ),
            },
            "selector_report": {
                "item_kind": (
                    selector_report.get("provenance", {}).get("item_kind")
                    if isinstance(selector_report.get("provenance"), Mapping)
                    else None
                ),
                "benchmark_fingerprint": selector_report.get("benchmark_fingerprint"),
                "corpus": selector_report.get("corpus") or {},
            },
            "operational_certification": (
                {
                    "run_id": operational_run_id,
                    "report_sha256": operational_certification.get("report_sha256"),
                    "contract_sha256": operational_certification.get("contract_sha256"),
                    "source": "experiment_run.operational_certification_campaign",
                }
                if operational_certification
                else {}
            ),
        },
        "success": True,
    }
    if operational_certification:
        payload["effective_namespace"] = effective_operational_namespace
        payload["user_id"] = effective_operational_user_id
        payload["org_id"] = effective_operational_org_id
    return _with_rag_provenance(
        payload=payload,
        item_kind="turn_execution_dashboard_report",
        source_system="composite.turn_execution_dashboard",
    )


