_DELEGATED_TELEMETRY_STDIO_MAX_RESPONSE_CHARS_DEFAULT = 100_000
_DELEGATED_TELEMETRY_STDIO_MAX_RESPONSE_CHARS_MIN = 10_000
_DELEGATED_TELEMETRY_PAGE_CONTEXT_FIELDS = (
    "request_id",
    "history_location",
    "read_delegation",
    "provenance",
    "session_id",
    "chat_session_id",
    "history_owner_user_id",
    "requested_user_id",
    "namespace",
    "access_mode",
    "session_name",
    "session_name_source",
    "last_message_at",
    "created_at",
    "identifier_binding",
    "history_coverage",
)


def _delegated_telemetry_json_default(value: Any) -> Any:
    """Return a stable JSON representation for persisted BSON/Python values."""

    if isinstance(value, datetime):
        normalised = value
        if normalised.tzinfo is None:
            normalised = normalised.replace(tzinfo=timezone.utc)
        return normalised.isoformat()
    if isinstance(value, (set, frozenset)):
        return sorted(value, key=lambda item: str(item))
    return str(value)


def _delegated_telemetry_stdio_max_response_chars() -> int:
    """Mirror the stdio text guard without importing its catalogue consumer."""

    raw_value = os.getenv("VON_MCP_STDIO_MAX_RESPONSE_CHARS")
    if raw_value:
        try:
            parsed = int(raw_value)
        except ValueError:
            parsed = _DELEGATED_TELEMETRY_STDIO_MAX_RESPONSE_CHARS_DEFAULT
        return max(_DELEGATED_TELEMETRY_STDIO_MAX_RESPONSE_CHARS_MIN, parsed)
    return _DELEGATED_TELEMETRY_STDIO_MAX_RESPONSE_CHARS_DEFAULT


def _delegated_telemetry_stdio_response_chars(payload: Mapping[str, Any]) -> int:
    """Measure the exact JSON text length checked by the stdio response guard."""

    import json

    return len(
        json.dumps(
            dict(payload),
            indent=2,
            ensure_ascii=True,
            default=_delegated_telemetry_json_default,
        )
    )


def _bounded_delegated_telemetry_payload(
    payload: Mapping[str, Any],
    *,
    arguments: Mapping[str, Any],
    delegated: bool,
    artifact_kind: str,
    preserve_inline_below_limit: bool,
) -> dict[str, Any]:
    """Keep bearer-delegated stdio reads below the MCP text response guard."""

    if not delegated:
        return dict(payload)

    import hashlib
    import json

    default_limit = 60_000
    max_limit = 75_000
    raw_offset = arguments.get("offset", 0)
    raw_limit = arguments.get("limit", default_limit)
    offset = (
        raw_offset
        if isinstance(raw_offset, int) and not isinstance(raw_offset, bool)
        else 0
    )
    limit = (
        raw_limit
        if isinstance(raw_limit, int) and not isinstance(raw_limit, bool)
        else default_limit
    )
    offset = max(0, offset)
    limit = min(max_limit, max(1, limit))
    canonical_json = json.dumps(
        dict(payload),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        default=_delegated_telemetry_json_default,
    )
    canonical_payload = json.loads(canonical_json)
    total_chars = len(canonical_json)
    digest = hashlib.sha256(canonical_json.encode("utf-8")).hexdigest()
    response_limit = _delegated_telemetry_stdio_max_response_chars()

    page_context: dict[str, Any] = {
        "success": True,
        "artifact_kind": artifact_kind,
    }
    for field_name in _DELEGATED_TELEMETRY_PAGE_CONTEXT_FIELDS:
        if field_name in canonical_payload or field_name in {
            "request_id",
            "history_location",
            "read_delegation",
            "provenance",
        }:
            page_context[field_name] = canonical_payload.get(field_name)

    def _page_for_end(end: int) -> dict[str, Any]:
        return {
            "schema_version": "bounded_telemetry_json_page.v1",
            "artifact_kind": artifact_kind,
            "encoding": "canonical_json_ascii",
            "sha256": digest,
            "offset": offset,
            "limit": limit,
            "returned_chars": max(0, end - offset),
            "total_chars": total_chars,
            "has_more": end < total_chars,
            "next_offset": end if end < total_chars else None,
            "json_chunk": (canonical_json[offset:end] if offset <= total_chars else ""),
        }

    def _paged_response_for_end(end: int) -> dict[str, Any]:
        return {
            **page_context,
            "bounded_read": _page_for_end(end),
        }

    if preserve_inline_below_limit and offset == 0 and total_chars <= limit:
        inline_page = _page_for_end(total_chars)
        inline_payload = {
            **canonical_payload,
            "bounded_read": {
                key: value for key, value in inline_page.items() if key != "json_chunk"
            },
        }
        if _delegated_telemetry_stdio_response_chars(inline_payload) <= response_limit:
            return inline_payload

    requested_end = min(total_chars, offset + limit)
    requested_page = _paged_response_for_end(requested_end)
    if _delegated_telemetry_stdio_response_chars(requested_page) <= response_limit:
        return requested_page

    low = min(offset, total_chars)
    high = requested_end
    while low < high:
        candidate_end = (low + high + 1) // 2
        candidate_page = _paged_response_for_end(candidate_end)
        if _delegated_telemetry_stdio_response_chars(candidate_page) <= response_limit:
            low = candidate_end
        else:
            high = candidate_end - 1

    if low <= offset and offset < total_chars:
        return {
            **page_context,
            "success": False,
            "error_code": "telemetry_page_envelope_too_large",
            "message": (
                "Authority-bound telemetry page metadata exceeds the configured "
                "stdio response guard."
            ),
            "response_guard_chars": response_limit,
        }
    return _paged_response_for_end(low)


def _conversation_list(**kwargs):
    from ...services import chat_history_service
    from ...services.conversation_management_service import (
        ConversationManagementError,
        list_actor_conversations,
    )

    actor_scope, scope_error = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="conversation_list",
        require_actor=True,
    )
    if scope_error is not None:
        return scope_error
    if actor_scope is None or not actor_scope.user_concept_id:
        return make_error_response(
            "authenticated_actor_context_required",
            "Conversation discovery requires a trusted authenticated user.",
        )
    try:
        raw_limit = kwargs.get("limit", 20)
        limit = int(raw_limit) if raw_limit is not None else 20
    except (TypeError, ValueError):
        return make_error_response(
            "invalid_limit", "Conversation list limit must be an integer."
        )
    include_hidden = kwargs.get("include_hidden", False)
    if not isinstance(include_hidden, bool):
        return make_error_response(
            "invalid_include_hidden", "include_hidden must be a boolean."
        )
    include_trashed = kwargs.get("include_trashed", False)
    if not isinstance(include_trashed, bool):
        return make_error_response(
            "invalid_include_trashed", "include_trashed must be a boolean."
        )
    name_present = kwargs.get("name_present")
    if name_present is not None and not isinstance(name_present, bool):
        return make_error_response(
            "invalid_name_present", "name_present must be true, false, or omitted."
        )
    if kwargs.get("cursor_evidence_id") is not None and kwargs.get("cursor") is None:
        return make_error_response(
            "cursor_evidence_requires_turn_runtime",
            "cursor_evidence_id is resolved only by the actor-bound turn runtime; "
            "direct MCP clients must pass cursor.",
        )
    try:
        return list_actor_conversations(
            actor_user_id=str(actor_scope.user_concept_id),
            namespace=actor_scope.namespace,
            organisation_concept_id=actor_scope.organisation_concept_id,
            limit=max(1, min(limit, 100)),
            include_hidden=include_hidden,
            include_trashed=include_trashed,
            cursor=_clean_optional_string(kwargs.get("cursor")),
            name_present=name_present,
            cursor_context=None,
        )
    except (
        ConversationManagementError,
        chat_history_service.ChatHistoryServiceError,
    ) as exc:
        return make_error_response(
            "conversation_list_failed",
            str(exc),
        )


def _conversation_search(**kwargs):
    from ...services.conversation_search_service import (
        ConversationSearchError,
        search_actor_conversations,
    )

    actor_scope, scope_error = _resolve_internal_mcp_scoped_assertion_actor_scope(
        kwargs,
        surface="conversation_search",
        require_actor=True,
    )
    if scope_error is not None:
        return scope_error
    if actor_scope is None or not actor_scope.user_concept_id:
        return make_error_response(
            "authenticated_actor_context_required",
            "Conversation search requires a trusted authenticated user.",
        )
    filters = (
        dict(kwargs.get("filters"))
        if isinstance(kwargs.get("filters"), dict)
        else {}
    )
    typed_filter_fields = {
        "date_from": str,
        "date_to": str,
        "focal_concept_id": str,
        "access_mode": str,
        "hidden": bool,
        "pinned": bool,
        "trashed": bool,
        "name_present": bool,
    }
    for field_name, expected_type in typed_filter_fields.items():
        field_value = kwargs.get(field_name)
        if field_value is not None:
            if not isinstance(field_value, expected_type):
                return make_error_response(
                    "conversation_search_failed",
                    f"{field_name} must be a {expected_type.__name__} or omitted.",
                )
            nested_value = filters.get(field_name)
            if nested_value is not None and nested_value != field_value:
                return make_error_response(
                    "conversation_search_failed",
                    f"Conflicting {field_name} values were supplied.",
                )
            filters[field_name] = field_value
    name_present = kwargs.get("name_present")
    if name_present is not None:
        if not isinstance(name_present, bool):
            return make_error_response(
                "conversation_search_failed",
                "name_present must be true, false, or omitted.",
            )
    if kwargs.get("cursor_evidence_id") is not None and kwargs.get("cursor") is None:
        return make_error_response(
            "cursor_evidence_requires_turn_runtime",
            "cursor_evidence_id is resolved only by the actor-bound turn runtime; "
            "direct MCP clients must pass cursor.",
        )
    try:
        return search_actor_conversations(
            actor_user_id=str(actor_scope.user_concept_id),
            namespace=actor_scope.namespace,
            organisation_concept_id=actor_scope.organisation_concept_id,
            query=kwargs.get("query"),
            match_mode=kwargs.get("match_mode") or "hybrid",
            filters=filters,
            sort=kwargs.get("sort") or "relevance",
            page_size=kwargs.get("page_size") or 20,
            cursor=_clean_optional_string(kwargs.get("cursor")),
            include_hidden=kwargs.get("include_hidden") is True,
            trashed_only=kwargs.get("trashed_only") is True,
        )
    except (ConversationSearchError, TypeError, ValueError) as exc:
        return make_error_response("conversation_search_failed", str(exc))


def _conversation_get(**kwargs):
    effective_kwargs = dict(kwargs)
    effective_kwargs["include_debug"] = False
    requested_tail_limit = effective_kwargs.get("history_tail_limit")
    effective_kwargs["history_tail_limit"] = min(
        100,
        (
            requested_tail_limit
            if isinstance(requested_tail_limit, int)
            and not isinstance(requested_tail_limit, bool)
            and requested_tail_limit > 0
            else 24
        ),
    )
    requested_segment_size = effective_kwargs.get("segment_size")
    effective_kwargs["segment_size"] = min(
        20,
        (
            requested_segment_size
            if isinstance(requested_segment_size, int)
            and not isinstance(requested_segment_size, bool)
            and requested_segment_size > 0
            else 20
        ),
    )
    payload = _chat_history_get_segments(**effective_kwargs)
    if isinstance(payload, dict):
        history_coverage = payload.get("history_coverage")
        if isinstance(history_coverage, dict):
            recovery = history_coverage.get("recovery")
            if isinstance(recovery, dict):
                recovery["tool_name"] = "conversation_get"
        if payload.get("success") is True and "segments" in payload:
            return _bounded_delegated_telemetry_payload(
                payload,
                arguments=effective_kwargs,
                delegated=True,
                artifact_kind="conversation",
                preserve_inline_below_limit=True,
            )
    return payload


def _conversation_transcript_page(**kwargs):
    from ...services import chat_history_service
    from ...services.opaque_cursor_service import (
        OpaqueCursorError,
        decode_opaque_cursor,
        encode_opaque_cursor,
    )

    if kwargs.get("cursor_evidence_id") is not None and kwargs.get("cursor") is None:
        return make_error_response(
            "cursor_evidence_requires_turn_runtime",
            "cursor_evidence_id is resolved only by the actor-bound turn runtime; "
            "direct MCP clients must pass cursor.",
        )
    access = _resolve_chat_history_read_target(kwargs)
    if not isinstance(access, dict) or not access.get("success", False):
        return access
    requested_page_size = kwargs.get("page_size", 50)
    if (
        not isinstance(requested_page_size, int)
        or isinstance(requested_page_size, bool)
        or requested_page_size <= 0
    ):
        return make_error_response(
            "invalid_transcript_page_size",
            "page_size must be a positive integer.",
        )
    page_size = min(requested_page_size, 100)
    cursor_scope = {
        "actor_user_id": str(access["requested_user_id"]),
        "owner_user_id": str(access["read_user_id"]),
        "session_id": str(access["session_id"]),
        "namespace": _clean_optional_string(access.get("read_namespace")),
    }
    offset = 0
    raw_cursor = _clean_optional_string(kwargs.get("cursor"))
    if raw_cursor is not None:
        try:
            cursor_payload = decode_opaque_cursor(
                cursor=raw_cursor, purpose="conversation_transcript_page"
            )
        except OpaqueCursorError as exc:
            return make_error_response(
                "invalid_transcript_cursor", f"Invalid transcript cursor: {exc}"
            )
        if cursor_payload.get("scope") != cursor_scope:
            return make_error_response(
                "invalid_transcript_cursor",
                "Transcript cursor actor or conversation scope changed.",
            )
        raw_offset = cursor_payload.get("offset")
        if not isinstance(raw_offset, int) or isinstance(raw_offset, bool) or raw_offset < 0:
            return make_error_response(
                "invalid_transcript_cursor",
                "Transcript cursor offset is invalid.",
            )
        offset = raw_offset
    try:
        page = chat_history_service.get_chat_history_transcript_page(
            user_id=str(access["read_user_id"]),
            session_id=str(access["session_id"]),
            namespace=_clean_optional_string(access.get("read_namespace")),
            include_legacy=True,
            offset=offset,
            page_size=page_size,
        )
    except chat_history_service.ChatHistoryServiceError as exc:
        return make_error_response("conversation_transcript_read_failed", str(exc))
    if page.get("found") is not True:
        return make_error_response(
            "conversation_not_found", "The conversation was no longer available."
        )
    next_cursor = None
    source_has_more = page.get("has_more") is True
    source_next_offset = page.get("next_offset")
    if source_has_more and (
        not isinstance(source_next_offset, int)
        or isinstance(source_next_offset, bool)
        or source_next_offset <= offset
    ):
        return make_error_response(
            "conversation_transcript_read_failed",
            "The transcript source did not provide a valid forward continuation.",
        )
    if source_has_more:
        next_cursor = encode_opaque_cursor(
            purpose="conversation_transcript_page",
            payload={"scope": cursor_scope, "offset": source_next_offset},
            ttl_seconds=24 * 60 * 60,
        )
    payload = {
        "success": True,
        "schema_version": "conversation_transcript_page.v1",
        "session_id": access.get("session_id"),
        "access_mode": access.get("access_mode"),
        "history_owner_user_id": access.get("read_user_id"),
        "messages": page.get("messages", []),
        "message_count": page.get("message_count"),
        "page_count": page.get("page_count"),
        "page_size": page_size,
        "transcript_offset": page.get("offset"),
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
        "coverage_complete": (
            page.get("coverage_complete") is True and next_cursor is None
        ),
        "transport_paging": {
            "cursor_field": "bounded_read.next_offset",
            "distinct_from_transcript_cursor": True,
        },
    }
    return _bounded_delegated_telemetry_payload(
        payload,
        arguments={"offset": kwargs.get("offset"), "limit": kwargs.get("limit")},
        delegated=True,
        artifact_kind="conversation_transcript_page",
        preserve_inline_below_limit=True,
    )


def _conversation_title_evidence_for_access(access: Mapping[str, Any]) -> dict[str, Any]:
    from ...services import chat_history_service
    from ...services.conversation_management_service import (
        apply_conversation_preferences,
        build_canonical_conversation_reference,
        build_conversation_title_evidence,
    )

    actor_user_id = str(access["requested_user_id"])
    owner_user_id = str(access["read_user_id"])
    session_id = str(access["session_id"])
    namespace = _clean_optional_string(access.get("read_namespace"))
    source_evidence = chat_history_service.get_chat_history_title_evidence(
        user_id=owner_user_id,
        session_id=session_id,
        namespace=namespace,
        include_legacy=True,
    )
    if not isinstance(source_evidence, Mapping):
        return make_error_response(
            "conversation_not_found", "The conversation was no longer available."
        )
    visible_rows = apply_conversation_preferences(
        actor_user_id=actor_user_id,
        conversations=[
            {
                "session_id": session_id,
                "session_name": source_evidence.get("session_name"),
            }
        ],
    )
    visible_name = visible_rows[0].get("session_name") if visible_rows else None
    evidence = build_conversation_title_evidence(
        actor_user_id=actor_user_id,
        owner_user_id=owner_user_id,
        session_id=session_id,
        namespace=namespace,
        access_mode=str(access.get("access_mode") or "owner"),
        current_display_name=(
            visible_name if isinstance(visible_name, str) else None
        ),
        source_evidence=source_evidence,
    )
    evidence["conversation_reference"] = build_canonical_conversation_reference(
        owner_user_id=owner_user_id,
        session_id=session_id,
        namespace=namespace,
        organisation_concept_id=access.get("organisation_concept_id"),
    )
    return {"success": True, "evidence": evidence}


def _conversation_inspect_batch(**kwargs):
    from ...services import chat_history_service
    from ...services.conversation_management_service import ConversationManagementError

    mode = _clean_optional_string(kwargs.get("mode")) or "title_evidence"
    if mode != "title_evidence":
        return make_error_response(
            "unsupported_conversation_inspection_mode",
            "conversation_inspect_batch currently supports mode='title_evidence'.",
        )
    raw_targets = kwargs.get("conversation_refs")
    if not isinstance(raw_targets, list):
        raw_targets = kwargs.get("session_ids")
    if not isinstance(raw_targets, list) or not raw_targets:
        return make_error_response(
            "missing_conversation_inspection_targets",
            "conversation_refs or session_ids must contain at least one target.",
        )
    if len(raw_targets) > 50:
        return make_error_response(
            "conversation_inspection_batch_too_large",
            "A conversation inspection batch is limited to 50 targets.",
        )

    def _failure_state(result: Mapping[str, Any]) -> str:
        error_code = str(result.get("error_code") or result.get("error") or "")
        if error_code == "conversation_not_found":
            return "missing"
        if error_code in {
            "PERMISSION_DENIED",
            "authenticated_actor_context_required",
        }:
            return "denied"
        if error_code.endswith("_FAILED") or error_code.endswith("_failed"):
            return "unavailable"
        return "invalid"

    results: list[dict[str, Any]] = []
    for index, target in enumerate(raw_targets):
        forwarded = {
            key: kwargs.get(key)
            for key in (
                "acting_user_concept_id",
                "organisation_concept_id",
                "namespace",
            )
            if kwargs.get(key) is not None
        }
        if isinstance(target, Mapping):
            forwarded["conversation_ref"] = dict(target)
        elif isinstance(target, str) and target.strip():
            forwarded["session_id"] = target.strip()
        else:
            results.append(
                {
                    "success": False,
                    "status": "invalid",
                    "index": index,
                    "error_code": "invalid_conversation_inspection_target",
                    "message": "Target must be a conversation reference or session ID.",
                }
            )
            continue
        access = _resolve_chat_history_read_target(forwarded)
        if not isinstance(access, dict) or not access.get("success", False):
            state = _failure_state(access)
            results.append(
                {
                    "index": index,
                    "status": state,
                    "evidence_state": state,
                    **access,
                }
            )
            continue
        try:
            result = _conversation_title_evidence_for_access(access)
        except (
            ConversationManagementError,
            chat_history_service.ChatHistoryServiceError,
        ) as exc:
            result = make_error_response(
                "conversation_inspection_failed", str(exc)
            )
        if result.get("success") is True:
            evidence = result.get("evidence") or {}
            evidence_truncated = any(
                isinstance(message, Mapping)
                and message.get("content_truncated") is True
                for message in (
                    evidence.get("first_user_message"),
                    evidence.get("latest_user_message"),
                )
            )
            status = (
                "ready"
                if evidence.get("eligible_for_rename") is True
                else (
                    "already_named"
                    if evidence.get("ineligibility_reason")
                    == "existing_name_present"
                    else "insufficient_evidence"
                )
            )
            evidence_state = (
                "truncated"
                if evidence_truncated
                else (
                    "insufficient"
                    if status == "insufficient_evidence"
                    else "complete"
                )
            )
            results.append(
                {
                    "index": index,
                    "success": True,
                    "status": status,
                    "evidence_state": evidence_state,
                    "evidence_truncated": evidence_truncated,
                    **result,
                }
            )
        else:
            state = _failure_state(result)
            results.append(
                {
                    "index": index,
                    "status": state,
                    "evidence_state": state,
                    **result,
                }
            )
    succeeded_count = sum(1 for row in results if row.get("success") is True)
    failed_count = len(results) - succeeded_count
    title_evidence_items: list[dict[str, Any]] = []
    for row in results:
        evidence = row.get("evidence")
        evidence_mapping = evidence if isinstance(evidence, Mapping) else {}
        first_user_message = evidence_mapping.get("first_user_message")
        first_user_mapping = (
            first_user_message if isinstance(first_user_message, Mapping) else {}
        )
        latest_user_message = evidence_mapping.get("latest_user_message")
        latest_user_mapping = (
            latest_user_message if isinstance(latest_user_message, Mapping) else {}
        )
        title_evidence_items.append(
            {
                "index": row.get("index"),
                "session_id": (
                    evidence_mapping.get("session_id") or row.get("session_id")
                ),
                "status": row.get("status"),
                "evidence_state": row.get("evidence_state"),
                "eligible_for_rename": evidence_mapping.get(
                    "eligible_for_rename"
                ),
                "current_display_name": evidence_mapping.get(
                    "current_display_name"
                ),
                "first_user_text": first_user_mapping.get("content"),
                "first_user_text_truncated": first_user_mapping.get(
                    "content_truncated"
                ),
                "latest_user_text": latest_user_mapping.get("content"),
                "latest_user_text_truncated": latest_user_mapping.get(
                    "content_truncated"
                ),
                "error_code": row.get("error_code"),
            }
        )
    return {
        "success": failed_count == 0,
        "schema_version": "conversation_inspection_batch.v1",
        "mode": mode,
        "count": len(results),
        "succeeded_count": succeeded_count,
        "failed_count": failed_count,
        "title_evidence_items": title_evidence_items,
        "results": results,
    }


def _conversation_manage(**kwargs):
    from ...services import chat_history_service
    from ...services.conversation_management_service import (
        ConversationManagementError,
        apply_conversation_preferences,
        set_conversation_preference,
        validate_conversation_rename_evidence_token,
    )

    action = _clean_optional_string(kwargs.get("action"))
    if action is None:
        return make_error_response("missing_action", "action is required.")
    action = action.lower()
    supported_actions = {
        "rename",
        "hide",
        "unhide",
        "pin",
        "unpin",
        "trash",
        "restore",
    }
    if action not in supported_actions:
        return make_error_response(
            "unsupported_conversation_action",
            f"Unsupported conversation action: {action}",
            details={"supported_actions": sorted(supported_actions)},
        )

    access = _resolve_chat_history_read_target(kwargs)
    if not isinstance(access, dict) or not access.get("success", False):
        return access
    session_id = str(access["session_id"])
    actor_user_id = str(access["requested_user_id"])
    history_owner_user_id = str(access["read_user_id"])
    changed = False

    try:
        if action in {"trash", "restore"}:
            if history_owner_user_id != actor_user_id:
                return make_error_response(
                    "PERMISSION_DENIED",
                    "Only the conversation owner can move a conversation to or from Trash.",
                )
            lifecycle_result = chat_history_service.set_chat_session_trashed(
                user_id=history_owner_user_id,
                session_id=session_id,
                trashed=action == "trash",
                actor_user_id=actor_user_id,
                namespace=_clean_optional_string(access.get("read_namespace")),
                organisation_concept_id=_clean_optional_string(
                    access.get("organisation_concept_id")
                ),
                include_legacy=False,
            )
            if not lifecycle_result.get("matched"):
                return make_error_response(
                    "conversation_not_found",
                    "The conversation was no longer available.",
                )
            changed = lifecycle_result.get("changed") is True
        elif action == "rename":
            session_name = _clean_optional_string(kwargs.get("session_name"))
            if session_name is None:
                return make_error_response(
                    "missing_session_name",
                    "session_name is required for rename.",
                )
            evidence_binding = None
            evidence_idempotent_replay = False
            evidence_token = _clean_optional_string(kwargs.get("evidence_token"))
            if evidence_token is not None:
                try:
                    evidence_binding = validate_conversation_rename_evidence_token(
                        evidence_token=evidence_token,
                        actor_user_id=actor_user_id,
                        owner_user_id=history_owner_user_id,
                        session_id=session_id,
                        namespace=_clean_optional_string(access.get("read_namespace")),
                    )
                    current_evidence_result = _conversation_title_evidence_for_access(
                        access
                    )
                except ConversationManagementError as exc:
                    return make_error_response(
                        "invalid_conversation_rename_evidence", str(exc)
                    )
                if current_evidence_result.get("success") is not True:
                    return current_evidence_result
                current_evidence = current_evidence_result.get("evidence") or {}
                current_revision = current_evidence.get("source_revision") or {}
                fresh_unnamed_evidence = (
                    current_evidence.get("eligible_for_rename") is True
                    and current_revision.get("evidence_fingerprint")
                    == evidence_binding.get("evidence_fingerprint")
                )
                evidence_idempotent_replay = (
                    current_evidence.get("current_display_name") == session_name
                    and current_revision.get("source_evidence_fingerprint")
                    == evidence_binding.get("source_evidence_fingerprint")
                )
                if not fresh_unnamed_evidence and not evidence_idempotent_replay:
                    return make_error_response(
                        "stale_conversation_rename_evidence",
                        "The conversation name or transcript changed after inspection; inspect it again before renaming.",
                    )
            if evidence_idempotent_replay:
                changed = False
            elif history_owner_user_id == actor_user_id:
                rename_result = chat_history_service.rename_chat_session(
                    user_id=history_owner_user_id,
                    session_id=session_id,
                    session_name=session_name,
                    namespace=_clean_optional_string(access.get("read_namespace")),
                    include_legacy=True,
                    require_unnamed=evidence_binding is not None,
                    expected_updated_at=(
                        evidence_binding.get("source_updated_at")
                        if isinstance(evidence_binding, Mapping)
                        else None
                    ),
                )
                if not rename_result.get("matched"):
                    if evidence_binding is not None:
                        return make_error_response(
                            "stale_conversation_rename_evidence",
                            "The conversation changed before the evidence-bound rename could be applied.",
                        )
                    return make_error_response(
                        "conversation_not_found",
                        "The conversation was no longer available to rename.",
                    )
                changed = rename_result.get("updated") is True
            else:
                preference_result = set_conversation_preference(
                    actor_user_id=actor_user_id,
                    session_id=session_id,
                    session_name_override=session_name,
                    update_session_name_override=True,
                )
                changed = preference_result.get("changed") is True
        else:
            preference_kwargs: dict[str, Any] = {}
            if action in {"hide", "unhide"}:
                preference_kwargs["hidden"] = action == "hide"
            else:
                preference_kwargs["pinned"] = action == "pin"
            preference_result = set_conversation_preference(
                actor_user_id=actor_user_id,
                session_id=session_id,
                **preference_kwargs,
            )
            changed = preference_result.get("changed") is True

        summary = chat_history_service.get_chat_history_session_summary(
            history_owner_user_id,
            session_id,
            namespace=_clean_optional_string(access.get("read_namespace")),
            include_legacy=True,
            summary_mode="light",
        )
        if not isinstance(summary, Mapping):
            return {
                "success": False,
                "effect_status": "indeterminate",
                "changed": changed,
                "error": "conversation_read_back_failed",
                "error_code": "conversation_read_back_failed",
                "message": (
                    "The conversation may have been updated, but canonical read-back "
                    "did not confirm the current conversation state."
                ),
                "session_id": session_id,
            }
        summary_row = dict(summary)
        if history_owner_user_id != actor_user_id:
            summary_row.update(
                {
                    "shared_with_me": True,
                    "shared_owner_user_id": history_owner_user_id,
                }
            )
        read_back_rows = apply_conversation_preferences(
            actor_user_id=actor_user_id,
            conversations=[summary_row],
        )
        if not read_back_rows:
            return make_error_response(
                "conversation_read_back_failed",
                "Canonical conversation preference read-back failed.",
            )
        canonical_read_back = read_back_rows[0]
    except chat_history_service.ConversationActiveWorkError as exc:
        return make_error_response(
            "conversation_has_active_work",
            str(exc),
        )
    except (
        ConversationManagementError,
        chat_history_service.ChatHistoryServiceError,
    ) as exc:
        return make_error_response(
            "conversation_manage_failed",
            str(exc),
        )

    return {
        "success": True,
        "effect_status": "succeeded",
        "changed": changed,
        "action": action,
        "session_id": session_id,
        "request_id": _clean_optional_string(kwargs.get("request_id")),
        "access_mode": access.get("access_mode"),
        "history_owner_user_id": history_owner_user_id,
        "actor_user_id": actor_user_id,
        "effect_id": (
            lifecycle_result.get("effect_id")
            if action in {"trash", "restore"}
            else None
        ),
        "index_reconciliation": (
            lifecycle_result.get("index_reconciliation")
            if action in {"trash", "restore"}
            else None
        ),
        "active_work": (
            lifecycle_result.get("active_work")
            if action in {"trash", "restore"}
            else None
        ),
        "sharing_impact": (
            lifecycle_result.get("sharing_impact")
            if action in {"trash", "restore"}
            else None
        ),
        "related_records": (
            lifecycle_result.get("related_records")
            if action in {"trash", "restore"}
            else None
        ),
        "canonical_read_back": canonical_read_back,
    }


def _conversation_manage_batch(**kwargs):
    if kwargs.get("inspection_evidence_id") is not None:
        return make_error_response(
            "inspection_evidence_requires_turn_runtime",
            "inspection_evidence_id is resolved only by the actor-bound turn "
            "runtime; direct MCP clients must pass evidence_token values.",
        )
    action = _clean_optional_string(kwargs.get("action"))
    if action not in {"rename", "trash", "restore"}:
        return make_error_response(
            "unsupported_conversation_batch_action",
            "Batch conversation management supports rename, trash, or restore.",
        )
    raw_targets = kwargs.get("rename_items") if action == "rename" else None
    if not isinstance(raw_targets, list):
        raw_targets = kwargs.get("conversation_refs")
    if not isinstance(raw_targets, list):
        raw_targets = kwargs.get("session_ids")
    if not isinstance(raw_targets, list) or not raw_targets:
        return make_error_response(
            "missing_conversation_batch_targets",
            "rename_items, conversation_refs, or session_ids must contain at least one target.",
        )
    batch_limit = 50 if action == "rename" else 100
    if len(raw_targets) > batch_limit:
        return make_error_response(
            "conversation_batch_too_large",
            f"A {action} conversation batch is limited to {batch_limit} targets.",
        )
    continuation_cursor = _clean_optional_string(kwargs.get("continuation_cursor"))

    results: list[dict[str, Any]] = []
    for index, target in enumerate(raw_targets):
        forwarded = {
            key: kwargs.get(key)
            for key in (
                "acting_user_concept_id",
                "organisation_concept_id",
                "namespace",
                "request_id",
            )
            if kwargs.get(key) is not None
        }
        forwarded["action"] = action
        if action == "rename":
            if not isinstance(target, Mapping):
                results.append(
                    {
                        "success": False,
                        "effect_status": "not_attempted",
                        "index": index,
                        "error_code": "invalid_conversation_rename_item",
                        "message": "Each rename item must be an object.",
                    }
                )
                continue
            session_name = _clean_optional_string(target.get("session_name"))
            evidence_token = _clean_optional_string(target.get("evidence_token"))
            if session_name is None or evidence_token is None:
                results.append(
                    {
                        "success": False,
                        "effect_status": "not_attempted",
                        "index": index,
                        "error_code": "rename_evidence_required",
                        "message": "Each rename item requires session_name and evidence_token.",
                    }
                )
                continue
            forwarded["session_name"] = session_name
            forwarded["evidence_token"] = evidence_token
            item_ref = target.get("conversation_ref")
            item_session_id = _clean_optional_string(target.get("session_id"))
            if isinstance(item_ref, Mapping):
                forwarded["conversation_ref"] = dict(item_ref)
            elif item_session_id is not None:
                forwarded["session_id"] = item_session_id
            else:
                results.append(
                    {
                        "success": False,
                        "effect_status": "not_attempted",
                        "index": index,
                        "error_code": "invalid_conversation_rename_item",
                        "message": "Each rename item requires conversation_ref or session_id.",
                    }
                )
                continue
        elif isinstance(target, Mapping):
            forwarded["conversation_ref"] = dict(target)
        elif isinstance(target, str) and target.strip():
            forwarded["session_id"] = target.strip()
        else:
            results.append(
                {
                    "success": False,
                    "effect_status": "not_attempted",
                    "index": index,
                    "error_code": "invalid_conversation_batch_target",
                    "message": "Target must be a conversation reference or session ID.",
                }
            )
            continue
        item_result = _conversation_manage(**forwarded)
        results.append({"index": index, **item_result})

    succeeded_count = sum(1 for result in results if result.get("success") is True)
    failed_count = len(results) - succeeded_count
    effect_status = (
        "succeeded"
        if failed_count == 0
        else ("failed" if succeeded_count == 0 else "partial")
    )
    return {
        "success": failed_count == 0,
        "effect_status": effect_status,
        "action": action,
        "count": len(results),
        "succeeded_count": succeeded_count,
        "failed_count": failed_count,
        "results": results,
        "request_id": _clean_optional_string(kwargs.get("request_id")),
        "continuation_cursor": continuation_cursor,
    }


def _chat_history_get_segments(**kwargs):
    authorisation = _authorise_internal_mcp_telemetry_read(
        kwargs,
        tool_name="chat_history_get_segments",
        surface="chat history",
        reference_argument="conversation_ref",
        operator_control_plane=False,
    )
    if not authorisation.get("success"):
        return authorisation
    effective_kwargs = dict(authorisation["payload"])
    if authorisation.get("delegated"):
        effective_kwargs["include_debug"] = False
        requested_segment_size = effective_kwargs.get("segment_size")
        effective_kwargs["segment_size"] = min(
            20,
            (
                requested_segment_size
                if isinstance(requested_segment_size, int)
                and not isinstance(requested_segment_size, bool)
                and requested_segment_size > 0
                else 20
            ),
        )
        requested_tail_limit = effective_kwargs.get("history_tail_limit")
        effective_kwargs["history_tail_limit"] = min(
            100,
            (
                requested_tail_limit
                if isinstance(requested_tail_limit, int)
                and not isinstance(requested_tail_limit, bool)
                and requested_tail_limit > 0
                else 100
            ),
        )
    from ...services import chat_history_service

    access = _resolve_chat_history_read_target(effective_kwargs)
    if not isinstance(access, dict) or not access.get("success", False):
        return access

    include_debug = effective_kwargs.get("include_debug", True)
    if not isinstance(include_debug, bool):
        include_debug = bool(include_debug)
    include_legacy = effective_kwargs.get(
        "include_legacy", access.get("include_legacy", True)
    )
    if not isinstance(include_legacy, bool):
        include_legacy = bool(include_legacy)

    try:
        result = chat_history_service.get_chat_history_segments(
            str(access["read_user_id"]),
            str(access["session_id"]),
            include_locations=True,
            namespace=_clean_optional_string(access.get("read_namespace")),
            include_legacy=include_legacy,
            segment_size=effective_kwargs.get("segment_size"),
            include_debug=include_debug,
            history_tail_limit=effective_kwargs.get("history_tail_limit"),
            return_meta=True,
            include_conversation_state=True,
        )
    except chat_history_service.ChatHistoryServiceError as exc:
        return make_error_response(
            "CHAT_HISTORY_ERROR",
            str(exc),
            details={
                "session_id": access.get("session_id"),
                "namespace": access.get("read_namespace"),
            },
        )

    if isinstance(result, tuple):
        segments, meta = result
    else:
        segments, meta = result, {"history_truncated": False}

    meta_mapping = meta if isinstance(meta, Mapping) else {}
    session_name = _clean_optional_string(meta_mapping.get("session_name"))
    session_name_source = "conversation" if session_name is not None else None
    metadata_warnings: list[str] = []
    if access.get("access_mode") != "owner":
        from ...services.conversation_management_service import (
            ConversationManagementError,
            apply_conversation_preferences,
        )

        try:
            preference_rows = apply_conversation_preferences(
                actor_user_id=str(access["requested_user_id"]),
                conversations=[
                    {
                        "session_id": str(access["session_id"]),
                        "session_name": session_name,
                    }
                ],
            )
            preference_row = preference_rows[0] if preference_rows else {}
            session_name = _clean_optional_string(preference_row.get("session_name"))
            session_name_source = _clean_optional_string(
                preference_row.get("session_name_source")
            ) or ("conversation" if session_name is not None else None)
        except ConversationManagementError as exc:
            session_name = None
            session_name_source = None
            metadata_warnings.append(
                f"conversation_name_preference_unavailable:{type(exc).__name__}"
            )
    raw_situation = meta_mapping.get("conversation_situation")
    conversation_situation = (
        dict(raw_situation) if isinstance(raw_situation, Mapping) else None
    )
    raw_observations = meta_mapping.get("conversation_observations")
    conversation_observations = (
        list(raw_observations) if isinstance(raw_observations, list) else []
    )
    raw_observation_state = meta_mapping.get("conversation_observation_state")
    if isinstance(raw_observation_state, Mapping):
        conversation_observation_state = dict(raw_observation_state)
    else:
        conversation_observation_state = {
            "schema_version": "conversation_observation_state.v1",
            "retained_count": len(conversation_observations),
            "total_count": len(conversation_observations),
            "omitted_count": 0,
            "retention_limit": chat_history_service.CONVERSATION_OBSERVATION_MAX_ITEMS,
        }
    history_truncated = bool(meta_mapping.get("history_truncated", False))
    history_coverage = {
        "schema_version": "conversation_history_coverage.v1",
        "status": "truncated" if history_truncated else "complete",
        "history_truncated": history_truncated,
        "exhaustive_answer_supported": not history_truncated,
        "continuation_required_for_exhaustive_answer": history_truncated,
    }
    if history_truncated:
        history_coverage["recovery"] = {
            "tool_name": "chat_history_get_segments",
            "instruction": (
                "Repeat the active-conversation read without history_tail_limit "
                "before answering an exhaustive list or count request."
            ),
        }
    payload = {
        "success": True,
        "session_id": access.get("session_id"),
        "chat_session_id": access.get("chat_session_id"),
        "history_owner_user_id": access.get("read_user_id"),
        "requested_user_id": access.get("requested_user_id"),
        "namespace": access.get("read_namespace"),
        "access_mode": access.get("access_mode"),
        "session_name": session_name,
        "session_name_source": session_name_source,
        "last_message_at": _clean_optional_string(meta_mapping.get("last_message_at")),
        "created_at": _clean_optional_string(meta_mapping.get("created_at")),
        "identifier_binding": access.get("identifier_binding"),
        "segments": segments,
        "segment_count": len(segments) if isinstance(segments, list) else 0,
        "history_truncated": history_truncated,
        "history_coverage": history_coverage,
        "conversation_situation": conversation_situation,
        "conversation_observations": conversation_observations,
        "conversation_observation_state": conversation_observation_state,
    }
    if metadata_warnings:
        payload["warnings"] = metadata_warnings
    if authorisation.get("delegated"):
        payload["read_delegation"] = authorisation.get("read_delegation")
    provenanced_payload = _with_rag_provenance(
        payload=payload,
        item_kind="chat_history_segments",
        source_system="mongo.chat_history",
    )
    bounded_payload = _bounded_delegated_telemetry_payload(
        provenanced_payload,
        arguments=effective_kwargs,
        delegated=bool(authorisation.get("delegated")),
        artifact_kind="chat_history_segments",
        preserve_inline_below_limit=True,
    )
    if authorisation.get("delegated"):
        for field_name in (
            "session_id",
            "chat_session_id",
            "history_owner_user_id",
            "requested_user_id",
            "namespace",
            "access_mode",
            "session_name",
            "session_name_source",
            "last_message_at",
            "created_at",
            "identifier_binding",
            "read_delegation",
        ):
            if field_name in provenanced_payload:
                bounded_payload.setdefault(
                    field_name,
                    provenanced_payload[field_name],
                )
    return bounded_payload


def _chat_history_get_debug_entry(**kwargs):
    authorisation = _authorise_internal_mcp_telemetry_read(
        kwargs,
        tool_name="chat_history_get_debug_entry",
        surface="chat history",
        reference_argument="history_location_ref",
        operator_control_plane=False,
    )
    if not authorisation.get("success"):
        return authorisation
    effective_kwargs = dict(authorisation["payload"])
    from ...services import chat_history_service

    access = _resolve_chat_history_read_target(effective_kwargs)
    if not isinstance(access, dict) or not access.get("success", False):
        return access

    history_index = effective_kwargs.get("history_index")
    if not isinstance(history_index, int):
        history_index = access.get("history_index")
    if not isinstance(history_index, int) or history_index < 0:
        return make_error_response(
            "missing_parameter",
            "Missing required parameter: history_location_ref or history_index",
            details={"missing": ["history_location_ref", "history_index"]},
            suggestions=[
                "Provide an authoritative history_location_ref",
                "Or provide a non-negative history_index",
            ],
        )

    include_legacy = effective_kwargs.get(
        "include_legacy", access.get("include_legacy", True)
    )
    if not isinstance(include_legacy, bool):
        include_legacy = bool(include_legacy)

    try:
        debug_data = chat_history_service.get_chat_history_debug_entry(
            user_id=str(access["read_user_id"]),
            session_id=str(access["session_id"]),
            history_index=history_index,
            namespace=_clean_optional_string(access.get("read_namespace")),
            include_legacy=include_legacy,
        )
    except chat_history_service.ChatHistoryServiceError as exc:
        return make_error_response(
            "CHAT_HISTORY_ERROR",
            str(exc),
            details={
                "session_id": access.get("session_id"),
                "history_index": history_index,
                "namespace": access.get("read_namespace"),
            },
        )

    if not isinstance(debug_data, dict):
        return {
            "success": False,
            "error": "debug_not_available",
            "history_location": {
                "session_id": access.get("session_id"),
                "history_index": history_index,
            },
            "chat_session_id": access.get("chat_session_id"),
            "history_owner_user_id": access.get("read_user_id"),
            "requested_user_id": access.get("requested_user_id"),
            "namespace": access.get("read_namespace"),
            "access_mode": access.get("access_mode"),
            "identifier_binding": access.get("identifier_binding"),
        }

    payload = {
        "success": True,
        "history_location": {
            "session_id": access.get("session_id"),
            "history_index": history_index,
        },
        "chat_session_id": access.get("chat_session_id"),
        "history_owner_user_id": access.get("read_user_id"),
        "requested_user_id": access.get("requested_user_id"),
        "namespace": access.get("read_namespace"),
        "access_mode": access.get("access_mode"),
        "identifier_binding": access.get("identifier_binding"),
        "llm_debug_data": debug_data,
    }
    if authorisation.get("delegated"):
        payload["read_delegation"] = authorisation.get("read_delegation")
    result = _with_rag_provenance(
        payload=payload,
        item_kind="chat_history_debug_entry",
        source_system="mongo.chat_history",
    )
    return _bounded_delegated_telemetry_payload(
        result,
        arguments=effective_kwargs,
        delegated=bool(authorisation.get("delegated")),
        artifact_kind="chat_history_debug_entry",
        preserve_inline_below_limit=True,
    )


