def _workflow_bind_event(**kwargs):
    """Create or update an event -> workflow binding."""

    from ...workflows.durable import WorkflowInstanceManager
    from ...workflows.durable.registry_factory import (
        build_durable_workflow_registry_read_only,
    )
    from ...services.workflow_event_integration_service import (
        _normalise_event_binding_condition,
        resolve_event_actor_context,
    )

    event_type_raw = kwargs.get("event_type")
    workflow_id_raw = kwargs.get("workflow_id")
    if not isinstance(event_type_raw, str) or not event_type_raw.strip():
        return make_error_response(
            "missing_parameter",
            "event_type is required",
            details={"missing": ["event_type"]},
        )
    if not isinstance(workflow_id_raw, str) or not workflow_id_raw.strip():
        return make_error_response(
            "missing_parameter",
            "workflow_id is required",
            details={"missing": ["workflow_id"]},
        )
    if not _internal_mcp_global_workflow_admin_authorised():
        return make_error_response(
            "workflow_global_admin_authority_required",
            "Global workflow event-binding mutation requires trusted operator authority.",
        )

    event_type = event_type_raw.strip()
    workflow_id = workflow_id_raw.strip()

    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=kwargs.get("user_id"),
            org_id=kwargs.get("org_id"),
            namespace=kwargs.get("namespace"),
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)

    from ...workflows.workflow_listing_service import (
        filter_workflow_ids_for_current_actor,
    )

    if workflow_id not in filter_workflow_ids_for_current_actor([workflow_id]):
        return make_error_response(
            "not_found",
            "Workflow is not available for event binding.",
        )

    input_mapping_raw = kwargs.get("input_mapping")
    condition_raw = kwargs.get("condition")
    enabled = kwargs.get("enabled", True)
    replace_existing = kwargs.get("replace_existing", False)

    input_mapping: dict[str, str] = {}
    if isinstance(input_mapping_raw, dict):
        for key, value in input_mapping_raw.items():
            key_clean = str(key or "").strip()
            value_clean = str(value or "").strip()
            if key_clean and value_clean:
                input_mapping[key_clean] = value_clean

    try:
        condition = _normalise_event_binding_condition(condition_raw)
    except ValueError as exc:
        return make_error_response(
            "invalid_binding_condition",
            str(exc),
            details={"event_type": event_type, "workflow_id": workflow_id},
            suggestions=[
                "Use the workflow condition language, for example "
                "{'kind':'context_value_equals','key':'event.new_status','value':'completed'}."
            ],
        )

    if not isinstance(enabled, bool):
        enabled = bool(enabled)
    if not isinstance(replace_existing, bool):
        replace_existing = bool(replace_existing)

    # Mutation provenance is the authoritative ambient/operator actor, never a
    # caller-supplied audit label.
    actor_clean = actor_scope.user_concept_id
    if actor_clean is None:
        actor_clean, _actor_org = resolve_event_actor_context()

    workflow_registry_known: bool | None = None
    try:
        registry = build_durable_workflow_registry_read_only()
        workflow_registry_known = workflow_id in set(registry.all_workflow_ids())
    except Exception:
        workflow_registry_known = None

    manager = WorkflowInstanceManager()
    try:
        binding, created, updated = manager.upsert_event_binding(
            event_type=event_type,
            workflow_id=workflow_id,
            input_mapping=input_mapping,
            condition=condition,
            enabled=enabled,
            actor=actor_clean,
            replace_existing=replace_existing,
        )
    except ValueError as exc:
        if str(exc) == "binding_conflict":
            return make_error_response(
                "binding_conflict",
                (
                    "Binding already exists with different configuration. "
                    "Set replace_existing=true to overwrite."
                ),
                details={
                    "event_type": event_type,
                    "workflow_id": workflow_id,
                    "replace_existing": replace_existing,
                },
            )
        return make_error_response(
            "invalid_binding",
            str(exc),
            details={"event_type": event_type, "workflow_id": workflow_id},
        )
    except Exception as exc:
        return make_error_response(
            "bind_failed",
            f"Failed to bind event to workflow: {exc}",
            details={"event_type": event_type, "workflow_id": workflow_id},
        )

    return {
        "success": True,
        "binding": binding.to_status_dict(),
        "created": created,
        "updated": updated,
        "unchanged": not created and not updated,
        "workflow_registry_known": workflow_registry_known,
    }


def _workflow_list_event_bindings(**kwargs):
    """List authoritative persisted event -> workflow bindings."""

    if not _internal_mcp_global_workflow_admin_authorised():
        return make_error_response(
            "workflow_global_admin_authority_required",
            "Global workflow event-binding inspection requires trusted operator authority.",
        )

    from ...services.workflow_event_integration_service import (
        build_event_workflow_binding_diagnostics,
        list_event_workflow_bindings,
    )
    from ...workflows.workflow_listing_service import (
        filter_workflow_ids_for_current_actor,
    )

    try:
        _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=kwargs.get("user_id"),
            org_id=kwargs.get("org_id"),
            namespace=kwargs.get("namespace"),
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)

    event_type = kwargs.get("event_type")
    enabled_only = kwargs.get("enabled_only", False)
    try:
        limit = int(kwargs.get("limit", 100))
    except (TypeError, ValueError):
        limit = 100
    limit = max(1, min(limit, 500))

    if not isinstance(event_type, str) or not event_type.strip():
        event_type = None
    if not isinstance(enabled_only, bool):
        enabled_only = bool(enabled_only)

    bindings = list_event_workflow_bindings(
        event_type=event_type,
        enabled_only=enabled_only,
        limit=limit,
    )
    binding_workflow_ids = [
        item.get("workflow_id") for item in bindings if isinstance(item, Mapping)
    ]
    visible_workflow_ids = set(
        filter_workflow_ids_for_current_actor(binding_workflow_ids)
    )
    bindings = [
        item
        for item in bindings
        if isinstance(item, Mapping) and item.get("workflow_id") in visible_workflow_ids
    ]
    diagnostics = build_event_workflow_binding_diagnostics(bindings)
    return {
        "success": True,
        "bindings": bindings,
        "count": len(bindings),
        "diagnostics": diagnostics,
        "has_conflicts": any(
            str(item.get("severity") or "").strip().lower() == "warning"
            for item in diagnostics
            if isinstance(item, dict)
        ),
    }


def _workflow_set_event_binding_enabled(**kwargs):
    """Enable or disable a persisted event -> workflow binding."""

    from ...services.workflow_event_integration_service import (
        resolve_event_actor_context,
    )
    from ...workflows.durable import WorkflowInstanceManager

    binding_id = kwargs.get("binding_id")
    if not isinstance(binding_id, str) or not binding_id.strip():
        return make_error_response(
            "missing_parameter",
            "binding_id is required",
            details={"missing": ["binding_id"]},
        )
    if not _internal_mcp_global_workflow_admin_authorised():
        return make_error_response(
            "workflow_global_admin_authority_required",
            "Global workflow event-binding mutation requires trusted operator authority.",
        )

    enabled = kwargs.get("enabled")
    if not isinstance(enabled, bool):
        return make_error_response(
            "missing_parameter",
            "enabled (boolean) is required",
            details={"missing": ["enabled"]},
        )

    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=kwargs.get("user_id"),
            org_id=kwargs.get("org_id"),
            namespace=kwargs.get("namespace"),
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)

    actor_clean = actor_scope.user_concept_id
    if actor_clean is None:
        actor_clean, _actor_org = resolve_event_actor_context()

    manager = WorkflowInstanceManager()
    existing = manager.get_event_binding(binding_id.strip())
    if existing is None:
        return make_error_response(
            "not_found",
            f"Event binding not found: {binding_id}",
        )
    from ...workflows.workflow_listing_service import (
        filter_workflow_ids_for_current_actor,
    )

    if existing.workflow_id not in filter_workflow_ids_for_current_actor(
        [existing.workflow_id]
    ):
        return make_error_response(
            "not_found",
            f"Event binding not found: {binding_id}",
        )
    prior_enabled = bool(existing.enabled)
    prior_revision = int(existing.revision)

    try:
        binding = manager.set_event_binding_enabled(
            binding_id.strip(),
            enabled=enabled,
            actor=actor_clean,
        )
    except Exception as exc:
        return make_error_response(
            "update_failed",
            f"Failed to update event binding: {exc}",
            details={"binding_id": binding_id},
        )

    if binding is None:
        return make_error_response(
            "not_found",
            f"Event binding not found: {binding_id}",
        )

    return {
        "success": True,
        "binding": binding.to_status_dict(),
        "binding_id": binding.binding_id,
        "enabled": bool(binding.enabled),
        "updated": bool(
            prior_enabled != bool(binding.enabled)
            or prior_revision != int(binding.revision)
        ),
    }


