def _resolve_internal_mcp_workflow_launch_actor_scope(
    *,
    user_id: Any,
    org_id: Any,
    namespace: Any,
):
    """Bind workflow-launch claims to actor authority predating tool payloads."""

    from ...security.access_control import (
        get_effective_organisation_concept_id,
        get_effective_user_concept_id,
    )
    from ...services.workflow_actor_scope_service import (
        resolve_authoritative_workflow_actor_scope,
    )
    from .gateway import (
        get_internal_mcp_actor_context_source,
        get_internal_mcp_preexisting_actor_context,
    )

    actor_source = get_internal_mcp_actor_context_source()
    preexisting_actor = get_internal_mcp_preexisting_actor_context()
    ambient_kwargs: dict[str, Any] = {}
    trusted_unscoped = False
    if preexisting_actor is not None:
        ambient_kwargs = {
            "ambient_user_id": preexisting_actor[0],
            "ambient_org_id": preexisting_actor[1],
            "ambient_context_supplied": True,
        }
    elif actor_source in {
        "tool_payload_fallback",
        "trusted_operator_payload_fallback",
    }:
        # The gateway installed actor context from these same arguments. It is
        # useful propagation for trusted operator/background calls, but it is
        # not ambient authentication authority against which claims may prove
        # themselves.
        ambient_kwargs = {
            "ambient_user_id": None,
            "ambient_org_id": None,
            "ambient_context_supplied": False,
        }
        trusted_unscoped = actor_source == "trusted_operator_payload_fallback"
    else:
        trusted_unscoped = not bool(
            get_effective_user_concept_id() or get_effective_organisation_concept_id()
        )

    claimed_namespace = (
        namespace.strip() if isinstance(namespace, str) and namespace.strip() else None
    )
    claimed_user_id = user_id
    claimed_org_id = org_id
    if trusted_unscoped and claimed_namespace is None:
        claimed_user_id = (
            user_id if isinstance(user_id, str) and user_id.strip() else "anonymous"
        )
        claimed_org_id = (
            org_id if isinstance(org_id, str) and org_id.strip() else "default"
        )

    return resolve_authoritative_workflow_actor_scope(
        claimed_user_id=claimed_user_id,
        claimed_org_id=claimed_org_id,
        claimed_namespace=claimed_namespace,
        allow_unscoped_claims=trusted_unscoped,
        **ambient_kwargs,
    )


def _internal_mcp_global_workflow_admin_authorised() -> bool:
    """Return whether a caller may mutate process-global workflow controls.

    Event bindings are currently global records rather than tenant-owned
    resources.  Until that storage contract carries represented ownership,
    ordinary authenticated actors must not be able to disable or replace a
    binding for every user merely because they can execute its workflow.
    """

    from ...security.access_control import (
        get_effective_organisation_concept_id,
        get_effective_user_concept_id,
    )
    from .gateway import (
        get_internal_mcp_actor_context_source,
        get_internal_mcp_preexisting_actor_context,
    )

    source = get_internal_mcp_actor_context_source()
    if source == "trusted_operator_payload_fallback":
        return True
    if source == "preexisting_authenticated_or_workflow_context":
        preexisting = get_internal_mcp_preexisting_actor_context()
        actor_id = preexisting[0] if preexisting is not None else None
        if actor_id:
            from ...services.von_operational_administrator_service import (
                is_live_von_operational_administrator,
            )

            # This lookup is deliberately operational-only. It does not bind a
            # bypass, organisation, or semantic-publication capability.
            return is_live_von_operational_administrator(actor_id)
    if source is not None or get_internal_mcp_preexisting_actor_context() is not None:
        return False
    # Preserve deliberately direct operator/startup calls, while refusing a
    # direct call made inside an authenticated user/workflow actor context.
    return not bool(
        get_effective_user_concept_id() or get_effective_organisation_concept_id()
    )


def _internal_mcp_operator_control_plane_denial(
    surface: str,
) -> dict[str, Any] | None:
    """Reject global diagnostic/control records outside operator provenance.

    Experiment runs and raw turn/chat telemetry do not yet carry one complete,
    consistently enforced actor-ownership contract. Until that represented
    authority is added, exposing them to ordinary or payload-only callers can
    reveal restricted workflow identifiers and evidence. Trusted operator and
    direct startup paths retain access; actor-owned access is a separate
    capability rather than a claim inferred from request fields.
    """

    if _internal_mcp_global_workflow_admin_authorised():
        return None
    return make_error_response(
        "workflow_global_admin_authority_required",
        f"{surface.strip().capitalize()} access requires trusted operator authority.",
    )


def _internal_mcp_actor_scoped_read_denial(
    surface: str,
) -> dict[str, Any] | None:
    """Require real actor provenance for reads whose storage is actor-scoped.

    An authenticated request/workflow actor and the deliberately configured
    local-operator MCP route are both sufficient. Raw tool arguments are not
    identity authority, so a payload-only caller cannot select another actor's
    namespace merely by naming it.
    """

    from ...security.access_control import (
        get_effective_organisation_concept_id,
        get_effective_user_concept_id,
    )
    from .gateway import (
        get_internal_mcp_actor_context_source,
        get_internal_mcp_preexisting_actor_context,
    )

    source = get_internal_mcp_actor_context_source()
    if get_internal_mcp_preexisting_actor_context() is not None:
        return None
    if source == "trusted_operator_payload_fallback":
        return None
    if source is None and not bool(
        get_effective_user_concept_id() or get_effective_organisation_concept_id()
    ):
        # Preserve explicit in-process operator/startup calls. Gateway and
        # proxy callers always bind a source and cannot reach this branch.
        return None
    return make_error_response(
        "authenticated_actor_context_required",
        (
            f"{surface.strip().capitalize()} access requires an authenticated "
            "actor or trusted operator route."
        ),
    )


def _authorise_internal_mcp_telemetry_read(
    payload: Mapping[str, Any],
    *,
    tool_name: str,
    surface: str,
    reference_argument: str,
    operator_control_plane: bool,
) -> dict[str, Any]:
    """Resolve a narrow signed stdio read delegation without actor elevation."""

    ordinary_denial = (
        _internal_mcp_operator_control_plane_denial(surface)
        if operator_control_plane
        else _internal_mcp_actor_scoped_read_denial(surface)
    )
    if ordinary_denial is None:
        return {
            "success": True,
            "payload": dict(payload),
            "delegated": False,
            "read_delegation": None,
        }

    reference = payload.get(reference_argument)
    if not isinstance(reference, Mapping):
        return ordinary_denial
    if (
        reference_argument == "conversation_ref"
        and reference.get("kind") == "von_conversation_ref"
    ):
        # Public locator wrappers are convenient identifiers, not proof of
        # actor authority. Preserve the ordinary actor-provenance denial
        # instead of treating an unsigned wrapper as a malformed signature.
        return ordinary_denial

    from ...services.conversation_scope_binding_service import (
        TELEMETRY_READ_DELEGATION_AUDIENCE,
        verify_conversation_scope_binding,
        verify_history_location_binding,
        verify_turn_telemetry_binding,
    )

    claimed_actor = _normalise_optional_concept_id(payload.get("user_concept_id"))
    if reference_argument == "conversation_ref":
        verified = verify_conversation_scope_binding(
            reference,
            require_read_delegation=True,
            expected_audience=TELEMETRY_READ_DELEGATION_AUDIENCE,
            expected_tool=tool_name,
            expected_actor_user_id=claimed_actor,
        )
    elif reference_argument == "history_location_ref":
        verified = verify_history_location_binding(
            reference,
            require_read_delegation=True,
            expected_audience=TELEMETRY_READ_DELEGATION_AUDIENCE,
            expected_tool=tool_name,
            expected_actor_user_id=claimed_actor,
        )
    elif reference_argument == "turn_telemetry_ref":
        verified = verify_turn_telemetry_binding(
            reference,
            expected_audience=TELEMETRY_READ_DELEGATION_AUDIENCE,
            expected_tool=tool_name,
            expected_actor_user_id=claimed_actor,
        )
    else:
        return make_error_response(
            "READ_DELEGATION_REFERENCE_UNSUPPORTED",
            "Unsupported telemetry read delegation reference",
            details={"reference_argument": reference_argument},
        )

    if not verified.get("success"):
        return make_error_response(
            str(verified.get("error_code") or "INVALID_CONTEXT_BINDING"),
            str(
                verified.get("error_message") or "Telemetry read delegation is invalid"
            ),
            details={
                "identifier_binding": dict(verified.get("identifier_binding") or {})
            },
        )

    effective = dict(payload)
    actor_user_id = _normalise_optional_concept_id(
        verified.get("delegated_actor_user_id")
    )
    actor_namespace = _clean_optional_string(verified.get("delegated_actor_namespace"))
    organisation_concept_id = _normalise_optional_concept_id(
        verified.get("organisation_concept_id")
    )
    bound_session_id = _clean_optional_string(verified.get("chat_session_id"))
    bound_request_id = _clean_optional_string(verified.get("request_id"))
    bound_history_index = verified.get("history_index")

    comparisons: tuple[tuple[str, Any, Any], ...] = (
        ("user_concept_id", claimed_actor, actor_user_id),
        (
            "namespace",
            _clean_optional_string(payload.get("namespace")),
            actor_namespace,
        ),
        (
            "organisation_concept_id",
            _normalise_optional_concept_id(payload.get("organisation_concept_id")),
            organisation_concept_id,
        ),
        (
            "session_id",
            _clean_optional_string(
                payload.get("session_id") or payload.get("conversation_session_id")
            ),
            bound_session_id,
        ),
        (
            "request_id",
            _clean_optional_string(payload.get("request_id")),
            bound_request_id,
        ),
        (
            "history_index",
            (
                payload.get("history_index")
                if isinstance(payload.get("history_index"), int)
                else None
            ),
            (bound_history_index if isinstance(bound_history_index, int) else None),
        ),
    )
    mismatches = [
        {
            "field": field,
            "provided": provided,
            "bound": bound,
        }
        for field, provided, bound in comparisons
        if provided is not None and bound is not None and provided != bound
    ]
    if mismatches:
        identifier_binding = dict(verified.get("identifier_binding") or {})
        identifier_binding["read_delegation_validation_status"] = "target_mismatch"
        return make_error_response(
            "INVALID_CONTEXT_BINDING",
            "Telemetry read arguments do not match the signed delegation target",
            details={
                "reason_code": "READ_DELEGATION_TARGET_MISMATCH",
                "field_mismatches": mismatches,
                "identifier_binding": identifier_binding,
            },
        )

    if actor_user_id:
        effective["user_concept_id"] = actor_user_id
    if actor_namespace:
        effective["namespace"] = actor_namespace
    if organisation_concept_id:
        effective["organisation_concept_id"] = organisation_concept_id
    if bound_session_id:
        effective["session_id"] = bound_session_id
    if bound_request_id:
        effective["request_id"] = bound_request_id
    if isinstance(bound_history_index, int):
        effective["history_index"] = bound_history_index
    effective["_verified_read_delegation"] = dict(verified.get("read_delegation") or {})
    effective["_verified_identifier_binding"] = dict(
        verified.get("identifier_binding") or {}
    )
    effective["_delegated_history_owner_user_id"] = _normalise_optional_concept_id(
        verified.get("history_owner_user_id")
    )
    effective["_delegated_read_namespace"] = _clean_optional_string(
        verified.get("read_namespace")
    )
    return {
        "success": True,
        "payload": effective,
        "delegated": True,
        "read_delegation": effective["_verified_read_delegation"],
        "identifier_binding": effective["_verified_identifier_binding"],
    }


def _workflow_actor_scope_error_response(exc: Exception) -> dict[str, Any]:
    reason = str(getattr(exc, "reason", "") or "workflow_actor_scope_mismatch")
    mismatch_fields = getattr(exc, "mismatch_fields", ())
    return make_error_response(
        reason,
        "Workflow launch actor scope conflicts with ambient authority.",
        details={
            "mismatch_fields": [
                str(item)
                for item in mismatch_fields
                if item in {"user_id", "org_id", "namespace"}
            ]
        },
    )


def _workflow_observation_parameter_error(field_name: str) -> dict[str, Any]:
    """Return typed no-effect feedback before any workflow submission/wait."""

    payload = make_error_response(
        "invalid_parameter",
        f"{field_name} must be finite.",
        details={"invalid": [field_name]},
        suggestions=[f"Provide a finite {field_name} value."],
    )
    payload.update(
        {
            "status": "not_started",
            "effect_status": "not_started",
            "mutation_outcome": "not_started",
            "outcome_finality": "terminal_for_turn",
            "changed": False,
        }
    )
    return payload


def _workflow_create_instance(**kwargs):
    """Create a new durable workflow instance."""
    from ...workflows.durable import WorkflowInstanceManager
    from ...workflows.durable.workflow_instance_submission_service import (
        submit_verified_workflow_instance,
    )

    workflow_id = kwargs.get("workflow_id")
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        return make_error_response(
            "missing_parameter",
            "workflow_id is required",
            details={"missing": ["workflow_id"]},
        )

    user_id_raw = kwargs.get("user_id")
    org_id_raw = kwargs.get("org_id")
    namespace_raw = kwargs.get("namespace")
    inputs_raw = kwargs.get("inputs", {})
    max_retries_raw = kwargs.get("max_retries", 3)
    source_event_type_raw = kwargs.get("source_event_type")
    source_event_id_raw = kwargs.get("source_event_id")
    event_idempotency_key_raw = kwargs.get("event_idempotency_key")
    required_worker_build_raw = kwargs.get("required_worker_build")

    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=user_id_raw,
            org_id=org_id_raw,
            namespace=namespace_raw,
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)
    user_id = actor_scope.user_concept_id
    org_id = actor_scope.organisation_concept_id
    namespace = actor_scope.namespace
    if not user_id or not namespace:
        return make_error_response(
            "workflow_actor_authority_required",
            "Workflow launch requires a canonical user and namespace.",
        )
    source_event_type = (
        source_event_type_raw.strip()
        if isinstance(source_event_type_raw, str) and source_event_type_raw.strip()
        else None
    )
    source_event_id = (
        source_event_id_raw.strip()
        if isinstance(source_event_id_raw, str) and source_event_id_raw.strip()
        else None
    )
    event_idempotency_key = (
        event_idempotency_key_raw.strip()
        if isinstance(event_idempotency_key_raw, str)
        and event_idempotency_key_raw.strip()
        else None
    )
    if required_worker_build_raw is None:
        required_worker_build = None
    elif (
        isinstance(required_worker_build_raw, str) and required_worker_build_raw.strip()
    ):
        required_worker_build = required_worker_build_raw.strip()
    else:
        return make_error_response(
            "invalid_parameter",
            "required_worker_build must be a non-empty string when supplied.",
            details={"invalid": ["required_worker_build"]},
        )
    inputs = inputs_raw if isinstance(inputs_raw, dict) else {}
    try:
        max_retries = int(max_retries_raw)
    except (TypeError, ValueError):
        max_retries = 3
    max_retries = max(0, min(max_retries, 50))

    try:
        manager = WorkflowInstanceManager()
        submission = submit_verified_workflow_instance(
            manager=manager,
            workflow_id=workflow_id.strip(),
            user_id=user_id,
            org_id=org_id,
            namespace=namespace,
            inputs=inputs if isinstance(inputs, dict) else {},
            max_retries=max_retries,
            source_event_type=source_event_type,
            source_event_id=source_event_id,
            event_idempotency_key=event_idempotency_key,
            required_worker_build=required_worker_build,
        )
        return submission.to_dict()
    except Exception as e:
        return make_error_response(
            "create_failed",
            f"Failed to create workflow instance: {e}",
        )


def _workflow_execute(**kwargs):
    """Launch a durable workflow instance and optionally await a terminal result."""
    from .transport import record_internal_mcp_effect_receipt
    from ...workflows.durable import WorkflowInstanceManager
    from ...workflows.durable.execution_observability import (
        await_workflow_terminal_state,
        build_workflow_execution_response,
    )
    from ...workflows.durable.startup import (
        get_system_status as get_durable_system_status,
    )
    from ...workflows.durable.workflow_instance_submission_service import (
        submit_verified_workflow_instance,
    )

    workflow_id = kwargs.get("workflow_id")
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        return make_error_response(
            "missing_parameter",
            "workflow_id is required",
            details={"missing": ["workflow_id"]},
        )

    user_id_raw = kwargs.get("user_id")
    org_id_raw = kwargs.get("org_id")
    namespace_raw = kwargs.get("namespace")
    inputs_raw = kwargs.get("inputs", {})
    max_retries_raw = kwargs.get("max_retries", 3)
    source_event_type_raw = kwargs.get("source_event_type")
    source_event_id_raw = kwargs.get("source_event_id")
    event_idempotency_key_raw = kwargs.get("event_idempotency_key")
    required_worker_build_raw = kwargs.get("required_worker_build")
    await_terminal_raw = kwargs.get("await_terminal")
    include_step_result_envelopes_raw = kwargs.get("include_step_result_envelopes")
    include_trace_raw = kwargs.get("include_trace")
    await_terminal = _coerce_bool_input(await_terminal_raw, default=False)
    include_step_result_envelopes = _coerce_bool_input(
        include_step_result_envelopes_raw,
        default=False,
    )
    include_trace = _coerce_bool_input(include_trace_raw, default=False)
    boolean_input_normalisation = {
        "await_terminal": _bool_input_normalisation_record(
            await_terminal_raw,
            normalised=await_terminal,
            default=False,
        ),
        "include_step_result_envelopes": _bool_input_normalisation_record(
            include_step_result_envelopes_raw,
            normalised=include_step_result_envelopes,
            default=False,
        ),
        "include_trace": _bool_input_normalisation_record(
            include_trace_raw,
            normalised=include_trace,
            default=False,
        ),
    }

    try:
        timeout_seconds = float(
            kwargs.get(
                "advisory_seconds",
                kwargs.get("timeout_seconds", 60.0 if await_terminal else 0.0),
            )
        )
    except (TypeError, ValueError):
        timeout_seconds = 60.0 if await_terminal else 0.0
    if not math.isfinite(timeout_seconds):
        return _workflow_observation_parameter_error("timeout_seconds")
    timeout_seconds = max(0.0, timeout_seconds)
    if await_terminal:
        timeout_seconds = min(
            timeout_seconds,
            _WORKFLOW_OBSERVATION_MAX_SECONDS,
        )

    try:
        poll_interval_seconds = float(kwargs.get("poll_interval_seconds", 1.0))
    except (TypeError, ValueError):
        poll_interval_seconds = 1.0
    if not math.isfinite(poll_interval_seconds):
        return _workflow_observation_parameter_error("poll_interval_seconds")
    poll_interval_seconds = max(0.0, poll_interval_seconds)

    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=user_id_raw,
            org_id=org_id_raw,
            namespace=namespace_raw,
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)
    user_id = actor_scope.user_concept_id
    org_id = actor_scope.organisation_concept_id
    namespace = actor_scope.namespace
    if not user_id or not namespace:
        return make_error_response(
            "workflow_actor_authority_required",
            "Workflow launch requires a canonical user and namespace.",
        )
    source_event_type = (
        source_event_type_raw.strip()
        if isinstance(source_event_type_raw, str) and source_event_type_raw.strip()
        else None
    )
    source_event_id = (
        source_event_id_raw.strip()
        if isinstance(source_event_id_raw, str) and source_event_id_raw.strip()
        else None
    )
    event_idempotency_key = (
        event_idempotency_key_raw.strip()
        if isinstance(event_idempotency_key_raw, str)
        and event_idempotency_key_raw.strip()
        else None
    )
    if required_worker_build_raw is None:
        required_worker_build = None
    elif (
        isinstance(required_worker_build_raw, str) and required_worker_build_raw.strip()
    ):
        required_worker_build = required_worker_build_raw.strip()
    else:
        return make_error_response(
            "invalid_parameter",
            "required_worker_build must be a non-empty string when supplied.",
            details={"invalid": ["required_worker_build"]},
        )
    inputs = inputs_raw if isinstance(inputs_raw, dict) else {}
    try:
        max_retries = int(max_retries_raw)
    except (TypeError, ValueError):
        max_retries = 3
    max_retries = max(0, min(max_retries, 50))

    try:
        manager = WorkflowInstanceManager()
        submission = submit_verified_workflow_instance(
            manager=manager,
            workflow_id=workflow_id.strip(),
            user_id=user_id,
            org_id=org_id,
            namespace=namespace,
            inputs=inputs,
            max_retries=max_retries,
            source_event_type=source_event_type,
            source_event_id=source_event_id,
            event_idempotency_key=event_idempotency_key,
            required_worker_build=required_worker_build,
        )
        instance = None
        poll_count: int | None = None
        timed_out = False
        observation_advisory_exceeded = False
        observation_enforcement = "advisory"
        durable_system_status: Mapping[str, Any] | None = None
        instance_id = (
            submission.instance_id
            if isinstance(submission.instance_id, str)
            and submission.instance_id.strip()
            else None
        )
        if instance_id:
            record_internal_mcp_effect_receipt(
                {
                    "schema_version": "workflow_durable_submission_receipt.v1",
                    "success": bool(submission.success),
                    "status": "submitted",
                    "effect_status": "partial",
                    "changed": (
                        submission.created_new
                        if isinstance(submission.created_new, bool)
                        else None
                    ),
                    "workflow_id": workflow_id.strip(),
                    "instance_id": instance_id,
                    "created_new": submission.created_new,
                    "durable_submission_status": submission.status,
                    "mutation_outcome": "partial",
                    "outcome_finality": "pending_durable_observation",
                }
            )
            if await_terminal:
                wait_result = await_workflow_terminal_state(
                    manager,
                    instance_id,
                    timeout_seconds=timeout_seconds,
                    poll_interval_seconds=poll_interval_seconds,
                )
                instance = wait_result.instance
                poll_count = wait_result.poll_count
                observation_enforcement = str(
                    getattr(
                        wait_result,
                        "elapsed_time_enforcement",
                        "legacy_hard",
                    )
                    or "legacy_hard"
                )
                observation_advisory_exceeded = bool(
                    getattr(wait_result, "advisory_exceeded", False)
                    or (wait_result.timed_out and observation_enforcement == "advisory")
                )
                timed_out = bool(
                    wait_result.timed_out and observation_enforcement != "advisory"
                )
                if timed_out:
                    try:
                        durable_system_status = get_durable_system_status()
                    except Exception:
                        durable_system_status = None
            else:
                instance = manager.get_instance(instance_id)
        response = build_workflow_execution_response(
            submission,
            workflow_inputs=inputs,
            instance=instance,
            await_terminal=await_terminal,
            timeout_seconds=timeout_seconds if await_terminal else None,
            poll_interval_seconds=poll_interval_seconds if await_terminal else None,
            poll_count=poll_count,
            timed_out=timed_out,
            advisory_exceeded=observation_advisory_exceeded,
            elapsed_time_enforcement=observation_enforcement,
            include_step_result_envelopes=include_step_result_envelopes,
            include_trace=include_trace,
            durable_system_status=durable_system_status,
        )
        workflow_execution = response.get("workflow_execution")
        if isinstance(workflow_execution, dict):
            workflow_execution["input_normalisation"] = {
                "boolean_fields": boolean_input_normalisation,
            }
        return response
    except Exception as e:
        return make_error_response(
            "workflow_execute_failed",
            f"Failed to execute workflow: {e}",
        )


def _workflow_persisted_record_matches_internal_actor(record: Any) -> bool:
    """Return whether a persisted workflow record belongs to the MCP actor."""

    def _value(field_name: str) -> Any:
        if isinstance(record, Mapping):
            return record.get(field_name)
        return getattr(record, field_name, None)

    claimed_user_id = _value("user_id") or _value("user_concept_id")
    claimed_org_id = _value("org_id") or _value("organisation_concept_id")
    claimed_namespace = _value("namespace") or _value("user_namespace")
    if not claimed_user_id and not claimed_namespace:
        from .gateway import (
            get_internal_mcp_actor_context_source,
            get_internal_mcp_preexisting_actor_context,
        )

        return bool(
            get_internal_mcp_preexisting_actor_context() is None
            and get_internal_mcp_actor_context_source()
            == "trusted_operator_payload_fallback"
        )
    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=claimed_user_id,
            org_id=claimed_org_id,
            namespace=claimed_namespace,
        )
    except WorkflowActorScopeError:
        return False
    from ...services.namespace_service import resolve_canonical_namespace

    persisted_namespace = resolve_canonical_namespace(
        claimed_namespace,
        claimed_user_id,
        claimed_org_id,
    )
    # Non-operator access requires an exact persisted cohort.  A legacy
    # user-only record cannot be safely attributed to one of that user's
    # current organisations and therefore fails closed.
    actor_matches = bool(
        persisted_namespace
        and actor_scope.namespace
        and persisted_namespace == actor_scope.namespace
    )
    if not actor_matches:
        return False

    workflow_id = _value("workflow_id")
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        return True
    from ...workflows.workflow_listing_service import (
        filter_workflow_ids_for_current_actor,
    )

    workflow_id = workflow_id.strip()
    return workflow_id in filter_workflow_ids_for_current_actor([workflow_id])


def _workflow_get_execution_trace(**kwargs):
    """Get a persisted durable workflow execution trace by execution or instance ID."""
    from ...workflows import get_workflow_execution_trace
    from ...workflows.durable import WorkflowInstanceManager
    from ...workflows.durable.execution_observability import (
        build_workflow_instance_payload,
    )

    execution_id_raw = kwargs.get("execution_id")
    instance_id_raw = kwargs.get("instance_id")

    execution_id = (
        execution_id_raw.strip()
        if isinstance(execution_id_raw, str) and execution_id_raw.strip()
        else None
    )
    instance_id = (
        instance_id_raw.strip()
        if isinstance(instance_id_raw, str) and instance_id_raw.strip()
        else None
    )
    if execution_id is None and instance_id is None:
        return make_error_response(
            "missing_parameter",
            "execution_id or instance_id is required",
            details={"missing_any_of": ["execution_id", "instance_id"]},
        )

    trace_link_authorised = False
    if execution_id is None and instance_id is not None:
        manager = WorkflowInstanceManager()
        instance = manager.get_instance(instance_id)
        if instance is None:
            return make_error_response(
                "not_found",
                f"Workflow instance not found: {instance_id}",
            )
        if not _workflow_persisted_record_matches_internal_actor(instance):
            return make_error_response(
                "not_found",
                f"Workflow instance not found: {instance_id}",
            )
        trace_link_authorised = True
        execution_id = (
            instance.execution_trace_id.strip()
            if isinstance(instance.execution_trace_id, str)
            and instance.execution_trace_id.strip()
            else None
        )
        if execution_id is None:
            instance_payload = build_workflow_instance_payload(
                instance,
                include_inputs=False,
                include_outputs=False,
                include_workflow_data=False,
            )
            return make_error_response(
                "workflow_execution_trace_not_linked",
                f"No execution trace is linked to workflow instance: {instance_id}",
                details={
                    "instance_id": instance_id,
                    "workflow_id": instance_payload.get("workflow_id"),
                    "status": instance_payload.get("status"),
                    "current_state": instance_payload.get("current_state"),
                    "step_index": instance_payload.get("step_index"),
                    "started_at": instance_payload.get("started_at"),
                    "completed_at": instance_payload.get("completed_at"),
                    "execution_trace_id": instance_payload.get("execution_trace_id"),
                    "trace_missing_reason": "instance_has_no_execution_trace_id",
                    "workflow_instance": instance_payload,
                },
            )

    trace_doc = get_workflow_execution_trace(execution_id or "")
    if not isinstance(trace_doc, dict):
        return make_error_response(
            "not_found",
            f"Workflow execution trace not found: {execution_id}",
        )
    if not _workflow_persisted_record_matches_internal_actor(trace_doc):
        return make_error_response(
            "not_found",
            f"Workflow execution trace not found: {execution_id}",
        )
    linked_instance_id = trace_doc.get("instance_id")
    if (
        trace_link_authorised
        and isinstance(linked_instance_id, str)
        and linked_instance_id.strip()
        and linked_instance_id.strip() != instance_id
    ):
        return make_error_response(
            "not_found",
            f"Workflow execution trace not found: {execution_id}",
        )
    trace_workflow_id = trace_doc.get("workflow_id")
    if isinstance(trace_workflow_id, str) and trace_workflow_id.strip():
        from ...workflows.workflow_listing_service import (
            filter_workflow_ids_for_current_actor,
        )

        if trace_workflow_id.strip() not in filter_workflow_ids_for_current_actor(
            [trace_workflow_id.strip()]
        ):
            return make_error_response(
                "not_found",
                f"Workflow execution trace not found: {execution_id}",
            )

    return {
        "success": True,
        "execution_id": execution_id,
        "instance_id": instance_id,
        "execution_trace": trace_doc,
    }


def _workflow_list_execution_traces(**kwargs):
    """List recent persisted workflow execution traces with bounded summaries."""
    from ...workflows import list_recent_workflow_execution_traces
    from ...workflows.durable.execution_observability import (
        build_workflow_execution_trace_summary,
    )

    try:
        limit = int(kwargs.get("limit", 20))
    except (TypeError, ValueError):
        limit = 20
    limit = max(1, min(limit, 100))

    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=kwargs.get("user_id"),
            org_id=kwargs.get("org_id"),
            namespace=kwargs.get("namespace"),
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)
    namespace = actor_scope.namespace
    if not namespace:
        return make_error_response(
            "workflow_actor_authority_required",
            "Workflow trace listing requires actor authority.",
        )

    workflow_id = kwargs.get("workflow_id")
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        workflow_id = None
    else:
        workflow_id = workflow_id.strip()

    traces = list_recent_workflow_execution_traces(
        limit=limit,
        namespace=namespace,
        workflow_id=workflow_id,
    )
    from ...workflows.workflow_listing_service import (
        filter_workflow_ids_for_current_actor,
    )

    visible_workflow_ids = set(
        filter_workflow_ids_for_current_actor(
            [trace.get("workflow_id") for trace in traces if isinstance(trace, Mapping)]
        )
    )
    summaries = [
        build_workflow_execution_trace_summary(trace)
        for trace in traces
        if isinstance(trace, Mapping)
        and trace.get("workflow_id") in visible_workflow_ids
    ]
    return {
        "success": True,
        "execution_traces": summaries,
        "count": len(summaries),
    }


def _workflow_build_prediction_envelope(**kwargs):
    """Build an observed workflow prediction envelope from recent traces."""
    from ...services.workflow_prediction_service import (
        build_workflow_prediction_envelope,
    )

    workflow_id = kwargs.get("workflow_id")
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        return make_error_response(
            "missing_parameter",
            "workflow_id is required",
            details={"missing": ["workflow_id"]},
        )
    workflow_id = workflow_id.strip()

    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=kwargs.get("user_id"),
            org_id=kwargs.get("org_id"),
            namespace=kwargs.get("namespace"),
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)
    namespace = actor_scope.namespace
    if not namespace:
        return make_error_response(
            "workflow_actor_authority_required",
            "Workflow prediction requires actor authority.",
        )

    from ...workflows.workflow_listing_service import (
        filter_workflow_ids_for_current_actor,
    )

    if workflow_id not in filter_workflow_ids_for_current_actor([workflow_id]):
        return make_error_response(
            "not_found",
            "Workflow is not available for prediction.",
        )

    try:
        limit = int(kwargs.get("limit", 50))
    except (TypeError, ValueError):
        limit = 50

    try:
        return build_workflow_prediction_envelope(
            workflow_id=workflow_id,
            namespace=namespace,
            model=kwargs.get("model"),
            provider=kwargs.get("provider"),
            limit=limit,
        )
    except ValueError as exc:
        return make_error_response(
            "invalid_prediction_request",
            str(exc),
        )
    except Exception as exc:
        return make_error_response(
            "workflow_prediction_envelope_failed",
            f"Failed to build workflow prediction envelope: {exc}",
        )


def _workflow_list_instances(**kwargs):
    """List workflow instances with filters."""
    from ...workflows.durable import WorkflowInstanceManager, WorkflowInstanceStatus

    try:
        actor_scope = _resolve_internal_mcp_workflow_launch_actor_scope(
            user_id=kwargs.get("user_id"),
            org_id=kwargs.get("org_id"),
            namespace=kwargs.get("namespace"),
        )
    except WorkflowActorScopeError as exc:
        return _workflow_actor_scope_error_response(exc)
    user_id = actor_scope.user_concept_id
    org_id = actor_scope.organisation_concept_id
    namespace = actor_scope.namespace
    if not user_id or not namespace:
        return make_error_response(
            "workflow_actor_authority_required",
            "Workflow instance listing requires actor authority.",
        )
    status_str = kwargs.get("status")
    workflow_id = kwargs.get("workflow_id")
    if isinstance(workflow_id, str):
        workflow_id = workflow_id.strip() or None
    if workflow_id:
        from ...workflows.workflow_listing_service import (
            filter_workflow_ids_for_current_actor,
        )

        if workflow_id not in filter_workflow_ids_for_current_actor([workflow_id]):
            return {"success": True, "instances": [], "count": 0}
    source_event_type = kwargs.get("source_event_type")
    source_event_id = kwargs.get("source_event_id")
    session_id = kwargs.get("session_id") or kwargs.get("conversation_session_id")
    request_id = kwargs.get("request_id") or kwargs.get("turn_id")
    from_utc = kwargs.get("from_utc")
    to_utc = kwargs.get("to_utc")
    try:
        limit = int(kwargs.get("limit", 50))
    except (TypeError, ValueError):
        limit = 50
    limit = max(1, min(limit, 200))

    status = None
    if status_str:
        try:
            status = WorkflowInstanceStatus(status_str.lower())
        except ValueError:
            return make_error_response(
                "invalid_status",
                f"Invalid status: {status_str}. Valid values: pending, running, completed, failed, cancelled, paused",
            )

    manager = WorkflowInstanceManager()
    instances = manager.list_instances(
        user_id=user_id,
        org_id=org_id,
        namespace=namespace,
        status=status,
        workflow_id=workflow_id,
        source_event_type=source_event_type,
        source_event_id=source_event_id,
        conversation_session_id=(
            session_id if isinstance(session_id, str) and session_id.strip() else None
        ),
        request_id=(
            request_id if isinstance(request_id, str) and request_id.strip() else None
        ),
        from_utc=from_utc if isinstance(from_utc, str) and from_utc.strip() else None,
        to_utc=to_utc if isinstance(to_utc, str) and to_utc.strip() else None,
        limit=limit,
    )

    instances = [
        instance
        for instance in instances
        if _workflow_persisted_record_matches_internal_actor(instance)
    ]
    return {
        "success": True,
        "instances": [inst.to_status_dict() for inst in instances],
        "count": len(instances),
    }


def _workflow_get_instance(**kwargs):
    """Get, or boundedly await, details of a specific workflow instance."""
    from ...workflows.durable import WorkflowInstanceManager
    from ...workflows.durable.execution_observability import (
        await_workflow_terminal_state,
    )

    instance_id = kwargs.get("instance_id")
    if not isinstance(instance_id, str) or not instance_id.strip():
        return make_error_response(
            "missing_parameter",
            "instance_id is required",
            details={"missing": ["instance_id"]},
        )

    manager = WorkflowInstanceManager()
    instance = manager.get_instance(instance_id.strip())

    if not instance:
        return make_error_response(
            "not_found",
            f"Workflow instance not found: {instance_id}",
        )
    if not _workflow_persisted_record_matches_internal_actor(instance):
        return make_error_response(
            "not_found",
            f"Workflow instance not found: {instance_id}",
        )

    await_terminal = _coerce_bool_input(
        kwargs.get("await_terminal"),
        default=False,
    )
    try:
        timeout_seconds = float(
            kwargs.get(
                "advisory_seconds",
                kwargs.get("timeout_seconds", 60.0),
            )
        )
    except (TypeError, ValueError):
        timeout_seconds = 60.0
    if not math.isfinite(timeout_seconds):
        return _workflow_observation_parameter_error("timeout_seconds")
    timeout_seconds = min(
        max(0.0, timeout_seconds),
        _WORKFLOW_OBSERVATION_MAX_SECONDS,
    )
    try:
        poll_interval_seconds = float(kwargs.get("poll_interval_seconds", 1.0))
    except (TypeError, ValueError):
        poll_interval_seconds = 1.0
    if not math.isfinite(poll_interval_seconds):
        return _workflow_observation_parameter_error("poll_interval_seconds")
    poll_interval_seconds = max(0.05, poll_interval_seconds)

    poll_count: int | None = None
    timed_out = False
    observation_advisory_exceeded = False
    observation_enforcement = "advisory"
    if await_terminal:
        wait_result = await_workflow_terminal_state(
            manager,
            instance_id.strip(),
            timeout_seconds=timeout_seconds,
            poll_interval_seconds=poll_interval_seconds,
        )
        if wait_result.instance is not None:
            instance = wait_result.instance
        poll_count = wait_result.poll_count
        observation_enforcement = str(
            getattr(
                wait_result,
                "elapsed_time_enforcement",
                "legacy_hard",
            )
            or "legacy_hard"
        )
        observation_advisory_exceeded = bool(
            getattr(wait_result, "advisory_exceeded", False)
            or (wait_result.timed_out and observation_enforcement == "advisory")
        )
        timed_out = bool(
            wait_result.timed_out and observation_enforcement != "advisory"
        )
        if not _workflow_persisted_record_matches_internal_actor(instance):
            return make_error_response(
                "not_found",
                f"Workflow instance not found: {instance_id}",
            )

    result = instance.to_status_dict()
    result["success"] = True
    result["inputs"] = instance.inputs
    result["outputs"] = instance.outputs
    result["user_id"] = instance.user_id
    result["org_id"] = instance.org_id
    result["namespace"] = instance.namespace
    result["error_step"] = instance.error_step
    result["schedule_id"] = instance.schedule_id
    result["workflow_data"] = instance.workflow_data
    if await_terminal:
        result.update(
            {
                "await_terminal": True,
                "timeout_seconds": timeout_seconds,
                "advisory_seconds": timeout_seconds,
                "poll_interval_seconds": poll_interval_seconds,
                "poll_count": poll_count,
                "timed_out": timed_out,
                "elapsed_time_enforcement": observation_enforcement,
                "advisory_exceeded": observation_advisory_exceeded,
                "hard_timeout_seconds": (timeout_seconds if timed_out else None),
            }
        )

    return result


def _workflow_cancel_instance(**kwargs):
    """Cancel a running or pending workflow instance."""
    from ...workflows.durable import WorkflowInstanceManager

    instance_id = kwargs.get("instance_id")
    if not isinstance(instance_id, str) or not instance_id.strip():
        return make_error_response(
            "missing_parameter",
            "instance_id is required",
            details={"missing": ["instance_id"]},
        )

    manager = WorkflowInstanceManager()
    instance = manager.get_instance(instance_id.strip())

    if not instance:
        return make_error_response(
            "not_found",
            f"Workflow instance not found: {instance_id}",
        )
    if not _workflow_persisted_record_matches_internal_actor(instance):
        return make_error_response(
            "not_found",
            f"Workflow instance not found: {instance_id}",
        )

    if instance.status.is_terminal():
        return make_error_response(
            "already_terminal",
            f"Instance is already in terminal status: {instance.status.value}",
        )

    success = manager.mark_cancelled(instance_id.strip())
    if success:
        return {
            "success": True,
            "instance_id": instance_id,
            "status": "cancelled",
        }
    else:
        return make_error_response("cancel_failed", "Failed to cancel instance")


def _workflow_control_safe_value(value: Any) -> Any:
    """Copy lifecycle evidence while dropping raw worker claim credentials."""

    if isinstance(value, Mapping):
        return {
            str(key): _workflow_control_safe_value(item)
            for key, item in value.items()
            if str(key) != "claim_token"
        }
    if isinstance(value, list):
        return [_workflow_control_safe_value(item) for item in value]
    return value


def _workflow_instance_control_status(instance: Any) -> dict[str, Any]:
    """Build a bounded control-plane readback without exposing worker claims."""

    raw_status = instance.to_status_dict()
    return {
        "schema_version": "workflow_instance_control_status.v1",
        "instance_id": raw_status.get("instance_id"),
        "workflow_id": raw_status.get("workflow_id"),
        "status": raw_status.get("status"),
        "current_state": raw_status.get("current_state"),
        "step_index": raw_status.get("step_index"),
        "manual_resume_required": bool(raw_status.get("manual_resume_required", False)),
        "checkpoint_pause_receipt": _workflow_control_safe_value(
            raw_status.get("checkpoint_pause_receipt")
        ),
        "checkpoint_resume_receipt": _workflow_control_safe_value(
            raw_status.get("checkpoint_resume_receipt")
        ),
        "checkpoint_resume_count": int(
            raw_status.get("checkpoint_resume_count", 0) or 0
        ),
        "execution_trace_id": raw_status.get("execution_trace_id"),
    }


def _workflow_resume_instance(**kwargs):
    """Explicitly resume an actor-owned paused workflow on the same instance."""

    from ...workflows.durable import WorkflowInstanceManager, WorkflowInstanceStatus

    instance_id = kwargs.get("instance_id")
    if not isinstance(instance_id, str) or not instance_id.strip():
        return make_error_response(
            "missing_parameter",
            "instance_id is required",
            details={"missing": ["instance_id"]},
        )
    instance_id = instance_id.strip()

    manager = WorkflowInstanceManager()
    instance = manager.get_instance(instance_id)
    if not instance or not _workflow_persisted_record_matches_internal_actor(instance):
        return make_error_response(
            "not_found",
            f"Workflow instance not found: {instance_id}",
        )
    if instance.status != WorkflowInstanceStatus.PAUSED:
        return make_error_response(
            "not_paused",
            f"Instance is not in paused status: {instance.status.value}",
        )

    resume_receipt_raw = manager.resume_instance(instance_id)
    if not isinstance(resume_receipt_raw, dict):
        return make_error_response(
            "resume_failed",
            "Failed to resume the paused workflow instance.",
        )

    resumed_instance = manager.get_instance(instance_id)
    if (
        resumed_instance is None
        or not _workflow_persisted_record_matches_internal_actor(resumed_instance)
        or resumed_instance.status != WorkflowInstanceStatus.PENDING
    ):
        return make_error_response(
            "resume_readback_failed",
            "Workflow resume was not confirmed by persisted status readback.",
        )
    instance_status = _workflow_instance_control_status(resumed_instance)
    resume_receipt = _workflow_control_safe_value(resume_receipt_raw)
    return {
        "success": True,
        "schema_version": "workflow_instance_control_result.v1",
        "operation": "resume",
        "instance_id": instance_id,
        "status": WorkflowInstanceStatus.PENDING.value,
        "same_instance_resume": bool(resume_receipt.get("same_instance_resume")),
        "checkpoint_resume_receipt": resume_receipt,
        "instance_status": instance_status,
    }


def _workflow_retry_instance(**kwargs):
    """Reset a failed workflow instance for retry."""
    from ...workflows.durable import WorkflowInstanceManager, WorkflowInstanceStatus

    instance_id = kwargs.get("instance_id")
    if not isinstance(instance_id, str) or not instance_id.strip():
        return make_error_response(
            "missing_parameter",
            "instance_id is required",
            details={"missing": ["instance_id"]},
        )

    manager = WorkflowInstanceManager()
    instance = manager.get_instance(instance_id.strip())

    if not instance:
        return make_error_response(
            "not_found",
            f"Workflow instance not found: {instance_id}",
        )
    if not _workflow_persisted_record_matches_internal_actor(instance):
        return make_error_response(
            "not_found",
            f"Workflow instance not found: {instance_id}",
        )

    if instance.status != WorkflowInstanceStatus.FAILED:
        return make_error_response(
            "not_failed",
            f"Instance is not in failed status: {instance.status.value}",
        )

    success = manager.reset_for_retry(instance_id.strip())
    if success:
        return {
            "success": True,
            "instance_id": instance_id,
            "status": "pending",
            "retry_count": instance.retry_count,
        }
    else:
        return make_error_response(
            "retry_limit_exceeded",
            f"Maximum retries exceeded: {instance.retry_count}/{instance.max_retries}",
        )


