# RAG metadata/content MCP tools
def _rag_get_status(**kwargs):
    import requests
    import os

    try:
        ns_report = _resolve_rag_namespace_from_kwargs(kwargs)
        ns_error = _rag_namespace_resolution_error(ns_report)
        if ns_error is not None and ns_error.get("error") == "namespace_mismatch":
            return ns_error

        ns = ns_report.get("namespace") or os.environ.get("VON_DEFAULT_NAMESPACE")
        detail = kwargs.get("detail")
        base_url = (
            os.environ.get("VON_HTTP_BASE_URL")
            or os.environ.get("VON_WEB_BASE_URL")
            or "http://127.0.0.1:5000"
        )
        base_url = base_url.rstrip("/")
        url = f"{base_url}/admin/rag_status"
        if ns:
            url = f"{url}?namespace={ns}"
        if detail:
            url = f"{url}{'&' if '?' in url else '?'}detail=1"
        res = requests.get(url, timeout=5)
        if res.ok:
            payload = res.json()
            if isinstance(payload, dict):
                payload.update(ns_report)
                payload = _with_rag_provenance(
                    payload=payload,
                    item_kind="rag_status_report",
                    source_system="http.admin_rag_status",
                )
            return payload
        return make_error_response(
            "http_error",
            f"HTTP {res.status_code}",
            details={"status_code": res.status_code},
        )
    except Exception as e:
        return make_error_response(
            "exception", str(e), details={"exception_type": type(e).__name__}
        )


def _mongo_query_diagnostics_report(**kwargs):
    """Build a bounded, redacted Mongo query-targeting diagnostics report."""

    if denial := _internal_mcp_operator_control_plane_denial("Mongo diagnostics"):
        return denial
    from ...services.mongo_query_diagnostics_service import (
        build_von_mongo_query_diagnostics_report,
    )

    try:
        return build_von_mongo_query_diagnostics_report(
            allow_operator_diagnostics=bool(kwargs.get("allow_operator_diagnostics")),
            source=kwargs.get("source"),
            namespace=kwargs.get("mongo_namespace") or kwargs.get("namespace_filter"),
            min_millis=kwargs.get("min_millis"),
            sample_limit=kwargs.get("sample_limit"),
            report_limit=kwargs.get("report_limit") or kwargs.get("limit"),
            explain_samples=kwargs.get("explain_samples"),
            explain_max_time_ms=kwargs.get("explain_max_time_ms"),
            reset_in_process=kwargs.get("reset_in_process"),
        )
    except Exception as exc:
        return make_error_response(
            "mongo_query_diagnostics_failed",
            f"Failed to build Mongo query diagnostics report: {exc}",
            details={"exception_type": type(exc).__name__},
            suggestions=[
                "Retry with allow_operator_diagnostics=true only for trusted operator diagnostics",
                "Use source='query_stats' or 'in_process' if Mongo profiler is unavailable",
                "Use Atlas Query Insights for cluster-side evidence when Atlas credentials are configured",
            ],
        )


def _mongo_cost_guardrails_report(**kwargs):
    """Build a compact, redacted Mongo cost guardrail report."""

    if denial := _internal_mcp_operator_control_plane_denial("Mongo diagnostics"):
        return denial
    from ...db.mongo_client import (
        MONGO_URI,
        get_effective_mongo_uri,
        get_mongo_fallback_policy_state,
        is_using_fallback_uri,
    )
    from ...db.mongo_uri_redaction import build_safe_mongo_connection_location
    from ...services.mongo_observability_service import (
        build_mongo_cost_guardrail_report,
    )

    try:
        fallback_policy = get_mongo_fallback_policy_state()
        connection_location = build_safe_mongo_connection_location(
            get_effective_mongo_uri(),
            using_fallback=is_using_fallback_uri(),
            fallback_kind=fallback_policy.get("active_fallback_kind"),
            fallback_target_uri=MONGO_URI,
        )
        return build_mongo_cost_guardrail_report(
            mongo_classification=connection_location["classification"],
            sanitized_uri=connection_location["logical_sanitized_uri"],
            using_fallback=connection_location["using_fallback"],
            local_development=kwargs.get("local_development"),
            reset=bool(kwargs.get("reset")),
        )
    except Exception as exc:
        return make_error_response(
            "mongo_cost_guardrails_failed",
            f"Failed to build Mongo cost guardrail report: {exc}",
            details={"exception_type": type(exc).__name__},
            suggestions=[
                "Use /api/settings/db/guardrails for the same redacted report.",
                "Check VON_MONGO_GUARDRAIL_* threshold environment values.",
                "Use mongo_query_diagnostics_report for deeper query-shape investigation.",
            ],
        )


def _resolve_rag_collection_from_kwargs(kwargs: dict) -> dict[str, object]:
    """Resolve a user-provided collection selector.

    This exists to prevent silent defaults: responses should echo what the
    caller asked for vs what was actually used.
    """

    raw = kwargs.get("collection")
    if raw is None:
        return {
            "requested_collection": None,
            "effective_collection": "ka_sessions",
            "collection_source": "default",
            "collection_resolution_note": "default",
        }

    if not isinstance(raw, str):
        return {
            "requested_collection": raw,
            "effective_collection": "ka_sessions",
            "collection_source": "default",
            "collection_resolution_note": "invalid",
        }

    cleaned = raw.strip()
    if not cleaned:
        return {
            "requested_collection": raw,
            "effective_collection": "ka_sessions",
            "collection_source": "default",
            "collection_resolution_note": "empty",
        }

    lowered = cleaned.lower()
    aliases = {
        "ka": "ka_sessions",
        "ka_session": "ka_sessions",
        "ka_sessions": "ka_sessions",
        "interaction": "ka_sessions",
        "interaction_session": "ka_sessions",
        "interaction_sessions": "ka_sessions",
        "indexed_sessions": "ka_sessions",
        "indexed": "ka_sessions",
        "chat": "chat_history_sessions",
        "chat_session": "chat_history_sessions",
        "chat_sessions": "chat_history_sessions",
        "chat_history": "chat_history_sessions",
        "chat_history_session": "chat_history_sessions",
        "chat_history_sessions": "chat_history_sessions",
        "file_copy": "file_copy_concepts",
        "file_copies": "file_copy_concepts",
        "file_copy_concept": "file_copy_concepts",
        "file_copy_concepts": "file_copy_concepts",
        "blob_store": "file_copy_concepts",
        "blob_store_file": "file_copy_concepts",
        "blob_store_files": "file_copy_concepts",
        "uploaded_file": "file_copy_concepts",
        "uploaded_files": "file_copy_concepts",
        "text_relations": "vontology_text_relations",
        "text_relation": "vontology_text_relations",
        "text": "vontology_text_relations",
        "vontology_text_relations": "vontology_text_relations",
        "turn_execution": "turn_execution_records",
        "turn_execution_record": "turn_execution_records",
        "turn_execution_records": "turn_execution_records",
        "execution_record": "turn_execution_records",
        "execution_records": "turn_execution_records",
        "turn_record": "turn_execution_records",
        "turn_records": "turn_execution_records",
        "experiment_run": "experiment_runs",
        "experiment_runs": "experiment_runs",
        "experiment": "experiment_runs",
        "experiments": "experiment_runs",
        "episode_critique_memory": "episode_critique_memories",
        "episode_critique_memories": "episode_critique_memories",
        "critique_memory": "episode_critique_memories",
        "critique_memories": "episode_critique_memories",
        "episode_critique": "episode_critique_memories",
        "episode_critiques": "episode_critique_memories",
    }
    effective = aliases.get(lowered, lowered)
    return {
        "requested_collection": cleaned,
        "effective_collection": effective,
        "collection_source": (
            "request.collection_alias" if effective != lowered else "request.collection"
        ),
        "collection_resolution_note": (
            f"alias:{lowered}" if effective != lowered else None
        ),
    }


