def _gmail_get_auth_config(**kwargs):
    """Return the OAuth scope and token status for a configured Gmail profile."""
    from ...integrations.google import gmail_service as gs
    from ...services import concept_service as _cs
    from ...services.agent_gmail_token_store import get_agent_gmail_token_status
    from ...services.mail_profile_resource_vontology_service import (
        gmail_profile_resource_concept_id,
    )

    profile_id_arg = str(kwargs.get("profile_id") or "").strip()
    if not profile_id_arg:
        return make_error_response(
            "missing_profile_id",
            "profile_id is required",
            suggestions=[
                (
                    "Choose an actor-authorised profile supplied by the trusted "
                    "calling surface"
                )
            ],
        )

    profile_authority, authority_error = (
        _authorise_gmail_profile_for_current_invocation(profile_id_arg)
    )
    if authority_error is not None:
        return authority_error
    assert profile_authority is not None
    profile_id_arg = profile_authority.profile_id

    try:
        profiles = gs.load_profiles_from_env()
        profile = gs.get_profile(profile_id_arg, profiles)
    except Exception as exc:  # noqa: BLE001
        return make_error_response(
            "gmail_profile_configuration_unavailable",
            "Gmail profile configuration became unavailable during inspection.",
            details={"exception_type": type(exc).__name__},
            suggestions=[
                (
                    "Choose an actor-authorised and runtime-available profile "
                    "supplied by the trusted calling surface"
                )
            ],
        )

    concept_id = (
        profile_authority.profile_resource_concept_id
        or gmail_profile_resource_concept_id(profile_id_arg)
    )
    vontology_scopes: list[str] | None = None
    vontology_lookup_error: str | None = None
    try:
        concept_doc = _cs.get_concept_by_concept_id(concept_id)
        if isinstance(concept_doc, Mapping):
            raw = (concept_doc.get("attributes") or {}).get("oauth_scopes")
            if isinstance(raw, list) and raw:
                vontology_scopes = [s for s in raw if isinstance(s, str)]
    except Exception as _vl_exc:  # noqa: BLE001
        vontology_lookup_error = type(_vl_exc).__name__
        logger.debug(
            "gmail_get_auth_config: Vontology concept lookup failed for %s: %s",
            concept_id,
            _vl_exc,
        )

    scopes: list[str]
    scope_source: str
    if vontology_scopes is not None:
        scopes = vontology_scopes
        scope_source = "vontology"
    else:
        scopes = list(getattr(profile, "scopes", []) or [])
        scope_source = "env"

    try:
        token_status_obj = get_agent_gmail_token_status(profile_id_arg)
        token_status = "authorised" if token_status_obj.has_tokens else "missing"
        token_scopes = token_status_obj.scopes
        authorised_email = token_status_obj.authorised_email
        expires_at = (
            token_status_obj.expires_at.isoformat()
            if token_status_obj.expires_at is not None
            else None
        )
    except Exception:  # noqa: BLE001
        token_status = "unavailable"
        token_scopes = []
        authorised_email = None
        expires_at = None

    scope_mismatch = bool(token_scopes) and set(token_scopes) != set(scopes)
    reauth_advisory = None
    if scope_source == "env":
        reauth_advisory = (
            "Scopes resolved from env var only — call gmail_set_profile_scope "
            "with full scope URIs (e.g. 'https://www.googleapis.com/auth/gmail.modify') "
            "to persist the desired scope in Vontology, then re-authorise via Von UI."
        )
    elif scope_mismatch:
        reauth_advisory = (
            "Vontology scope differs from the scope on the stored token. "
            "Re-authorise via Von UI → Settings → Agent Gmail OAuth to issue "
            "a new token with the updated scopes."
        )

    scope_str = ", ".join(scopes) if scopes else "(none configured)"
    message = (
        f"Scopes for profile '{profile_id_arg}': {scope_str} "
        f"(source: {scope_source}). Token status: {token_status}."
    )
    if vontology_lookup_error:
        message += (
            f" Vontology concept lookup failed ({vontology_lookup_error});"
            " scope resolved from env. Call gmail_set_profile_scope — it will"
            " auto-bootstrap the profile concept and persist the scope."
        )
    if reauth_advisory:
        message += f" {reauth_advisory}"

    return {
        "success": True,
        "message": message,
        "profile_id": profile_id_arg,
        "concept_id": concept_id,
        "scopes": scopes,
        "scope_source": scope_source,
        "token_status": token_status,
        "token_scopes": token_scopes,
        "authorised_email": authorised_email,
        "expires_at": expires_at,
        "scope_mismatch": scope_mismatch,
        "reauth_advisory": reauth_advisory,
        "vontology_lookup_error": vontology_lookup_error,
    }


def _gmail_set_profile_scope(**kwargs):
    """Write an OAuth scope list to the Vontology Gmail profile concept."""
    from ...services import concept_service as _cs
    from ...services.mail_profile_resource_vontology_service import (
        gmail_profile_resource_concept_id,
    )

    profile_id_arg = str(kwargs.get("profile_id") or "").strip()
    new_scopes = kwargs.get("scopes")

    if not profile_id_arg:
        return make_error_response(
            "missing_profile_id",
            "profile_id is required",
            suggestions=["Call gmail_list_profiles to see configured profiles"],
        )
    if not isinstance(new_scopes, list) or not new_scopes:
        return make_error_response(
            "invalid_scopes",
            "scopes must be a non-empty list of OAuth scope URI strings",
            suggestions=[
                "Example: ['https://www.googleapis.com/auth/gmail.modify']",
                "Use gmail_get_auth_config to inspect the current scope",
            ],
        )
    scope_strings = [s for s in new_scopes if isinstance(s, str) and s.strip()]
    if not scope_strings:
        return make_error_response(
            "invalid_scopes",
            "scopes list contains no valid string values",
        )
    non_uri_scopes = [s for s in scope_strings if not s.startswith("https://")]
    if non_uri_scopes:
        return make_error_response(
            "invalid_scope_format",
            (
                f"Scope strings must be full OAuth URIs starting with 'https://'. "
                f"Invalid entries: {non_uri_scopes}"
            ),
            suggestions=[
                "Use the full scope URI, e.g. 'https://www.googleapis.com/auth/gmail.modify'",
                "Abbreviated names like 'gmail.readonly' are not accepted by Google OAuth.",
            ],
        )

    profile_authority, authority_error = (
        _authorise_gmail_profile_for_current_invocation(profile_id_arg)
    )
    if authority_error is not None:
        return authority_error
    assert profile_authority is not None
    profile_id_arg = profile_authority.profile_id

    concept_id = (
        profile_authority.profile_resource_concept_id
        or gmail_profile_resource_concept_id(profile_id_arg)
    )
    auto_bootstrapped = False
    try:
        _cs.update_concept(
            concept_id,
            {"attributes.oauth_scopes": scope_strings},
        )
    except Exception as exc:  # noqa: BLE001
        from ...services.concept_service import (
            ConceptNotFoundError as _ConceptNotFoundError,
        )

        if not isinstance(exc, _ConceptNotFoundError):
            return make_error_response(
                "vontology_update_failed",
                f"Failed to update OAuth scope in Vontology for profile '{profile_id_arg}': {exc}",
                details={"exception_type": type(exc).__name__},
            )
        if profile_authority.principal.kind != "trusted_local_operator":
            return make_error_response(
                "gmail_profile_authority_changed",
                "The represented Gmail profile authority changed before the "
                "scope update could be completed.",
                suggestions=[
                    "Refresh the actor-authorised Gmail profile choices and retry"
                ],
            )
        # Profile concept doesn't exist yet — auto-bootstrap it with the scope set inline
        try:
            from ...services.mail_profile_resource_vontology_service import (
                materialise_gmail_profile_resources_for_user,
            )
            from ...services.workflow_event_integration_service import (
                resolve_event_actor_context,
            )

            actor_user_id, _actor_org = resolve_event_actor_context()
            if not actor_user_id:
                raise RuntimeError(
                    "Cannot resolve user concept ID for profile bootstrap"
                )
            bootstrap_result = materialise_gmail_profile_resources_for_user(
                user_concept_id=actor_user_id,
                profile_ids=[profile_id_arg],
                profile_scopes={profile_id_arg: scope_strings},
            )
            if not bootstrap_result.get("success"):
                raise RuntimeError(
                    f"Bootstrap reported failure: {bootstrap_result.get('errors')}"
                )
            auto_bootstrapped = True
        except Exception as bootstrap_exc:  # noqa: BLE001
            return make_error_response(
                "vontology_update_failed",
                f"Profile concept '{concept_id}' not found and auto-bootstrap failed: {bootstrap_exc}",
                details={"exception_type": type(bootstrap_exc).__name__},
                suggestions=[
                    "The Gmail profile concept must exist in Vontology before setting scopes.",
                    "Ensure the profile was bootstrapped via the Gmail resource materialisation workflow.",
                ],
            )

    return {
        "success": True,
        "profile_id": profile_id_arg,
        "concept_id": concept_id,
        "scopes_set": scope_strings,
        "auto_bootstrapped": auto_bootstrapped,
        "reauth_required": True,
        "reauth_advisory": (
            "OAuth scope updated in Vontology. Re-authorise via Von UI → Settings → "
            "Agent Gmail OAuth to issue a new token with the updated scopes."
        ),
    }


# Jira MCP handlers

_JIRA_WRITE_CACHE: dict[str, dict[str, Any]] = {}
_JIRA_WRITE_CACHE_TTL_SEC = 3600.0
_JIRA_WRITE_CACHE_MAX = 200
_JIRA_ATTACHMENT_MAX_SIZE_BYTES_DEFAULT = 10 * 1024 * 1024
_JIRA_ATTACHMENT_ALLOWED_MIME_TYPES_DEFAULT = frozenset(
    {
        "image/png",
        "image/jpeg",
        "image/webp",
        "image/gif",
        "application/pdf",
        "text/plain",
        "text/markdown",
        "application/json",
    }
)
_GITHUB_WRITE_CACHE: dict[str, dict[str, Any]] = {}
_GITHUB_WRITE_CACHE_TTL_SEC = 3600.0
_GITHUB_WRITE_CACHE_MAX = 200


def _github_repo_allow_list() -> list[str]:
    import os

    raw = os.getenv("VON_GITHUB_REPO_ALLOW_LIST") or "Strong-AI-Lab/Von"
    repos: list[str] = []
    for part in raw.split(","):
        candidate = str(part or "").strip().strip("/")
        if not candidate or "/" not in candidate:
            continue
        owner, repo = candidate.split("/", 1)
        normalised = f"{owner.strip().lower()}/{repo.strip().lower()}"
        if not normalised or normalised not in repos:
            repos.append(normalised)
    return repos


def _github_repo_key(owner: Any, repo: Any) -> str | None:
    owner_text = str(owner).strip().lower() if isinstance(owner, str) else ""
    repo_text = str(repo).strip().lower() if isinstance(repo, str) else ""
    if not owner_text or not repo_text:
        return None
    return f"{owner_text}/{repo_text}"


def _github_execute_mode_enabled() -> bool:
    import os

    return os.getenv("VON_INTERNAL_MCP_GITHUB_EXECUTE_MODE", "0").lower() in {
        "1",
        "true",
    }


def _github_write_guardrails(
    *,
    action: str,
    repositories: Sequence[str],
    dry_run: bool,
    approved: bool,
    execute: bool,
) -> dict[str, Any] | None:
    allowed = _github_repo_allow_list()
    if not allowed:
        return {
            "success": False,
            "error": "GitHub writes are blocked: repository allow-list is empty",
            "error_code": "allowlist_missing",
            "action": action,
        }

    for repository in repositories:
        candidate = str(repository or "").strip().lower()
        if not candidate:
            return {
                "success": False,
                "error": "GitHub writes require owner/repo for allow-list checks",
                "error_code": "repository_required",
                "action": action,
            }
        if candidate not in allowed:
            return {
                "success": False,
                "error": (
                    f"GitHub writes are blocked for repository '{candidate}'. "
                    f"Allowed: {', '.join(allowed)}"
                ),
                "error_code": "repository_not_allowlisted",
                "repository": candidate,
                "allowed_repositories": allowed,
                "action": action,
            }

    if dry_run:
        return None
    if execute and _github_execute_mode_enabled():
        return None
    if approved:
        return None
    return {
        "success": False,
        "error": (
            "Approval required for GitHub write. Set approved=true to confirm this write, "
            "or run in execute mode (set VON_INTERNAL_MCP_GITHUB_EXECUTE_MODE=1 and pass execute=true)."
        ),
        "error_code": "approval_required",
        "action": action,
        "allowed_repositories": allowed,
    }


def _github_cache_get(tool: str, request_id: str) -> dict[str, Any] | None:
    import time

    key = f"{tool}:{request_id}"
    record = _GITHUB_WRITE_CACHE.get(key)
    if not isinstance(record, dict):
        return None
    ts = record.get("timestamp")
    if not isinstance(ts, (int, float)):
        return None
    if (time.time() - float(ts)) > _GITHUB_WRITE_CACHE_TTL_SEC:
        _GITHUB_WRITE_CACHE.pop(key, None)
        return None
    payload = record.get("payload")
    if not isinstance(payload, dict):
        return None
    return dict(payload)


def _github_cache_set(tool: str, request_id: str, payload: dict[str, Any]) -> None:
    import time

    if len(_GITHUB_WRITE_CACHE) >= _GITHUB_WRITE_CACHE_MAX:
        oldest_key = None
        oldest_ts = None
        for key, record in _GITHUB_WRITE_CACHE.items():
            ts = record.get("timestamp") if isinstance(record, dict) else None
            if not isinstance(ts, (int, float)):
                continue
            if oldest_ts is None or float(ts) < oldest_ts:
                oldest_ts = float(ts)
                oldest_key = key
        if oldest_key:
            _GITHUB_WRITE_CACHE.pop(oldest_key, None)

    _GITHUB_WRITE_CACHE[f"{tool}:{request_id}"] = {
        "timestamp": time.time(),
        "payload": dict(payload),
    }


def _github_clean_text(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    cleaned = value.strip()
    return cleaned or None


def _github_normalise_response(
    *,
    tool_name: str,
    proxy_tool_name: str,
    raw_result: Any,
    proxy_stats: Mapping[str, Any] | None,
) -> dict[str, Any]:
    payload: dict[str, Any]
    if isinstance(raw_result, dict):
        payload = dict(raw_result)
        payload.setdefault("success", True)
    elif isinstance(raw_result, list):
        payload = {"success": True, "items": list(raw_result), "count": len(raw_result)}
    else:
        payload = {"success": True, "result": raw_result}

    payload.setdefault("tool", tool_name)
    if proxy_tool_name != tool_name:
        payload.setdefault("proxy_tool", proxy_tool_name)
    if isinstance(proxy_stats, Mapping):
        payload.setdefault("proxy_stats", dict(proxy_stats))
    return payload


def _github_resolve_proxy_call(
    tool_name: str,
    arguments: Mapping[str, Any],
) -> tuple[str, dict[str, Any]] | dict[str, Any]:
    # Internal tool names mirror Von's `github_*` surface, while the external
    # `@modelcontextprotocol/server-github` server exposes mostly unprefixed
    # names.  Resolve the translation once here so handlers stay simple.
    proxy_arguments = dict(arguments)

    if tool_name == "github_pull_request_read":
        method = _github_clean_text(proxy_arguments.pop("method"))
        method_map = {
            "get": "get_pull_request",
            "get_files": "get_pull_request_files",
            "get_status": "get_pull_request_status",
            "get_comments": "get_pull_request_comments",
            "get_reviews": "get_pull_request_reviews",
        }
        proxy_tool_name = method_map.get(method or "")
        if proxy_tool_name is None:
            return make_error_response(
                "unsupported_operation",
                "Configured GitHub MCP server does not support this "
                f"github_pull_request_read method: {method!r}",
                details={
                    "tool": tool_name,
                    "method": method,
                    "supported_methods": sorted(method_map),
                },
                suggestions=[
                    "Use one of: get, get_files, get_status, get_comments, get_reviews",
                    "If you need other pull-request reads, extend the proxy-tool mapping first",
                ],
            )
        return proxy_tool_name, proxy_arguments

    if tool_name == "github_issue_read":
        method = _github_clean_text(proxy_arguments.pop("method"))
        method_map = {"get": "get_issue"}
        proxy_tool_name = method_map.get(method or "")
        if proxy_tool_name is None:
            return make_error_response(
                "unsupported_operation",
                "Configured GitHub MCP server does not support this "
                f"github_issue_read method: {method!r}",
                details={
                    "tool": tool_name,
                    "method": method,
                    "supported_methods": sorted(method_map),
                },
                suggestions=[
                    "Use method=get for the current GitHub MCP server version",
                    "If you need richer issue reads, add an explicit translation for the target tool",
                ],
            )
        return proxy_tool_name, proxy_arguments

    if tool_name.startswith("github_"):
        return tool_name.removeprefix("github_"), proxy_arguments
    return tool_name, proxy_arguments


def _github_invoke_proxy_tool(
    tool_name: str, arguments: Mapping[str, Any]
) -> dict[str, Any]:
    from .github_proxy_mcp import GitHubProxyError, get_github_proxy

    resolved_call = _github_resolve_proxy_call(tool_name, arguments)
    if isinstance(resolved_call, dict):
        return resolved_call
    proxy_tool_name, proxy_arguments = resolved_call

    async def _async_call():
        proxy = await get_github_proxy()
        result = await proxy.call_tool(proxy_tool_name, proxy_arguments)
        return result, proxy.get_stats()

    try:
        raw_result, proxy_stats = _run_async_compat(_async_call)
    except GitHubProxyError as exc:
        error_message = str(exc)
        return make_error_response(
            "github_proxy_error",
            error_message,
            details={
                "exception_type": "GitHubProxyError",
                "tool": tool_name,
                "proxy_tool": proxy_tool_name,
                "message": error_message,
            },
            suggestions=[
                "Check GitHub MCP connectivity, command args, and token configuration",
                "If using VS Code, ensure GITHUB_PERSONAL_ACCESS_TOKEN is set in .env "
                "(VS Code may override GITHUB_TOKEN with its own Copilot auth token)",
            ],
        )
    except Exception as exc:  # pragma: no cover - defensive
        return make_error_response(
            "github_proxy_error",
            f"GitHub proxy invocation failed: {exc}",
            details={
                "exception_type": type(exc).__name__,
                "tool": tool_name,
                "proxy_tool": proxy_tool_name,
            },
            suggestions=["Check GitHub MCP server availability"],
        )

    return _github_normalise_response(
        tool_name=tool_name,
        proxy_tool_name=proxy_tool_name,
        raw_result=raw_result,
        proxy_stats=proxy_stats if isinstance(proxy_stats, Mapping) else None,
    )


def _github_extract_owner_repo(
    kwargs: Mapping[str, Any],
) -> tuple[str | None, str | None]:
    owner = _github_clean_text(kwargs.get("owner"))
    repo = _github_clean_text(kwargs.get("repo"))
    return owner, repo


def _github_require_owner_repo(
    kwargs: Mapping[str, Any],
) -> tuple[str, str] | dict[str, Any]:
    owner, repo = _github_extract_owner_repo(kwargs)
    if not owner or not repo:
        return make_error_response(
            "missing_parameter",
            "Missing required parameters: owner and repo",
            details={"missing": ["owner", "repo"]},
            suggestions=["Provide GitHub repository owner and repo names"],
        )
    return owner, repo


def _github_execute_write_tool(
    *,
    action: str,
    proxy_tool_name: str,
    owner: str,
    repo: str,
    dry_run: bool,
    approved: bool,
    execute: bool,
    request_id: str | None,
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    repository = _github_repo_key(owner, repo)
    if not repository:
        return make_error_response(
            "missing_parameter",
            "Missing required parameters: owner and repo",
            details={"missing": ["owner", "repo"]},
        )

    guardrail_error = _github_write_guardrails(
        action=action,
        repositories=[repository],
        dry_run=dry_run,
        approved=approved,
        execute=execute,
    )
    if guardrail_error is not None:
        return guardrail_error

    if isinstance(request_id, str) and request_id.strip() and not dry_run:
        cached = _github_cache_get(proxy_tool_name, request_id.strip())
        if cached is not None:
            cached["reused"] = True
            return cached

    proposed_payload = dict(payload)
    if dry_run:
        return {
            "success": True,
            "dry_run": True,
            "executed": False,
            "action": action,
            "owner": owner,
            "repo": repo,
            "repository": repository,
            "proposed_payload": proposed_payload,
        }

    result = _github_invoke_proxy_tool(proxy_tool_name, proposed_payload)
    if not isinstance(result, dict):
        result = {"success": False, "error": "Unexpected GitHub proxy response shape"}

    if result.get("success") is False:
        result.setdefault("action", action)
        result.setdefault("dry_run", False)
        result.setdefault("executed", True)
        result.setdefault("owner", owner)
        result.setdefault("repo", repo)
        result.setdefault("repository", repository)
        return result

    result = dict(result)
    result.setdefault("success", True)
    result["action"] = action
    result["dry_run"] = False
    result["executed"] = True
    result["owner"] = owner
    result["repo"] = repo
    result["repository"] = repository
    if isinstance(request_id, str) and request_id.strip():
        _github_cache_set(proxy_tool_name, request_id.strip(), result)
    return result


def _github_get_auth_config(**kwargs):
    import os
    import shlex
    from ...utils.runtime_env import read_repo_dotenv_values
    from .github_proxy_mcp import (
        GitHubProxyError,
        GITHUB_PROXY_ENV_OVERRIDE_KEYS,
        get_github_proxy,
        resolve_github_token,
    )

    dotenv_values = read_repo_dotenv_values(GITHUB_PROXY_ENV_OVERRIDE_KEYS)
    env = os.environ.copy()
    env.update(dotenv_values)
    token_key, token = resolve_github_token(env)

    command = str(env.get("VON_GITHUB_MCP_COMMAND") or "npx").strip() or "npx"
    raw_args = env.get("VON_GITHUB_MCP_ARGS")
    if isinstance(raw_args, str) and raw_args.strip():
        args = shlex.split(raw_args.strip())
    else:
        args = ["-y", "@modelcontextprotocol/server-github"]

    payload: dict[str, Any] = {
        "success": True,
        "token_present": bool(token),
        "token_length": len(token) if token else 0,
        "env_keys_used": {
            "token": token_key,
            "command": (
                "VON_GITHUB_MCP_COMMAND" if env.get("VON_GITHUB_MCP_COMMAND") else None
            ),
            "args": "VON_GITHUB_MCP_ARGS" if env.get("VON_GITHUB_MCP_ARGS") else None,
            "allow_list": "VON_GITHUB_REPO_ALLOW_LIST",
            "execute_mode": "VON_INTERNAL_MCP_GITHUB_EXECUTE_MODE",
        },
        "dotenv_overrides_applied": sorted(dotenv_values.keys()),
        "process_environment_mutated": False,
        "allow_repositories": _github_repo_allow_list(),
        "execute_mode_enabled": _github_execute_mode_enabled(),
        "command": command,
        "args": args,
    }

    async def _async_probe():
        proxy = await get_github_proxy()
        tools = await proxy.list_tools()
        return tools, proxy.get_stats()

    try:
        tools, stats = _run_async_compat(_async_probe)
        payload["proxy_tools_available"] = True
        payload["proxy_tool_count"] = len(tools) if isinstance(tools, list) else 0
        if isinstance(stats, Mapping):
            payload["proxy_stats"] = dict(stats)
    except GitHubProxyError as exc:
        payload["proxy_tools_available"] = False
        payload["proxy_error"] = str(exc)
        payload["error"] = str(exc)
        payload["error_code"] = "github_proxy_error"
    except Exception as exc:  # pragma: no cover - defensive
        payload["proxy_tools_available"] = False
        payload["proxy_error"] = str(exc)
        payload["error"] = str(exc)
        payload["error_code"] = "github_proxy_error"
    return payload


def _github_list_tools(**kwargs):
    from .github_proxy_mcp import GitHubProxyError, get_github_proxy

    async def _async_list():
        proxy = await get_github_proxy()
        tools = await proxy.list_tools()
