def _jira_issue_type_context_names(payload: Any) -> list[str]:
    if not isinstance(payload, dict):
        return []

    names: list[str] = []
    available_names = payload.get("available_issue_type_names")
    if isinstance(available_names, list):
        for item in available_names:
            if isinstance(item, str) and item and item not in names:
                names.append(item)

    for field_name in ("creatable_issue_types", "project_issue_types"):
        values = payload.get(field_name)
        if not isinstance(values, list):
            continue
        for item in values:
            if not isinstance(item, dict):
                continue
            name = item.get("name")
            if isinstance(name, str) and name and name not in names:
                names.append(name)

    return names


def _jira_issue_type_available(payload: Any, requested_issue_type: str) -> bool:
    if not isinstance(payload, dict):
        return False

    requested_key = requested_issue_type.strip().casefold()
    if not requested_key:
        return False

    for name in _jira_issue_type_context_names(payload):
        if name.casefold() == requested_key:
            return True

    for field_name in ("creatable_issue_types", "project_issue_types"):
        values = payload.get(field_name)
        if not isinstance(values, list):
            continue
        for item in values:
            if not isinstance(item, dict):
                continue
            issue_type_id = item.get("id")
            if isinstance(issue_type_id, (str, int)) and str(issue_type_id).strip():
                if str(issue_type_id).strip() == requested_issue_type.strip():
                    return True
    return False


def _jira_issue_type_unavailable_error(
    *,
    project_key: str,
    requested_issue_type: str,
    issue_type_context: dict[str, Any],
) -> dict[str, Any]:
    available_names = _jira_issue_type_context_names(issue_type_context)
    is_team_managed = bool(issue_type_context.get("is_team_managed"))
    project_style = issue_type_context.get("project_style")

    suggestions = []
    if available_names:
        suggestions.append(
            "Use one of the available issue types for this project: "
            + ", ".join(available_names)
        )
    if is_team_managed:
        suggestions.append(
            "This is a team-managed Jira project, so the classic issue-type-scheme path does not apply."
        )
        suggestions.append(
            "If you need Bug semantics here, add or enable a Bug-like issue type in the team-managed project configuration."
        )
    else:
        suggestions.append(
            "If this issue type should be available, check the project's Jira issue type configuration before retrying."
        )

    return make_error_response(
        "jira_issue_type_not_available_for_project",
        (
            f"Issue type '{requested_issue_type}' is not available for Jira project "
            f"'{project_key}'."
        ),
        details={
            "project_key": project_key,
            "requested_issue_type": requested_issue_type,
            "available_issue_types": available_names,
            "project_style": project_style,
            "project_type_key": issue_type_context.get("project_type_key"),
            "project_id": issue_type_context.get("project_id"),
            "is_team_managed": is_team_managed,
            "issue_type_scheme_supported": issue_type_context.get(
                "issue_type_scheme_supported"
            ),
            "issue_type_context": issue_type_context,
        },
        suggestions=suggestions,
    )


def _jira_issue_type_records(issue_type_context: Any) -> list[dict[str, Any]]:
    if not isinstance(issue_type_context, dict):
        return []

    records: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for field_name in ("creatable_issue_types", "project_issue_types"):
        values = issue_type_context.get(field_name)
        if not isinstance(values, list):
            continue
        for item in values:
            if not isinstance(item, dict):
                continue
            issue_type_id = str(item.get("id") or "").strip()
            issue_type_name = str(item.get("name") or "").strip()
            if not issue_type_id and not issue_type_name:
                continue
            key = (issue_type_id, issue_type_name.casefold())
            if key in seen:
                continue
            seen.add(key)
            records.append(dict(item))
    return records


def _jira_issue_type_record_matches(
    record: Mapping[str, Any], requested_issue_type: str
) -> bool:
    requested = requested_issue_type.strip()
    if not requested:
        return False

    issue_type_id = record.get("id")
    if (
        isinstance(issue_type_id, (str, int))
        and str(issue_type_id).strip() == requested
    ):
        return True

    issue_type_name = record.get("name")
    return (
        isinstance(issue_type_name, str)
        and issue_type_name.strip().casefold() == requested.casefold()
    )


def _jira_resolve_issue_type_record(
    issue_type_context: Any,
    *,
    requested_issue_type: str | None = None,
    require_subtask: bool | None = None,
) -> dict[str, Any] | None:
    records = _jira_issue_type_records(issue_type_context)
    if not records:
        return None

    if isinstance(requested_issue_type, str) and requested_issue_type.strip():
        for record in records:
            if _jira_issue_type_record_matches(record, requested_issue_type):
                if (
                    require_subtask is None
                    or bool(record.get("subtask")) is require_subtask
                ):
                    return record
        return None

    if require_subtask is None:
        return None

    filtered = [
        record for record in records if bool(record.get("subtask")) is require_subtask
    ]
    if len(filtered) == 1:
        return filtered[0]
    return None


def _jira_extract_issue_context(issue_payload: Any) -> dict[str, Any] | None:
    if not isinstance(issue_payload, dict):
        return None

    issue_key = issue_payload.get("key")
    if not isinstance(issue_key, str) or not issue_key.strip():
        return None

    fields = issue_payload.get("fields")
    if not isinstance(fields, dict):
        fields = {}

    project_key = _jira_project_from_issue_key(issue_key)
    project = fields.get("project")
    if isinstance(project, dict):
        project_key = (
            str(project.get("key")).strip().upper()
            if str(project.get("key") or "").strip()
            else project_key
        )

    issue_type = fields.get("issuetype")
    issue_type_id: str | None = None
    issue_type_name: str | None = None
    issue_type_is_subtask = False
    if isinstance(issue_type, dict):
        raw_id = issue_type.get("id")
        if isinstance(raw_id, (str, int)) and str(raw_id).strip():
            issue_type_id = str(raw_id).strip()
        raw_name = issue_type.get("name")
        if isinstance(raw_name, str) and raw_name.strip():
            issue_type_name = raw_name.strip()
        issue_type_is_subtask = bool(issue_type.get("subtask"))

    parent_issue_key: str | None = None
    parent = fields.get("parent")
    if isinstance(parent, dict):
        raw_parent_key = parent.get("key")
        if isinstance(raw_parent_key, str) and raw_parent_key.strip():
            parent_issue_key = raw_parent_key.strip()

    return {
        "issue_key": issue_key.strip(),
        "project_key": project_key,
        "issue_type_id": issue_type_id,
        "issue_type_name": issue_type_name,
        "is_subtask": issue_type_is_subtask,
        "parent_issue_key": parent_issue_key,
        "raw_issue": issue_payload,
    }


def _jira_get_issue_context(issue_key: str) -> dict[str, Any] | dict[str, Any]:
    issue_payload = _jira_get_issue(
        issue_key=issue_key,
        fields=["project", "issuetype", "parent"],
    )
    if not isinstance(issue_payload, dict):
        return make_error_response(
            "jira_issue_preflight_failed",
            f"Jira issue preflight for '{issue_key}' returned an unexpected response",
            details={"response_type": type(issue_payload).__name__},
        )
    if issue_payload.get("success") is False and issue_payload.get("error"):
        return make_error_response(
            "jira_issue_preflight_failed",
            f"Could not read Jira issue '{issue_key}' for move preflight",
            details={"issue_key": issue_key, "preflight_result": issue_payload},
            suggestions=["Check Jira connectivity and authentication"],
        )

    issue_context = _jira_extract_issue_context(issue_payload)
    if issue_context is None:
        return make_error_response(
            "jira_issue_preflight_failed",
            f"Jira issue '{issue_key}' did not return the project/type fields required for move preflight",
            details={"issue_key": issue_key, "issue_payload": issue_payload},
        )
    return issue_context


def _jira_bulk_status_is_terminal(status: Any) -> bool:
    if not isinstance(status, str):
        return False
    return status.strip().upper() not in {
        "SUBMITTED",
        "PENDING",
        "ENQUEUED",
        "RUNNING",
        "IN_PROGRESS",
    }


def _jira_build_move_mapping_key(
    *,
    target_project_key: str,
    target_issue_type_id: str,
    target_parent_issue_key: str | None,
) -> str:
    parts = [target_project_key.strip().upper(), target_issue_type_id.strip()]
    if isinstance(target_parent_issue_key, str) and target_parent_issue_key.strip():
        parts.append(target_parent_issue_key.strip().upper())
    return ",".join(parts)


def _jira_move_issue(**kwargs):
    import logging
    import time
    from .jira_proxy_mcp import get_jira_proxy, JiraProxyError

    logger = logging.getLogger(__name__)

    issue_key = kwargs.get("issue_key")
    if not isinstance(issue_key, str) or not issue_key.strip():
        return make_error_response(
            "MISSING_PARAMS",
            "Missing required parameter: issue_key",
            suggestions=["Provide a Jira issue key such as JVNAUTOSCI-1874"],
        )

    issue_key_norm = issue_key.strip().upper()
    source_project_key = _jira_project_from_issue_key(issue_key_norm)
    if not source_project_key:
        return make_error_response(
            "INVALID_ISSUE_KEY",
            "Invalid issue_key format; expected PROJECT-123",
            suggestions=["Use the format PROJECT-123 for issue keys"],
        )

    dry_run, approved, execute = _jira_resolve_write_intent(kwargs)
    request_id = kwargs.get("request_id")

    source_issue_context = _jira_get_issue_context(issue_key_norm)
    if source_issue_context.get("success") is False:
        return source_issue_context

    source_issue_type_name = source_issue_context.get("issue_type_name")
    source_issue_type_id = source_issue_context.get("issue_type_id")
    source_parent_issue_key = source_issue_context.get("parent_issue_key")
    source_is_subtask = bool(source_issue_context.get("is_subtask"))

    target_project_key: str | None = None
    target_project_key_raw = kwargs.get("target_project_key")
    if isinstance(target_project_key_raw, str) and target_project_key_raw.strip():
        target_project_key = target_project_key_raw.strip().upper()

    target_parent_issue_key: str | None = None
    explicit_parent_issue_key = kwargs.get("target_parent_issue_key")
    if isinstance(explicit_parent_issue_key, str) and explicit_parent_issue_key.strip():
        target_parent_issue_key = explicit_parent_issue_key.strip().upper()
    elif (
        source_is_subtask
        and isinstance(source_parent_issue_key, str)
        and source_parent_issue_key.strip()
    ):
        target_parent_issue_key = source_parent_issue_key.strip().upper()

    target_parent_context: dict[str, Any] | None = None
    if isinstance(target_parent_issue_key, str) and target_parent_issue_key:
        if target_parent_issue_key == issue_key_norm:
            return make_error_response(
                "invalid_parent_issue",
                "target_parent_issue_key cannot be the same as issue_key",
                details={"issue_key": issue_key_norm},
            )
        target_parent_context = _jira_get_issue_context(target_parent_issue_key)
        if target_parent_context.get("success") is False:
            return target_parent_context
        parent_project_key = target_parent_context.get("project_key")
        if isinstance(parent_project_key, str) and parent_project_key:
            if target_project_key and target_project_key != parent_project_key:
                return make_error_response(
                    "jira_move_parent_project_mismatch",
                    (
                        "target_project_key does not match the project of "
                        "target_parent_issue_key"
                    ),
                    details={
                        "issue_key": issue_key_norm,
                        "target_project_key": target_project_key,
                        "target_parent_issue_key": target_parent_issue_key,
                        "parent_project_key": parent_project_key,
                    },
                    suggestions=[
                        "Omit target_project_key to infer it from the parent issue",
                        "Use a parent issue that belongs to the requested target project",
                    ],
                )
            target_project_key = parent_project_key

    if not target_project_key:
        target_project_key = source_project_key

    guardrail_projects = [source_project_key]
    if target_project_key not in guardrail_projects:
        guardrail_projects.append(target_project_key)

    guardrail_error = _jira_write_guardrails(
        action="move_issue",
        project_keys=guardrail_projects,
        dry_run=dry_run,
        approved=approved,
        execute=execute,
    )
    if guardrail_error is not None:
        return guardrail_error

    if isinstance(request_id, str) and request_id.strip() and not dry_run:
        cached = _jira_cache_get("jira_move_issue", request_id.strip())
        if cached is not None:
            cached["reused"] = True
            return cached

    target_issue_type_context = _jira_get_project_issue_types(
        project_key=target_project_key
    )
    if target_issue_type_context.get("success") is not True:
        return make_error_response(
            "jira_issue_type_preflight_failed",
            (
                f"Could not verify target issue types for Jira project "
                f"'{target_project_key}'."
            ),
            details={
                "issue_key": issue_key_norm,
                "target_project_key": target_project_key,
                "preflight_result": target_issue_type_context,
            },
            suggestions=[
                "Check Jira connectivity and authentication",
                "Verify the target project key is correct",
            ],
        )

    requested_target_issue_type = kwargs.get("target_issue_type")
    target_issue_type_record: dict[str, Any] | None = None
    if (
        isinstance(requested_target_issue_type, str)
        and requested_target_issue_type.strip()
    ):
        target_issue_type_record = _jira_resolve_issue_type_record(
            target_issue_type_context,
            requested_issue_type=requested_target_issue_type.strip(),
        )
        if target_issue_type_record is None:
            return _jira_issue_type_unavailable_error(
                project_key=target_project_key,
                requested_issue_type=requested_target_issue_type.strip(),
                issue_type_context=target_issue_type_context,
            )
    elif target_parent_issue_key:
        if source_is_subtask:
            if isinstance(source_issue_type_id, str) and source_issue_type_id:
                target_issue_type_record = _jira_resolve_issue_type_record(
                    target_issue_type_context,
                    requested_issue_type=source_issue_type_id,
                    require_subtask=True,
                )
            if target_issue_type_record is None and isinstance(
                source_issue_type_name, str
            ):
                target_issue_type_record = _jira_resolve_issue_type_record(
                    target_issue_type_context,
                    requested_issue_type=source_issue_type_name,
                    require_subtask=True,
                )
        if target_issue_type_record is None:
            target_issue_type_record = _jira_resolve_issue_type_record(
                target_issue_type_context,
                require_subtask=True,
            )
        if target_issue_type_record is None:
            subtask_names = [
                str(record.get("name")).strip()
                for record in _jira_issue_type_records(target_issue_type_context)
                if bool(record.get("subtask")) and str(record.get("name") or "").strip()
            ]
            return make_error_response(
                "jira_move_target_issue_type_ambiguous",
                (
                    "A target_parent_issue_key was provided, but the target project does "
                    "not have a uniquely inferable subtask issue type."
                ),
                details={
                    "issue_key": issue_key_norm,
                    "target_project_key": target_project_key,
                    "available_subtask_issue_types": subtask_names,
                    "issue_type_context": target_issue_type_context,
                },
                suggestions=[
                    "Provide target_issue_type explicitly",
                    "Ensure the target project has exactly one subtask issue type if automatic conversion is desired",
                ],
            )
    else:
        if isinstance(source_issue_type_id, str) and source_issue_type_id:
            target_issue_type_record = _jira_resolve_issue_type_record(
                target_issue_type_context,
                requested_issue_type=source_issue_type_id,
            )
        if target_issue_type_record is None and isinstance(source_issue_type_name, str):
            target_issue_type_record = _jira_resolve_issue_type_record(
                target_issue_type_context,
                requested_issue_type=source_issue_type_name,
            )
        if target_issue_type_record is None:
            requested = (
                source_issue_type_name
                if isinstance(source_issue_type_name, str) and source_issue_type_name
                else str(source_issue_type_id or "")
            )
            return _jira_issue_type_unavailable_error(
                project_key=target_project_key,
                requested_issue_type=requested or "source issue type",
                issue_type_context=target_issue_type_context,
            )

    target_issue_type_id = str(target_issue_type_record.get("id") or "").strip()
    target_issue_type_name = str(target_issue_type_record.get("name") or "").strip()
    target_is_subtask = bool(target_issue_type_record.get("subtask"))
    if not target_issue_type_id or not target_issue_type_name:
        return make_error_response(
            "jira_move_target_issue_type_invalid",
            "Resolved target issue type did not include a usable Jira id and name",
            details={
                "issue_key": issue_key_norm,
                "target_project_key": target_project_key,
                "target_issue_type_record": target_issue_type_record,
            },
        )

    if target_is_subtask and not target_parent_issue_key:
        return make_error_response(
            "jira_move_parent_required",
            (
                "A target parent issue is required when converting or moving an issue "
                "to a subtask issue type."
            ),
            details={
                "issue_key": issue_key_norm,
                "target_project_key": target_project_key,
                "target_issue_type": target_issue_type_name,
            },
            suggestions=[
                "Provide target_parent_issue_key",
                "If the issue should remain a top-level task, choose a non-subtask target_issue_type",
            ],
        )

    if not target_is_subtask:
        target_parent_issue_key = None
        target_parent_context = None

    mapping_key = _jira_build_move_mapping_key(
        target_project_key=target_project_key,
        target_issue_type_id=target_issue_type_id,
        target_parent_issue_key=target_parent_issue_key,
    )

    mapping_payload: dict[str, Any] = {
        "issueIdsOrKeys": [issue_key_norm],
        "inferFieldDefaults": bool(kwargs.get("infer_field_defaults", True)),
        "inferStatusDefaults": bool(kwargs.get("infer_status_defaults", True)),
        "inferSubtaskTypeDefault": bool(kwargs.get("infer_subtask_type_default", True)),
    }
    target_mandatory_fields = kwargs.get("target_mandatory_fields")
    if isinstance(target_mandatory_fields, list) and target_mandatory_fields:
        mapping_payload["targetMandatoryFields"] = target_mandatory_fields
    target_status = kwargs.get("target_status")
    if isinstance(target_status, list) and target_status:
        mapping_payload["targetStatus"] = target_status

    move_payload: dict[str, Any] = {
        "targetToSourcesMapping": {mapping_key: mapping_payload}
    }
    if "send_bulk_notification" in kwargs:
        move_payload["sendBulkNotification"] = bool(
            kwargs.get("send_bulk_notification")
        )

    preflight = {
        "source_issue": source_issue_context,
        "target_project_issue_types": target_issue_type_context,
        "target_project_key": target_project_key,
        "target_issue_type": {
            "id": target_issue_type_id,
            "name": target_issue_type_name,
            "subtask": target_is_subtask,
            "requested": (
                requested_target_issue_type.strip()
                if isinstance(requested_target_issue_type, str)
                and requested_target_issue_type.strip()
                else None
            ),
        },
        "target_parent_issue": target_parent_context,
        "mapping_key": mapping_key,
    }

    if dry_run:
        return {
            "success": True,
            "dry_run": True,
            "executed": False,
            "action": "move_issue",
            "issue_key": issue_key_norm,
            "target_project_key": target_project_key,
            "target_issue_type_id": target_issue_type_id,
            "target_issue_type_name": target_issue_type_name,
            "target_parent_issue_key": target_parent_issue_key,
            "move_preflight": preflight,
            "proposed_payload": move_payload,
        }

    await_completion = bool(kwargs.get("await_completion", False))
    try:
        poll_interval_seconds = float(kwargs.get("poll_interval_seconds", 2.0))
    except (TypeError, ValueError):
        poll_interval_seconds = 2.0
    poll_interval_seconds = max(0.1, poll_interval_seconds)

    try:
        timeout_seconds = float(
            kwargs.get(
                "advisory_seconds",
                kwargs.get(
                    "timeout_seconds",
                    60.0 if await_completion else 0.0,
                ),
            )
        )
    except (TypeError, ValueError):
        timeout_seconds = 60.0 if await_completion else 0.0
    timeout_seconds = max(0.0, timeout_seconds)

    async def _async_move():
        proxy = await get_jira_proxy()
        return await proxy.move_issue(payload=move_payload)

    try:
        logger.info(
            "[jira_write] move_issue key=%s target=%s type=%s parent=%s",
            issue_key_norm,
            target_project_key,
            target_issue_type_name,
            target_parent_issue_key,
        )
        result = _run_async_compat(_async_move)
    except JiraProxyError as exc:
        return make_error_response("JIRA_ERROR", str(exc))

    response_payload: dict[str, Any] = (
        dict(result) if isinstance(result, dict) else {"result": result}
    )
    response_payload.setdefault("success", True)
    response_payload["dry_run"] = False
    response_payload["executed"] = True
    response_payload["action"] = "move_issue"
    response_payload["issue_key"] = issue_key_norm
    response_payload["target_project_key"] = target_project_key
    response_payload["target_issue_type_id"] = target_issue_type_id
    response_payload["target_issue_type_name"] = target_issue_type_name
    response_payload["target_parent_issue_key"] = target_parent_issue_key
    response_payload["move_preflight"] = preflight

    bulk_task_id = response_payload.get("taskId") or response_payload.get("task_id")
    if isinstance(bulk_task_id, (str, int)) and str(bulk_task_id).strip():
        response_payload["bulk_task_id"] = str(bulk_task_id).strip()

    if await_completion and response_payload.get("bulk_task_id"):
        bulk_task_id = str(response_payload["bulk_task_id"]).strip()

        async def _async_progress():
            proxy = await get_jira_proxy()
            return await proxy.get_bulk_operation_progress(task_id=bulk_task_id)

        deadline = time.monotonic() + timeout_seconds
        last_progress: dict[str, Any] | None = None
        while True:
            try:
                progress_result = _run_async_compat(_async_progress)
            except JiraProxyError as exc:
                return make_error_response(
                    "JIRA_ERROR",
                    str(exc),
                    details={
                        "issue_key": issue_key_norm,
                        "bulk_task_id": bulk_task_id,
                    },
                )

            if isinstance(progress_result, dict):
                last_progress = dict(progress_result)
                last_progress.setdefault("success", True)
                last_progress["task_id"] = bulk_task_id
                last_progress["terminal"] = _jira_bulk_status_is_terminal(
                    last_progress.get("status")
                )
                if last_progress["terminal"]:
                    response_payload["awaited_completion"] = True
                    response_payload["bulk_progress"] = last_progress
                    break

            if time.monotonic() >= deadline:
                response_payload["awaited_completion"] = False
                response_payload["bulk_progress"] = last_progress
                response_payload["completion_pending"] = True
                response_payload["elapsed_time_enforcement"] = "advisory"
                response_payload["advisory_seconds"] = timeout_seconds
                response_payload["advisory_exceeded"] = True
                response_payload["hard_timeout_seconds"] = None
                response_payload["outcome_finality"] = (
                    "pending_external_operation_observation"
                )
                response_payload["recovery_affordances"] = [
                    {
                        "action_type": "poll_external_operation",
                        "tool": "jira_get_bulk_operation_progress",
                        "task_id": bulk_task_id,
                    }
                ]
                break

            time.sleep(poll_interval_seconds)

    if isinstance(request_id, str) and request_id.strip():
        _jira_cache_set("jira_move_issue", request_id.strip(), response_payload)
    return response_payload


def _jira_create_issue(**kwargs):
    import logging
    from .jira_proxy_mcp import get_jira_proxy, JiraProxyError

    logger = logging.getLogger(__name__)

    project_key = kwargs.get("project_key")
    issue_type = kwargs.get("issue_type")
    summary = kwargs.get("summary")

    if not project_key or not issue_type or not summary:
        return make_error_response(
            "MISSING_PARAMS",
            "Missing required parameters: project_key, issue_type, summary",
            suggestions=[
                "Provide project_key (e.g. 'PROJ'), issue_type (e.g. 'Task'), and summary text"
            ],
        )

    project_key_norm = str(project_key).strip().upper()
    dry_run, approved, execute = _jira_resolve_write_intent(kwargs)
    request_id = kwargs.get("request_id")

    guardrail_error = _jira_write_guardrails(
        action="create_issue",
        project_keys=[project_key_norm],
        dry_run=dry_run,
        approved=approved,
        execute=execute,
    )
    if guardrail_error is not None:
        return guardrail_error

    if isinstance(request_id, str) and request_id.strip() and not dry_run:
        cached = _jira_cache_get("jira_create_issue", request_id.strip())
        if cached is not None:
            cached["reused"] = True
            return cached

    requested_issue_type = str(issue_type).strip()
    issue_type_context = _jira_get_project_issue_types(project_key=project_key_norm)
    if issue_type_context.get("success") is not True:
        return make_error_response(
            "jira_issue_type_preflight_failed",
            (
                f"Could not verify whether issue type '{requested_issue_type}' is valid "
                f"for Jira project '{project_key_norm}'."
            ),
            details={
                "project_key": project_key_norm,
                "requested_issue_type": requested_issue_type,
                "preflight_result": issue_type_context,
            },
            suggestions=[
                "Check Jira connectivity and authentication",
                "Verify the project key is correct",
            ],
        )

    if not _jira_issue_type_available(issue_type_context, requested_issue_type):
        return _jira_issue_type_unavailable_error(
            project_key=project_key_norm,
            requested_issue_type=requested_issue_type,
            issue_type_context=issue_type_context,
        )

    payload: dict[str, Any] = {
        "fields": {
            "project": {"key": project_key_norm},
            "summary": str(summary),
            "issuetype": {"name": requested_issue_type},
        }
    }

    description = kwargs.get("description")
    if isinstance(description, str) and description.strip():
        payload["fields"]["description"] = description

    parent = kwargs.get("parent")
    if isinstance(parent, str) and parent.strip():
        payload["fields"]["parent"] = {"key": parent.strip()}

    assignee_account_id = kwargs.get("assignee_account_id")
    if isinstance(assignee_account_id, str) and assignee_account_id.strip():
        payload["fields"]["assignee"] = {"accountId": assignee_account_id.strip()}

    labels = kwargs.get("labels")
    if isinstance(labels, list):
        payload["fields"]["labels"] = [
            str(label) for label in labels if str(label).strip()
        ]

    components = kwargs.get("components")
    if isinstance(components, list):
        normalised_components: list[dict[str, str]] = []
        for component in components:
            if isinstance(component, str) and component.strip():
                normalised_components.append({"name": component.strip()})
                continue
            if not isinstance(component, dict):
                continue

            normalised_component: dict[str, str] = {}
            name = component.get("name")
            if isinstance(name, str) and name.strip():
                normalised_component["name"] = name.strip()

            component_id = component.get("id")
            if isinstance(component_id, (str, int)) and str(component_id).strip():
                normalised_component["id"] = str(component_id).strip()

            if normalised_component:
                normalised_components.append(normalised_component)

        if normalised_components:
            payload["fields"]["components"] = normalised_components

    if dry_run:
        return {
            "success": True,
            "dry_run": True,
            "executed": False,
            "action": "create_issue",
            "project_key": project_key_norm,
            "issue_type_preflight": issue_type_context,
            "proposed_payload": payload,
        }

    async def _async_create():
        proxy = await get_jira_proxy()
        return await proxy.create_issue(payload=payload)

    try:
        logger.info(
            "[jira_write] create_issue project=%s summary_preview=%r",
            project_key_norm,
            str(summary)[:120],
        )
        result = _run_async_compat(_async_create)
        if isinstance(result, dict):
            result = dict(result)
            result.setdefault("success", True)
            result["dry_run"] = False
            result["executed"] = True
            result["action"] = "create_issue"
            result.setdefault("issue_type_preflight", issue_type_context)
            if isinstance(request_id, str) and request_id.strip():
                _jira_cache_set("jira_create_issue", request_id.strip(), result)
            return result
        return {
            "success": True,
            "dry_run": False,
            "executed": True,
            "action": "create_issue",
            "issue_type_preflight": issue_type_context,
            "result": result,
        }
    except JiraProxyError as exc:
        return make_error_response("JIRA_ERROR", str(exc))


def _jira_update_issue(**kwargs):
    import logging
    from .jira_proxy_mcp import get_jira_proxy, JiraProxyError

    logger = logging.getLogger(__name__)

    issue_key = kwargs.get("issue_key")
    update_fields = kwargs.get("update_fields")
    if not issue_key or not isinstance(update_fields, dict):
        return make_error_response(
            "MISSING_PARAMS",
            "Missing required parameters: issue_key and update_fields (dict)",
            suggestions=[
                "Provide issue_key and update_fields as a dict of field names to values"
            ],
        )

    issue_key_str = str(issue_key).strip()
    project_key = _jira_project_from_issue_key(issue_key_str)
    if not project_key:
        return make_error_response(
            "INVALID_ISSUE_KEY",
            "Invalid issue_key format; expected PROJECT-123",
            suggestions=["Use the format PROJECT-123 for issue keys"],
        )

    dry_run, approved, execute = _jira_resolve_write_intent(kwargs)
    request_id = kwargs.get("request_id")

    guardrail_error = _jira_write_guardrails(
        action="update_issue",
        project_keys=[project_key],
        dry_run=dry_run,
        approved=approved,
        execute=execute,
    )
    if guardrail_error is not None:
        return guardrail_error

    if isinstance(request_id, str) and request_id.strip() and not dry_run:
        cached = _jira_cache_get("jira_update_issue", request_id.strip())
        if cached is not None:
            cached["reused"] = True
            return cached

    # Guardrail: do not allow changing the project via this helper.
    blocked_fields = {"project", "key", "id"}
    safe_fields = {
        str(k): v
        for k, v in update_fields.items()
        if isinstance(k, str) and k not in blocked_fields
    }
    if not safe_fields:
        return make_error_response(
            "NO_UPDATABLE_FIELDS",
            "No updatable fields provided (project/key/id are not allowed)",
            suggestions=["Provide fields like summary, description, assignee, etc."],
        )

    payload: dict[str, Any] = {"fields": safe_fields}

    if dry_run:
        return {
            "success": True,
            "dry_run": True,
            "executed": False,
            "action": "update_issue",
            "issue_key": issue_key_str,
            "proposed_payload": payload,
        }

    async def _async_update():
        proxy = await get_jira_proxy()
        return await proxy.update_issue(issue_key=issue_key_str, payload=payload)

    try:
        logger.info(
            "[jira_write] update_issue key=%s fields=%s",
            issue_key_str,
            sorted(safe_fields.keys())[:25],
        )
        result = _run_async_compat(_async_update)
        if isinstance(result, dict):
            result = dict(result)
            result.setdefault("success", True)
            result["dry_run"] = False
            result["executed"] = True
            result["action"] = "update_issue"
            result["issue_key"] = issue_key_str
            if isinstance(request_id, str) and request_id.strip():
                _jira_cache_set("jira_update_issue", request_id.strip(), result)
            return result
        return {
            "success": True,
            "dry_run": False,
            "executed": True,
            "action": "update_issue",
            "issue_key": issue_key_str,
            "result": result,
        }
    except JiraProxyError as exc:
        return make_error_response("JIRA_ERROR", str(exc))


def _jira_link_issue(**kwargs):
    import logging
    from .jira_proxy_mcp import get_jira_proxy, JiraProxyError

    logger = logging.getLogger(__name__)

    link_type = kwargs.get("link_type")

    def _clean_issue_key_param(name: str) -> str | None:
        value = kwargs.get(name)
        if value is None:
            return None
        cleaned = str(value).strip()
        return cleaned or None

    source_key = _clean_issue_key_param("source_issue_key")
    target_key = _clean_issue_key_param("target_issue_key")
    inward_key_from_kwargs = _clean_issue_key_param("inward_issue_key")
    outward_key_from_kwargs = _clean_issue_key_param("outward_issue_key")

    # Prefer semantic aliases to avoid accidental direction inversions.
    if source_key is not None or target_key is not None:
        if not source_key or not target_key:
            return make_error_response(
                "MISSING_PARAMS",
                "Missing required parameters: source_issue_key, target_issue_key, link_type",
                suggestions=[
                    "Provide both source_issue_key and target_issue_key, or use inward_issue_key and outward_issue_key."
                ],
            )
        if inward_key_from_kwargs and inward_key_from_kwargs != source_key:
            return make_error_response(
                "CONFLICTING_PARAMS",
                "Conflicting parameters: source_issue_key does not match inward_issue_key",
                suggestions=[
                    "Use only one key pair style, or provide matching values for source_issue_key/inward_issue_key."
                ],
                details={
                    "source_issue_key": source_key,
                    "inward_issue_key": inward_key_from_kwargs,
                },
            )
        if outward_key_from_kwargs and outward_key_from_kwargs != target_key:
            return make_error_response(
                "CONFLICTING_PARAMS",
                "Conflicting parameters: target_issue_key does not match outward_issue_key",
                suggestions=[
                    "Use only one key pair style, or provide matching values for target_issue_key/outward_issue_key."
                ],
                details={
                    "target_issue_key": target_key,
                    "outward_issue_key": outward_key_from_kwargs,
                },
            )
        inward_key = source_key
        outward_key = target_key
    else:
        if not inward_key_from_kwargs or not outward_key_from_kwargs or not link_type:
            return make_error_response(
                "MISSING_PARAMS",
                "Missing required parameters: link_type and one issue key pair (source/target or inward/outward)",
                suggestions=[
                    "Preferred: source_issue_key + target_issue_key + link_type.",
                    "Backward-compatible: inward_issue_key + outward_issue_key + link_type.",
                ],
            )
        inward_key = inward_key_from_kwargs
        outward_key = outward_key_from_kwargs
        source_key = inward_key
        target_key = outward_key

    if not link_type:
        return make_error_response(
            "MISSING_PARAMS",
            "Missing required parameter: link_type",
            suggestions=["Provide a link type (e.g. 'Blocks', 'Relates')."],
        )

    inward_project = _jira_project_from_issue_key(inward_key)
    outward_project = _jira_project_from_issue_key(outward_key)
    if not inward_project or not outward_project:
        return make_error_response(
            "INVALID_ISSUE_KEY",
            "Invalid issue key format; expected PROJECT-123",
            suggestions=["Use the format PROJECT-123 for issue keys"],
        )

    dry_run, approved, execute = _jira_resolve_write_intent(kwargs)
    request_id = kwargs.get("request_id")

    guardrail_error = _jira_write_guardrails(
        action="link_issue",
        project_keys=[inward_project, outward_project],
        dry_run=dry_run,
        approved=approved,
        execute=execute,
    )
    if guardrail_error is not None:
        return guardrail_error

    if isinstance(request_id, str) and request_id.strip() and not dry_run:
        cached = _jira_cache_get("jira_link_issue", request_id.strip())
        if cached is not None:
            cached["reused"] = True
            return cached

    payload: dict[str, Any] = {
        "type": {"name": str(link_type)},
        "inwardIssue": {"key": inward_key},
        "outwardIssue": {"key": outward_key},
    }

    comment = kwargs.get("comment")
    if isinstance(comment, str) and comment.strip():
        payload["comment"] = {"body": comment}

    if dry_run:
        return {
            "success": True,
            "dry_run": True,
            "executed": False,
            "action": "link_issue",
            "source_issue_key": source_key,
            "target_issue_key": target_key,
            "inward_issue_key": inward_key,
            "outward_issue_key": outward_key,
            "link_type": str(link_type),
            "proposed_payload": payload,
        }

    async def _async_link():
        proxy = await get_jira_proxy()
        return await proxy.link_issue(payload=payload)

    try:
        logger.info(
            "[jira_write] link_issue source=%s target=%s jira_outward=%s jira_inward=%s (%s)",
            source_key,
            target_key,
            outward_key,
            inward_key,
            str(link_type),
        )
        result = _run_async_compat(_async_link)
        if isinstance(result, dict):
            result = dict(result)
            result.setdefault("success", True)
            result["dry_run"] = False
            result["executed"] = True
            result["action"] = "link_issue"
            result["source_issue_key"] = source_key
            result["target_issue_key"] = target_key
            result["inward_issue_key"] = inward_key
            result["outward_issue_key"] = outward_key
            result["link_type"] = str(link_type)
            if isinstance(request_id, str) and request_id.strip():
                _jira_cache_set("jira_link_issue", request_id.strip(), result)
            return result
        return {
            "success": True,
            "dry_run": False,
            "executed": True,
            "action": "link_issue",
            "result": result,
        }
    except JiraProxyError as exc:
        return make_error_response("JIRA_ERROR", str(exc))


def _jira_delete_issue_link(**kwargs):
    import logging
    from .jira_proxy_mcp import get_jira_proxy, JiraProxyError

    logger = logging.getLogger(__name__)

    issue_link_id_raw = kwargs.get("issue_link_id")
    issue_link_id = (
        str(issue_link_id_raw).strip() if issue_link_id_raw is not None else ""
    )
    if not issue_link_id:
        return make_error_response(
            "MISSING_PARAMS",
            "Missing required parameter: issue_link_id",
            suggestions=["Provide the Jira issue link ID to delete."],
        )

    if not issue_link_id.isdigit():
        return make_error_response(
            "INVALID_ISSUE_LINK_ID",
            "Invalid issue_link_id format; expected a numeric Jira link ID",
            suggestions=["Use a numeric link ID from Jira issue link metadata."],
        )

    def _clean_issue_key_param(name: str) -> str | None:
        value = kwargs.get(name)
        if value is None:
            return None
        cleaned = str(value).strip()
        return cleaned or None

    source_key = _clean_issue_key_param("source_issue_key")
    target_key = _clean_issue_key_param("target_issue_key")

    source_project = (
        _jira_project_from_issue_key(source_key)
        if isinstance(source_key, str)
        else None
    )
    if source_key and not source_project:
        return make_error_response(
            "INVALID_ISSUE_KEY",
            "Invalid source_issue_key format; expected PROJECT-123",
            suggestions=["Use the format PROJECT-123 for source_issue_key."],
        )

    target_project = (
        _jira_project_from_issue_key(target_key)
        if isinstance(target_key, str)
        else None
    )
    if target_key and not target_project:
        return make_error_response(
            "INVALID_ISSUE_KEY",
            "Invalid target_issue_key format; expected PROJECT-123",
            suggestions=["Use the format PROJECT-123 for target_issue_key."],
        )

    project_keys: list[str] = []
    if source_project:
        project_keys.append(source_project)
    if target_project and target_project not in project_keys:
        project_keys.append(target_project)

    if not project_keys:
        return make_error_response(
            "MISSING_PARAMS",
            "Missing allow-list context: provide source_issue_key and/or target_issue_key",
            suggestions=[
                "Include source_issue_key and/or target_issue_key so project allow-list guardrails can be enforced."
            ],
        )

    dry_run, approved, execute = _jira_resolve_write_intent(kwargs)
    request_id = kwargs.get("request_id")

    guardrail_error = _jira_write_guardrails(
        action="delete_issue_link",
        project_keys=project_keys,
        dry_run=dry_run,
        approved=approved,
        execute=execute,
    )
    if guardrail_error is not None:
        return guardrail_error

    if isinstance(request_id, str) and request_id.strip() and not dry_run:
        cached = _jira_cache_get("jira_delete_issue_link", request_id.strip())
        if cached is not None:
            cached["reused"] = True
            return cached

    if dry_run:
        return {
            "success": True,
            "dry_run": True,
            "executed": False,
            "action": "delete_issue_link",
            "issue_link_id": issue_link_id,
            "source_issue_key": source_key,
            "target_issue_key": target_key,
            "proposed_endpoint": f"/rest/api/3/issueLink/{issue_link_id}",
        }

    async def _async_delete():
        proxy = await get_jira_proxy()
        return await proxy.delete_issue_link(issue_link_id=issue_link_id)

    try:
        logger.info(
            "[jira_write] delete_issue_link link_id=%s source=%s target=%s",
            issue_link_id,
            source_key,
            target_key,
        )
        result = _run_async_compat(_async_delete)
        if isinstance(result, dict):
            result = dict(result)
            result.setdefault("success", True)
            result["dry_run"] = False
            result["executed"] = True
            result["action"] = "delete_issue_link"
            result["issue_link_id"] = issue_link_id
            result["source_issue_key"] = source_key
            result["target_issue_key"] = target_key
            if isinstance(request_id, str) and request_id.strip():
                _jira_cache_set("jira_delete_issue_link", request_id.strip(), result)
            return result
        return {
            "success": True,
            "dry_run": False,
            "executed": True,
            "action": "delete_issue_link",
            "issue_link_id": issue_link_id,
            "result": result,
        }
    except JiraProxyError as exc:
        return make_error_response("JIRA_ERROR", str(exc))


