def _normalise_optional_concept_id(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    cleaned = value.strip()
    if not cleaned:
        return None
    if not cleaned.startswith("#V#"):
        cleaned = f"#V#{cleaned}"
    return cleaned


def _clean_optional_string(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    cleaned = value.strip()
    return cleaned or None


def _concept_id_to_namespace_slug(concept_id: str | None) -> str | None:
    if not isinstance(concept_id, str):
        return None
    cleaned = concept_id.strip()
    if not cleaned:
        return None
    if cleaned.startswith("#V#"):
        cleaned = cleaned[3:]
    cleaned = cleaned.strip()
    return cleaned or None


def _derive_namespace_for_actor(
    user_concept_id: str | None,
    organisation_concept_id: str | None,
) -> str | None:
    from ...services.namespace_service import derive_namespace

    user_slug = _concept_id_to_namespace_slug(user_concept_id)
    if not user_slug:
        return None
    org_slug = _concept_id_to_namespace_slug(organisation_concept_id)
    try:
        return derive_namespace(user_slug, org_slug)
    except Exception:
        return None


def _bootstrap_coding_agent_identity_for_actor(actor_concept_id: str | None) -> None:
    if actor_concept_id not in {"#V#coding_agent", "#V#github_copilot_instance"}:
        return
    try:
        from ...services.coding_agent_identity_bootstrap_service import (
            ensure_coding_agent_identity_concepts,
        )

        ensure_coding_agent_identity_concepts()
    except Exception:
        # Best effort only: conversation actions should still proceed even if bootstrap fails.
        return


def _resolve_shared_conversation_actor_context(
    payload: Mapping[str, Any],
    *,
    allow_actor_bootstrap_writes: bool = False,
) -> tuple[str | None, str | None, str | None, str | None]:
    from ...services.workflow_event_integration_service import (
        resolve_event_actor_context,
    )

    from .gateway import get_internal_mcp_preexisting_actor_context

    preexisting_actor = get_internal_mcp_preexisting_actor_context()
    if preexisting_actor is not None:
        # These fields denote the acting principal for this capability, rather
        # than a target or filter. The gateway's pre-existing actor context
        # therefore outranks all payload spellings as one indivisible scope.
        requested_user = _normalise_optional_concept_id(preexisting_actor[0])
        requested_org = _normalise_optional_concept_id(preexisting_actor[1])
        namespace = _derive_namespace_for_actor(requested_user, requested_org)
        actor_concept_id = None
    else:
        namespace = _clean_optional_string(payload.get("namespace"))
        requested_user = _normalise_optional_concept_id(
            payload.get("user_concept_id")
            or payload.get("acting_user_concept_id")
            or payload.get("actor_user_id")
            or payload.get("on_behalf_of_user_concept_id")
        )
        requested_org = _normalise_optional_concept_id(
            payload.get("organisation_concept_id") or payload.get("org_id")
        )
        actor_concept_id = _normalise_optional_concept_id(
            payload.get("actor_concept_id") or payload.get("agent_concept_id")
        )
    # Keep shared-conversation read paths side-effect free: bootstrap writes are
    # only allowed when the caller explicitly opts in on write-category paths.
    if allow_actor_bootstrap_writes:
        _bootstrap_coding_agent_identity_for_actor(actor_concept_id)

    resolved_user, resolved_org = resolve_event_actor_context(
        user_id=requested_user,
        org_id=requested_org,
        namespace=namespace,
    )

    user_concept_id = _normalise_optional_concept_id(resolved_user) or requested_user
    organisation_concept_id = (
        _normalise_optional_concept_id(resolved_org) or requested_org
    )
    return user_concept_id, organisation_concept_id, actor_concept_id, namespace


def _is_user_member_of_organisation(
    *,
    user_concept_id: str,
    organisation_concept_id: str,
) -> bool:
    from ...services.organisation_membership_service import get_user_memberships

    memberships = get_user_memberships(user_concept_id)
    for membership in memberships.get("memberships", []):
        if not isinstance(membership, dict):
            continue
        member_org = _normalise_optional_concept_id(
            membership.get("organisation_concept_id")
        )
        if member_org == organisation_concept_id:
            return True
    return False


def _looks_like_signed_conversation_scope_binding(value: Any) -> bool:
    if not isinstance(value, Mapping):
        return False
    return (
        _clean_optional_string(value.get("schema_version"))
        == "conversation_scope_binding.v1"
        and _clean_optional_string(value.get("binding_kind")) == "conversation_scope"
        and bool(_clean_optional_string(value.get("signature")))
    )


def _normalise_optional_bool(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value
    if not isinstance(value, str):
        return None
    cleaned = value.strip().lower()
    if cleaned in {"true", "1", "yes"}:
        return True
    if cleaned in {"false", "0", "no"}:
        return False
    return None


def _public_conversation_ref_mapping(value: Any) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        return {}
    return {str(key): item for key, item in value.items() if isinstance(key, str)}


def _normalise_public_conversation_ref_fields(
    raw_ref: Mapping[str, Any],
    lookup: Mapping[str, Any],
    *,
    input_shape: str,
) -> dict[str, Any]:
    fields: dict[str, Any] = {}
    field_sources: dict[str, str] = {}
    field_conflicts: list[dict[str, Any]] = []

    def add_field(
        key: str,
        value: Any,
        source: str,
        *,
        normaliser: Any = _clean_optional_string,
    ) -> None:
        normalised = normaliser(value)
        if normalised is None:
            return
        if key in fields and fields[key] != normalised:
            field_conflicts.append(
                {
                    "field": key,
                    "existing_value": fields[key],
                    "existing_source": field_sources.get(key),
                    "conflicting_value": normalised,
                    "conflicting_source": source,
                }
            )
            return
        fields[key] = normalised
        field_sources[key] = source

    add_field("session_id", raw_ref.get("session_id"), f"{input_shape}.session_id")
    add_field(
        "session_id",
        raw_ref.get("chat_session_id"),
        f"{input_shape}.chat_session_id",
    )
    add_field("session_id", lookup.get("session_id"), "chat_history_lookup.session_id")
    add_field(
        "user_concept_id",
        raw_ref.get("user_concept_id"),
        f"{input_shape}.user_concept_id",
        normaliser=_normalise_optional_concept_id,
    )
    add_field(
        "user_concept_id",
        raw_ref.get("history_owner_user_id"),
        f"{input_shape}.history_owner_user_id",
        normaliser=_normalise_optional_concept_id,
    )
    add_field(
        "user_concept_id",
        lookup.get("user_concept_id"),
        "chat_history_lookup.user_concept_id",
        normaliser=_normalise_optional_concept_id,
    )
    add_field(
        "user_concept_id",
        lookup.get("user_id"),
        "chat_history_lookup.user_id",
        normaliser=_normalise_optional_concept_id,
    )
    add_field("namespace", raw_ref.get("namespace"), f"{input_shape}.namespace")
    add_field(
        "namespace",
        raw_ref.get("read_namespace"),
        f"{input_shape}.read_namespace",
    )
    add_field("namespace", lookup.get("namespace"), "chat_history_lookup.namespace")
    add_field(
        "organisation_concept_id",
        raw_ref.get("organisation_concept_id"),
        f"{input_shape}.organisation_concept_id",
        normaliser=_normalise_optional_concept_id,
    )
    add_field(
        "organisation_concept_id",
        raw_ref.get("org_id"),
        f"{input_shape}.org_id",
        normaliser=_normalise_optional_concept_id,
    )
    add_field(
        "organisation_concept_id",
        lookup.get("organisation_concept_id"),
        "chat_history_lookup.organisation_concept_id",
        normaliser=_normalise_optional_concept_id,
    )
    add_field(
        "include_legacy",
        raw_ref.get("include_legacy"),
        f"{input_shape}.include_legacy",
        normaliser=_normalise_optional_bool,
    )
    add_field(
        "include_legacy",
        lookup.get("include_legacy"),
        "chat_history_lookup.include_legacy",
        normaliser=_normalise_optional_bool,
    )

    return {
        "fields": fields,
        "field_sources": field_sources,
        "field_conflicts": field_conflicts,
    }


def _normalise_chat_history_conversation_ref_argument(value: Any) -> dict[str, Any]:
    raw = _public_conversation_ref_mapping(value)
    if not raw:
        return {"recognised_public_ref": False}
    if _looks_like_signed_conversation_scope_binding(raw):
        return {
            "recognised_public_ref": False,
            "signed_conversation_ref": raw,
        }

    emitted_wrapper = raw.get("kind") == "von_conversation_ref"
    canonical_flat = (
        raw.get("binding_kind") is not None
        or str(raw.get("schema_version") or "").startswith("conversation_reference.")
    )
    if not emitted_wrapper and not canonical_flat:
        return {"recognised_public_ref": False}

    nested_ref = _public_conversation_ref_mapping(raw.get("conversation_ref"))
    nested_lookup = _public_conversation_ref_mapping(raw.get("chat_history_lookup"))
    if nested_ref and _looks_like_signed_conversation_scope_binding(nested_ref):
        return {
            "recognised_public_ref": False,
            "signed_conversation_ref": nested_ref,
        }

    ref_payload = nested_ref or raw
    validation_errors: list[dict[str, Any]] = []
    validation_fields = [
        (
            (
                "conversation_ref.conversation_ref.schema_version"
                if nested_ref
                else "conversation_ref.schema_version"
            ),
            ref_payload.get("schema_version"),
            "conversation_reference.v1",
        ),
        (
            (
                "conversation_ref.conversation_ref.binding_kind"
                if nested_ref
                else "conversation_ref.binding_kind"
            ),
            ref_payload.get("binding_kind"),
            "explicit_session_id",
        ),
    ]
    if emitted_wrapper:
        validation_fields.append(
            (
                "conversation_ref.schema_version",
                raw.get("schema_version"),
                "conversation_reference.v1",
            )
        )
    strict_canonical = (canonical_flat and not emitted_wrapper) or (
        raw.get("schema_version") == "conversation_reference.v1"
    )
    for field_path, field_value, expected in validation_fields:
        if (strict_canonical and field_value is None) or (
            field_value is not None and field_value != expected
        ):
            validation_errors.append(
                {
                    "field": field_path,
                    "value": field_value,
                    "expected": expected,
                }
            )
    input_shape = (
        "conversation_ref.conversation_ref" if nested_ref else "conversation_ref"
    )
    normalised = _normalise_public_conversation_ref_fields(
        ref_payload,
        nested_lookup,
        input_shape=input_shape,
    )
    field_sources = normalised["field_sources"]
    fields = normalised["fields"]
    return {
        "recognised_public_ref": True,
        "input_shape": (
            "emitted_von_conversation_ref_wrapper"
            if nested_ref
            else (
                "canonical_conversation_reference"
                if canonical_flat
                else "flattened_von_conversation_ref"
            )
        ),
        "fields": fields,
        "field_conflicts": normalised["field_conflicts"],
        "validation_errors": validation_errors,
        "identifier_binding": {
            "mode": "public_conversation_ref",
            "reference_kind": "von_conversation_ref",
            "validation_status": "normalised",
            "signature_verified": False,
            "input_shape": (
                "emitted_von_conversation_ref_wrapper"
                if nested_ref
                else (
                    "canonical_conversation_reference"
                    if canonical_flat
                    else "flattened_von_conversation_ref"
                )
            ),
            "chat_session_id_source": field_sources.get("session_id"),
            "requested_user_id_source": field_sources.get("user_concept_id"),
            "requested_namespace_source": field_sources.get("namespace"),
            "organisation_concept_id_source": field_sources.get(
                "organisation_concept_id"
            ),
            "include_legacy_source": field_sources.get("include_legacy"),
            "normalised_conversation_ref": {
                key: value
                for key, value in {
                    "session_id": fields.get("session_id"),
                    "user_concept_id": fields.get("user_concept_id"),
                    "namespace": fields.get("namespace"),
                    "organisation_concept_id": fields.get("organisation_concept_id"),
                    "include_legacy": fields.get("include_legacy"),
                }.items()
                if value is not None
            },
        },
    }


def _merge_public_conversation_ref_fields_into_payload(
    payload: dict[str, Any],
    fields: Mapping[str, Any],
    identifier_binding: dict[str, Any],
) -> list[dict[str, Any]]:
    conflicts: list[dict[str, Any]] = []

    def merge(
        payload_key: str,
        field_key: str,
        *,
        normaliser: Any = _clean_optional_string,
    ) -> None:
        ref_value = fields.get(field_key)
        if ref_value is None:
            return
        current = normaliser(payload.get(payload_key))
        normalised_ref = normaliser(ref_value)
        if (
            current is not None
            and normalised_ref is not None
            and current != normalised_ref
        ):
            conflicts.append(
                {
                    "field": field_key,
                    "payload_key": payload_key,
                    "payload_value": current,
                    "conversation_ref_value": normalised_ref,
                }
            )
            return
        if current is None and normalised_ref is not None:
            payload[payload_key] = normalised_ref

    merge("session_id", "session_id")
    merge("conversation_session_id", "session_id")
    merge(
        "user_concept_id",
        "user_concept_id",
        normaliser=_normalise_optional_concept_id,
    )
    merge("namespace", "namespace")
    merge(
        "organisation_concept_id",
        "organisation_concept_id",
        normaliser=_normalise_optional_concept_id,
    )
    include_legacy = fields.get("include_legacy")
    if include_legacy is not None and payload.get("include_legacy") is None:
        payload["include_legacy"] = bool(include_legacy)

    if conflicts:
        identifier_binding["validation_status"] = "field_mismatch"
    return conflicts


def _resolve_chat_history_read_target(
    payload: Mapping[str, Any],
) -> dict[str, Any] | dict[str, object]:
    from ...services import chat_history_service
    from ...services.conversation_scope_binding_service import (
        verify_conversation_scope_binding,
        verify_history_location_binding,
    )
    from ...services.shared_conversation_service import (
        get_accepted_invite_for_user_session,
        resolve_conversation_owner,
    )

    def _binding_error_result(
        *,
        message: str,
        identifier_binding_payload: Mapping[str, Any],
        details: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        merged_details = {
            "identifier_binding": dict(identifier_binding_payload),
        }
        if isinstance(details, Mapping):
            merged_details.update(dict(details))
        return make_error_response(
            "INVALID_CONTEXT_BINDING",
            message,
            details=merged_details,
        )

    normalised_conversation_ref = _normalise_chat_history_conversation_ref_argument(
        payload.get("conversation_ref")
    )
    payload_for_resolution = dict(payload)
    public_ref_context: dict[str, Any] | None = None
    public_ref_identifier_binding: dict[str, Any] | None = None

    if normalised_conversation_ref.get("recognised_public_ref"):
        public_ref_identifier_binding = dict(
            normalised_conversation_ref.get("identifier_binding") or {}
        )
        validation_errors = normalised_conversation_ref.get("validation_errors")
        if isinstance(validation_errors, list) and validation_errors:
            public_ref_identifier_binding["validation_status"] = "invalid_schema"
            return _binding_error_result(
                message="conversation_ref contains an invalid canonical reference field",
                identifier_binding_payload=public_ref_identifier_binding,
                details={"invalid_fields": validation_errors},
            )
        conflicts = normalised_conversation_ref.get("field_conflicts")
        if isinstance(conflicts, list) and conflicts:
            return _binding_error_result(
                message="conversation_ref contains conflicting locator fields",
                identifier_binding_payload=public_ref_identifier_binding,
                details={"field_conflicts": conflicts},
            )

        raw_extracted_fields = normalised_conversation_ref.get("fields")
        extracted_fields: Mapping[str, Any] = (
            raw_extracted_fields if isinstance(raw_extracted_fields, Mapping) else {}
        )
        explicit_conflicts = _merge_public_conversation_ref_fields_into_payload(
            payload_for_resolution,
            extracted_fields,
            public_ref_identifier_binding,
        )
        if explicit_conflicts:
            return _binding_error_result(
                message="payload parameters do not match conversation_ref fields",
                identifier_binding_payload=public_ref_identifier_binding,
                details={"field_conflicts": explicit_conflicts},
            )

        public_ref_context = {
            "history_owner_user_id": _normalise_optional_concept_id(
                extracted_fields.get("user_concept_id")
            ),
            "read_namespace": _clean_optional_string(extracted_fields.get("namespace")),
            "organisation_concept_id": _normalise_optional_concept_id(
                extracted_fields.get("organisation_concept_id")
            ),
        }
    elif normalised_conversation_ref.get("signed_conversation_ref") is not None:
        payload_for_resolution["conversation_ref"] = normalised_conversation_ref[
            "signed_conversation_ref"
        ]

    user_concept_id, organisation_concept_id, _actor_concept_id, namespace = (
        _resolve_shared_conversation_actor_context(payload_for_resolution)
    )
    raw_session_id = payload_for_resolution.get("session_id")
    raw_conversation_session_id = payload_for_resolution.get("conversation_session_id")
    session_id = _clean_optional_string(raw_session_id or raw_conversation_session_id)
    identifier_binding: dict[str, Any] = {
        "mode": "raw_parameters",
        "chat_session_id_source": (
            "payload.session_id"
            if _clean_optional_string(raw_session_id)
            else (
                "payload.conversation_session_id"
                if _clean_optional_string(raw_conversation_session_id)
                else None
            )
        ),
        "history_index_source": (
            "payload.history_index"
            if isinstance(payload.get("history_index"), int)
            else None
        ),
        "reference_kind": None,
    }
    bound_conversation_context: dict[str, Any] | None = None
    bound_history_index: int | None = None

    if public_ref_identifier_binding is not None:
        identifier_binding = public_ref_identifier_binding
        bound_conversation_context = public_ref_context

    conversation_ref = (
        None
        if public_ref_identifier_binding is not None
        else payload_for_resolution.get("conversation_ref")
    )
    if conversation_ref is not None:
        verified_conversation = verify_conversation_scope_binding(conversation_ref)
        if not verified_conversation.get("success"):
            return _binding_error_result(
                message=str(verified_conversation.get("error_message")),
                identifier_binding_payload=verified_conversation.get(
                    "identifier_binding", {}
                ),
            )
        bound_conversation_context = dict(verified_conversation)
        bound_session_id = _clean_optional_string(
            verified_conversation.get("chat_session_id")
        )
        if session_id and session_id != bound_session_id:
            return _binding_error_result(
                message="session_id does not match conversation_ref.chat_session_id",
                identifier_binding_payload=verified_conversation.get(
                    "identifier_binding", {}
                ),
                details={
                    "provided_session_id": session_id,
                    "bound_chat_session_id": bound_session_id,
                },
            )
        session_id = bound_session_id
        identifier_binding = dict(verified_conversation["identifier_binding"])

    history_location_ref = payload_for_resolution.get("history_location_ref")
    if history_location_ref is not None:
        verified_history_location = verify_history_location_binding(
            history_location_ref
        )
        if not verified_history_location.get("success"):
            return _binding_error_result(
                message=str(verified_history_location.get("error_message")),
                identifier_binding_payload=verified_history_location.get(
                    "identifier_binding", {}
                ),
            )
        bound_session_id = _clean_optional_string(
            verified_history_location.get("chat_session_id")
        )
        if session_id and session_id != bound_session_id:
            return _binding_error_result(
                message=(
                    "session_id does not match history_location_ref.chat_session_id"
                ),
                identifier_binding_payload=verified_history_location.get(
                    "identifier_binding", {}
                ),
                details={
                    "provided_session_id": session_id,
                    "bound_chat_session_id": bound_session_id,
                },
            )
        raw_history_index = payload_for_resolution.get("history_index")
        history_index_value = (
            raw_history_index if isinstance(raw_history_index, int) else None
        )
        bound_history_index = verified_history_location.get("history_index")
        if (
            isinstance(history_index_value, int)
            and isinstance(bound_history_index, int)
            and history_index_value != bound_history_index
        ):
            return _binding_error_result(
                message=(
                    "history_index does not match history_location_ref.history_index"
                ),
                identifier_binding_payload=verified_history_location.get(
                    "identifier_binding", {}
                ),
                details={
                    "provided_history_index": history_index_value,
                    "bound_history_index": bound_history_index,
                },
            )
        session_id = bound_session_id
        if bound_conversation_context is None:
            bound_conversation_context = dict(verified_history_location)
        identifier_binding = dict(verified_history_location["identifier_binding"])

    if not session_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: conversation_ref or session_id",
            suggestions=[
                "Provide an authoritative conversation_ref",
                "Or provide a non-empty session_id",
            ],
        )
    if not user_concept_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: user_concept_id",
            suggestions=[
                "Provide user_concept_id explicitly",
                "Or pass namespace containing a user identity",
            ],
        )

    try:
        owner_user_id = _normalise_optional_concept_id(
            resolve_conversation_owner(session_id=session_id)
        )
    except Exception as exc:
        return make_error_response(
            "SHARED_CONVERSATION_LOOKUP_FAILED",
            f"Failed to resolve conversation owner: {exc}",
            details={"session_id": session_id},
        )

    if owner_user_id and owner_user_id != user_concept_id:
        try:
            invite = get_accepted_invite_for_user_session(
                user_concept_id=user_concept_id,
                session_id=session_id,
            )
        except Exception as exc:
            return make_error_response(
                "SHARED_CONVERSATION_LOOKUP_FAILED",
                f"Failed to resolve shared conversation invite: {exc}",
                details={
                    "session_id": session_id,
                    "user_concept_id": user_concept_id,
                },
            )
        if not isinstance(invite, dict):
            return make_error_response(
                "PERMISSION_DENIED",
                "User does not own this conversation and has no accepted invite",
                details={
                    "user_concept_id": user_concept_id,
                    "session_id": session_id,
                },
            )
        invite_org = _normalise_optional_concept_id(
            invite.get("organisation_concept_id")
        )
        effective_org = organisation_concept_id or invite_org
        if effective_org:
            try:
                if not _is_user_member_of_organisation(
                    user_concept_id=user_concept_id,
                    organisation_concept_id=effective_org,
                ):
                    return make_error_response(
                        "PERMISSION_DENIED",
                        f"User {user_concept_id} is not a member of {effective_org}",
                        details={
                            "user_concept_id": user_concept_id,
                            "organisation_concept_id": effective_org,
                        },
                    )
            except Exception as exc:
                return make_error_response(
                    "ORG_MEMBERSHIP_CHECK_FAILED",
                    f"Failed to verify organisation membership: {exc}",
                    details={
                        "user_concept_id": user_concept_id,
                        "organisation_concept_id": effective_org,
                    },
                )
        owner_namespace = (
            _derive_namespace_for_actor(owner_user_id, effective_org)
            or namespace
            or chat_history_service.resolve_chat_history_namespace(owner_user_id)
        )
        if isinstance(bound_conversation_context, Mapping):
            bound_owner = _normalise_optional_concept_id(
                bound_conversation_context.get("history_owner_user_id")
            )
            bound_org = _normalise_optional_concept_id(
                bound_conversation_context.get("organisation_concept_id")
            )
            bound_read_namespace = _clean_optional_string(
                bound_conversation_context.get("read_namespace")
            )
            if bound_owner and bound_owner != owner_user_id:
                return _binding_error_result(
                    message=(
                        "Bound conversation reference owner does not match the "
                        "resolved authorised conversation owner"
                    ),
                    identifier_binding_payload=identifier_binding,
                    details={
                        "bound_history_owner_user_id": bound_owner,
                        "resolved_history_owner_user_id": owner_user_id,
                        "chat_session_id": session_id,
                    },
                )
            if (
                bound_org
                and _normalise_optional_concept_id(effective_org)
                and bound_org != _normalise_optional_concept_id(effective_org)
            ):
                return _binding_error_result(
                    message=(
                        "Bound conversation reference organisation does not match "
                        "the resolved authorised conversation organisation"
                    ),
                    identifier_binding_payload=identifier_binding,
                    details={
                        "bound_organisation_concept_id": bound_org,
                        "resolved_organisation_concept_id": _normalise_optional_concept_id(
                            effective_org
                        ),
                        "chat_session_id": session_id,
                    },
                )
            if (
                bound_read_namespace
                and owner_namespace
                and bound_read_namespace != owner_namespace
            ):
                return _binding_error_result(
                    message=(
                        "Bound conversation reference namespace does not match "
                        "the resolved authorised read namespace"
                    ),
                    identifier_binding_payload=identifier_binding,
                    details={
                        "bound_read_namespace": bound_read_namespace,
                        "resolved_read_namespace": owner_namespace,
                        "chat_session_id": session_id,
                    },
                )
        return {
            "success": True,
            "session_id": session_id,
            "chat_session_id": session_id,
            "read_user_id": owner_user_id,
            "requested_user_id": user_concept_id,
            "read_namespace": owner_namespace,
            "requested_namespace": namespace,
            "access_mode": "invitee",
            "organisation_concept_id": effective_org,
            "history_index": bound_history_index,
            "include_legacy": payload_for_resolution.get("include_legacy"),
            "identifier_binding": {
                **identifier_binding,
                "requested_user_id": user_concept_id,
                "requested_namespace": namespace,
                "resolved_history_owner_user_id": owner_user_id,
                "resolved_read_namespace": owner_namespace,
                "access_mode": "invitee",
            },
        }

    read_user_id = owner_user_id or user_concept_id
    read_namespace = (
        namespace
        or _derive_namespace_for_actor(read_user_id, organisation_concept_id)
        or chat_history_service.resolve_chat_history_namespace(read_user_id)
    )

    try:
        has_session = chat_history_service.has_chat_history_session(
            read_user_id,
            session_id,
            namespace=read_namespace,
            include_legacy=True,
        )
    except Exception:
        has_session = False
    if not has_session:
        try:
            has_session = chat_history_service.has_chat_history_session(
                read_user_id,
                session_id,
                namespace=None,
                include_legacy=True,
            )
        except Exception:
            has_session = False
        if has_session:
            read_namespace = None
    if not has_session:
        return make_error_response(
            "PERMISSION_DENIED",
            "Not authorised for conversation",
            details={
                "user_concept_id": user_concept_id,
                "session_id": session_id,
                "identifier_binding": identifier_binding,
            },
        )

    if isinstance(bound_conversation_context, Mapping):
        bound_owner = _normalise_optional_concept_id(
            bound_conversation_context.get("history_owner_user_id")
        )
        bound_org = _normalise_optional_concept_id(
            bound_conversation_context.get("organisation_concept_id")
        )
        bound_read_namespace = _clean_optional_string(
            bound_conversation_context.get("read_namespace")
        )
        if bound_owner and bound_owner != read_user_id:
            return _binding_error_result(
                message=(
                    "Bound conversation reference owner does not match the "
                    "resolved authorised conversation owner"
                ),
                identifier_binding_payload=identifier_binding,
                details={
                    "bound_history_owner_user_id": bound_owner,
                    "resolved_history_owner_user_id": read_user_id,
                    "chat_session_id": session_id,
                },
            )
        if (
            bound_org
            and _normalise_optional_concept_id(organisation_concept_id)
            and bound_org != _normalise_optional_concept_id(organisation_concept_id)
        ):
            return _binding_error_result(
                message=(
                    "Bound conversation reference organisation does not match "
                    "the resolved authorised conversation organisation"
                ),
                identifier_binding_payload=identifier_binding,
                details={
                    "bound_organisation_concept_id": bound_org,
                    "resolved_organisation_concept_id": _normalise_optional_concept_id(
                        organisation_concept_id
                    ),
                    "chat_session_id": session_id,
                },
            )
        if (
            bound_read_namespace
            and read_namespace
            and bound_read_namespace != read_namespace
        ):
            return _binding_error_result(
                message=(
                    "Bound conversation reference namespace does not match "
                    "the resolved authorised read namespace"
                ),
                identifier_binding_payload=identifier_binding,
                details={
                    "bound_read_namespace": bound_read_namespace,
                    "resolved_read_namespace": read_namespace,
                    "chat_session_id": session_id,
                },
            )

    return {
        "success": True,
        "session_id": session_id,
        "chat_session_id": session_id,
        "read_user_id": read_user_id,
        "requested_user_id": user_concept_id,
        "read_namespace": read_namespace,
        "requested_namespace": namespace,
        "access_mode": "owner" if read_user_id == user_concept_id else "delegated",
        "organisation_concept_id": organisation_concept_id,
        "history_index": bound_history_index,
        "include_legacy": payload_for_resolution.get("include_legacy"),
        "identifier_binding": {
            **identifier_binding,
            "requested_user_id": user_concept_id,
            "requested_namespace": namespace,
            "resolved_history_owner_user_id": read_user_id,
            "resolved_read_namespace": read_namespace,
            "access_mode": "owner" if read_user_id == user_concept_id else "delegated",
        },
    }


def _shared_conversation_create_session(**kwargs):
    from ...services import chat_history_service
    from ...services.episode_logging_service import log_episode

    user_concept_id, organisation_concept_id, actor_concept_id, namespace = (
        _resolve_shared_conversation_actor_context(
            kwargs,
            allow_actor_bootstrap_writes=True,
        )
    )
    session_id = _clean_optional_string(kwargs.get("session_id"))
    session_name = _clean_optional_string(kwargs.get("session_name"))
    role_in_org = _clean_optional_string(kwargs.get("role_in_org"))

    if not user_concept_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: user_concept_id",
            suggestions=[
                "Provide user_concept_id (or acting_user_concept_id) explicitly",
                "Or pass namespace containing a user identity (for example #V#user@org)",
            ],
        )
    if not session_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: session_id",
            suggestions=["Provide a non-empty session_id"],
        )

    try:
        if organisation_concept_id and not _is_user_member_of_organisation(
            user_concept_id=user_concept_id,
            organisation_concept_id=organisation_concept_id,
        ):
            return make_error_response(
                "PERMISSION_DENIED",
                f"User {user_concept_id} is not a member of {organisation_concept_id}",
                details={
                    "user_concept_id": user_concept_id,
                    "organisation_concept_id": organisation_concept_id,
                },
            )
    except PermissionError as exc:
        return make_error_response("PERMISSION_DENIED", str(exc))
    except ValueError as exc:
        return make_error_response("INVALID_DATA", str(exc))
    except Exception as exc:
        return make_error_response(
            "ORG_MEMBERSHIP_CHECK_FAILED",
            f"Failed to verify organisation membership: {exc}",
        )

    effective_namespace = namespace or _derive_namespace_for_actor(
        user_concept_id, organisation_concept_id
    )
    created = True
    try:
        created = not chat_history_service.has_chat_history_session(
            user_concept_id,
            session_id,
            namespace=effective_namespace,
            include_legacy=True,
        )
    except Exception:
        # Best effort: session creation remains idempotent even without pre-check.
        created = True

    try:
        session_result = chat_history_service.create_chat_session(
            user_id=user_concept_id,
            session_id=session_id,
            session_name=session_name,
            namespace=effective_namespace,
            organisation_concept_id=organisation_concept_id,
            role_in_org=role_in_org,
        )
    except Exception as exc:
        return make_error_response("CHAT_HISTORY_ERROR", str(exc))

    episode_id = log_episode(
        episode_type="shared_conversation_session_created",
        actor_user_id=user_concept_id,
        organisation_concept_id=organisation_concept_id,
        session_id=session_id,
        payload={
            "actor_concept_id": actor_concept_id,
            "created": created,
            "namespace": effective_namespace,
        },
        status="created" if created else "exists",
    )

    return {
        "success": True,
        "created": created,
        "session_id": session_id,
        "session": session_result,
        "user_concept_id": user_concept_id,
        "actor_user_id": user_concept_id,
        "actor_concept_id": actor_concept_id,
        "organisation_concept_id": organisation_concept_id,
        "episode_id": episode_id,
    }


def _shared_conversation_join_session(**kwargs):
    from ...services import chat_history_service
    from ...services.episode_logging_service import log_episode
    from ...services.shared_conversation_service import (
        get_accepted_invite_for_user_session,
        resolve_conversation_owner,
    )

    user_concept_id, organisation_concept_id, actor_concept_id, namespace = (
        _resolve_shared_conversation_actor_context(
            kwargs,
            allow_actor_bootstrap_writes=True,
        )
    )
    session_id = _clean_optional_string(kwargs.get("session_id"))
    session_name = _clean_optional_string(kwargs.get("session_name"))

    if not user_concept_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: user_concept_id",
            suggestions=[
                "Provide user_concept_id (or acting_user_concept_id) explicitly",
                "Or pass namespace containing a user identity (for example #V#user@org)",
            ],
        )
    if not session_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: session_id",
            suggestions=["Provide a non-empty session_id"],
        )

    try:
        invite = get_accepted_invite_for_user_session(
            user_concept_id=user_concept_id,
            session_id=session_id,
        )
        owner_user_id = _normalise_optional_concept_id(
            resolve_conversation_owner(session_id=session_id)
        )
        has_accepted_invite = isinstance(invite, dict)
        is_owner = owner_user_id == user_concept_id
    except Exception as exc:
        return make_error_response(
            "SHARED_CONVERSATION_LOOKUP_FAILED",
            f"Failed to resolve shared conversation access: {exc}",
        )

    if not is_owner and not has_accepted_invite:
        return make_error_response(
            "PERMISSION_DENIED",
            "User does not own this conversation and has no accepted invite",
            details={
                "user_concept_id": user_concept_id,
                "session_id": session_id,
            },
        )

    invite_org = (
        _normalise_optional_concept_id((invite or {}).get("organisation_concept_id"))
        if isinstance(invite, dict)
        else None
    )
    effective_org = organisation_concept_id or invite_org
    if effective_org:
        try:
            if not _is_user_member_of_organisation(
                user_concept_id=user_concept_id,
                organisation_concept_id=effective_org,
            ):
                return make_error_response(
                    "PERMISSION_DENIED",
                    f"User {user_concept_id} is not a member of {effective_org}",
                    details={
                        "user_concept_id": user_concept_id,
                        "organisation_concept_id": effective_org,
                    },
                )
        except PermissionError as exc:
            return make_error_response("PERMISSION_DENIED", str(exc))
        except ValueError as exc:
            return make_error_response("INVALID_DATA", str(exc))
        except Exception as exc:
            return make_error_response(
                "ORG_MEMBERSHIP_CHECK_FAILED",
                f"Failed to verify organisation membership: {exc}",
            )

    effective_namespace = namespace or _derive_namespace_for_actor(
        user_concept_id, effective_org
    )
    session_exists = False
    try:
        session_exists = chat_history_service.has_chat_history_session(
            user_concept_id,
            session_id,
            namespace=effective_namespace,
            include_legacy=True,
        )
    except Exception:
        session_exists = False

    try:
        if session_exists:
            session_result = chat_history_service.get_chat_history_session_summary(
                user_concept_id,
                session_id,
                namespace=effective_namespace,
                include_legacy=True,
                summary_mode="light",
            ) or {"session_id": session_id}
        else:
            session_result = chat_history_service.create_chat_session(
                user_id=user_concept_id,
                session_id=session_id,
                session_name=session_name,
                namespace=effective_namespace,
                organisation_concept_id=effective_org,
            )
    except Exception as exc:
        return make_error_response("CHAT_HISTORY_ERROR", str(exc))

    access_mode = "owner" if is_owner else "invitee"
    created_session = not session_exists
    episode_id = log_episode(
        episode_type="shared_conversation_session_joined",
        actor_user_id=user_concept_id,
        organisation_concept_id=effective_org,
        session_id=session_id,
        payload={
            "actor_concept_id": actor_concept_id,
            "access_mode": access_mode,
            "has_accepted_invite": has_accepted_invite,
            "created_session": created_session,
            "owner_user_id": owner_user_id,
        },
        status="joined",
    )

    return {
        "success": True,
        "joined": True,
        "created_session": created_session,
        "access_mode": access_mode,
        "is_owner": is_owner,
        "has_accepted_invite": has_accepted_invite,
        "session_id": session_id,
        "session": session_result,
        "invite": invite if isinstance(invite, dict) else None,
        "owner_user_id": owner_user_id,
        "user_concept_id": user_concept_id,
        "actor_user_id": user_concept_id,
        "actor_concept_id": actor_concept_id,
        "organisation_concept_id": effective_org,
        "episode_id": episode_id,
    }


def _shared_conversation_invite_create(**kwargs):
    from ...services.episode_logging_service import log_episode
    from ...services.organisation_membership_service import (
        get_organisation_members,
    )
    from ...services.shared_conversation_service import create_invite

    user_concept_id, organisation_concept_id, actor_concept_id, _namespace = (
        _resolve_shared_conversation_actor_context(
            kwargs,
            allow_actor_bootstrap_writes=True,
        )
    )
    session_id = _clean_optional_string(kwargs.get("session_id"))
    invitee_concept_id = _normalise_optional_concept_id(
        kwargs.get("invitee_concept_id") or kwargs.get("invitee_user_id")
    )

    if not user_concept_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: user_concept_id",
            suggestions=[
                "Provide user_concept_id (or acting_user_concept_id) explicitly",
                "Or pass namespace containing a user identity (for example #V#user@org)",
            ],
        )
    if not session_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: session_id",
            suggestions=["Provide a non-empty session_id"],
        )
    if not invitee_concept_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: invitee_concept_id",
            suggestions=["Provide invitee_concept_id (or invitee_user_id)"],
        )
    if invitee_concept_id == user_concept_id:
        return make_error_response(
            "INVALID_DATA",
            "Cannot invite the actor to their own conversation",
            details={"invitee_concept_id": invitee_concept_id},
        )
    if not organisation_concept_id:
        return make_error_response(
            "MISSING_ORGANISATION_CONTEXT",
            "organisation_concept_id is required for shared conversation invites",
            suggestions=[
                "Provide organisation_concept_id (or org_id)",
                "Or pass namespace in #V#user@org format",
            ],
        )

    try:
        if not _is_user_member_of_organisation(
            user_concept_id=user_concept_id,
            organisation_concept_id=organisation_concept_id,
        ):
            return make_error_response(
                "PERMISSION_DENIED",
                f"User {user_concept_id} is not a member of {organisation_concept_id}",
                details={
                    "user_concept_id": user_concept_id,
                    "organisation_concept_id": organisation_concept_id,
                },
            )
    except PermissionError as exc:
        return make_error_response("PERMISSION_DENIED", str(exc))
    except ValueError as exc:
        return make_error_response("INVALID_DATA", str(exc))
    except Exception as exc:
        return make_error_response(
            "ORG_MEMBERSHIP_CHECK_FAILED",
            f"Failed to verify organisation membership: {exc}",
        )

    try:
        organisation_members = get_organisation_members(organisation_concept_id)
        valid_member_ids = {
            _normalise_optional_concept_id(member.get("user_concept_id"))
            for member in organisation_members.get("members", [])
            if isinstance(member, dict)
        }
        if invitee_concept_id not in valid_member_ids:
            return make_error_response(
                "PERMISSION_DENIED",
                "Invitee is not a member of the organisation",
                details={
                    "invitee_concept_id": invitee_concept_id,
                    "organisation_concept_id": organisation_concept_id,
                },
            )
    except PermissionError as exc:
        return make_error_response("PERMISSION_DENIED", str(exc))
    except ValueError as exc:
        return make_error_response("INVALID_DATA", str(exc))
    except Exception as exc:
        return make_error_response(
            "ORGANISATION_MEMBER_LOOKUP_FAILED",
            f"Failed to validate organisation members: {exc}",
        )

    try:
        invite_result = create_invite(
            session_id=session_id,
            inviter_user_id=user_concept_id,
            invitee_user_id=invitee_concept_id,
            organisation_concept_id=organisation_concept_id,
        )
    except Exception as exc:
        return make_error_response("SHARED_CONVERSATION_INVITE_FAILED", str(exc))

    invite_payload = invite_result.get("invite", {})
    episode_id = log_episode(
        episode_type="shared_conversation_invite_created",
        actor_user_id=user_concept_id,
        organisation_concept_id=organisation_concept_id,
        session_id=session_id,
        related_invite_id=invite_payload.get("invite_id"),
        payload={
            "actor_concept_id": actor_concept_id,
            "invitee_user_id": invitee_concept_id,
            "created": bool(invite_result.get("created")),
        },
        status="created" if invite_result.get("created") else "exists",
    )

    return {
        "success": True,
        "created": bool(invite_result.get("created")),
        "invite": invite_payload if isinstance(invite_payload, dict) else None,
        "session_id": session_id,
        "user_concept_id": user_concept_id,
        "actor_user_id": user_concept_id,
        "actor_concept_id": actor_concept_id,
        "organisation_concept_id": organisation_concept_id,
        "episode_id": episode_id,
    }


def _shared_conversation_list_invites(**kwargs):
    from ...services.shared_conversation_service import list_invites_for_user

    user_concept_id, organisation_concept_id, actor_concept_id, _namespace = (
        _resolve_shared_conversation_actor_context(
            kwargs,
            allow_actor_bootstrap_writes=False,
        )
    )
    direction_raw = _clean_optional_string(kwargs.get("direction")) or "incoming"
    direction_value = direction_raw.lower()
    if direction_value in {"incoming", "in"}:
        direction = "incoming"
    elif direction_value in {"outgoing", "out"}:
        direction = "outgoing"
    else:
        return make_error_response(
            "INVALID_DATA",
            f"Invalid direction: {direction_raw}",
            suggestions=["Use direction='incoming' or direction='outgoing'"],
        )

    status_raw = _clean_optional_string(kwargs.get("status"))
    status = status_raw if status_raw is not None else "pending"
    session_id = _clean_optional_string(kwargs.get("session_id"))

    if not user_concept_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: user_concept_id",
            suggestions=[
                "Provide user_concept_id (or acting_user_concept_id) explicitly",
                "Or pass namespace containing a user identity (for example #V#user@org)",
            ],
        )

    if organisation_concept_id:
        try:
            if not _is_user_member_of_organisation(
                user_concept_id=user_concept_id,
                organisation_concept_id=organisation_concept_id,
            ):
                return make_error_response(
                    "PERMISSION_DENIED",
                    f"User {user_concept_id} is not a member of {organisation_concept_id}",
                    details={
                        "user_concept_id": user_concept_id,
                        "organisation_concept_id": organisation_concept_id,
                    },
                )
        except PermissionError as exc:
            return make_error_response("PERMISSION_DENIED", str(exc))
        except ValueError as exc:
            return make_error_response("INVALID_DATA", str(exc))
        except Exception as exc:
            return make_error_response(
                "ORG_MEMBERSHIP_CHECK_FAILED",
                f"Failed to verify organisation membership: {exc}",
            )

    try:
        invites = list_invites_for_user(
            user_concept_id=user_concept_id,
            status=status,
            direction=direction,
            session_id=session_id,
        )
    except Exception as exc:
        return make_error_response("SHARED_CONVERSATION_LOOKUP_FAILED", str(exc))

    if organisation_concept_id:
        invites = [
            invite
            for invite in invites
            if (
                _normalise_optional_concept_id(invite.get("organisation_concept_id"))
                in (None, organisation_concept_id)
            )
        ]

    return {
        "success": True,
        "invites": invites,
        "count": len(invites),
        "user_concept_id": user_concept_id,
        "actor_user_id": user_concept_id,
        "actor_concept_id": actor_concept_id,
        "organisation_concept_id": organisation_concept_id,
    }


def _shared_conversation_respond_invite(**kwargs):
    from ...services import chat_history_service
    from ...services.episode_logging_service import log_episode
    from ...services.shared_conversation_service import respond_to_invite

    user_concept_id, organisation_concept_id, actor_concept_id, namespace = (
        _resolve_shared_conversation_actor_context(
            kwargs,
            allow_actor_bootstrap_writes=True,
        )
    )
    invite_id = _clean_optional_string(kwargs.get("invite_id"))
    action = (_clean_optional_string(kwargs.get("action")) or "").lower()
    session_name = _clean_optional_string(kwargs.get("session_name"))
    join_session_on_accept = _coerce_bool_input(
        kwargs.get("join_session_on_accept"),
        default=True,
    )

    if not user_concept_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: user_concept_id",
            suggestions=[
                "Provide user_concept_id (or acting_user_concept_id) explicitly",
                "Or pass namespace containing a user identity (for example #V#user@org)",
            ],
        )
    if not invite_id:
        return make_error_response(
            "MISSING_PARAM",
            "Missing required parameter: invite_id",
            suggestions=["Provide a non-empty invite_id"],
        )
    if action not in {"accept", "decline"}:
        return make_error_response(
            "INVALID_DATA",
            "action must be 'accept' or 'decline'",
            details={"action": kwargs.get("action")},
        )

    try:
        invite = respond_to_invite(
            invite_id=invite_id,
            user_concept_id=user_concept_id,
            action=action,
        )
    except ValueError as exc:
        return make_error_response("INVALID_DATA", str(exc))
    except Exception as exc:
        return make_error_response("SHARED_CONVERSATION_UPDATE_FAILED", str(exc))

    if not isinstance(invite, dict):
        return make_error_response(
            "NOT_FOUND",
            "Invite not found",
            details={"invite_id": invite_id},
        )

    invite_org = _normalise_optional_concept_id(invite.get("organisation_concept_id"))
    effective_org = organisation_concept_id or invite_org
    if organisation_concept_id and invite_org and invite_org != organisation_concept_id:
        return make_error_response(
            "PERMISSION_DENIED",
            "Invite organisation scope does not match supplied organisation_concept_id",
            details={
                "invite_id": invite_id,
                "invite_organisation_concept_id": invite_org,
                "organisation_concept_id": organisation_concept_id,
            },
        )

    created_session = False
    session_result = None
    session_id = _clean_optional_string(invite.get("session_id"))
    if action == "accept" and join_session_on_accept and session_id:
        join_namespace = namespace or _derive_namespace_for_actor(
            user_concept_id, effective_org
        )
        try:
            session_exists = chat_history_service.has_chat_history_session(
                user_concept_id,
                session_id,
                namespace=join_namespace,
                include_legacy=True,
            )
        except Exception:
            session_exists = False
        try:
            if session_exists:
                session_result = chat_history_service.get_chat_history_session_summary(
                    user_concept_id,
                    session_id,
                    namespace=join_namespace,
                    include_legacy=True,
                    summary_mode="light",
                ) or {"session_id": session_id}
            else:
                session_result = chat_history_service.create_chat_session(
                    user_id=user_concept_id,
                    session_id=session_id,
                    session_name=session_name,
                    namespace=join_namespace,
                    organisation_concept_id=effective_org,
                )
                created_session = True
        except Exception as exc:
            return make_error_response("CHAT_HISTORY_ERROR", str(exc))

    episode_id = log_episode(
        episode_type="shared_conversation_invite_responded",
        actor_user_id=user_concept_id,
        organisation_concept_id=effective_org,
        session_id=session_id,
        related_invite_id=invite_id,
        payload={
            "actor_concept_id": actor_concept_id,
            "action": action,
            "join_session_on_accept": join_session_on_accept,
            "created_session": created_session,
        },
        status=invite.get("status"),
    )

    return {
        "success": True,
        "invite_id": invite_id,
        "action": action,
        "invite": invite,
        "session_id": session_id,
        "session": session_result,
        "created_session": created_session,
        "user_concept_id": user_concept_id,
        "actor_user_id": user_concept_id,
        "actor_concept_id": actor_concept_id,
        "organisation_concept_id": effective_org,
        "episode_id": episode_id,
    }


def _operational_learning_release_error_response(exc: Exception) -> dict[str, Any]:
    from ...services.operational_learning_release_service import (
        LearningReleaseValidationError,
    )
    from ...services.operational_learning_release_vontology_service import (
        LearningReleasePersistenceError,
    )

    if isinstance(
        exc, (LearningReleaseValidationError, LearningReleasePersistenceError)
    ):
        projection = exc.to_dict()
        recovery_affordances = projection.get("recovery_affordances") or []
        suggestions = [
            str(item.get("action_type"))
            for item in recovery_affordances
            if isinstance(item, Mapping) and item.get("action_type")
        ]
        return make_error_response(
            str(projection.get("error_code") or "operational_learning_release_failed"),
            str(exc),
            details=projection,
            suggestions=suggestions or None,
        )
    logger.exception("Operational learning-release MCP operation failed", exc_info=exc)
    return make_error_response(
        "operational_learning_release_internal_error",
        "Operational learning-release persistence failed.",
        details={"exception_type": type(exc).__name__},
    )


def _operational_learning_build_failure_evidence_packets(**kwargs):
    from ...services.operational_learning_release_service import (
        build_failure_evidence_packets,
    )

    try:
        packets = build_failure_evidence_packets(
            cast(Sequence[Mapping[str, Any]], kwargs["failure_evidence"])
        )
        return {"success": True, "failure_evidence_packets": packets}
    except Exception as exc:
        return _operational_learning_release_error_response(exc)


